INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "下表是四位小伙伴读同一本书的情况,请完成表格。已知第一位已读 31 页、剩 64 页,第二位已读 22 页,第三位剩 46 页,第四位已读 68 页。这本书共有多少页?请填出第二位剩下、第三位已读、第四位剩下的页数。", "options": null}', '73、49、27', '总页数=31+64=95;第二位剩=95-22=73;第三位已读=95-46=49;第四位剩=95-68=27。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "柜台里的球鞋,卖出了 23 双,又运来 17 双,现在有 27 双,原来有( )双。", "options": null}', '33', '原来=现在+卖出-运来=27+23-17=33。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "把 11、22、33、44、55、66、77、88 这八个数填入方框中,使等式成立(每个数只能用一次):[ ]-[ ]=11、[ ]-[ ]=22、[ ]-[ ]=33、[ ]-[ ]=44。", "options": null}', '88-77=11,55-33=22,44-11=33,66-22=44', '枚举:88-77=11 唯一;55-33=22;44-11=33;66-22=44,各数刚好用完。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "排排队,来报数,正着报数我报 6,倒着报数我报 9。请你算一算,一共有( )个小朋友在报数。", "options": null}', '14', '正着+倒着-1(同一人)=6+9-1=14。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "兄弟俩各有一些卡片,哥哥给弟弟 18 张后,弟弟还比哥哥少 18 张。原来哥哥比弟弟多( )张卡片。", "options": null}', '54', '给 18 后还差 18,说明原来差 18+18×2=54 张;验证:哥-弟=54,给 18 后哥-18,弟+18,差=54-36=18。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "最大的两位数与 59 相减的差是( )。", "options": ["A. 68", "B. 69", "C. 40"]}', 'C', '99-59=40,选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "学校开展兴趣小组活动,数学组和航模组共有 29 人,其中航模组有 9 人,数学组有多少人?列式计算正确的是( )。", "options": ["A. 29-20=9(人)", "B. 29-9=20(人)", "C. 20-9=11(人)"]}', 'B', '数学组=29-9=20 人,选 B。', 'paper', '[]', NULL, 0);
