INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 3, '{"stem": "欢欢看《小马过河》,两周看完,第一周看了 11 页。这本故事书有多少页?如果列式为 11+10+11,那么要补充的条件是( )。", "options": ["A. 第二周看了 10 页", "B. 第一周看的比第二周多 10 页", "C. 第二周看的比第一周多 10 页"]}', 'C', '11+10+11=32 表示第一周 11 页、第二周比第一周多 10 页(11+10=21)、再加 11 是首周+差值结构,选 C。', 'paper', '[]', NULL, 0);
