INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "看图列式计算。番茄和黄瓜共 57 千克,番茄比黄瓜多 15 千克,番茄多少千克?", "options": null}', '(57+15)÷2=36', '(57+15)÷2=36,番茄 36 千克(黄瓜=57-36=21 千克)。', 'paper', '[]', '["/static/qimg/js_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "国庆假期第一天,某公园迎来文旅小热潮。1 号停车场原来有汽车 94 辆,开走了 28 辆,又开来了 31 辆,现在 1 号停车场里有多少辆汽车?", "options": null}', '94-28+31=97', '94-28+31=97,现在 1 号停车场里有 97 辆汽车。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "同学们进行垃圾分类,第一个月学校产生的可回收垃圾是 47 千克,第二个月学校产生的可回收垃圾比第一个月少 19 千克,两个月学校一共产生多少千克可回收垃圾?", "options": null}', '47-19=28,47+28=75', '第二月=47-19=28,两月共=47+28=75 千克。', 'paper', '[]', NULL, 0);
