INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "图书馆把新买来的书进行编号,从 45 号编到 72 号,新买来的书一共有( )本,后来这些新书又被借走了 9 本,还剩下( )本。", "options": null}', '28、19', '共=72-45+1=28,剩=28-9=19。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "二(1)班有 25 名男同学,19 名女同学,后来男同学、女同学各增加了 3 名。现在男同学和女同学相差( )名。", "options": null}', '6', '现男=25+3=28,女=19+3=22,差=6 名。', 'paper', '[]', NULL, 0);
