INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "王大伯上午卖出 32 只公鸡,下午卖出 25 只公鸡和 18 只母鸡。这一天卖出的公鸡比母鸡多( )只。", "options": ["A. 39", "B. 25", "C. 75"]}', 'A', '公鸡=32+25=57,母鸡=18,多=57-18=39,选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "四位小伙伴比赛跳绳,请看图完成表格。小红跳 94 个,小华比小红少 18 个,小明比小华多 5 个,小海比小明少 19 个。求四人各跳多少个。", "options": null}', '小红 94、小华 76、小明 81、小海 62', '小华=94-18=76;小明=76+5=81;小海=81-19=62。', 'paper', '[]', '["/static/qimg/js_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "一批生梨,卖出 20 筐,还剩 23 筐。选合适的问题并解答:(1)这批生梨一共有多少筐?(2)卖出的生梨比剩下的少多少筐?", "options": null}', '(1)43 筐;(2)少 3 筐', '(1)20+23=43;(2)23-20=3。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "科技书有 45 本,______,故事书有多少本?选合适条件并解答:(1)故事书比科技书少 27 本;(2)故事书比科技书多 35 本。", "options": null}', '(1)18 本;(2)80 本', '(1)45-27=18;(2)45+35=80。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式。桃比苹果多38个, 梨比苹果少8个, 苹果26个。(1) 桃有多少个？", "options": null}', '26+38=64 (个)', '桃比苹果多38个, 用加法: 苹果26个 + 多出的38个 = 64个。', 'paper', '[]', '["/static/qimg/js_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式。桃比苹果多38个, 梨比苹果少8个, 苹果26个。(2) 梨有多少个？", "options": null}', '26-8=18 (个)', '梨比苹果少8个, 用减法: 苹果26个 - 少的8个 = 18个。', 'paper', '[]', '["/static/qimg/js_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "运动会。我们班有35人参加运动会, 每人只参加一项运动。已知参加跑步的有13人, 参加跳远的有5人。参加其他运动项目的有多少人？", "options": null}', '35-13-5=17 (人)', '总人数35人, 减去跑步13人, 再减去跳远5人, 剩17人参加其他项目。', 'paper', '[]', '["/static/qimg/js_p20.jpg"]', 0);
