INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "欢欢和小海在手工课上折纸鹤, 欢欢1小时能折8只, 欢欢1小时折的只数和小海2小时折的只数一样多, 小海1小时能折( )只。两人一起折2小时, 一共能折( )只纸鹤。", "options": null}', '小海1小时折4只; 两人2小时共折24只', '欢欢1小时=小海2小时=8只, 小海1小时=8÷2=4只。两人2小时: 欢欢2×8=16只+小海2×4=8只, 共24只。', 'paper', '[]', NULL, 0);
