INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "与 2×6 结果不相等的是( )。A. 2+6  B. 3×4  C. 6+6  D. 6×2", "options": null}', 'A', '2×6=12; A. 2+6=8 ≠12; B. 3×4=12; C. 6+6=12; D. 6×2=12。答案A。', 'paper', '[]', NULL, 0);
