INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "一套《昆虫记》有5本书。(1) 小丁、小亚、小明各买了一套, 他们一共有几本书？", "options": null}', '3×5=15 (本)', '3人各1套, 每套5本: 3×5=15本。', 'paper', '[]', NULL, 0);
