INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "一套《昆虫记》有5本书。(3) 书店的10套卖掉了4套, 卖掉了多少本？剩下多少本？", "options": null}', '卖掉: 4×5=20 (本); 剩下: 6×5=30 (本)', '卖掉4套: 4×5=20本; 剩10-4=6套: 6×5=30本。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小明每天写8个大字, 一周后还剩下6个大字没写, 小明一共要写几个大字？", "options": null}', '62 (个)', '一周=7天, 共写 8×7=56个; 还剩6个没写, 总共要写 56+6=62个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小白兔拔了8行萝卜, 每行6个, 送给小黑兔10个, 还剩多少个萝卜？", "options": null}', '8×6-10=38 (个)', '总萝卜 8×6=48个; 送走10个, 剩 48-10=38个。', 'paper', '[]', NULL, 0);
