INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "公园里的观光车每车坐9人, 填下表。2辆 ( )人, 5辆 45人, 6辆 ( )人, 7辆 63人, 8辆 ( )人, 9辆 81人。", "options": null}', '2辆18人, 6辆54人, 8辆72人', '每车9人, 所以 2×9=18人, 6×9=54人, 8×9=72人。', 'paper', '[]', '["/static/qimg/js_p35.jpg"]', 0);
