INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "选择题。(3) 4×□<32, □里最大填( )。 A. 8  B. 10  C. 7  D. 6", "options": null}', 'C. 7', '4×□<32, □<8, 最大整数填 7 (4×7=28<32, 4×8=32不小于32)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "先读一读下面这些词语, 再数一数, 一共有多少个字？词语: 打扫打扫、学习学习、乐和乐和、活动活动、练习练习、比试试试。", "options": null}', '6×4=24 (字)', '每个词语4个字, 6个词语: 6×4=24个字。', 'paper', '[]', '["/static/qimg/js_p35b.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "6块巧克力可以装一盒, 3盒可以装一箱, 9箱一共多少盒？", "options": null}', '9×3=27 (盒)', '每箱3盒, 9箱: 9×3=27盒。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "1只手有5根手指, 7个小朋友有多少根手指？", "options": null}', '7×5=35 (根)', '每人5根手指, 7人: 7×5=35根。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "有4盆花, 其中有3盆, 每盆开了6朵花, 还有1盆开了9朵花, 一共开了几朵花？", "options": null}', '3×6+9=27 (朵)', '3盆各6朵: 3×6=18朵; 加另1盆9朵: 18+9=27朵。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小朋友们一起庆祝春节。(1) 原本计划每个小朋友剪3个窗花, 9个小朋友剪完后发现还少2个窗花才够布置展示区, 那么小朋友们实际一共需要剪多少个窗花？", "options": null}', '9×3+2=29 (个)', '9人每人3个: 9×3=27个; 还少2个才够, 实际需要 27+2=29个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小朋友们一起庆祝春节。(2) 小朋友们邀请了一个舞龙表演方阵, 方阵有6行, 每行有9人。表演过程中临时有3人因伤退场, 那么此时这个方阵还有多少人在参加表演？", "options": null}', '6×9-3=51 (人)', '方阵原人数 6×9=54人; 3人退场: 54-3=51人。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "路边插了10面红旗, 每两面红旗之间有3面黄旗, 一共插了多少面黄旗？", "options": null}', '(10-1)×3=27 (面)', '10面红旗之间有 10-1=9 个间隔, 每间隔3面黄旗: 9×3=27面。', 'paper', '[]', '["/static/qimg/js_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "想一想, 填一填。△+△+△+△=12, ○+△+△=14, △=( ), ○=( ), △×○=( )。", "options": null}', '△=3, ○=8, △×○=24', '4个△=12, 所以 △=3; ○+3+3=14, ○=8; △×○=3×8=24。', 'paper', '[]', NULL, 0);
