INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "填空题。(5) 有5个盘子, 每个盘子里放6颗草莓, 一共需要多少颗草莓? 解决这个问题的数量关系式是( )。", "options": null}', '盘子数×每盘草莓数=总草莓数 (5×6=30)', '数量关系式: 盘子数×每盘草莓数=总草莓数, 即 5×6=30颗。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填空题。(6) 看图算一算, 列乘法算式求一共有多少个小方格。算式: (1) 图1: ( ); (2) 图2: ( )。", "options": null}', '图1: 3×5=15; 图2: 1+2+3+4=10', '图1是3行5列方格阵, 3×5=15; 图2是阶梯状累加, 1+2+3+4=10。', 'paper', '[]', '["/static/qimg/js_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填空题。(7) 三(3)班组织社会实践活动, 有50名学生要去坐船游览。每条船最多能坐7名学生, 7条船( )(填「够」或「不够」), 需要( )条船。", "options": null}', '不够, 8', '7条船最多坐 7×7=49人, 49<50, 不够; 50÷7=7余1, 需 7+1=8条船。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "选择题。(1) 2个8的和是多少? 错误的算式是( )。 A. 2×8=16  B. 2+8=10  C. 8+8=16", "options": null}', 'B. 2+8=10', '2个8的和是 8+8=16 或 2×8=16, 2+8=10 表示2和8相加, 不是2个8的和。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "选择题。(2) 2×2○2+2, ○里应填( )。 A. >  B. <  C. =", "options": null}', 'C. =', '2×2=4, 2+2=4, 4=4, 所以填 =。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "选择题。(3) 小丁有8袋橘子, ______, 一共有多少个橘子? 空格上应该填( )。 A. 小巧有6袋橘子  B. 每袋苹果有5个  C. 每袋橘子有9个  D. 小亚比小丁多3袋橘子", "options": null}', 'C. 每袋橘子有9个', '求橘子总数需要每袋个数: 8×9=72个, 选 C。', 'paper', '[]', NULL, 0);
