INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "看图列式计算。(2) 面包每个7元, 牛奶每盒5元, 3个面包和1盒牛奶一共多少元? □○□○□=□( )", "options": null}', '3×7+5=26(元)', '3个面包 3×7=21元, 加1盒牛奶 5元, 一共 21+5=26元。', 'paper', '[]', '["/static/qimg/js_p38c.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "小亚用彩纸折星星, 一张彩纸折4颗, 8张彩纸可以折几颗?", "options": null}', '8×4=32 (颗)', '每张4颗, 8张: 8×4=32颗。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "一束花有6朵, 小明买了3束, 小丁买了24朵, 谁买的花多? 多多少?", "options": null}', '小丁买的多, 多6朵', '小明: 3×6=18朵; 小丁: 24朵; 24-18=6朵, 小丁买的多, 多6朵。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "小海有70元, 每天用7元。(1) 一个星期后共用了多少元?", "options": null}', '7×7=49 (元)', '一周7天, 每天7元: 7×7=49元。', 'paper', '[]', NULL, 0);
