INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "李老师带同学们去公园划船, 男同学9人, 女同学10人, 一共有多少人去划船? 若只租一种船, 怎么租便宜? 一共要多少元? (大船: 限10人, 每条45元; 小船: 限4人, 每条20元)", "options": null}', '19人, 租2条大船最便宜, 共90元', '总人数 9+10=19人; 大船45元/10人, 小船20元/4人; 大船人均 4.5元, 小船人均 5元; 大船便宜; 2条大船坐20人够19人, 2×45=90元。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "图形各代表几? (1) ○×△=20, □×○=15, □×△=12, ☆×○=10; 求 ○=( ), △=( ), □=( ), ☆=( )。", "options": null}', '○=5, △=4, □=3, ☆=2', '□×△=12, □×○=15, 故○/△=15/12=5/4; ○×△=20=4×5, 所以○=5, △=4; □×5=15, □=3; ☆×5=10, ☆=2。', 'paper', '[]', NULL, 0);
