INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "选择题。(1) □×3=○×9 (不同图案表示不同数字), 比较□与○的大小, 结果○( )□。 A. >  B. <  C. =  D. 无法确定", "options": null}', 'B. <', '□×3=○×9, □=3○, □是○的3倍, □>○, 所以○<□。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "选择题。(2) 在 12, 42, 18, 27, 36, 45, 54 中, 既符合6的乘法口诀, 又符合9的乘法口诀的有( )个。 A. 2个  B. 3个  C. 4个  D. 5个", "options": null}', 'B. 3个', '6的倍数: 12, 42, 18, 36, 54; 9的倍数: 18, 27, 36, 45, 54; 都有: 18, 36, 54, 共3个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "看图列式计算。(1) 三角阵 (1+2+3+4+5+6=21), 列两个乘法算式。", "options": null}', '6×7÷2=21 (或 1+2+3+4+5+6=21)', '三角阵共 1+2+3+4+5+6=21 点, 可写 6×7÷2=21 或 3×7=21 (对称数)。', 'paper', '[]', '["/static/qimg/js_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "看图列式计算。(2) 4个图形 (3块、5块、4块、3块), □○□○□=□ 和 □○□○□=□", "options": null}', '3+5+4+3=15 (或 3×5=15)', '4个图形总块数 3+5+4+3=15; 也可 3×5=15。', 'paper', '[]', '["/static/qimg/js_p43b.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "根据条件先补上一个合适的问题, 再列式解答。(1) 神话中哪吒施展三头六臂, 每个手臂都拿着一件兵器。如果一件兵器能攻击6次, 问: 6只手一共能攻击多少次?", "options": null}', '6×6=36 (次)', '三头六臂=6只手, 6×6=36次。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "根据条件先补上一个合适的问题, 再列式解答。(2) 学校举办活动需要同学们排成方阵。方阵有9行, 每行有8名同学, 问: 一共有多少名同学?", "options": null}', '9×8=72 (名)', '9行×8名=72名同学。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "应用题。二年级学生进行大课间活动,跳绳的学生有7组,每组6名;踢球的学生有25名。问题(1): 跳绳的学生一共有多少名?", "options": null}', '7×6=42 (名)', '跳绳7组×每组6名=42名。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "应用题。二年级学生进行大课间活动,跳绳的学生有7组,每组6名;踢球的学生有25名。问题(2): 跳绳的学生比踢球的学生多多少名?", "options": null}', '42-25=17 (名)', '跳绳42名, 踢球25名, 差 42-25=17名。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "应用题。二(2)班教室有4排座位,每排有8个座位,其中有3个是空座位,二(2)班一共有多少人?", "options": null}', '4×8-3=29 (人)', '总座位 4×8=32, 实际人数 32-3=29人。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "应用题。鸟妈妈有5只鸟宝宝,每只鸟宝宝要吃4条虫子,鸟妈妈要吃7条虫子,它们一共吃多少条虫子?", "options": null}', '5×4+7=27 (条)', '5只鸟宝宝×每只4条=20条, 鸟妈妈7条, 合计 20+7=27条。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "思维拓展。盒子里有一些巧克力,多于10颗且不到50颗。如果7颗7颗地数,那么正好数完;如果5颗5颗地数,那么还剩2颗。这盒巧克力共有( )颗。", "options": null}', '42', '7的倍数(10-50): 14, 21, 28, 35, 42, 49; 其中 5的倍数余2: 42-2=40, 40÷5=8 ✓。', 'paper', '[]', NULL, 0);
