INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "欢欢在计算97减一个两位数时, 把这个两位数个位上的6看成了0, 算出来的结果是37, 正确的结果是( )", "options": null}', '31', '错读数: 97-37=60, 个位看成0所以是X0, 即60; 实际两位数=X6=66; 正确: 97-66=31', 'paper', '[]', '["/static/qimg/js_p54.jpg"]', 0);
