INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "下面这些数的十位被遮挡, ( )不可能是一个一位数与7的积. A.●2  B.●7  C.●3  D.●9", "options": null}', 'B', '一位数×7的积: 7,14,21,28,35,42,49,56,63; 个位为1,2,3,4,5,6,8,9均有, 但个位为7没有, 所以●7不可能', 'paper', '[]', '["/static/qimg/js_p54.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "小河一边种了10棵柳树, 每两棵柳树之间的距离是4米, 第1棵柳树到第10棵柳树的距离是( )米. A.30  B.27  C.36  D.24", "options": null}', 'C', '10棵树之间有9个间隔, 9×4=36米', 'paper', '[]', '["/static/qimg/js_p54.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "有12个数, 按照下面规律排列: 3,1,2,3,1,2,3,1,2,3,1,2, 这12个数的和是( ). A.30  B.27  C.33  D.24", "options": null}', 'D', '每组3,1,2循环, 12÷3=4组, 每组和=6, 4×6=24', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "有三个瓶子, 第二个瓶子里有24颗纸星星, 比第一个瓶子里少12颗, 比第三个瓶子里多8颗. 三个瓶子里一共有( )颗纸星星. A.98  B.76  C.86  D.82", "options": null}', 'B', '第一个=24+12=36, 第三个=24-8=16, 总=36+24+16=76颗', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式: 每行5朵花, 5行, 旁边还有1朵. □×□+□=□", "options": null}', '5×5+1=26', '5×5=25, 25+1=26朵花', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图: 红灯8个, 黄灯25个, 绿灯6个. 黄灯比绿灯多几个? 算式:___", "options": null}', '25-6=19', '黄灯25个比绿灯6个多: 25-6=19个', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "三个小动物发放宣传海报: 小猴13张, 小兔69张, 小猪14张. 请问谁发的最多, 谁发的最少? 发的最多与最少相差多少?", "options": null}', '小兔最多(69张), 小猴最少(13张), 相差56张', '69-13=56张', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "二(3)班的同学做了许多小红花, 每个盒子里放8朵, 放满了7盒, 还剩下13朵. 放在盒子里的小红花一共有多少朵?", "options": null}', '56朵', '8×7=56朵, 盒子里的有56朵(剩下的13朵不计算)', 'paper', '[]', '["/static/qimg/js_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "玩具价格: 直升机45元, 帆船38元, 翻斗车19元, 魔方?元. (1) 欢欢想买帆船和翻斗车, 她有50元钱, 够吗?", "options": null}', '不够', '38+19=57, 57>50, 不够', 'paper', '[]', '["/static/qimg/js_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "(2) 魔方比飞机(45元)便宜29元, 买两个魔方多少钱?", "options": null}', '32元', '魔方单价=45-29=16元, 两个=16×2=32元', 'paper', '[]', '["/static/qimg/js_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "(3) 六一儿童节, 玩具超市满50元立减6元, 买飞机(45元)和帆船(38元)一共需要多少钱?", "options": null}', '77元', '45+38=83, 满50减6: 83-6=77元', 'paper', '[]', '["/static/qimg/js_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "5. 小刚和小兰穿彩珠. 小刚穿了3种颜色, 每种颜色用6颗珠子; 小兰穿了2种颜色, 一种用了8颗珠子, 另一种用了6颗珠子. 他们各用了多少颗珠子?", "options": null}', '小刚18颗, 小兰14颗', '小刚: 3×6=18颗; 小兰: 8+6=14颗', 'paper', '[]', '["/static/qimg/js_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "思维拓展1. 小明在农场体验做木工活, 工人拿来一根木头让小明将其锯成8段备用. 已知每锯下一段需要4分钟, 且每次只能锯下一段. 小明将这根木头锯成8段一共需要多少分钟?", "options": null}', '28分钟', '8段需要锯7次, 7×4=28分钟', 'paper', '[]', '["/static/qimg/js_p56.jpg"]', 0);
