INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "概念1(4): ◇+□=17, □+△=22, 在○里填>或<: ◇○△", "options": null}', '<', '由◇=17-□, △=22-□, 得△-◇=5>0, 所以◇<△', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "概念1(5): 把7+7+7+7+5+2改写成乘法算式是( )", "options": null}', '5×7=35或7×5=35', '5+2=7, 共5个7, 5×7=35', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "概念1(6): 甲数是65, 比乙数少14, 乙数是多少? 算式是( )", "options": null}', '65+14=79', '乙数=甲数+差=65+14=79', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "概念1(7): 苹果和桃子的筐数一样多, 苹果运走76筐, 桃子运走58筐, 现在( )的筐数少, 少( )筐", "options": null}', '苹果, 18', '同样多, 运走多的剩少, 76>58所以苹果剩少, 76-58=18筐', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "2. 把乘法口诀补充完整(上排): 三七( )、八( )七十二、( )八二十四", "options": null}', '二十一、九、三', '三七二十一; 八九七十二; 三八二十四', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "2. 把乘法口诀补充完整(下排): 五九( )、四( )二十四、( )七四十二", "options": null}', '四十五、六、六', '五九四十五; 四六二十四; 六七四十二', 'paper', '[]', '["/static/qimg/js_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "把 4×5 改写成加法算式是（  ）", "options": ["A. 4+5", "B. 5+4", "C. 5+5+5+5"]}', 'C', '4×5 表示 5 个 4 相加，即 4+4+4+4+4=20。选项 C 为 5+5+5+5=20，与 4×5 相等；A、B 都只有 1 个加号，不是把 4×5 改写成加法算式。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "5×□<20，□里最大填（  ）", "options": ["A. 3", "B. 4", "C. 5"]}', 'A', '5×3=15<20 成立；5×4=20 不满足 <20。故 □ 最大填 3，选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "6+6+6+4 不可以改写成算式（  ）", "options": ["A. 6×4", "B. 6×3+4", "C. 4×6-2"]}', 'A', '6+6+6+4=22。B：6×3+4=18+4=22；C：4×6-2=24-2=22；A：6×4=24≠22。故不可以改写成 6×4。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "小华想把 1 元的硬币换成 1 角和 5 角的硬币，她共有（  ）种不同的换法。", "options": ["A. 2", "B. 3", "C. 4"]}', 'B', '1元=10角。枚举：(1) 2个5角+0个1角；(2) 1个5角+5个1角；(3) 0个5角+10个1角。共 3 种。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式计算：一段 4 米和一段 ? 米合起来是 44 米，求 ? 米。", "options": null}', '44-4=40（米）', '总长 44 米，已知一段 4 米，求另一段用减法：44-4=40（米）。', 'paper', '[]', '["/static/qimg/js_p059.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式计算：鸡有 32 只，鸭比鸡少 19 只，鸭有多少只？", "options": null}', '32-19=13（只）', '鸭比鸡少，求鸭用减法：32-19=13（只）。', 'paper', '[]', '["/static/qimg/js_p059.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小海买了一些玻璃珠，每 5 个装一袋，一共装了 3 袋，还剩 2 个，小海一共买了多少个玻璃珠？", "options": null}', '5×3+2=17（个）', '装 3 袋每袋 5 个共 15 个，再加剩余 2 个：5×3+2=17（个）。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "商店第一天卖出服装 51 套，第二天比第一天少卖 18 套，两天一共卖出多少套？", "options": null}', '51+(51-18)=84（套）', '第二天：51-18=33（套）；两天共：51+33=84（套）。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小轿车有 27 辆，面包车比小轿车少 15 辆，大客车比小轿车多 15 辆。面包车和大客车各有多少辆？", "options": null}', '面包车：27-15=12（辆）；大客车：27+15=42（辆）', '求少的用减法：27-15=12（辆）；求多的用加法：27+15=42（辆）。', 'paper', '[]', NULL, 0);
