INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "找规律填数：3、5、8、12、（  ）、（  ）、30。", "options": null}', '17, 23', '相邻差为 2、3、4、5、6、7，依次递增：12+5=17，17+6=23。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "在计算「25+3×4」时,先算（  ）法,再算（  ）法。", "options": null}', '乘,加', '先算乘 3×4=12,再算加 25+12=37。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "体育室有100个乒乓球,借出45个后,剩下的球比原来的少了（  ）个。", "options": null}', '45', '借出多少就少多少，少了 45 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "小华有18支铅笔,小海有30支铅笔,小海比小华多（  ）支铅笔,小海送给小华（  ）支铅笔后,两人的铅笔就同样多。", "options": null}', '12, 6', '30-18=12 支; 同样多需各 24 支,小海送 30-24=6 支。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "小巧用一些火柴棒搭了3颗星星（如图所示）,还剩下7根火柴棒。她一共用了几根火柴棒？（  ）×10+（  ）=（  ）(根)", "options": null}', '3×10+7=37', '3 颗星星每颗 10 根,共用 3×10=30 根,加上剩 7 根,一共 30+7=37 根。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem": "3个4也可以看成4个3相加。", "options": null}', '√', '3个4是 4+4+4=12,4个3是 3+3+3+3=12,两者结果相同,可以互相转化。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem": "小华买一个36元的书包,付3张10元、6张1元或者付一张10元、一张20元、一张5元、一张1元,都不需要找零钱。", "options": null}', '√', '第一种：3×10+6×1=36 元;第二种：10+20+5+1=36 元,两种方法都正好 36 元,不需要找零。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem": "学校足球队原来有36人,14人退出后,又补招了6人,足球队现在有28人。", "options": null}', '√', '36-14+6=22+6=28 人,与题目所述一致。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "小华有相同张数的10元和1元的纸币若干张,小华可能有（  ）元。", "options": ["A. 31", "B. 33", "C. 43"]}', 'B. 33', '设各有 n 张,总钱数 10n+n=11n,需是 11 的倍数;33=11×3 符合,故选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "下图中△的总数可以用算式（  ）来表示（5组完整4个△+1组2个△）。", "options": ["A. 5×4+2", "B. 4×5", "C. 4×4+2"]}', 'A. 5×4+2', '5 组各 4 个是 5×4=20 个,加上最后一组 2 个,共 5×4+2=22 个,选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "5+5+5+4 不可以写成算式（  ）。", "options": ["A. 5×4", "B. 3×5+4", "C. 4×5-1"]}', 'A. 5×4', '5+5+5+4=19;A 5×4=20 不等于 19;B 3×5+4=19;C 4×5-1=19,故选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "二(1)班庆元旦活动,老师买了5包彩带,每包8个,还买了25个气球和50个棒棒糖。可以解决的数学问题是（  ）。", "options": ["A. ①和④", "B. ①和③", "C. ②和③"]}', 'A. ①和④', '① 棒棒糖比彩带多多少:50-5×8=10,可解;② 缺条件;③ 没买苹果,不可解;④ 一共多少彩带:5×8=40,可解;选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "下面算式计算错误的原因是（  ）。（80-45+26=71,竖式 80-45 错得 45）", "options": ["A. 数位没有对齐", "B. 没有满十进一", "C. 没有减进位的 1"]}', 'C. 没有减进位的 1', '80-45 应为 35,竖式错算成 45,是因为个位 0-5 借位后十位没减借走的 1,选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "看图列式:一段 9 米,再加一段 ? 米,共长 ? 米（10棵树,等间隔）。", "options": null}', '9+1=10(米)', '10 棵树间有 10 段间隔,前 9 段 9 米,最后 1 段 1 米,共 9+1=10 米。', 'paper', '[]', '["/static/qimg/js_p062.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式:一共 62 人,前一段标 8 人,后面 ? 人。", "options": null}', '62-8=54(人)', '总人数 62,已知 8 人,剩余 62-8=54 人。', 'paper', '[]', '["/static/qimg/js_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "看图列式:二(2)班男生 32 人女生 16 人,二(3)班比二(2)班少 9 人,二(3)班共 ? 人。", "options": null}', '32+16-9=39(人)', '二(2)班 32+16=48 人,二(3)班比二(2)班少 9 人,即 48-9=39 人。', 'paper', '[]', '["/static/qimg/js_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "端午节时,张奶奶包了一些粽子,每6个系成一串,包了8串多4个,张奶奶一共包了多少个粽子？", "options": null}', '6×8+4=52(个)', '8 串是 6×8=48 个,再多 4 个,共 48+4=52 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小海买了1根跳绳和2只毽子,一共花了多少钱？（跳绳12元5角,毽子3元4角）", "options": null}', '12元5角+3元4角×2=19元3角', '1 根跳绳 12 元 5 角,2 只毽子 3 元 4 角×2=6 元 8 角,合计 12 元 5 角+6 元 8 角=19 元 3 角。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小明带20元钱买了3个网球,共用去多少元？还剩多少元？（网球每个5元）", "options": null}', '共用 3×5=15 元;还剩 20-15=5 元', '3 个网球 3×5=15 元;20-15=5 元。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "欢欢和乐乐读课外书,欢欢读了34页,比乐乐多读9页,两人一共读了多少页？", "options": null}', '34+(34-9)=59(页)', '乐乐读 34-9=25 页;两人共 34+25=59 页。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "同学们做操,每排站6人,______,一共有多少人？（先补充条件,再解答）", "options": null}', '补充条件示例:站了4排,6×4=24(人)', '补充条件不唯一,如''站了4排''则 6×4=24 人;''站了5排''则 6×5=30 人;学生可填不同条件,答案随条件变化。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "妈妈买来了1盒巧克力,分给9个小朋友,每人得到4粒,盒子里还剩4粒,这盒巧克力共有多少粒？", "options": null}', '4×9+4=40(粒)', '9 人每人 4 粒共 4×9=36 粒,加剩 4 粒,共 36+4=40 粒。', 'paper', '[]', NULL, 0);
