INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "先用个位上的6减8,不够减,从( )位退1作( ),个位要算( )-( )=( ),十位要算( )-( )=( ),结果是( )。", "options": null}', '十;10;16;8;8;4;1;3;28', '46-18:个位 6 不够减 8,从十位退 1 作 10,个位 16-8=8,十位 4-1=3,结果 28。', 'paper', '[]', '["/static/qimg/js_p66.jpg"]', 0);
