INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "李叔叔今天在聊天群里抢了26元的红包,昨天比今天少抢了16元,李叔叔两天一共抢了( )的红包。", "options": null}', 'C 36元', '昨天 26-16=10 元,两天 26+10=36 元,选 C。', 'paper', '[]', NULL, 0);
