INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "下列说法中, ( )是错误的。A.任何数加上0都等于原来的数 B.任何数乘1都等于原来的数 C.任何数减0都等于原来的数 D.任何数乘0都等于原来的数", "options": null}', 'D', '任何数乘0都得0, 而不是原来的数, 故D错误。', 'paper', '[]', NULL, 0);
