INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "看图填空: □×□+□=□ (图中5个笑脸, 2个一组再加1个)。", "options": null}', '2×2+1=5', '2个一组, 共有2组, 再加1个, 即2×2+1=5。', 'paper', '[]', '["/static/qimg/js_p70.jpg"]', 0);
