INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "找规律填数: 36, 42, 48, ( ), ( )。", "options": null}', '54, 60', '相邻两数差6, 48+6=54, 54+6=60。', 'paper', '[]', NULL, 0);
