INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "看动物园方位图填空(北朝上):①游乐场在体育馆的( )面;②海洋馆的南面是( );③海洋馆的( )面是电影院;④聪聪从游乐场经海洋馆去电影院,先往( )走,再往( )走"}', '①西 ②游乐场 ③东 ④北,东', '看图:北朝上,海洋馆在左上(西北),电影院在右上(东北),游乐场在左下(西南),体育馆在右下(东南)。①游乐场(左下)在体育馆(右下)的西面(同水平,左=西);②海洋馆(左上)正下方=游乐场(左下);③海洋馆(左)的东面=电影院(右);④从游乐场(左下)→先往北(到海洋馆左上)→再往东(到电影院右上)', 'paper', '[方位]', '["/static/qimg/js_p102.jpg"]', 0);
