INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "游乐园满 50 减 10,乐乐玩 1 次小火车和 1 次碰碰车,实际付多少元"}', '48 元', '小火车 23+碰碰车 35=58 元,满 50 减 10,实际 58-10=48 元', 'paper', '[促销]', '["/static/qimg/js_p104.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "相邻两盏路灯相距 7 米,第 1 盏和第 8 盏之间相距多少米"}', '49 米', '8 盏路灯之间有 8-1=7 段间隔,7×7=49 米(注意:7 段而非 8 段)', 'paper', '[间隔]', '["/static/qimg/js_p104.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "图中共34支铅笔,下面不正确的算式是( )。", "options": ["A. 3×10+4", "B. 4×10-4", "C. 10+10+10+4", "D. 4×10-6"]}', 'B', '3×10+4=34 ✓, 4×10-4=36 ✗, 10+10+10+4=34 ✓, 4×10-6=34 ✓, 只有 B 不等于 34, 选 B。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "乐乐有12元钱,她用这些钱只买了一种食物,且正好花完。她买的不可能是( )。", "options": ["A. 4元", "B. 5元", "C. 6元", "D. 3元"]}', 'B', '12÷4=3(整除)✓, 12÷5 不能整除 ✗, 12÷6=2(整除)✓, 12÷3=4(整除)✓, 选 B。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "小海从一棵树到相邻的另一棵树要走5步,每两棵树之间的间隔相等(不考虑树的宽度),照这样计算,他从第一棵树走到第10棵树,一共走了( )。", "options": ["A. 55步", "B. 50步", "C. 45步", "D. 40步"]}', 'C', '10 棵树之间有 9 个间隔, 9×5=45 步, 选 C。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "一只蚂蚁从起点向西爬2格,又向东爬4格,又向西爬6格,又向东爬2格,最后停下来。这只蚂蚁最后停在( )。", "options": ["A. 起点的西面,距离起点2格处", "B. 起点的东面,距离起点2格处", "C. 起点处", "D. 起点的北面,距离起点2格处"]}', 'A', '净位移 = -2(西)+4(东)-6(西)+2(东) = -2(西2格), 蚂蚁最后停在起点西面2格, 选 A。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式: 足球有32个, 篮球比足球多15个, 篮球有多少个?"}', '32+15=47(个)', '求比一个数多几的数用加法: 32+15=47(个)。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "看图列式: 4堆方块, 大小递减(每堆比前一堆少1块, 最高堆4块, 最矮1块), 一共有多少个?"}', '4+3+2+1=10(个)(图示估读)', '4 堆依次为 4、3、2、1 块, 共 4+3+2+1=10(个)。图示估读,以实际图形为准。', 'paper', '[]', '["/static/qimg/js_p95.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "小华站在操场中间,他的北面是教学楼,南面是办公楼,东面是图书馆,西面是体育馆,请画出简单布局图,并说明体育馆在小华的哪一方?"}', '体育馆在小华的西面', '以北为上、东为右、西为左、南为下, 体育馆在操场(小华位置)西面, 布局: 上北教学楼、下南办公楼、左西体育馆、右东图书馆。', 'paper', '[]', '["/static/qimg/js_p96.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "小明看了一个星期的书,每天看8页,还有20页没看完,这本书一共多少页?"}', '8×7+20=76(页)', '一个星期 7 天, 看了 8×7=56 页, 加上没看的 20 页, 共 56+20=76 页。', 'paper', '[]', '["/static/qimg/js_p96.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "欢乐购物: 玩具小熊4元,玩具自行车6元,玩具飞机?元。买4只玩具小熊的钱,可以买1架玩具飞机,1架玩具飞机多少元?"}', '4×4=16(元)', '4 只小熊 4×4=16 元, 1 架飞机价 = 4 只小熊的钱 = 16 元。', 'paper', '[]', '["/static/qimg/js_p96.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "王老师要买7辆玩具自行车作为奖品,带50元够吗?"}', '7×6=42(元), 42<50, 够', '7 辆自行车 7×6=42 元, 50-42=8 元, 42<50, 够。', 'paper', '[]', '["/static/qimg/js_p96.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "先选择合适的条件,再列式计算。条件:①每班有5人参加拔河比赛 ②拍球每组有3人 ③每条跑道有4人参加接力跑。 ____,有4条跑道,一共有多少人参加接力跑?"}', '选 ③每条跑道有4人参加接力跑, 算式: 4×4=16(人)', '接力跑每条跑道 4 人, 共 4 条, 4×4=16 人。', 'paper', '[]', '["/static/qimg/js_p96.jpg"]', 0);
