INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "最小的三位数比最大的两位数大几? 列式计算。"}', '100-99=1', '最小的三位数是100, 最大的两位数是99, 差为 100-99=1。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "10个8的和比2个8的和多多少? 列式计算。"}', '10×8-2×8=64 (或 8×(10-2)=8×8=64)', '10个8的和 10×8=80, 2个8的和 2×8=16, 差为 80-16=64; 或用乘法分配律 (10-2)×8=64。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "把口诀补充完整: ( )六二十四; 5×8=40 读作 ( )。"}', '四;五八四十(或八五四十)', '4×6=24, 口诀"四六二十四"; 5×8=40, 口诀"五八四十"。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "零钱包里有90元, 妈妈先拿出50元, 后来又放进26元, 现在零钱包里有多少元?"}', '66元', '90-50+26=66(元)。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "数字谜(两图): 在○里填数,使每条线上三个数的和都是80。(图示已知数24,19,26,18)"}', '图示估读', '两个 3×3 数字谜, 已知四数和=87, 每条线=80, 需根据具体图形位置推算(原图示估读, 具体解以图形结构为准)。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "看图(布局: 邮局/市政府/第一中学, 华联超市/世纪广场/实验小学, 新华书店/建设银行/教育局): 市政府在世纪广场的( )面, 在第一中学的( )面。"}', '北;西', '市政府在世纪广场的北面(世纪广场正上方), 在第一中学的西面(第一中学在市政府右侧)。', 'paper', '[]', '["/static/qimg/js_p98.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "按规律填数: 3, 6, ( ), 12, ( ), ( ), 21。"}', '9; 15; 18', '公差为3的等差数列: 3,6,9,12,15,18,21, 故三个空依次填 9、15、18。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "一件上衣和一条裤子可以配成一套,现有上衣29件和47件,裤子52条,要使这些衣服全部配套,还需要( )条裤子。", "options": ["A. 23", "B. 24", "C. 25"]}', 'B', '上衣共 29+47=76 件, 裤子 52 条, 76-52=24 条, 选 B。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "5+5+5+4 不可以改写成算式( )。", "options": ["A. 5×4", "B. 5×3+4", "C. 4×5-1"]}', 'A', '5+5+5+4=19, B 5×3+4=19 ✓, C 4×5-1=19 ✓, A 5×4=20 ✗ 不能改写, 选 A。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "填写正确的单位: 放学后,我用 8( )买了一本厚 5 毫米的笔记本,店员找零 5( )。", "options": ["A. 元", "B. 角", "C. 分"]}', 'AB', '8 元买笔记本合理, 5 角找零合理: 8元-7.5元(笔记本)=0.5元=5角, 答案: A、B。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "看图列式计算: 图为 4 盘完整(每盘 4 个方块) + 1 盘 2 个方块。"}', '4×4+2=18; 5×4-2=18', '4 盘完整每盘 4 个共 4×4=16, 加上散开 2 个共 18 个: 4×4+2=18; 或看作 5 盘 4 个缺 2 个: 5×4-2=18。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "人民币按制作材料分类,可以分为( )和( )。"}', '纸币;硬币', '人民币按材料分两类: 纸币(纸质) 和 硬币(金属)。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "人民币按面额分类,可以分为( )、( )和( )。"}', '元;角;分', '人民币按面额单位分三类: 元、角、分(1元=10角, 1角=10分)。', 'paper', '[]', '["/static/qimg/js_p99.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "请按面额对人民币进行分类(图中为1元/5角/1分硬币/纸币等)。"}', '元;角;分', '1元纸币/硬币归"元"类, 5角硬币归"角"类, 1分硬币归"分"类, 3个椭圆圈分别归类元/角/分。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "体育用品商店: 皮球8元, 毽子5元, 羽毛球3元, 网球9元。买 3 个羽毛球的价钱和谁的价钱同样多?"}', '3×3=9元, 和网球同样多', '3个羽毛球 3×3=9 元, 网球单价 9 元, 同样多。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "4 个皮球和 6 个网球一共多少钱?"}', '4×8+6×9=32+54=86(元)', '4 个皮球 4×8=32 元, 6 个网球 6×9=54 元, 共 32+54=86 元。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "带 50 元钱买 9 个毽子够吗?"}', '9×5=45元, 45<50, 够', '9个毽子 9×5=45 元, 50-45=5 元, 45<50, 够。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "每盒装 6 块饼干, 小巧有 30 块, 小丁有这样的 4 盒, 谁的饼干多? 多多少?"}', '小巧多, 多 6 块', '小巧 30 块, 小丁 4×6=24 块, 30-24=6 块, 小巧多 6 块。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "按要求画一画,画出各图形最终位置(图为 6×5 网格,北向上): (1) △ 先向东移 3 格, 再向南移 1 格; (2) 在 □ 南边第 2 格画 □; (3) ○ 先向南移 3 格, 再向西移 4 格, 最后向北移 2 格。"}', '图示估读', '以图示网格坐标为准: (1) △ 最终位置(南移后); (2) □ 南边第2格; (3) ○ 最终位置。具体坐标图示估读。', 'paper', '[]', '["/static/qimg/js_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "找规律,画一画。第4个圆里应画哪些图形?", "options": null}', '△上、■右、◇下、○左', '规律:4个图形(■○△◇)按顺时针方向,每个图形在4个位置(上/右/下/左)依次轮换90度。■轨迹:上(圆1)→下(圆2)→左(圆3)→右(圆4);○轨迹:右(圆1)→上(圆2)→下(圆3)→左(圆4);△轨迹:左(圆1)→左(圆2)→右(圆3)→上(圆4);◇轨迹:下(圆1)→右(圆2)→上(圆3)→下(圆4)。故第4个圆:上△、右■、下◇、左○。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "填表:应付8元、实付50元,找回多少元?", "options": null}', '42', '找回 = 实付 - 应付 = 50 - 8 = 42(元)。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填表:应付9元、实付7元5角,还差多少元多少角?", "options": null}', '1元5角', '还差 = 应付 - 实付 = 9元 - 7元5角 = 1元5角(5角 = 0.5元,9 - 7.5 = 1.5元 = 1元5角)。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填表:应付4元9角、实付10元,找回多少元多少角?", "options": null}', '5元1角', '找回 = 10元 - 4元9角 = 5元1角(10元 = 9元10角,9元10角 - 4元9角 = 5元1角)。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "看图,邮局在学校的( )面,超市在学校的( )面,书店在学校的( )面,公园在学校的( )面。", "options": null}', '西;北;东;南', '方位图:邮局在学校的左边(西面),超市在学校上方(北面),书店在学校的右边(东面),公园在学校下方(南面)。地图惯例:上北下南,左西右东。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "按要求把图形分类(A-H共8个):①按形状分,( )一组,( )一组。", "options": null}', '长方形(A、C、D、H);圆(B、E、F、G)', '①按形状分:长方形4个(A、C、D、H),圆形4个(B、E、F、G)。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "按要求把图形分类(A-H共8个):②按星星数量分,( )一组(4星),( )一组(3星)。", "options": null}', 'A、C、F、G;B、D、E、H', '②按星星数量分:4颗星(A、C、F、G)4个,3颗星(B、D、E、H)4个。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "按要求把图形分类(A-H共8个):③先按形状分,再按星星数量分,有( )个长方形里有4颗星,( )个长方形里有3颗星,( )个圆里有4颗星,( )个圆里有3颗星。", "options": null}', '2;2;2;2', '③先按形状分,再按星星数分:长方形里有4颗星(A、C)2个,长方形里有3颗星(D、H)2个,圆里有4颗星(F、G)2个,圆里有3颗星(B、E)2个。', 'paper', '[]', '["/static/qimg/js_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "选一个3×3方格,把1~9这9个数字填入方格中,使每行、每列、每条对角线上的3个数字之和都是15。", "options": null}', '图示估读', '标准3×3幻方(洛书)解:2 7 6 / 9 5 1 / 4 3 8(横、竖、斜和均为15)。3个方格任选其一填入即可,本题有8种旋转/镜像解,图示估读。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem": "判断:3个6相加的和,写成加法算式是3+3+3+3+3+3。", "options": null}', '错', '3个6相加表示6+6+6,3是数量(3个6)而非加数。3+3+3+3+3+3表示6个3相加。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 2, '{"stem": "判断:计算4×9和6×6,都用『四九三十六』这句口诀。", "options": null}', '错', '4×9用『四九三十六』,6×6用『六六三十六』。两句口诀不同,本题说『都用』错误。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 2, '{"stem": "判断:小亚带2个同学去看戏,票价每人4元,一共要花8元钱买票。", "options": null}', '错', '小亚+2个同学=3人,3×4=12(元),不是8元。8元是按2人×4元算的,人数算错。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem": "判断:地图通常是按照上北、下南、左西、右东绘制的。", "options": null}', '对', '地图绘制惯例:上北下南,左西右东。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 2, '{"stem": "判断:分类的标准不同,分类的各项相加的和也不同。", "options": null}', '对', '不同分类标准会产生不同分组,同一组数据按不同标准分类后,各项之和等于总数,和相同。但若按某一标准分类各项之和指的是每组内部求和再相加,因分组不同,每组内容不同,各项求和结果也不同。本题判对。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 2, '{"stem": "判断:李老师带16名女生和16名男生去游船,每艘船可以坐4人,租8艘船就够了。", "options": null}', '对', '16+16=32人,32÷4=8(艘),刚好坐满,所以租8艘船就够了。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "小丁在正方形花坛四周插彩旗,每一边插5面彩旗,小丁最少插( )面彩旗。(画一画解决问题)", "options": null}', '16', '画一画:正方形4个角,每个角的彩旗被两条边共享,若每边5面则角上重复计算1次。最少 = 4×5 - 4 = 16(面)(4个角各少算1面)。', 'paper', '[]', '["/static/qimg/js_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "最大的两位数与最大的一位数相差( )。A.9  B.10  C.90  D.81", "options": null}', 'C', '最大两位数是99,最大一位数是9,99-9=90,选C。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 1, '{"stem": "妈妈把一些饼干分给小红和其他3位同学,每人5块,一共有( )块饼干。A.24  B.20  C.15  D.16", "options": null}', 'B', '小红+其他3位=4人,4×5=20(块),选B。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "小红做减法时,把减数26错写成了62,结果得到的差是13,正确的差是( )。A.48  B.49  C.39  D.38", "options": null}', 'B', '被减数 = 错写的差 + 错写减数 = 13 + 62 = 75;正确差 = 75 - 26 = 49,选B。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "1只狗5分钟吃1块肉,10只狗用同样的速度吃10块肉需要( )分钟。A.5  B.1  C.10  D.50", "options": null}', 'A', '1只狗5分钟吃1块肉,即每只狗吃1块肉需5分钟。10只狗同时各吃1块肉,还是5分钟吃完。选A。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "过年挂灯笼是中国的传统习俗。某社区安装的圆形灯笼比方形灯笼多35个,兔子灯笼比方形灯笼多37个。( )灯笼最多。A.圆形  B.方形  C.兔子  D.不确定", "options": null}', 'C', '设方形灯笼为X,圆=X+35,兔=X+37,兔子比圆形还多2个,故兔子最多。选C。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "苗苗今年14岁,妈妈今年41岁,当苗苗24岁时,妈妈( )岁。A.51  B.41  C.37  D.38", "options": null}', 'A', '24-14=10(年后),妈妈41+10=51(岁),选A。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "游乐园里上午9时有游客63人,中午12时有12人离园,有8人进园。这时游乐园里的游客比9时( )。A.减少4人  B.增加4人  C.减少8人  D.增加8人", "options": null}', 'A', '63-12+8=59(人),59-63=-4,即比9时减少4人,选A。', 'paper', '[]', '["/static/qimg/js_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "象形文字是最早的文字，现在的很多汉字都是由象形字演变而来的。你能学着老师的样子，给它们配对吗？", "options": null}', '云朵—云；月牙—月；水滴—水；树—木；山峰—山；太阳—日（或人）', '根据图片与心形汉字配对：云朵配云，月牙配月，水滴配水，树配木，山峰配山，太阳配日。', 'paper', '[]', '["/static/qimg/mz_yw_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "汉字都是方方正正的，汉字要写得端 正 才会美 观。老师要请出三位小帮手。第一个小帮手：田字格。第二个小帮手：笔画。第三个小帮手：笔顺。", "options": null}', '端 正 美 观', '填空：汉字要写得端正、才会美观。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "写出下列笔画：撇（ ）、横折（ ）、弯钩（ ）、捺（ ）、点（ ）、竖弯钩（ ）。", "options": null}', '撇(丿)、横折(𠃍)、弯钩(㇂)、捺(㇏)、点(丶)、竖弯钩(乚)', '常用基础笔画名称与符号：撇、横折、弯钩、捺、点、竖弯钩。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "现在请看图片，并借助田字格这个帮手，端 正 地写出相应的字。（图中四个田字格：太阳、水、石头、手）", "options": null}', '日；水；石；手', '看图写字：在田字格里端正地写出「日」（太阳）、「水」（水滴）、「石」（石头）、「手」（手）。', 'paper', '[]', '["/static/qimg/mz_yw_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "现在请看图片，并借助田字格这个帮手，端 正 地写出相应的字。（图中四个田字格：耳朵、树、眼睛、火苗）", "options": null}', '耳；木（或树）；目；火', '看图写字：在田字格里端正地写出「耳」（耳朵）、「木」（树）、「目」（眼睛）、「火」（火苗）。', 'paper', '[]', '["/static/qimg/mz_yw_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "每个字的笔画书写是有先后顺序的，这就叫「笔顺」。请你写出下面各字的笔顺，再填空。", "options": null}', '见下方三小题', '笔顺是汉字笔画的书写顺序规则。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "写出下面各字的笔顺，再填空：（1）上：____ 第一笔是____。", "options": null}', '上：竖、横；第一笔是「竖」。', '「上」字共3画，笔顺：竖、横横。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "写出下面各字的笔顺，再填空：（2）火：____ 第一笔是____。", "options": null}', '火：点、撇、撇、捺；第一笔是「点」。', '「火」字共4画，笔顺：点、撇、撇、捺。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "写出下面各字的笔顺，再填空：（3）目：____ 共____笔。", "options": null}', '目：竖、横折、横、横、横；共5笔。', '「目」字共5画，笔顺：竖、横折、横、横、横。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "我会看图连一连。读书、写字（看图：男孩读书、女孩写字）。", "options": null}', '读书—男孩；写字—女孩', '看图将「读书」与男孩图相连，「写字」与女孩图相连。', 'paper', '[]', '["/static/qimg/mz_yw_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "我会说「反义词」。上（ ）、天（ ）、水（ ）、绿（ ）、手（ ）、站（ ）、日（ ）。", "options": null}', '上（反：下）、天（反：地）、水（反：火）、绿（反：红）、手（反：足）、站（反：坐）、日（反：月）', '常用反义词：上下、天地、水火、绿红、手足、站坐、日月。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "我会数字 汉字配对。1（ ）、3（ ）、5（ ）、4（ ）、2（ ）、8（ ）、7（ ）、9（ ）、6（ ）、10（ ）。", "options": null}', '1（一）、3（三）、5（五）、4（四）、2（二）、8（八）、7（七）、9（九）、6（六）、10（十）', '数字与汉字一一对应。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "加一笔：（1）口→（ ），（2）日→（ ），（3）二→（ ），（4）一→（ ）。", "options": null}', '（1）日；（2）目/旦/白；（3）三或十；（4）二或十', '加一笔变新字：口→日；日→目/旦/白；二→三或十；一→二或十。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "加两笔：口→（ ）、（ ）。", "options": null}', '日/田/目/回/古/句（任选两个）', '加两笔变新字：口可加两笔变成日、田、目、回、古、句等。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "减一笔：（1）白→（ ），（2）天→（ ）。", "options": null}', '（1）日/百/自；（2）大/夫', '减一笔变新字：白减一笔可成日/百/自；天减一笔可成大/夫。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "我能读一读，再给自己评星。天地人；你我他；一二三四五；金木水火土；天地分上下；日月照今古。", "options": null}', '天地人；你我他；一二三四五；金木水火土；天地分上下；日月照今古', '部编一上《天地人》《金木水火土》课文朗读并自我评星。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读下面的古诗。咏鹅（骆宾王）：鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。", "options": null}', '鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。', '唐·骆宾王《咏鹅》：鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读下面的古诗。悯农（其二）（李绅）：锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。", "options": null}', '锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。', '唐·李绅《悯农（其二）》：锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 2, '{"stem": "我会说：我看到了____（谁），____（在哪里），____（干什么）。", "options": null}', '示例：小白兔，在草地上，吃萝卜。（看图写话）', '用「我看到了…（谁）…（在哪里）…（干什么）」的句式看图说话。', 'paper', '[]', '["/static/qimg/mz_yw_p4.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读下面的儿歌，回答问题。云像小船，像小娃娃…天上云，层层，像小船，像羊群，像小鼓，像小娃娃，坐着凳儿在谈心。（选自《小小的船》）", "options": null}', '天上云，层层，像小船，像羊群，像小鼓，像小娃娃，坐着凳儿在谈心。', '部编一上《小小的船》课后儿歌：天上云，层层，像小船，像羊群，像小鼓，像小娃娃，坐着凳儿在谈心。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 2, '{"stem": "我会说：云像____、____、____，又像____。", "options": null}', '示例：云像棉花、像绵羊、又像小白兔。', '仿照《小小的船》用「像…」的句式描述天上的云。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 2, '{"stem": "我觉得天上的云有时候还像____。", "options": null}', '示例：天上的云有时候还像棉花糖、像大象、像飞机。', '展开想象：天上的云还像什么？写出自己的联想。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "小朋友们，我们已经学会了一些本领。现在我们要拉起手来比一比汉字闯关吧！看看你能闯过几关。（主题引导）", "options": null}', '继续完成下面各关题目。', '第一单元测试卷（名校二）主题引导语。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "我能给认识的字所在的花朵涂上漂亮的颜色。（图：6 朵花，里面分别是地/王/址/上/运/谷等会认字）", "options": null}', '把认识的字所在的花朵涂上颜色。', '部编一上第一单元会认字涂色练习，无标准答案。', 'paper', '[]', '["/static/qimg/mz_yw_p5.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 1, '{"stem": "请在同一行的其他字不属于同一类的字上画「○」。（1）日 月 天 水", "options": null}', '「水」与其他不同类。', '日/月/天是天空相关，水不属于。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 1, '{"stem": "请在同一行的其他字不属于同一类的字上画「○」。（2）是 他 你 我", "options": null}', '「是」不是人称代词。', '他/你/我是人称代词，「是」是判断词。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 1, '{"stem": "请在同一行的其他字不属于同一类的字上画「○」。（3）口 平 火 目", "options": null}', '「平」不属于同类型。', '口/火/目都是独体字，「平」形声字。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 1, '{"stem": "请在同一行的其他字不属于同一类的字上画「○」。（4）四 禾 木 田", "options": null}', '「禾」不属于同类型。', '四/木/田是基础字形，禾为庄稼类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "认一认，连一连。左边 7 个象形字图（太阳/月亮/水滴/火苗/田字格/方口/禾苗/鱼苗），右边 7 个字（月/日/口/火/平/禾/目）。", "options": null}', '太阳—日；月牙—月；水滴—平；火苗—火；田—目或田（无田字，连口或目）；方口—口；禾苗—禾；鱼—目。', '看图把象形字与对应的现代汉字相连。具体配对以教材为准。', 'paper', '[]', '["/static/qimg/mz_yw_p5.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "我能连字组词。上面一排：天/上/手/大/山；下面一排：足/地/下/川/小。", "options": null}', '天上；手—大手；山—大山；足—足下；地下；下川—川下；小—小川。', '把上下两排字连成词语或短语。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "选出正确的演变，并把它圈出来。（1）下面张开口，两横在里头。（月/日/目 选一个）", "options": ["月", "日", "目"]}', '目', '「目」字下面像张开的口（口），中间有两横。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "选出正确的演变，并把它圈出来。（2）地上两个人。（你/他/坐 选一个）", "options": ["你", "他", "坐"]}', '坐', '「坐」字下部像两个人坐在地面上。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "看图选字，填入句子中（填编号）。①九 ②三 ③十 ④天 ⑤四。", "options": ["①九", "②三", "③十", "④天", "⑤四"]}', '见下面各小题答案。', '供选字：①九 ②三 ③十 ④天 ⑤四。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看图选字填句：（1）春___到了，池塘里有___只鸭子，___片荷叶。（①九 ②三 ③十 ④天 ⑤四）", "options": null}', '春②（三）到了，池塘里有②（三）只鸭子，③（十）片荷叶。', '春天到了，池塘里有三只鸭子，十片荷叶。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看图选字填句：（2）___月___日是教师节。（①九 ②三 ③十 ④天 ⑤四）", "options": null}', '①（九）月 ③（十）日是教师节。', '教师节是每年的 9 月 10 日。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "拼音是我们学习语文的好帮手。小朋友，现在我们来到了拼音王国！国王说：小朋友们，你们好！我是拼音王国的国王。请跟我一起去做一些拼音游戏吧！（主题引导）", "options": null}', '继续完成下面各游戏。', '第二单元测试卷（名校一）主题引导。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "它叫「四线三格」。拼音字母就住在四线三格里。四线三格分上格/中格/下格，由四条线划分。", "options": null}', '上格在第一线和第二线之间；中格在第二线和第三线之间；下格在第三线和第四线之间。', '四线三格：上格、中格、下格，分别由四条线划分。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "请看图，在「拼音的家」中写出对应的单韵母。（图：鹅、阿姨、鹅、乌龟、衬衣、小鱼）", "options": null}', '鹅—é（e）；阿姨—ā（a）；鹅—é（e）；乌龟—ū（u）；衬衣—ī（i）；小鱼—ǖ（ü）。', '看图识单韵母：a/o/e/i/u/ü。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看图片，把四线三格中的音节补充完整。（图：梨、兔、马）", "options": null}', 'l í；t ù；m ǎ。', '看图补全音节：梨(lí)、兔(tù)、马(mǎ)。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连一连。下方字母：a e b ü l m f o t。下方分类：声母/单韵母。", "options": null}', '声母：b/l/m/f/t；单韵母：a/e/ü/o。', '把字母连到「声母/单韵母」对应的两个房子。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "按顺序写一写。第一行火车上有字母 a o e i u ü；第二行火车上有字母 b p m f d n。", "options": null}', 'a-o-e-i-u-ü；b-p-m-f-d-n。', '照样子按顺序在四线三格中写一写。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "照样子，给音节词分类。① dà mǐ(大米) ② là bǐ(蜡笔) ③ é(鹅) ④ mǎ(马)。动物：___；文具：___；食物：___。", "options": null}', '动物：③（é 鹅）、④（mǎ 马）；文具：②（là bǐ 蜡笔）；食物：①（dà mǐ 大米）。', '按物品类别分类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "读一读，连一连。5 个音节：pò nà là fù dù；下方 5 幅图（小朋友做不同动作）。", "options": null}', 'pò—破（破坏图）；nà—那（指图）；là—辣（辣味图）；fù—父（父亲图）；dù—肚（肚皮图）。', '游戏三：找朋友——看图认读音节并连线。', 'paper', '[]', '["/static/qimg/mz_yw_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "读读词语，读读拼音，再和图片连一连。3 行错位配对：第 1 行「爸爸（汉字）+ 男士头像图 + má lù（拼音）」；第 2 行「妈妈 + 一桌人吃饭图 + bà ba」；第 3 行「马路 + 男士头像图 + mā ma」。", "options": null}', '爸爸—bà ba；妈妈—mā ma；马路—má lù（注：马路标准拼音 mǎ lù，图中印成二声 má lù，按图记录）。', '汉字、拼音、图片三者打乱顺序后正确配对。注意拼音声调按图所示。', 'paper', '[]', '["/static/qimg/mz_yw_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "读一读，连一连。上面 7 个字：马、七、目、足、地、路、他。中间 3 个篮子（图示 3 个字：日、月、目）。下面 4 个字谜：远看山有色、人来鸟不惊、春去花还在、近听水无声。", "options": null}', '3 篮子看图认字：日、月、目。4 字谜答案：远看山有色—色；春去花还在—草（春去日剩草头）；近听水无声—雪；人来鸟不惊—人。', '看图认字（日/月/目）+ 字谜（4 个，字谜答案不在 7 字中，是独立字谜练习）。', 'paper', '[]', '["/static/qimg/mz_yw_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "游戏四·实践活动 1：在你的拼音本上正确填写信息。拼音本：学校：___；班级：___；姓名：___。", "options": null}', '学校：第九小学；班级：一年级（4）班；姓名：王小安。', '在拼音本上填写学校、班级、姓名信息。', 'paper', '[]', '["/static/qimg/mz_yw_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "游戏四·实践活动 2：请你照样子做一下自我介绍，请爸爸妈妈打分。示范：我叫王小明，今年 7 岁，在上海市虹星小学读一年级。我喜欢看动画片和吃巧克力。我最爱的人是爸爸和妈妈。填写：我叫___，今年___岁，在___读一年级。我喜欢___。我最爱的人是___。", "options": null}', '我叫___，今年___岁，在___读一年级。我喜欢___。我最爱的人是___。', '照样子做自我介绍：姓名+年龄+学校+爱好+最爱的人。', 'paper', '[]', '["/static/qimg/mz_yw_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "游戏四·实践活动评价标准：声音响亮☆☆☆；按句型说☆☆☆；表达流畅☆☆☆。", "options": null}', '声音响亮；按句型说；表达流畅。', '评价标准：声音响亮、按句型说、表达流畅。', 'paper', '[]', '["/static/qimg/mz_yw_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "小朋友们，我们已经学了一个单元的拼音啦！现在我们要拉起手来拼音闯关啦！看看你能闯过几关。（第二单元·名校二主题引导）", "options": null}', '继续完成下面各关题目。', '第二单元测试卷（名校二）主题引导语。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "给声母小花涂上你喜欢的颜色。6 朵小花，每朵花中心 1 个声母：o、o、i、i、u、ü。", "options": null}', '为 6 朵声母小花涂上颜色。', '部编一上第二单元声母涂色练习，6 朵花含 6 个声母（2 o、2 i、1 u、1 ü）。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "请你读一读，把认识的字圈出来。拼音本：学校：第九小学；班级：一年级（4）班；姓名：王小安。", "options": null}', '把认识的字圈出来。', '读一读拼音本上的字，圈出认识的字。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读一读儿歌，请爸爸妈妈评分。小白兔：小白兔，穿皮袄，耳朵长，尾巴小，三瓣嘴，胡子翘，一动一动总在笑。", "options": null}', '熟读儿歌。', '部编一上拼音儿歌朗读练习。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读儿歌评价标准：声音响亮☆☆☆；字音正确☆☆☆；朗读流畅☆☆☆。", "options": null}', '声音响亮；字音正确；朗读流畅。', '读儿歌评价标准：声音响亮、字音正确、朗读流畅。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "给 o 加声调。6 个 o：左列 3 个 o（ó、ǒ、ò 从上到下），右列 3 个 o（é、è、ó 从上到下）。中间 4 个声调标签：一声/二声/三声/四声。连线。", "options": null}', '一声：ō（图中无调号的 o 对应一声）；二声：ó、é；三声：ǒ；四声：ò、è。', '6 个 o 分配到 4 个声调：ō(1)、ó(2)、é(2)、ǒ(3)、ò(4)、è(4)。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "看图猜音节。4 张图：飞机、金字塔、西瓜、米袋。4 个音节：là bǐ（蜡笔）、fǔ tī（斧头？）、dà mǐ（米）、dì tú（地图）。", "options": null}', '米袋—dà mǐ；其他 3 图（金字塔/飞机/西瓜）与 4 音节（蜡笔/斧头/米/地图）无直接对应。', '看图猜音节，4 图与 4 音节「打乱」配对，仅米袋—dà mǐ 匹配，其他图无对应音节（题目设计或印刷问题）。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "5 个水果人（写有汉字）：大、马、木、足、他。5 个水果人（写有拼音）：mǎ、mù、dà、tā、zú。连一连。", "options": null}', '大—dà；马—mǎ；木—mù；足—zú；他—tā。', '5 字 5 音节一一对应。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "小朋友们，我们已经学习了拼音，现在让我们一起走进拼音闯关！看看你能闯过几关。（第三单元·名校一主题引导）", "options": null}', '继续完成下面各关题目。', '第三单元测试卷（名校一）主题引导语。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "圈出加点字的正确读音。天地(dì/bì)；耳目(mù/nù)；泥土(tǔ/lǔ)；你们(ní/mǐ)；六个(bà/bā)；马路(lù/nù)。", "options": null}', '天地—dì；耳目—mù；泥土—tǔ；你们—nǐ；六个—bā；马路—lù。', '正确读音：dì、mù、tǔ、nǐ、bā、lù。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "请在与其他音节词不属于同一类的音节词上画「√」。（1）tǔ、mǎ、é、lí。", "options": null}', 'tǔ（声母 t，韵母 u）；其他含不同声母。答案以教材为准。', '从 4 个音节词中找不同类。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "请在与其他音节词不属于同一类的音节词上画「√」。（2）nǎ、pā、lǔ、mō。", "options": null}', 'nǎ、pā、mō 含鼻韵母；lǔ 韵母是 u。答案以教材为准。', '从 4 个音节词中找不同类。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "请在与其他音节词不属于同一类的音节词上画「√」。（3）dì di、bà ba、pó po、bó bo。", "options": null}', 'bó bo 轻声；其他为非轻声或规律不同。答案以教材为准。', '从 4 个称谓词中找不同类。', 'paper', '[]', '["/static/qimg/mz_yw_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "读一读，选一选（写编号）。①u ②a ③i。（1）他 爸 大（ ）。", "options": ["①u", "②a", "③i"]}', '大（dà）含 a，②a。', '三字中选含 a 韵母的字。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "读一读，选一选（写编号）。（2）七 地 你（ ）。", "options": ["①u", "②a", "③i"]}', '七(qī)、地(dì)、你(nǐ) 都含 i，③i。', '三字中选含 i 韵母的字。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "读一读，选一选（写编号）。（3）目 土 足（ ）。", "options": ["①u", "②a", "③i"]}', '目(mù)、土(tǔ)、足(zú) 都含 u，①u。', '三字中选含 u 韵母的字。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "古诗填空（填编号）。①远看山有色 ②春去花还在。____，近听水无声。____，人来鸟不惊。", "options": null}', '①远看山有色，②春去花还在。', '出自王维《画》：远看山有色，近听水无声。春去花还在，人来鸟不惊。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第四关：我会写。找规律，填一填；比一比，再写一写；看图，给下列音节标上声调。", "options": null}', '完成下面 3 个练习。', '第四关主题引导，含 3 个练习。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "找规律，填一填。6 个空圈：a、（ ）、（ ）、i、u、（ ）。", "options": null}', 'a、o、e、i、u、ü（单韵母 6 个，按顺序填空）。', '部编一上单韵母 6 个：a o e i u ü，按顺序排列填空。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "比一比，再写一写。7 组字母：d—b、f—l、n—m、b—p、l—i、u—n、u—ü。每组在四线三格里写一遍。", "options": null}', '7 组字母按大小写或顺序在四线三格中正确书写。', '易混淆字母对比书写：d/b、f/l、n/m、b/p、l/i、u/n、u/ü。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看图，给下列音节标上声调。4 张图：蜻蜓、喇叭、宝塔、人群。4 个音节：pa po（爬坡）、la ba（喇叭）、mu ma（沐浴）、ma lu（马路）。", "options": null}', 'pá po（爬坡，po 二声）；là ba（喇叭，la 四声 ba 轻声）；mù ma（沐浴，mu 四声）；mǎ lù（马路，ma 三声 lu 四声）。', '结合图片判断音节声调：pa po=爬坡（爬为二声）、la ba=喇叭（la 四声 ba 轻声）、mu ma=沐浴（沐为四声）、ma lu=马路（马三声路四声）。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第五关：我会读。儿歌《秋》：秋，凉爽。高粱熟了昂着头，稻子熟了低着头，玉米熟了歪着头，芦花白了摇着头，一阵秋风吹来了，树上苹果露着头，娃娃唱起丰收歌，拍着手儿点着头。", "options": null}', '熟读儿歌《秋》。', '部编一上儿歌《秋》，含拟人化描写秋天庄稼成熟景象。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连一连。5 物（高粱/稻子/玉米/芦花/娃娃）配 5 动词短语（昂着头/低着头/歪着头/白了（露着）/低着头）。", "options": null}', '高粱—昂着头；稻子—低着头；玉米—歪着头；芦花—白了（露着）；娃娃—点着头（拍手）。', '按儿歌原句连线：高粱昂、稻子低、玉米歪、芦花白、娃娃点。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "你来说一说：秋天还有哪些果实成熟了？可以画一画或写一写。", "options": null}', '秋天成熟的果实：苹果、梨、葡萄、橘子、柿子、石榴、栗子、枣、稻子、高粱、玉米等。', '开放题：画一画或写一写秋天的成熟果实。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读儿歌，依照例句，用拟人的描写秋天的果实。例：秋天的苹果，涨红了脸。4 行空白。", "options": null}', '例：秋天的橘子，披上了黄袍。秋天的葡萄，睁大了眼。秋天的稻子，低下了头。', '拟人句练习：秋天的XX + 拟人动作/状态。', 'paper', '[]', '["/static/qimg/mz_yw_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "小朋友们，今天我们继续畅游拼音王国。国王说：小朋友们，我们又见面了！还记得吗？我是拼音王国的国王，我们再来做拼音游戏吧！（第三单元·名校一主题引导）", "options": null}', '完成下面 3 个游戏。', '第三单元测试卷（名校一）主题引导，3 个游戏。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏一：画一画。把声母按顺序连一连，看看画出来的是什么。23 个声母点（b p m f d t n l g k h j q x zh ch sh r z c s y w）按声母表顺序连成轮廓。", "options": null}', '按声母表顺序连接 23 个点，组成图形（具体图形视连线结果）。', '声母 23 个按顺序连点成画练习。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "请你把三拼音苹果涂成红色。8 个苹果：hē、duō、gē、luó、yī、wū、kuò、lüè。", "options": null}', '三拼音：duō（d+u+o）、luó（l+u+o）、kuò（k+u+o）、lüè（l+ü+ê）。', '三拼音=声母+介母（i/u/ü）+韵母。8 个音节中 duō、luó、kuò、lüè 介母是 u 或 ü。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：连一连。请在与其他音节词不属于同一类的音节词上画「√」。（1）è yú、bō luó、luò tuo、mǎ。", "options": null}', 'bō luó（菠萝是植物），其他 3 个是动物。', 'è yú 鳄鱼/luò tuo 骆驼/mǎ 马=动物；bō luó 菠萝=植物。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：连一连。请在与其他音节词不属于同一类的音节词上画「√」。（2）yā lí、jú zi、píng guǒ、wū yā。", "options": null}', 'wū yā（乌鸦是动物），其他 3 个是水果。', 'yā lí 鸭梨/jú zi 橘子/píng guǒ 苹果=水果；wū yā 乌鸦=动物。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：连一连。请在与其他音节词不属于同一类的音节词上画「√」。（3）yǔ wén、shù xué、lí yú、shù。", "options": null}', 'lí yú（鲤鱼是动物），其他 3 个是学科或植物（yǔ wén 语文/shù xué 数学=学科，shù 树=植物）。', 'yǔ wén 语文/shù xué 数学=学科；lí yú 鲤鱼=动物；shù 树=植物。三类，实际答案以教材教师用书为准。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：连一连。请在与其他音节词不属于同一类的音节词上画「√」。（4）qián bǐ、xiàng pí、wén jù hé、jī mù。", "options": null}', 'jī mù（积木是玩具），其他 3 个是学习工具。', 'qián bǐ 铅笔/xiàng pí 橡皮/wén jù hé 文具盒=学习工具；jī mù 积木=玩具。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 2, '{"stem": "圈出下列汉字的正确读音。弟(dì/di)、哥(gē/guō)、打(dā/bǎ)、棋(qí/pǐ)、扫(sǎo/shǎo)、桌(zhuō/zuō)。", "options": null}', '弟—dì；哥—gē；打—dǎ；棋—qí；扫—sǎo；桌—zhuō。', '正确读音：dì、gē、dǎ、qí、sǎo、zhuō。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "游戏三：找朋友。6 音节（yī、ruò、mǎ、shè、rì、duò）分到 3 篮筐（双拼音节/三拼音节/整体认读音节）。", "options": null}', '双拼音节：mǎ、shè、ruò；三拼音节：duò（d+u+o）；整体认读音节：yī、rì。', '双拼=声母+韵母；三拼=声母+介母+韵母；整体认读=yi/wu/yu 等特殊音节。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "游戏三：找朋友。4 音节词（yī zi、mù mǎ、mǎ yǐ、là ba）配 4 图（椅子/木马/蚂蚁/喇叭）。", "options": null}', 'yī zi—椅子；mù mǎ—木马；mǎ yǐ—蚂蚁；là ba—喇叭。', '音节词与图一一对应。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "游戏三：找朋友。4 音节词（yǎ chǐ、mó fǎ、fǔ zi、luò bo）配 4 图（牙齿/魔法棒/斧子/萝卜）。", "options": null}', 'yǎ chǐ—牙齿；mó fǎ—魔法；fǔ zi—斧子；luò bo—萝卜。', '音节词与图一一对应。', 'paper', '[]', '["/static/qimg/mz_yw_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "3. 花 画 字 纸 词 语（6 字）与 6 个拼音 huā、huà、zhǐ、zǐ、cì、yǔ 连线。", "options": null}', '花—huā；画—huà；纸—zhǐ；字—zǐ；语—yǔ（注：图中「词」标 cì，与标准拼音 cí 不符，疑为印刷错误）。', '6 字配 6 拼音连线；图中「词」标 cì，但汉语拼音「词」标准为 cí，疑似印刷问题。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏四：写一写。1. 按顺序写声母。上排 7 格：b、_、_、_、_、_、n。", "options": null}', 'b、p、m、f、d、t、n（按声母表顺序，共 7 个声母）。', '声母顺序：b-p-m-f-d-t-n。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏四：写一写。1. 按顺序写声母。下排 6 格：_、x、_、_、y、w。", "options": null}', 'j、q、x、z、c、s（按声母表顺序，待填 3 个为 j、z、c）。', '下排 6 格，已知 x、y、w，待填 3 个：按声母表顺序，x 前是 j、q，y 前是 z、c。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "游戏四：写一写。2. 照样子写一写。例：zhū→(zh)—(ū)；m—i→(mǐ)。共 10 行：①jù→j—( )；②q—ü—( )；③x—ü—( )；④m—ù→( )；⑤guā→( )—( )—(ā)；⑥zh—u—ā→( )；⑦xiá→( )—( )—(á)；⑧h—u—ā→( )；⑨zhuā→(zh)—( )—(ā)；⑩sh—u—ā→( )。", "options": null}', '①ù；②ù；③ù；④mù；⑤g、u；⑥zhuā；⑦x、i；⑧huā；⑨u；⑩shuā。', '拼音拆分与组合：①-③「j/q/x+ü+ù」类（ü 与 j/q/x 相拼时去两点）；④整体音节 mù；⑤/⑦声母+介母+韵母拆解；⑥/⑧/⑩声母+介母+韵母组合成整体音节；⑨整体音节拆出声母、介母、韵母。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏五：说一说。看图说话（蓝天白云太阳、飞鸟、大树、河流、小鱼）。1. 树上结满了___。", "options": null}', '示例：树上结满了又大又红的苹果。', '看图说话练习，按「地点+动词+事物」句式作答。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏五：说一说。2. 地上开着___。", "options": null}', '示例：地上开着五颜六色的鲜花。', '看图说话练习。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏五：说一说。3. 空中___。", "options": null}', '示例：空中飞着几只小鸟。', '看图说话练习。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏五：说一说。4. 水中___。", "options": null}', '示例：水中游着可爱的小鱼。', '看图说话练习。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "评价标准：声音响亮☆☆；句子正确☆☆；表述流利☆☆☆。", "options": null}', '按三项标准分级评价：声音响亮 1 星、句子正确 1 星、表述流利 1.5 星。', '看图说话评价标准。', 'paper', '[]', '["/static/qimg/mz_yw_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 2, '{"stem": "第一关：我会认。1. 读一读，给整体认读音节涂上你喜欢的颜色。音节：z、cì、yi、b、zì、c、wu、s、o、si。", "options": null}', 'yi、wu、si（这 3 个是整体认读音节）。', '整体认读音节 16 个：zhi chi shi ri zi ci si yi wu yu ye yue yuan yin yun ying。本题 10 个中只有 yi、wu、si 符合；z、b、c、s 是声母，o 是单韵母，cì、zì 是带调音节而非整体认读。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关：2. 读一读儿歌，请爸爸妈妈评分。儿歌：红色屋顶，黄墙壁，草儿青青树儿绿，妈妈洗衣我喂鱼，鸟我邻居。评价：声音响亮☆☆；字音正确☆☆；朗读流利☆☆☆。", "options": null}', '朗读练习，按「声音响亮、字音正确、朗读流利」三项分级评价。', '儿歌朗读，注意「红、黄、绿、鱼」等字的读音，读准翘舌音、轻声。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关：3. 我会看课程表。课程表（周一至周五，每天 5 节）。", "options": null}', '周一：语文、数学、音乐、体育、道德与法治；周二：数学、语文、语文、音乐、班队活动；周三：美术、语文、语文、写字、体育；周四：语文、美术、数学、道德与法治、综合实践；周五：语文、道德与法治、体育、体育、校本课程。', '看课程表填课程名称，认识「语文、数学、美术、音乐、体育、道德与法治、写字、班队活动、综合实践、校本课程」等学科词。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 2, '{"stem": "第二关：我会连。1. 给下面的声母分类。声母：zh、sh、c、s、ch、shi、z、zi。", "options": null}', '翘舌音：zh、sh、ch、shi；平舌音：c、s、z、zi。', '翘舌音是舌尖翘起抵硬腭前部，平舌音是舌尖抵下齿背。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第二关：2. 读一读，连一连。6 个音节词与 6 幅图：dà xiā、qǐ é、mù jī、jú huā、yú gǔ、sī jī。", "options": null}', 'dà xiā—虾；qǐ é—企鹅；mù jī—母鸡；jú huā—菊花；yú gǔ—鱼骨；sī jī—司机。', '看图识音节词，注意声调与三拼音、整体认读。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "第二关：3. 读一读，连一连。4 个拼音词与 4 个汉字词：hé huà、sǎo dì、zhé zhǐ、huā huà 配 画画、扫地、折纸、荷花。", "options": null}', 'hé huà—荷花；sǎo dì—扫地；zhé zhǐ—折纸；huā huà—画画（拼音与汉字词故意错位，需按正确读音连线；图中部分拼音标注有印刷错误）。', '注意拼音与汉字的正确对应：hé huà 应为「荷花」（图中部分拼音与汉字错位，需按标准读音判断）。', 'paper', '[]', '["/static/qimg/mz_yw_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "把 8 个音节按类别分到 4 个盒子里。①qì chē ②é ③huǒ chē ④shā fā ⑤hú li ⑥xī guā ⑦bō luó ⑧zhuō zi。分类：交通工具、水果、动物、家具。", "options": null}', '交通工具：①qì chē(汽车)、③huǒ chē(火车)；水果：⑥xī guā(西瓜)、⑦bō luó(菠萝)；动物：②é(鹅)、⑤hú li(狐狸)；家具：④shā fā(沙发)、⑧zhuō zi(桌子)。', '按词义分类：交通工具类（汽车、火车）；水果类（西瓜、菠萝）；动物类（鹅、狐狸）；家具类（沙发、桌子）。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "我会区分（写编号）：①字 ②词 ③句。①树木（  ）②土（  ）③我是小学生。（  ）④虫（  ）⑤小岛（  ）⑥我画了荷花。（  ）。", "options": null}', '树木（②词）；土（①字）；我是小学生。（③句）；虫（①字）；小岛（②词）；我画了荷花。（③句）。', '字：单字；词：两字或以上组成的词；句：完整句子带标点。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "看图选音节词。备选：dà shǔ、cā zhuō zi、chī guā、hé chá。(1) 医生给小孩治疗图：Bà ba zài ___。", "options": ["A. dà shǔ", "B. cā zhuō zi", "C. chī guā", "D. hé chá"]}', '(1) dà shǔ（打鼠，谐音「打针」= 医生给小孩治疗）。', 'dà shǔ = 打鼠，借音代「打针」表治疗。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "看图选音节词。备选：dà shǔ、cā zhuō zi、chī guā、hé chá。(2) 小孩吃西瓜图：Dì dì zài ___。", "options": ["A. dà shǔ", "B. cā zhuō zi", "C. chī guā", "D. hé chá"]}', '(2) chī guā（吃瓜）。', '图中小孩在吃西瓜，对应 chī guā。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "看图选音节词。备选：dà shǔ、cā zhuō zi、chī guā、hé chá。(3) 医院图：Mā ma zài ___。", "options": ["A. dà shǔ", "B. cā zhuō zi", "C. chī guā", "D. hé chá"]}', '(3) cā zhuō zi（擦桌子= 医院清洁）。', '医院场景对应 cā zhuō zi（清洁擦桌）。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "看图选音节词。备选：dà shǔ、cā zhuō zi、chī guā、hé chá。(4) 哥哥做事图：Gē ge zài ___。", "options": ["A. dà shǔ", "B. cā zhuō zi", "C. chī guā", "D. hé chá"]}', '(4) hé chá（喝茶）。', '图意哥哥喝茶，对应 hé chá。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "第四关：我会写。1. 拼一拼，写音节。①j—i→___ ②j—ǔ→___ ③j—i—ǎ→___ ④d—ǔ→___ ⑤q—ù→___ ⑥q—i—ǎ→___ ⑦n—ǔ→___ ⑧x—ù→___ ⑨x—i—ǔ→___ ⑩zh—è→___ ⑪r—ú→___ ⑫ch—u—ǒ→___ ⑬ch—ǔ→___ ⑭zh—ǔ→___ ⑮r—u—ò→___。", "options": null}', '①jī ②jǔ ③jiǎ ④dǔ ⑤qù ⑥qiǎ ⑦nǔ ⑧xù ⑨xiǔ ⑩zhè ⑪rú ⑫chuǒ ⑬chǔ ⑭zhǔ ⑮ruò。', '拼音合成：声母+韵母+声调拼成完整音节。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关：2. 看图，把音节词补充完整。①鸽子+乌鸦图 w__y__；②牙齿图 y__ch__；③鼓图 ó__u__；④数字 4 图 i__i。", "options": null}', '①wū yā(乌鸦)；②yá chǐ(牙齿)；③gǔ(鼓，题中 ó—u 应为 ǔ—u 即 gǔ)；④题图意不明，建议教师用书核对。', '看图填拼音：乌鸦 wū yā、牙齿 yá chǐ、鼓 gǔ。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关：3. 看图，给下列字词注音。①打鼓；②禾；③下棋；④七只鸡。", "options": null}', '①dǎ gǔ；②hé；③xià qí；④qī zhī jī。', '看图给汉字注音：d—ǎ—g—ǔ、h—é、x—i—à q—í、q—ī zh—ī j—ī。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第五关：我会读。谜语：身披绿衣服，唱歌呱呱叫，田里捉害虫，丰收立功劳。", "options": null}', '谜底：青蛙。', '根据外形（绿衣）、叫声（呱呱叫）、习性（捉害虫）判断。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "第五关：1. 写出儿歌里的翘舌音。儿歌：身披绿衣服，唱歌呱呱叫，田里捉害虫，丰收立功劳。", "options": null}', 'sh(身)、ch(唱)、zh(捉)、ch(虫)、sh(收)。', '翘舌音为舌尖后音：sh、ch、zh、r。本句中含 sh、ch、zh。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "第五关：2. 谜语的谜底是___（填编号）。①zhī liǎo ②dà shù ③qīng wā。", "options": ["A. ①zhī liǎo 知了", "B. ②dà shù 大树", "C. ③qīng wā 青蛙"]}', '③qīng wā(青蛙)。', '谜面对应「青蛙」：绿衣、呱呱叫、捉害虫。', 'paper', '[]', '["/static/qimg/mz_yw_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：写一写。1. 把它们正确地写到四线三格里。音节：ui iu ou ei ie üe。", "options": null}', 'ui、iu、ou、ei、ie、üe。', '复韵母正确书写：ui(威)、iu(优)、ou(欧)、ei(欸)、ie(耶)、üe(约)，注意 üe 的 ü 上两点。', 'paper', '[]', '["/static/qimg/mz_yw_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏二：2. 看图，把下列拼音补充完整。①图1(好球) _ǎo _iú；②图2(苹果) _íng _uǒ；③图3(气球) _ì _iú；④图4(西瓜) _ī _uā。", "options": null}', '①hǎo qiú(好球) ②píng guǒ(苹果) ③qì qiú(气球) ④xī guā(西瓜)。', '看图补声母韵母：好球 h+ǎo/q+iú、苹果 p+íng/g+uǒ、气球 q+ì/q+iú、西瓜 x+ī/g+uā。', 'paper', '[]', '["/static/qimg/mz_yw_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏三：连一连。1. 把整体认读音节送回家。音节：yin yuan lun yun ri li yue ye re。", "options": null}', '整体认读音节：yin、yuan、yun、yue、ye。非整体认读：lun、ri、li、re。', '整体认读音节共 16 个：zhi chi shi ri zi ci si yi wu yu ye yue yuan yin yun ying。其中 ri 也是整体认读音节，本句中 ri 应归入整体认读（题中 ri 属易混项，标准归整体认读）。', 'paper', '[]', '["/static/qimg/mz_yw_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏三：2. 连一连（把词语和对应的图连起来）。上排 5 词：wū guī、jú huā、yú xiā、tóu fa、chèn yī。", "options": null}', 'wū guī(乌龟)、jú huā(菊花)、yú xiā(鱼虾)、tóu fa(头发)、chèn yī(衬衣)。', '看图连线：乌龟、菊花、鱼虾、头发、衬衣。', 'paper', '[]', '["/static/qimg/mz_yw_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "游戏三：2. 连一连（把词语和对应的图连起来）。下排 5 词：qīng wā、fó xiàng、lán qiú、nào zhōng、xiǎo gǒu。", "options": null}', 'qīng wā(青蛙)、fó xiàng(佛像)、lán qiú(篮球)、nào zhōng(闹钟)、xiǎo gǒu(小狗)。', '看图连线：青蛙、佛像、篮球、闹钟、小狗。', 'paper', '[]', '["/static/qimg/mz_yw_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "看图连一连：把图和对应的音节连起来。5 个图：白菜、鸭梨、大桥、垂柳、夜色；5 个音节（错位）：chuí liú、bái cài、yā lí、dà qiáo、yè sè。", "options": null}', '白菜→bái cài、鸭梨→yā lí、大桥→dà qiáo、垂柳→chuí liú、夜色→yè sè。', '图与音节对应：图1白菜→bái cài，图2鸭梨→yā lí，图3大桥→dà qiáo，图4垂柳→chuí liú，图5夜色→yè sè。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "把下列词语分分类。列1：蓝天、树林、小河、泥土、祖国；列2：鱼儿、白云、我们、小鸟、种子；列3：看、听、写、打、踢；列4：生字、故事、书本、自行车、乒乓球。", "options": null}', '自然景物：蓝天、树林、小河、泥土、白云、种子。人物/动物：鱼儿、我们、小鸟、祖国。动作：看、听、写、打、踢。学习/生活物品：生字、故事、书本、自行车、乒乓球。', '按词性/主题分类：动词归为动作；其余多为名词，景物/动植物/人/物品/抽象概念可细分。开放题，分类合理即可。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "你知道什么时候该带什么吗？① wàng yuǎn jìng(望远镜) ② miàn bāo(面包) ③ xiàng pí(橡皮) ④ shū běn(书本) ⑤ shuǐ cǎi bǐ(水彩笔) ⑥ shuǐ guǒ(水果) ⑦ líng shí(零食) ⑧ qiān bǐ hé(铅笔盒)。游玩：① ___；上学：___。", "options": null}', '游玩参考：①望远镜（带去观景）、⑤水彩笔、⑥水果、⑦零食。上学参考：③橡皮、④书本、⑧铅笔盒。', '游玩带吃喝零食类：⑥水果、⑦零食；或户外用品：①望远镜、⑤水彩笔。上学带学习用品：③橡皮、④书本、⑧铅笔盒。答案不唯一，合理即可。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "照样子，给音节词分类。① huā cài ② píng guǒ ③ huā bīng ④ liú bō ⑤ táo huā ⑥ yóu yǒng ⑦ liǔ shù ⑧ xī guā。", "options": null}', '含「花」字：①huā cài(花菜)、③huā bīng(花冰)、⑤táo huā(桃花)。不含「花」字：②píng guǒ(苹果)、④liú bō(流波)、⑥yóu yǒng(游泳)、⑦liǔ shù(柳树)、⑧xī guā(西瓜)。', '按音节词是否含「花」(huā)字分类：含「花」字有 ①③⑤；不含「花」字有 ②④⑥⑦⑧。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "看图选出合适的音节。4 个音节：dǎ gǔ(打鼓)、chàng gē(唱歌)、kàn diàn shì(看电视)、hē shuǐ(喝水)。(1) Mā ma zài ___；(2) Dì zài ___。", "options": null}', '(1) dǎ gǔ（打鼓）；(2) kàn diàn shì（看电视）。', '图1：图中人在打鼓，对应音节 dǎ gǔ；图2：图中人在看电视，对应音节 kàn diàn shì。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读一读儿歌《小蚂蚁》（作者姓名印糊）：xiǎo mǎ yǐ，zhēn yǒu qù，jiàn miàn pèng pèng xiǎo xū xu。nǐ pèng wǒ，wǒ pèng nǐ，bào gào yí gè hǎo xiāo xi。pái duì zǒu，yī èr yī，dà jiā qù tái yí lì mǐ。（选自《小小的船》，北京师范大学出版社 1996 年版）", "options": null}', '小蚂蚁，真有趣，见面碰碰小须须。你碰我，我碰你，报告一个好消息！排队走，一二一，大家去抬一粒米。', '儿歌描述小蚂蚁见面打招呼、排队搬米的场景。评价标准：声音响亮☆☆☆、字音正确☆☆、朗读流利☆☆。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 2, '{"stem": "读完儿歌想一想：小蚂蚁见面为什么要碰小须须？", "options": null}', '小蚂蚁见面碰小须须，是为了互相打招呼、传递信息（如报告好消息）。', '「你碰我，我碰你，报告一个好消息」—— 触角（须须）是小蚂蚁交流的工具。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 2, '{"stem": "说一说：小蚂蚁是怎么抬米的？", "options": null}', '小蚂蚁们排队走（一二一，齐步走），大家齐心协力一起去抬一粒米。', '「排队走，一二一，大家去抬一粒米」—— 通过排队协作的方式搬运。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 2, '{"stem": "仔细观察，结合生活经验，介绍一下你的小书包。评价标准：声音响亮☆☆☆、语句通顺☆☆、表达流利☆☆。", "options": null}', '示例：我的小书包是红色的，上面有一只可爱的小兔子图案。它有两只耳朵形状的提手和一个主袋。主袋里装着我的课本、铅笔盒和作业本。我每天背着它去上学，它是我学习的好伙伴。', '主观题。介绍书包可从外观（颜色、图案）、结构（提手、口袋）、内容物（书本、文具）入手，言之有理即可。', 'paper', '[]', '["/static/qimg/mz_yw_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读一读，给后鼻音涂上你喜欢的颜色。10 个音节：yin、zhuāng、rén、děng、gōng、hóng、bīn、jīng、hēi、huī。", "options": null}', '后鼻音（-ng 结尾）：zhuāng(ang)、děng(eng)、gōng(ong)、hóng(ong)、jīng(eng)，共 5 个。', '前鼻音 -n：yin、rén、bīn（共 3 个）。非前后鼻音：hēi(ei)、huī(ui)（共 2 个）。后鼻音 -ng：zhuāng、děng、gōng、hóng、jīng（共 5 个）。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "我会连（把音节分到对应的类别）。9 个音节：in、ing、u、yin、ong、yun、an、ün、yue；三个类别：前鼻韵母、后鼻韵母、整体认读音节。", "options": null}', '前鼻韵母（-n）：in、an、ün。后鼻韵母（-ng）：ing、ong。整体认读音节：yin、yun、yue。单韵母：u。', '按韵母结构分类：-n 结尾为前鼻，-ng 结尾为后鼻，yin/yun/yue 为整体认读音节，u 为单韵母。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "我会连（把音节词和对应的中文连起来）。左边：shuǐ tián、xuě huā、lán tiān、yè sè、sēn lín、dà jiā；右边（7 词 1 干扰项）：草地、大家、水田、雪花、夜色、蓝天、森林。", "options": null}', 'shuǐ tián→水田、xuě huā→雪花、lán tiān→蓝天、yè sè→夜色、sēn lín→森林、dà jiā→大家。干扰项：草地。', '音节词与中文对应：水田、雪花、蓝天、夜色、森林、大家。「草地」为干扰项，无对应音节词。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "我会选（看图选词）。6 个图（从上到下）：山羊、小桥、雪花、草原、黄牛、皮球；6 个词：shān yáng(山羊)、xiǎo qiáo(小桥)、xuě huā(雪花)、cǎo yuán(草原)、huáng niú(黄牛)、pí qiú(皮球)。", "options": null}', 'shān yáng→山羊图、xiǎo qiáo→小桥图、xuě huā→雪花图、cǎo yuán→草原图、huáng niú→黄牛图、pí qiú→皮球图。', '图与拼音词一一对应：动物类(山羊/黄牛)、景物类(小桥/雪花/草原)、物品类(皮球)。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读句子，选一选（填编号）。① xiǎo gǒu(小狗) ② gāng qín(钢琴) ③ xī guā(西瓜) ④ xiǎo tí qín(小提琴) ⑤ píng guǒ(苹果) ⑥ mí fēng(蜜蜂)。句子：(1) ___ hé ___ shì shuǐ guǒ。", "options": null}', '(1) ③ hé ⑤（xī guā 西瓜 hé píng guǒ 苹果）shì shuǐ guǒ。', '水果类：③xī guā 西瓜、⑤píng guǒ 苹果。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读句子，选一选（填编号）。① xiǎo gǒu ② gāng qín ③ xī guā ④ xiǎo tí qín ⑤ píng guǒ ⑥ mí fēng。句子：(2) ___ hé ___ shì yuè qì。", "options": null}', '(2) ② hé ④（gāng qín 钢琴 hé xiǎo tí qín 小提琴）shì yuè qì。', '乐器类：②gāng qín 钢琴、④xiǎo tí qín 小提琴。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读句子，选一选（填编号）。① xiǎo gǒu ② gāng qín ③ xī guā ④ xiǎo tí qín ⑤ píng guǒ ⑥ mí fēng。句子：(3) ___ hé ___ shì dòng wù。", "options": null}', '(3) ① hé ⑥（xiǎo gǒu 小狗 hé mí fēng 蜜蜂）shì dòng wù。', '动物类：①xiǎo gǒu 小狗、⑥mí fēng 蜜蜂。', 'paper', '[]', '["/static/qimg/mz_yw_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "看图连一连：把图和对应的音节连起来。6 个图：唱歌、读书、写字、画画、钟表（挂钟）、闹钟；6 个音节：chàng gē、dú shū、xiě zì、huà huà、kàn zhōng、nào zhōng。", "options": null}', '唱歌→chàng gē、读书→dú shū、写字→xiě zì、画画→huà huà、钟表→kàn zhōng、闹钟→nào zhōng。', '图与音节一一对应：人物动作类（唱歌 chàng gē、读书 dú shū、写字 xiě zì、画画 huà huà）、钟表类（挂钟看钟 kàn zhōng、闹钟 nào zhōng）。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "一阵风把句子卡片吹乱了，请你理一理，加标点，注意大小写。卡片(1)：kǎi le、chūn tiān、táo huā。", "options": null}', '春天，桃花开了。（Chūn tiān，táo huā kāi le。）', '按「什么季节+什么花+怎么样」排序：春天到了，桃花开了。注意句首大写、句末句号。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "一阵风把句子卡片吹乱了，请你理一理，加标点，注意大小写。卡片(2)：zuò fān、zhēng zài、mā ma。", "options": null}', '妈妈正在做饭。（Mā ma zhèng zài zuò fàn。）', '按「谁+正在+干什么」排序：妈妈正在做饭。「做饭」正确拼音为 zuò fàn（图中卡片作 zuò fān）。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "分清它们的区别，再写一写。四组易混韵母：ie-ei、ui-iu、un-ün、an-ang。", "options": null}', 'ie、ei（i 在前读 ie，e 在前读 ei）；ui、iu（u 在前读 ui，i 在前读 iu）；un、ün（ü 上两点不能丢）；an、ang（ang 有后鼻音 -ng）。', '易混韵母辨析：ie/ei、ui/iu 是字母顺序不同；un/ün 是 ü 两点有无；an/ang 是前鼻音与后鼻音之分。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看图，写出对应的音节词。6 个图：小鸟、香蕉、钢琴、长颈鹿、乌龟、苹果。", "options": null}', 'xiǎo niǎo（小鸟）、xiāng jiāo（香蕉）、gāng qín（钢琴）、cháng jǐng lù（长颈鹿）、wū guī（乌龟）、píng guǒ（苹果）。', '看图写音节词：动物（小鸟、长颈鹿、乌龟）、水果（香蕉、苹果）、乐器（钢琴）。注意三拼音节 xiāng、jiāo、guā 与后鼻音 gāng、jǐng、píng。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "照样子拼一拼，读一读，把音节写出来。zh—u—àn→(　)；x—i—óng→(　)；j—üé→(　)；q—ü—àn→(　)；x—üé→(　)；x—i—é→(　)。", "options": null}', 'zhuàn、xióng、jué、quàn、xué、xié。', '三拼音节与 ü 拼读：j、q、x 与 ü 相拼 ü 上两点去掉。zh—u—àn→zhuàn，x—i—óng→xióng，j—üé→jué，q—ü—àn→quàn，x—üé→xué，x—i—é→xié。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "把下面的音节拆一拆。chún→(　)—(　)；duàn→(　)—(　)；qún→(　)—(　)；juǎn→(　)—(　)。", "options": null}', 'chún→ch—ún；duàn→d—uàn；qún→q—ún；juǎn→j—u—ǎn。', '音节拆分：chún 拆为声母 ch 与韵母 ún；duàn 拆为 d 与 uàn；qún 拆为 q 与 ún；juǎn 为三拼音节，拆为 j—u—ǎn（ü 在 j 后省略两点写 u）。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读一读儿歌《鸟和花》：鸟和花 niǎo hé huā。鸟叫啦，花开啦 niǎo jiào la，huā kāi la。鸟儿花儿可多啦 niǎo ér huā ér kě duō la！我们爱鸟不摘鸟 wǒ men ài niǎo bù zhāi niǎo，我们爱花不摘花 wǒ men ài huā bù zhāi huā。", "options": null}', '鸟和花：鸟叫啦，花开啦。鸟儿花儿可多啦！我们爱鸟不摘鸟，我们爱花不摘花。', '儿歌表达「爱护花草鸟兽」的主题。朗读评价标准：声音响亮☆☆☆、字音正确☆☆、朗读流利☆☆。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "在儿歌《鸟和花》中找出三拼音节，在下面画上横线。", "options": null}', '三拼音节：niǎo、huā、jiào、duō（含反复出现的 niǎo、huā）。', '三拼音节 = 声母+介音(i/u/ü)+韵母。niǎo(n-i-ǎo)、jiào(j-i-ào)、huā(h-u-ā)、duō(d-u-ō)。hé、kāi、zhāi、bù 等为两拼音节，不是三拼。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "读一读，填一填。我们爱鸟不___鸟，我们爱花不___花。（填拼音）", "options": null}', 'zhāi、zhāi（我们爱鸟不 zhāi 鸟，我们爱花不 zhāi 花）。', '原文「我们爱鸟不摘鸟，我们爱花不摘花」，两处均填「摘」的拼音 zhāi（翘舌音，韵母 ai）。', 'paper', '[]', '["/static/qimg/mz_yw_p17.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "一、把骨头放到相应的篮子里（分分类）。12 个拼音：wu、ei、üe、ch、ui、zi、h、ao、yin、yu、zh、u；三个篮子：声母、韵母、整体认读音节。", "options": null}', '声母：ch、h、zh。韵母：ei、üe、ui、ao、u。整体认读音节：wu、zi、yin、yu。', '声母共 3 个（ch、h、zh）；韵母共 5 个（ei、üe、ui、ao、u，其中 üe 图中或印作 ve）；整体认读音节共 4 个（wu、zi、yin、yu）。合计 12 个。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "二、读一读，分一分（写编号）。8 个词：① shēng lí ② hú li ③ kē dǒu ④ yā zi ⑤ mǔ jī ⑥ bō luó ⑦ lí zi ⑧ hóu zi。两类：水果、动物。", "options": null}', '水果：① shēng lí（生梨）、⑥ bō luó（菠萝）、⑦ lí zi（梨子）。动物：② hú li（狐狸）、③ kē dǒu（蝌蚪）、④ yā zi（鸭子）、⑤ mǔ jī（母鸡）、⑧ hóu zi（猴子）。', '水果类 3 个（生梨、菠萝、梨子）；动物类 5 个（狐狸、蝌蚪、鸭子、母鸡、猴子）。注意「生梨」「梨子」同为梨类水果。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "三、看图，写出对应的音节词。6 个图：海豚、兔子、蝴蝶、孔雀、青蛙、蜗牛。", "options": null}', 'hǎi tún（海豚）、tù zi（兔子）、hú dié（蝴蝶）、kǒng què（孔雀）、qīng wā（青蛙）、wō niú（蜗牛）。', '看图写音节词，均为动物：海豚 hǎi tún、兔子 tù zi、蝴蝶 hú dié、孔雀 kǒng què、青蛙 qīng wā、蜗牛 wō niú。注意后鼻音 kǒng、qīng 与轻声 zi。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "四、把汉字与对应的音节词连起来。左边：马路、荷花、积木、扫地、乌鸦、西瓜；右边：hé huā、mǎ lù、sǎo dì、wū yā、jī mù、xī guā。", "options": null}', '马路→mǎ lù、荷花→hé huā、积木→jī mù、扫地→sǎo dì、乌鸦→wū yā、西瓜→xī guā。', '汉字与拼音词对应：「荷花」正确拼音为 hé huā（图中或标 hé huà，以标准读音为准）；「扫地」sǎo dì（dì 为第四声）。其余直接对应。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、看拼音，写汉字。6 个拼音：kǒu、tiān、rì、hé、huǒ、ěr。", "options": null}', '口、天、日、禾、火、耳。', '基础汉字书写：口（门口）、天（天明/天空）、日（日升/生日）、禾（禾苗）、火（火灾/火车）、耳（耳朵）。图中提示字分别为：门、明、生、苗、灾、朵。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "六、在汉字的正确拼音上打「√」。梅(méi mèi)、棋(pí qí)、词(cí chí)、句(jù jú)、桌(zhuō zuò)、扫(sā sǎo)、菜(cài cìa)、鱼(yú yún)、果(guǒ guō)、柳(liǔ liú)。", "options": null}', '梅 méi、棋 qí、词 cí、句 jù、桌 zhuō、扫 sǎo、菜 cài、鱼 yú、果 guǒ、柳 liǔ。', '选择正确读音：梅 méi（阳平）、棋 qí、词 cí、句 jù、桌 zhuō（zh 翘舌）、扫 sǎo（第三声）、菜 cài、鱼 yú（整体认读）、果 guǒ、柳 liǔ（li 第三声）。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、填一填。①「手」共有___画，第四画是___。②「去」共有___画，第四画是___。③「牛」共有___画，第三画是___。④「年」共有___画，第五画是___。", "options": null}', '①手 4 画，第四画是「弯钩」（竖钩）。②去 5 画，第四画是「撇折」。③牛 4 画，第三画是「横」。④年 6 画，第五画是「横」。', '笔画笔顺：手（撇、横、横、弯钩）共 4 画；去（横、竖、横、撇折、点）共 5 画；牛（撇、横、横、竖）共 4 画；年（撇、横、横、竖、横、竖）共 6 画。', 'paper', '[]', '["/static/qimg/mz_yw_p18.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "八、读一读，连一连。把诗名与对应的诗句连起来。诗名：《悯农》《咏鹅》《画》。诗句：白毛浮绿水、汗滴禾下土、鹅，鹅，鹅、曲项向天歌、远看山有色、近听水无声。", "options": null}', '《悯农》→ 汗滴禾下土；《咏鹅》→ 鹅，鹅，鹅、曲项向天歌、白毛浮绿水；《画》→ 远看山有色、近听水无声。', '古诗对应：《悯农》「锄禾日当午，汗滴禾下土」；《咏鹅》「鹅鹅鹅，曲项向天歌，白毛浮绿水，红掌拨清波」；《画》「远看山有色，近听水无声，春去花还在，人来鸟不惊」。', 'paper', '[]', '["/static/qimg/mz_yw_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "九、选一选（填编号）。①朵 ②座 ③只 ④道。三（  ）山、七（  ）花、两（  ）鸟、四（  ）数学题。", "options": null}', '三（②座）山、七（①朵）花、两（③只）鸟、四（④道）数学题。', '量词搭配：山用「座」（座山、座桥）；花用「朵」（朵花、朵云）；鸟用「只」（一只鸟）；题用「道」（道题、道菜）。', 'paper', '[]', '["/static/qimg/mz_yw_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、读儿歌，完成练习。儿歌：花朵的妈妈是大地，星星的妈妈是天空，浪花的妈妈是大海，我们的妈妈是祖国。我们爱妈妈，我们爱祖国。第 1 题：这首儿歌共有___句话。", "options": null}', '5 句。', '数句子按句号（含并列句共用一句号）算：「花朵的妈妈是大地」「星星的妈妈是天空」「浪花的妈妈是大海」「我们的妈妈是祖国」「我们爱妈妈，我们爱祖国」共 5 句。', 'paper', '[]', '["/static/qimg/mz_yw_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "十、读儿歌，完成练习。第 2 题：连一连（填编号）。①天空 ②大地 ③祖国 ④大海。花朵的妈妈是___，星星的妈妈是___，浪花的妈妈是___，我们的妈妈是___。", "options": null}', '花朵的妈妈是②大地，星星的妈妈是①天空，浪花的妈妈是④大海，我们的妈妈是③祖国。', '按儿歌内容配对：花朵→大地、星星→天空、浪花→大海、我们→祖国。', 'paper', '[]', '["/static/qimg/mz_yw_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十一、看图写话。图上画了都有谁？他们在干什么？想一想，写一句。", "options": null}', '示例：图上有两个小朋友，他们在一起下棋，玩得很开心。', '看图写话要点：交代时间、地点、人物、事情。图中是两个小朋友对坐下棋（或五子棋），棋子摆在棋盘两旁，可写：两个小朋友在认真地比赛下棋。', 'paper', '[]', '["/static/qimg/mz_yw_p19.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "第一关：拼音关。第 1 题：按要求分类，正确抄写在四线三格内。18 个拼音：zh、b、a、zhi、u、yi、i、r、wu、ü、ci、c、o、yu、w、e、ri、f。分类：(1) 声母 (2) 韵母 (3) 整体认读音节。", "options": null}', '(1) 声母：zh、b、r、c、w、f（共 6 个）。(2) 韵母：a、u、i、ü、o、e（共 6 个）。(3) 整体认读音节：zhi、yi、wu、ci、yu、ri（共 6 个）。', '分类依据：声母 23 个中的 zh、b、r、c、w、f；单韵母 6 个 a、o、e、i、u、ü；整体认读音节 zhi、chi、shi、ri、zi、ci、si、yi、wu、yu、ye、yue、yin、yun、yuan、ying 中的 zhi、yi、wu、ci、yu、ri。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "第一关：拼音关。第 2 题：请给同类的音节词涂上相同的颜色。8 个音节词：è yú（鳄鱼）、bō luó（菠萝）、cì wei（刺猬）、píng guǒ（苹果）、hóu zi（猴子）、xī guā（西瓜）、xiǎo jī（小鸡）、xiǎo niǎo（小鸟）。", "options": null}', '动物类（一种颜色）：è yú（鳄鱼）、cì wei（刺猬）、hóu zi（猴子）、xiǎo jī（小鸡）、xiǎo niǎo（小鸟）共 5 个。水果/食物类（另一种颜色）：bō luó（菠萝）、píng guǒ（苹果）、xī guā（西瓜）共 3 个。', '分类标准：动物（能活动、有生命）与水果（植物果实、可食用）。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第一关：拼音关。第 3 题：连一连。把图和对应的音节词连起来。4 个音节：xuě huā（雪花）、táo huā（桃花）、xià qí（下棋）、yóu yǒng（游泳）。", "options": null}', '雪景图→xuě huā（雪花）；花/草图→táo huā（桃花）；下棋图（两人对坐）→xià qí（下棋）；游泳图→yóu yǒng（游泳）。', '图与音节对应：「xià qí 下棋」图中或印作 xià qì（声调混淆），正确拼音为 xià qí（第二声）。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关：拼音关。第 4 题：照样子，写一写。例：b—ù→(bù)。t—üí→(　)、ch—u—àng→(　)、g—āi→(　)、h—u—ā→(　)、n—(　)→nǔ、j—(　)→jǔ、sh—uí→(　)、q—ǜ→(　)。", "options": null}', 'b—ù→bù；t—üí→tuí（腿）；ch—u—àng→chuáng（床）；g—āi→gāi（该）；h—u—ā→huā（花）；n—(ǔ)→nǔ（努）；j—(ǔ)→jǔ（举）；sh—uí→shuí（谁）；q—ǜ→qù（去）。', '拼音拼读：bù 布、tuí 腿（三拼音节 t-ü-í）、chuáng 床（三拼 ch-u-áng）、gāi 该、huā 花（三拼 h-u-ā）、nǔ 努（n+ǔ）、jǔ 举（j+ǔ）、shuí 谁（两拼 sh-uí，三拼 sh-u-í）、qù 去（q+ǜ）。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关：拼音关。第 5 题：看图，把音节词补充完整。6 个图：萝卜、橘子、庙、地球、斧子、下棋。", "options": null}', 'lú bo（萝卜）、jú zi（橘子）、miào（庙）、dì qiú（地球）、fǔ zi（斧子）、xià qí（下棋）。', '看图补音节词：萝卜 lú bo、橘子 jú zi、庙 miào（图中填空形式 m_m_ 应为 miào）、地球 dì qiú、斧子 fǔ zi、下棋 xià qí。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关：汉字关。第 1 题：汉字变魔术。(1) 加一笔变成新字，再组词：二→(　)→组词___；木→(　)→组词___。(2) 加两笔变成新字，再组词：人→(　)→组词___；口→(　)→组词___。", "options": null}', '(1) 二→十（十字）；木→本（běn，本子）。(2) 人→从（cóng，从前）；口→日（rì，日子）或田（tián，田地）。', '汉字魔术：(1) 加一笔：「二」加一横变「十」（十字），「木」加一撇变「本」（běn，本子）。(2) 加两笔：「人」加一撇一捺变「从」（cóng，从前），「口」加一横变「日」（rì，日子）或加一撇一横变「田」（tián，田地）。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关：汉字关。第 2 题：拼一拼，写一写。shuāng、wáng、huǒ、qù nián、shàng wǔ。", "options": null}', 'shuāng→双（shuāng）；wáng→王（nǚ wáng 女王）；huǒ→火（chái huǒ 柴火）；qù nián→去年；shàng wǔ→上午。', '音节书写与组词：双 shuāng（一双）、王 wáng（女王 nǚ wáng）、火 huǒ（柴火 chái huǒ）、去年 qù nián、上午 shàng wǔ。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关：汉字关。第 3 题：填一填。「九」共有___画，第一画是___。", "options": null}', '「九」共 2 画，第一画是「撇」（丿）。', '「九」笔顺：撇、横折弯钩，共 2 画，第一画是「撇」（丿）。', 'paper', '[]', '["/static/qimg/mz_yw_p20.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关：识字关。(2)「火」共有___画，第三画是___。(3)「平」共有___画，第四画是___。组词：___。(4)「手」共有___画，第四画是___。组词：___。", "options": null}', '(2) 火 4 画，第三画是「撇」。(3) 平 5 画，第四画是「横」。组词：平安 píng ān（太平、平常）。(4) 手 4 画，第四画是「竖钩」。组词：手指 shǒu zhǐ（洗手、小手）。', '汉字笔顺：「火」4 画（点、撇、撇、捺），第三画撇；「平」5 画（横、横、竖、横、横），第四画横；「手」4 画（撇、横、横、竖钩），第四画竖钩。', 'paper', '[]', '["/static/qimg/mz_yw_p21.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第三关：诗歌关。读一读，连一连（填编号）。①人来鸟不惊 ②汗滴禾下土 ③粒粒皆辛苦 ④白毛浮绿水。(1) 春去花还在，___。(2) 锄禾日当午，___。(3) ___，红掌拨清波。(4) 谁知盘中餐，___。", "options": null}', '(1) 春去花还在，①人来鸟不惊。(2) 锄禾日当午，②汗滴禾下土。(3) ④白毛浮绿水，红掌拨清波。(4) 谁知盘中餐，③粒粒皆辛苦。', '古诗原文：《画》「远看山有色，近听水无声，春去花还在，人来鸟不惊」；《悯农》「锄禾日当午，汗滴禾下土，谁知盘中餐，粒粒皆辛苦」；《咏鹅》「鹅鹅鹅，曲项向天歌，白毛浮绿水，红掌拨清波」。', 'paper', '[]', '["/static/qimg/mz_yw_p21.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关：阅读关。儿歌「数一数」：山顶立着一只虎。林中跑着一只鹿。路上走来一只猪。草中藏着一只兔。洞里出来一只鼠。一二三四五，虎鹿猪兔鼠。第 1 题：儿歌共有___句话。", "options": null}', '6 句。', '数句子按句号（含并列句）算：5 个分句描述（虎、鹿、猪、兔、鼠各一句）+ 1 个总结句（一二三四五）= 共 6 句。', 'paper', '[]', '["/static/qimg/mz_yw_p21.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关：阅读关。第 2 题：儿歌中提到了哪些动物？请在相应的图片下画「√」。3 个图：虎、兔、鼠。", "options": null}', '3 个图（虎、兔、鼠）全部画「√」（儿歌中提到 5 种动物：虎、鹿、猪、兔、鼠；3 个图均为儿歌中动物）。', '判断标准：儿歌中提到的动物有虎、鹿、猪、兔、鼠共 5 种，3 个图（图示的虎、兔、鼠）都在儿歌中出现，全部打 √。', 'paper', '[]', '["/static/qimg/mz_yw_p21.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 2, '{"stem": "第四关：阅读关（续 3 题判断）。根据儿歌判断，正确的打「√」，错误的打「×」。(1) 儿歌共提到五种动物。( )(2) 树林中跑出了一只猪。( )(3) 草丛中藏着一只兔子。( )", "options": null}', '(1) √（儿歌中提到 5 种动物：虎、鹿、猪、兔、鼠）。(2) ×（是「鹿」不是「猪」，原文「林中跑着一只鹿」）。(3) √（原文「草中藏着一只兔」）。', '判断依据：儿歌中描述 5 种动物各 1 句，第 2 句明确「林中跑着一只鹿」而非猪。', 'paper', '[]', '["/static/qimg/mz_yw_p21.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "一、读一读，分一分。把 10 个拼音分到 3 个「屋顶」中：声母、韵母、整体认读音节。10 个拼音：r、zh、yu、ei、yue、üe、ye、ch、ong、shi。", "options": null}', '声母：r、zh、ch（共 3 个）。韵母：ei、üe、ong（共 3 个）。整体认读音节：yu、yue、ye、shi（共 4 个）。', '分类依据：声母 23 个中的 r、zh、ch；单/复/鼻韵母 ei、üe、ong；整体认读音节 yu、yue、ye、shi。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "二、看图，用「——」画出正确的音节词。6 个图：耳朵、月牙、鞋（拖鞋/布鞋）、小猫、青蛙、电话。音节对：rěi duo / ěr duo；yuè ěr / yuè yá；bù xié / tuō xié；xiǎo māo / xiǎo mǎo；qīn wā / qīng wā；diàn huà / diān huà。", "options": null}', '耳朵：ěr duo；月牙：yuè yá；鞋：tuō xié；小猫：xiǎo māo；青蛙：qīng wā；电话：diàn huà。', '选正确音节：耳朵 ěr duo（不读 rěi duo）；月牙 yuè yá（不读 yuè ěr）；拖鞋 tuō xié；小猫 xiǎo māo（māo = 猫，第一声）；青蛙 qīng wā（qīng 末 ng）；电话 diàn huà（第四声 diàn）。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "三、看图，把下列音节词补充完整。6 个图：灯笼、冰箱、老鹰、熊猫、南瓜、萝卜。", "options": null}', 'l(óng)dēng（灯笼）；bīng x(iāng)（冰箱）；l(ǎo)ying（老鹰）；x(ióng)māo（熊猫）；nán g(uā)（南瓜）；l(uó)bo（萝卜）。', '音节词补充：灯笼 lóng dēng（灯 dēng + 笼 lóng）；冰箱 bīng xiāng；老鹰 lǎo yīng；熊猫 xióng māo；南瓜 nán guā；萝卜 luó bo。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "四、根据情境，给合适的小花涂上你喜欢的颜色。1. 上学时，你需要带的是：qiān bǐ（铅笔）、wán jù（玩具）、shū bāo（书包）、bù wá wa（布娃娃）。2. 出去郊游，你想带的是：mào zi（帽子）、wén jù（文具）、shuǐ guǒ（水果）、zhuān bǐ dāo（转笔刀）。", "options": null}', '1. 上学带：qiān bǐ（铅笔）、shū bāo（书包）。2. 郊游带：mào zi（帽子）、shuǐ guǒ（水果）。', '生活常识：上学需要学习用品（铅笔、书包），不需要玩具/布娃娃；郊游需要遮阳（帽子）和食物（水果），文具/转笔刀是学习用品不需要。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "五、选择合适的句子填在图片下面的括号里（写编号）。3 个图：跳舞的小女孩、学习的小男孩、下棋的两人。① Méi mei zài tiào wǔ（妹妹在跳舞）。② Xiǎo péng you zài xué xí（小朋友在学习）。③ Wǒ hé tóng xué zài xià qí（我和同学在下棋）。", "options": null}', '跳舞图→①；学习图→②；下棋图→③。', '图与句子对应：① 妹妹在跳舞（跳裙小女孩）；② 小朋友在学习（伏案小男孩）；③ 我和同学在下棋（对坐两人）。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "六、连一连。学校、马路、美术、夜色、冰山。mǎ lù、xué xiào、yè sè、bīng shān、měi shuǐ。", "options": null}', '学校→xué xiào；马路→mǎ lù；美术→měi shù（图中印作 měi shuǐ，疑为 měi shù 之误）；夜色→yè sè；冰山→bīng shān。', '中文与拼音配对：「美术」标准拼音 měi shù（第四声 shù），图中印作 měi shuǐ（第三声 shuǐ），疑为印刷错误，正确的是 měi shù。', 'paper', '[]', '["/static/qimg/mz_yw_p22.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 2, '{"stem": "七、读一读并判断，正确的打\\\"√\\\"，错误的打\\\"×\\\"。(1)\\\"火\\\"的笔顺是\\\"、冖火\\\"。(2)\\\"耳\\\"一共有六笔，第四笔是丨。(3)\\\"九\\\"第一笔是丿。(4)\\\"手\\\"的最后一笔是\\\"丿\\\"。\\\"", "options": null}', '(1) ×；(2) ×；(3) √；(4) ×。', '笔顺分析：(1)"火"正确笔顺是点、撇、撇、捺，题中"、冖火"含"冖"（盖头），错。(2)"耳"6 笔（横竖竖横横横），第 4 笔是横不是竖，错。(3)"九"笔顺是 丿+乙，第一笔 丿，对。(4)"手"4 笔（撇横横竖钩），最后一笔是竖钩不是 丿，错。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、拼一拼，写一写。kǒu、shēng、rì、hé miáo、ěr mù、shēng wù。", "options": null}', 'kǒu→口；shēng→生；rì→日；hé miáo→禾苗；ěr mù→耳目；shēng wù→生物。', '拼音识字：kǒu（口）、shēng（生）、rì（日）、hé miáo（禾苗，hé 第二声、miáo 第二声）、ěr mù（耳目）、shēng wù（生物）。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、古诗选一选（填编号）。①歌 ②红掌 ③白毛。(1)鹅，鹅，鹅，曲项向天___。___浮绿水，___拨清波。", "options": null}', '(1)曲项向天①歌；③白毛浮绿水；②红掌拨清波。', '《咏鹅》骆宾王：「鹅鹅鹅，曲项向天歌。白毛浮绿水，红掌拨清波。」白毛浮绿水对应「③白毛」，红掌拨清波对应「②红掌」。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、古诗选一选（填编号）。①粒粒皆辛苦 ②锄禾日当午。(2)___，汗滴禾下土。谁知盘中餐，___。", "options": null}', '(2)②锄禾日当午，汗滴禾下土。谁知盘中餐，①粒粒皆辛苦。', '《悯农》李绅：「锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。」', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、古诗选一选（填编号）。①近听 ②远看 ③春 ④人 ⑤花。(3)___山有色，___水无声。___去___还在，___来鸟不惊。", "options": null}', '(3)②远看山有色，①近听水无声。③春去⑤花还在，④人来鸟不惊。', '《画》王维：「远看山有色，近听水无声。春去花还在，人来鸟不惊。」', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、读儿歌，做练习。《过马路》：红灯停，绿灯行。交通路牌要看清。过街要走人行道。交通规则须记牢。(1)这首儿歌一共有___句话。", "options": null}', '4 句。', '儿歌四行，每行一句话，共 4 句：①红灯停，绿灯行；②交通路牌要看清；③过街要走人行道；④交通规则须记牢。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、读儿歌，做练习。《过马路》(2)在儿歌中圈出拼音含有后鼻韵母的字（重复的只圈一次）。", "options": null}', '圈出：红(hóng)、灯(dēng)、停(tíng)、行(xíng)、通(tōng)、清(qīng)，共 6 个字不重复。', '后鼻韵母：ang、eng、ing、ong。逐字排查：「红 hóng(ong)✓、灯 dēng(eng)✓、停 tíng(ing)✓、行 xíng/háng(含 ing)✓、通 tōng(ong)✓、清 qīng(ing)✓；其他字为前鼻音/复韵母/单韵母，不圈」。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 2, '{"stem": "十、读儿歌，做练习。《过马路》(3)过马路时应该注意什么？用「___」在儿歌中画出相关的语句。", "options": null}', '相关语句："红灯停，绿灯行"、"过街要走人行道"、"交通规则须记牢"。', '过马路安全注意事项：看红绿灯、走人行道、记交通规则。儿歌中相关语句为三句。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "十一、看图写一句话。提示：图上画的是谁？他在哪里？他在干什么？（不会写的字可以写拼音）", "options": null}', '示例：星期天，小明在草地上高高地放风筝。', '看图写话三要素：人物（谁）+地点（在哪里）+事情（干什么）。图中小孩在空旷处放风筝。', 'paper', '[]', '["/static/qimg/mz_yw_p23.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、读一读，分一分。iu、yuan、yun、un、zh、ou、w、yin、n、ong、ying、f。(1)声母：___。(2)韵母：___。(3)整体认读音节：___。", "options": null}', '(1)声母：zh、n、f。(2)韵母：iu、un、ou、ong。(3)整体认读音节：yuan、yun、w、yin、ying。', '声母：b p m f d t n l g k h j q x zh ch sh r z c s y w（共 23 个）。韵母：单元/复/鼻韵母 + 特殊韵母。整体认读音节：zhi chi shi ri zi ci si yi wu yu ye yue yuan yin yun ying。逐项分类。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "二、给表示动物的音节词涂上你喜欢的颜色。cǎo méi、lǎo hǔ、tù zì、qián bì、xióng、dà xiàng、shǒu tào、kǒng què。", "options": null}', '动物：lǎo hǔ（老虎）、tù zì（兔子）、xióng（熊）、dà xiàng（大象）、kǒng què（孔雀）。非动物（不涂）：cǎo méi（草莓）、qián bì（钱币）、shǒu tào（手套）。', '动物类音节词：老虎、兔子、熊、大象、孔雀（5 个）。非动物类：草莓（水果）、钱币（物品）、手套（物品）。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "三、看图片，在正确的音节词后打「√」。图1：白云。图2：奶牛。选项：bái yún( )、bái yún( )、shuǐ niú( )、shuǐ niú( )。", "options": null}', '白云图选 bái yún(√)；奶牛图选 shuǐ niú(√)。', '「白云」读 bái yún（白二声、云二声）；「奶牛」读 nǎi niú，但图中印 shuǐ niú（水牛），疑为「水牛」图（水牛 biǎn niú 也可）。水牛 shuǐ niú（三声+二声）。按图中选项填 bái yún 和 shuǐ niú。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、看图，把音节词补充完整。y___liang（月亮）、x___zi（鞋子）、xióng m___（熊猫）、shān y___（山羊）、x___guā（西瓜）、m___gu（蘑菇）。", "options": null}', 'y-uè liang（yuè，月亮）；xié-zi（xié，鞋子）；xióng-māo（māo，熊猫）；shān-yáng（yáng，山羊）；xī-guā（guā，西瓜）；mó-gu（mó，蘑菇）。', '完整音节：yuè（y+üe，y 与 üe 拼写省略两点）、xié（x+ié）、māo（m+āo）、yáng（y+áng）、guā（g+uā）、mó（m+ó）。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "五、音节排队，连成一句话（写编号）。(1)① zōng guó rén ② dòu shi ③ wǒ men。", "options": null}', '③①②（我们是中国人）。', '完整句：wǒ men dōu shi zōng guó rén。我们都是中国人。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "五、音节排队，连成一句话（写编号）。(2)① zhuō chóng ② xiǎo jī ③ xǐ huan。", "options": null}', '②③①（小鸡喜欢吃虫）。', '完整句：xiǎo jī xǐ huan zhuō chóng。小鸡喜欢吃虫。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "五、音节排队，连成一句话（写编号）。(3)① zài ② dà shù shàng ③ xiǎo niǎo ④ jiào。", "options": null}', '③①②④（小鸟在大树上叫）。', '完整句：xiǎo niǎo zài dà shù shàng jiào。小鸟在大树上叫。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、看图写汉字。图片：手（掌）、嘴、耳、6、火。", "options": null}', '图1手→写「手」或「掌」；图2嘴→写「嘴」或「口」；图3耳→写「耳」；图4「6」→写「六」；图5火→写「火」。', '看图识字 5 个：手、嘴/口、耳、六、火。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、汉字变变变。1. 加一笔，再组词。「口」加一笔→___，组词：___。「云」加一笔→___，组词：___。", "options": null}', '「口」加一笔→「日」或「中」或「田」或「目」，如「日」组词：日子/生日/今日；「云」加一笔→「去」或「三」或「运」或「动」，如「去」组词：去年/回去。', '加一笔变形：「口」+一横→「日」/「中」/「田」/「目」；「云」+一横→「三」；「云」+一撇→「去」；「云」+一竖→「运」/「动」。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、汉字变变变。2. 减一笔，再组词。「天」减一笔→___，组词：___。「禾」减一笔→___，组词：___。", "options": null}', '「天」减一笔→「大」或「夫」，如「大」组词：大小/大家/大学；「禾」减一笔→「木」或「千」，如「木」组词：树木/木头。', '减一笔变形：「天」去一横→「大」/「夫」；「禾」去一撇→「木」/「千」。', 'paper', '[]', '["/static/qimg/mz_yw_p24.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "八、连一连。左边 5 张图（西瓜、积木、白菜、小鱼、石桥），中间 5 个字（积木、白菜、小鱼、石桥、西瓜），右边 5 个拼音（bái cài、xiǎo yú、shí qiáo、jī mù、xī guā）。用线把图、字、拼音连起来。", "options": null}', '西瓜—西瓜—xī guā；积木—积木—jī mù；白菜—白菜—bái cài；小鱼—小鱼—xiǎo yú；石桥—石桥—shí qiáo。', '三列错位连：图（实物）→字（汉字）→拼音（音节）。逐项配对。', 'paper', '[]', '["/static/qimg/mz_yw_p25.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "九、看图数一数，再填一填。草地上开了___朵小花。那里还住着___只母鸡和___只小鸡。", "options": null}', '图示估读：草地上开了约 4 朵小花；约住着 4 只母鸡和 6 只小鸡。', '看图数数：花朵按可见瓣数估读；母鸡为图中体形较大带冠的鸡，小鸡为雏鸡。一年级看图估读题，答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p25.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、阅读。陶行知《自立歌》：滴自己的汗，吃自己的饭，自己的事自己干，靠人、靠天、靠祖上，不算是好汉！(1)儿歌共有___句话。", "options": null}', '8 句。', '自立歌 8 行：①自立歌 ②滴自己的汗 ③吃自己的饭 ④自己的事自己干 ⑤靠人 ⑥靠天 ⑦靠祖上 ⑧不算是好汉。题目问「儿歌共有几句话」，按行计数为 8 句（标题不计）。', 'paper', '[]', '["/static/qimg/mz_yw_p25.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、阅读。(2)在儿歌中圈出读音是整体认读音节的字（重复的只圈一次）。", "options": null}', '圈出：自(zì)、吃(chī)、事(shì)、是(shì) 四个不重复的字。', '整体认读音节：zhi、chi、shi、ri、zi、ci、si、yi、wu、yu、ye、yue、yuan、yin、yun、ying。逐字排查《自立歌》：自 zì(zi 整体认读 ✓)、己 jǐ(非)、的 de(非)、汗 hàn(非)、吃 chī(chi 整体认读 ✓)、饭 fàn(非)、事 shì(shi 整体认读 ✓)、干 gàn(非)、靠 kào(非)、天 tiān(非)、祖 zǔ(非)、上 shàng(非)、不 bù(非整体认读，整体认读有 yi/wu/yu 但 bu 不是)、算 suàn(非)、是 shì(shi 重复不计)、好 hǎo(非)、汉 hàn(非)。', 'paper', '[]', '["/static/qimg/mz_yw_p25.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "十、阅读。(3)这首儿歌的作者是陶行知爷爷，他想告诉我们的道理是___。（填编号）①可以靠天吃饭 ②自己的事要自己干 ③可以多吃点饭。", "options": null}', '②。', '《自立歌》核心思想：自己的事自己干，靠人靠天靠祖上不算是好汉。故选 ②。', 'paper', '[]', '["/static/qimg/mz_yw_p25.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、看拼音，写词语。dōng xī、kè shì、yè zi、sì tiān、nǔ rén、mǎ shàng。", "options": null}', 'dōng xī→东西；kè shì→教室；yè zi→叶子；sì tiān→四天；nǔ rén→女人（或「努力」）；mǎ shàng→马上。', '拼音识字 6 词：dōng xī（东西）、kè shì（教室）、yè zi（叶子）、sì tiān（四天）、nǔ rén（女人，或「努力」读 nǔ lì）、mǎ shàng（马上）。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "二、帮小蚂蚁找到自己的家（在正确的拼音上打「√」）。6 只蚂蚁各爬 2 个拼音：qū/qiú、shuō/shuò、fēi/féi、pí/qí、shù/sù、chèn/chēng。", "options": null}', 'qiú(√)、shuō(√)、fēi(√)、pí(√)、shù(√)、chēng(√)。', '正确拼音：蛐→qiú（不是 qū 屈）；说→shuō；非→fēi；皮→pí；树→shù；称（chēng 称呼）→chēng。逐对勾选。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "三、按要求完成练习。认一认，记一记：蛙、江、莲、象、夏、叶 6 个生字。", "options": null}', '会认会记：蛙（wā）、江（jiāng）、莲（lián）、象（xiàng）、夏（xià）、叶（yè）。', '第五单元课文生字 6 个：蛙（青蛙）、江（江水）、莲（莲花）、象（大象）、夏（夏天）、叶（叶子）。会读会认。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、在不是同一类的词上画「\\\\」。1. 春天、冬天、秋天、四季、夏天。\\\"", "options": null}', '画「\」在「四季」上。', '春天/冬天/秋天/夏天都是具体季节；「四季」是春夏秋冬的统称，不是具体季节，画在「四季」上。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、在不是同一类的词上画「\\\\」。2. 竹子、小鸟、青蛙、小马、小鸭。\\\"", "options": null}', '画「\」在「竹子」上。', '小鸟/青蛙/小马/小鸭都是动物；「竹子」是植物，画在「竹子」上。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、在不是同一类的词上画「\\\\」。3. 青草、莲叶、大地、草芽、荷花。\\\"", "options": null}', '画「\」在「大地」上。', '青草/莲叶/草芽/荷花都是植物；「大地」是土地/泥土，画在「大地」上。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、在不是同一类的词上画「\\\\」。4. 江南、参加、说话、读书、下棋。\\\"", "options": null}', '画「\」在「江南」上。', '参加/说话/读书/下棋都是动词（活动）；「江南」是地名，画在「江南」上。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、小鱼回家（选字填空）。4 条小鱼分别有「了、子、人、大」4 个字；4 个鱼缸中央分别有「饼、句、来、口」4 个字。把鱼上的字和鱼缸中央字组成词。", "options": null}', '大→饼（大饼）；子→句（子句）；人→口（人口）；了→来（来了）。', '组词匹配：鱼上字+鱼缸字 或 鱼缸字+鱼上字。常见词：大饼 ✓、子句 ✓、人口 ✓、来了 ✓。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "六、反义词连一连。左边 8 字（男、反、正、关、南、女、北、开），右边 8 字（远、下、上、水、大、东、西、天）。", "options": null}', '男—女；反—正；关—开；南—北；上—下；东—西。剩余字（远、水、大、天）反义词未在图中给出，不强配对。', '确定反义配对 6 对：男-女、反-正、关-开、南-北、上-下、东-西。「远/水/大/天」其反义词（近/火/小/地）不在图中，按题目可连可不连。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、填一填。1.「子」共有___画，第一画是___。", "options": null}', '3 画，第一画是「横折」（或「⺄」）。', '「子」3 画：横折、横、竖钩。第一画为横折。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、填一填。2.「牙」共有___画，第二画是___。", "options": null}', '4 画，第二画是「竖折」。', '「牙」4 画：横、竖折、竖钩、撇。第二画为竖折。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、填一填。3.「用」共有___画，第二画是___。", "options": null}', '5 画，第二画是「横」。', '「用」5 画：撇、横、横折钩、点、横（部分教材笔画顺序略有差异）。第二画为横。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、填一填。4.「竹」共有___画，第三画是___，组词：___。", "options": null}', '6 画，第三画是「竖」（竹字头：短撇+横+短竖+点+横折+横），组词：竹子/竹林/竹叶。', '「竹」6 画：撇、横、竖、点、横、撇（竹字头 4 画：短撇+横+短竖+点；下面 2 画：竖+横折钩/撇）。第三画是竖。组词常见：竹子、竹林、竹叶。', 'paper', '[]', '["/static/qimg/mz_yw_p26.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "看图读一读。图中妈妈（长辈）说：「小朋友，我们又学习了几个单元的生字。现在我们来检查一下自己的学习情况吧！看看你能闯过几关。」", "options": null}', '小朋友，我们又学习了几个单元的生字。现在我们来检查一下自己的学习情况吧！看看你能闯过几关。', '看图观察妈妈角色的提示语，按原文抄写，注意「闯过几关」的「闯」字不要写成「闪」。', 'paper', '[]', '["/static/qimg/mz_yw_p27.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关·我会拼。1. 拼一拼，写出相应的笔画。shù gōu( )、héng gōu( )、shù wān( )、shù zhé( )、piě diǎn( )、héng zhé gōu( )、shù zhé zhé gōu( )。", "options": null}', '竖钩、横钩、竖弯、竖折、撇点、横折钩、竖折折钩。', '基本笔画名称：竖钩、横钩、竖弯、竖折、撇点、横折钩、竖折折钩。需按顺序记忆每个笔画的形状与名称。', 'paper', '[]', '["/static/qimg/mz_yw_p27.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第一关·我会拼。2. 将拼音和对应的汉字连起来。拼音：qiú、shù、cái、bù、wā、pí。汉字：蛙、步、秋、树、皮、采。", "options": null}', 'qiú—秋（求）；shù—树；cái—采；bù—步；wā—蛙；pí—皮。', '形声字音形结合：树(shù 木字旁)、步(bù 止字底)、蛙(wā 虫字旁)、皮(pí 皮部首)、采(cǎi 采字头)。qiú 对应「求/秋」，按一年上常用字优先「秋」。', 'paper', '[]', '["/static/qimg/mz_yw_p27.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关·我会拼。3. 给加点字注音。(1) 地( ) 上有很多水，妈妈生气地( ) 说：「是谁洒的水？」", "options": null}', 'dì；de。', '多音字「地」：作名词「土地、地面」读 dì（第四声）；作状语修饰动词（「生气地说」）读 de（轻声）。本题第一空「地上」是名词，第二空「地」修饰「说」是状语。', 'paper', '[]', '["/static/qimg/mz_yw_p27.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第一关·我会拼。3. 给加点字注音。(2) 天空飞来了一( ) 群鸟儿，一( ) 片片树叶飘落下来。", "options": null}', 'yì；yí。', '多音字「一」：单用或表序数读 yī；在「一群」中变调读 yì（第四声）；在「一片片」中变调读 yí（第二声）。', 'paper', '[]', '["/static/qimg/mz_yw_p27.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关·我会写。1. 比一比，再组词。了( )—子( )、四( )—西( )、大( )—天( )、十( )—土( )。", "options": null}', '了(了解/走了)；子(孩子/儿子)；四(四个/四季)；西(东西/西瓜)；大(大小/大人)；天(天空/今天)；十(十个/十分)；土(土地/泥土)。', '形近字辨析：了/子、四/西、大/天、十/土。每组均要会组两个常用词。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第二关·我会写。2. 写出下列词语的反义词。后—( )、男—( )、下—( )、关—( )、东—( )。", "options": null}', '前(后)、女(男)、上(下)、开(关)、西(东)。', '常见反义词：后-前、男-女、下-上、关-开、东-西。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关·我会写。3. 按要求完成练习。(1) 天那么蓝，那么高。（用加点词语写一句话）：___那么___，那么___。", "options": null}', '示例：花那么红，那么美。/ 河水那么清，那么凉。', '照样子用「那么……，那么……」写句子。「那么」指「很、非常」，前后结构相同。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关·我会写。3. 按要求完成练习。(2) 大雁一会儿排成个「人」字，一会儿排成个「一」字。（用加点词语写一句话）：___一会儿___，一会儿___。", "options": null}', '示例：小猫一会儿捉蝴蝶，一会儿追蜻蜓。/ 弟弟一会儿画画儿，一会儿搭积木。', '照样子用「一会儿……，一会儿……」写句子。表示两个动作短时间内交替发生。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "第三关·我会选。1. 选字填空。(1) 早上，太阳从 (东/西/大/小) 方 升起。傍晚，太阳从 (东/西/大/小) 方 边落下。", "options": ["东", "西", "大", "小"]}', '东；西。', '方位常识：太阳从东方升起（早上），从西方落下（傍晚）。东西相对。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会选。1. 选字填空。(2) 苹果( ) 果，西爪( ) 爪（图示估读：形近字「苹/平」与「瓜/呱」辨析）。", "options": null}', '苹；瓜。', '形近字辨析：苹果的「苹」是草字头（艹），与「平」区别；西瓜的「瓜」是独体字，与「呱」区别。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会选。2. 积累。(1) 江南( )采莲，莲叶何田田。", "options": null}', '可。', '古诗《江南》（汉乐府）：「江南可采莲，莲叶何田田。」意为江南可以采莲，莲叶多么茂盛鲜亮。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会选。2. 积累。(2) 雪( )大肚子一挺，他顽皮地说：「我此( )冬天。」", "options": null}', '孩子；时。', '课文《雪孩子》节选：「雪孩子大肚子一挺，他顽皮地说：『我此刻就是冬天。』」「孩」「时」是记忆重点。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会选。3. 把下列词语排成一句通顺的话（写编号）。①一群 ②飞 ③往南 ④大雁", "options": null}', '②④①③（「一群大雁往南飞」）。', '正确语序：「一群大雁往南飞」。编号：②飞 ④大雁 ①一群 ③往南。', 'paper', '[]', '["/static/qimg/mz_yw_p28.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "2.根据课文内容选词填空（填编号）。①光阴 ②金。(1) 一寸( )一寸( )，寸( )难买寸( )。（图示估读）", "options": null}', '①、②、②、①（一寸光阴一寸金，寸金难买寸光阴）。', '课文《一寸光阴一寸金》原文：「一寸光阴一寸金，寸金难买寸光阴。」第一空「一寸+时间」=光阴，第二空「一寸+金子」=金，第三空「寸+金」=金，第四空「寸+光阴」=光阴。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "2.根据课文内容选词填空（填编号）。①东 ②北 ③西 ④南。(2) 鱼戏莲叶( )，鱼戏莲叶( )，鱼戏莲叶( )，鱼戏莲叶( )。", "options": null}', '①、③、④、②（鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北）。', '古诗《江南》（汉乐府）原文：「鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。」四个空对应东、西、南、北四个方位。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "2.根据课文内容选词填空（填编号）。①青蛙 ②小鸟 ③小马 ④小鸭 ⑤小狗。(3) ( )画竹叶，( )画梅花，( )画枫叶，( )月牙，( )在洞里睡午觉（图示估读）。", "options": null}', '参考：①青蛙、②小鸟、③小马、④小鸭、⑤小狗（图示估读，答案不唯一）。', '图示估读：一年级课文《动物儿歌》或《四季》有动物主题。原题 5 个动物对应 5 种行为，根据课文大意推测，标「图示估读」说明以教材实际内容为准。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第四关：我爱阅读。1. 儿歌共有( )句话。儿歌内容：春天里，东风多，吹来燕子做新窝。夏天里，南风多，吹得太阳像盆火。秋天里，西风多，吹熟庄稼吹熟果。冬天里，北风多，吹得雪花纷纷落。", "options": null}', '4 句。', '儿歌共 4 个季节段，每段为一个长句（押韵），所以共有 4 句话。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关：我爱阅读。2. 选词填空（填编号）。①雪花 ②燕子 ③太阳。( )像盆火，( )做新窝，( )纷纷落。", "options": null}', '③、②、①（太阳像盆火，燕子做新窝，雪花纷纷落）。', '对应儿歌内容：夏天「吹得太阳像盆火」对应「太阳」；春天「吹来燕子做新窝」对应「燕子」；冬天「吹得雪花纷纷落」对应「雪花」。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第四关：我爱阅读。3. 想一想，连一连。左边：春天、夏天、秋天、冬天。中间：北风、东风、南风、西风。右边：太阳、果实、雪花、燕子。", "options": null}', '春天—东风—燕子；夏天—南风—太阳；秋天—西风—果实；冬天—北风—雪花。', '图中乱排需重新连：按儿歌原文匹配。春天东风燕子（新窝）；夏天南风太阳（像盆火）；秋天西风果实（吹熟庄稼吹熟果）；冬天北风雪花（纷纷落）。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第四关：我爱阅读。4. 我喜欢( )天，因为( )。", "options": null}', '示例：我喜欢春天，因为春天百花盛开，景色美丽。/ 我喜欢冬天，因为冬天可以堆雪人、打雪仗。', '开放题，鼓励学生表达自己的感受与课文内容的联系。答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第五关：我爱写话。选一幅图，写一写。提示：图中的小朋友在哪里干什么？", "options": null}', '图一（堆雪人）：示例：冬天到了，雪花从天上飘下来。小朋友在雪地里堆雪人，他们先把雪滚成一个大球做身子，再滚一个小球做脑袋，最后给雪人戴上了帽子，围上了围巾，堆好一个又白又胖的雪人，小朋友玩得真开心！/ 图二（放风筝）：示例：春天来了，天气真好。小明来到草地上放风筝。他一手拿着线轴，一手高高举起风筝，迎着风跑起来，风筝越飞越高，飞到了云朵上面，小明玩得真高兴！', '看图写话要点：时间、地点、人物、事情。看清图片内容（堆雪人 / 放风筝），按「什么时间—谁—在哪里—做什么—怎么样」的顺序写一段通顺连贯的话。', 'paper', '[]', '["/static/qimg/mz_yw_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、读一读，想一想，写一写。dà fēng( )、běn zi( )、lì zhèng( )、zhōng xīn( )、yǔ shuǐ( )、bǔ shāo( )。", "options": null}', '大风、本子、立正、中心、雨水、补刀（图示估读，第 6 词 bǔ shāo 待核）。', '根据拼音写出词语：dà fēng=大风、běn zi=本子、lì zhèng=立正、zhōng xīn=中心、yǔ shuǐ=雨水。第 6 个拼音 bǔ shāo 与图示「刀」有出入，标「图示估读」以原文为准。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "二、读一读，圈一圈。圈出正确的读音或字：作业(zuò zuó)、清水(qīng qīn)、风雪(xuě xuè)、男生(lán nán)、上山(shān sān)、三年(nián lián)、关(力 丽)、国(拱 棋)、一条(心 星)、工(厂 广)。", "options": null}', 'zuò、qīng、xuě、nán、shān、nián、丽、棋、心、厂。', '易混淆字音字形：作业zuò（一声，不读二声zuó）；清水qīng（后鼻音，不读qīn）；风雪xuě（上声，不读xùe）；男生nán（阳平，不读lán）；上山shān（阴平，不读sān）；三年nián（阳平，不读lián）。形近字：「关」应选下半部为「王」的「丽」（不是「力」）；「国」中应为「玉」（写作「棋」是同音借代）；「一条」应为「心」（不是「星」）；「工」下加撇为「厂」（不是「广」）。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "三、想一想，写一写。按笔顺规则写出下列字：叶、木、土、竹、下、天（每个字下方有「♢」标笔顺）。", "options": null}', '叶（丨𠃌一丨一）、木（一丨ノ丶）、土（一丨一）、竹（丿㇀一丨丶㇏）、下（一丨丶）、天（一ノ一丿）。', '基本笔顺：叶（5 画 丨𠃌一丨一）；木（4 画 一丨ノ丶）；土（3 画 一丨一）；竹（6 画 丿㇀一丨丶㇏）；下（3 画 一丨丶）；天（4 画 一ノ一丿）。要按「先横后竖、先撇后捺、从左到右、从上到下」的笔顺规则写。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "1. 从左写到右的字：写两个具有「从左写到右」笔顺规则的字（格子 2 个，猴子图示意）。", "options": null}', '示例：林（两木，从左到右）；明（左右结构：日+月，从左到右）。', '「从左到右」笔顺规则：左右结构的字先写左边的部分，再写右边的部分，如「林」「明」「好」「妈」等。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "2. 先写横后写竖的字：写三个具有「先横后竖」笔顺规则的字（格子 3 个）。", "options": null}', '示例：十、干、王（先横后竖，且上横短下横长）。', '「先横后竖」笔顺规则：当一个字同时有横和竖，先写横后写竖，如「十」「干」「王」「土」「干」等。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "3. 先写撇后写捺的字：写两个具有「先撇后捺」笔顺规则的字（格子 2 个）。", "options": null}', '示例：八、人、入（先撇后捺）。', '「先撇后捺」笔顺规则：当一个字同时有撇和捺，先写撇后写捺，如「八」「人」「入」「大」等。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、比一比，再组词。力( ) 刀( )、水( ) 小( )、午( ) 牛( )、去( ) 木( )、白( ) 云( )、本( ) 日( )。", "options": null}', '力(力气)、刀(刀子)；水(清水)、小(小草)；午(中午)、牛(水牛)；去(走去)、木(树木)；白(白云)、云(云朵)；本(本子)、日(日子)。', '形近字组词：力/刀（多加撇）、水/小（多一笔）、午/牛（多一笔）、去/木（多一笔）、白/云（多一笔）、本/日（多一笔）。每组都要会组两个常用词。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、填一填。1.「头」共有( )画，第四画是( )。", "options": null}', '5 画；丶（点）。', '「头」5 画，笔顺：丶、二、丨、丶、一（即点、横、竖、点、横）。第四画是「点」（丶）。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、填一填。2.「心」共有( )画，第二画是( )。", "options": null}', '4 画；卧钩。', '「心」4 画，笔顺：丶、㇇（卧钩）、丶、丶（即点、卧钩、点、点）。第二画是「卧钩」。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、填一填。3.「五」共有( )画，第二画是( )。", "options": null}', '4 画；竖。', '「五」4 画，笔顺：一、丨、一、一（即横、竖、横、横）。第二画是「竖」（丨）。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、填一填。4.「果」共有( )画，第五画是( )，组词( )。", "options": null}', '8 画；竖；水果。', '「果」8 画，笔顺：丨、𠃌、一、一、丨、一、丨、一（即竖、横折、横、横、竖、横、竖、横）。第五画是「竖」（丨）。组词：水果、苹果、果实、结果。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "六、连一连。字：林、休、众、明。配图：①人靠树 ②月亮+星 ③一棵树 ④三个女人（图示估读）。", "options": null}', '林—③（树）；休—①（人+树）；众—④（3个人，众字示意）；明—②（月亮，明=日+月，图以月示意）。', '字源与图对应：「林」=木+木，对应图③（大树）作单棵代表；「休」=亻+木，对应图①（人靠树）；「众」=人+人+人，对应图④（三人）；「明」=日+月，对应图②（月亮）。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "六、连一连。词：花、鸟、山清、柳绿。配词：虫、树、水秀、桃红。", "options": null}', '花—桃红；鸟—虫；山清—水秀；柳绿—桃红/树。', '成语搭配：「山清水秀」、「柳绿桃红」、「鸟语花香」是常见成语组合。鸟配虫（动物之间关系）；花配桃红（颜色）；山清配水秀（环境）；柳绿配桃红（春天景色）。', 'paper', '[]', '["/static/qimg/mz_yw_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、根据课文内容填空。1. ( ) 对 ( )，雪对风。"}', '云、雨。', '课文《对韵歌》（人教版一年级上）：「云对雨，雪对风，花对树，鸟对虫。」第一空填「云」，第二空填「雨」。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、根据课文内容填空。2. ( )( ) 不成众，独( ) 不成林。"}', '单、木。', '谚语「单丝不成线，独木不成林」。「单」两字+「独」+「木」一字。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "七、根据课文内容填空。3. ( ) 时( ) 识( )，呼作( ) 玉盘。"}', '小、不、月、白。', '古诗《古朗月行》（节选，李白）：「小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。」四个空依次填：小、不、月、白。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、阅读《加点歌》：广字加点建广场，亡字加点晒太阳，子字加点九子香，玉字加点是宝玉，鸟字加点鸟飞翔，万字加点看前方。1. 读一读，找规律，补上儿歌中缺少的字。"}', '每句「X字加点X」格式，缺字依次为：广、阳、九、玉、翔、方。', '规律：每句「某字+加点+新字」结构。依括号前字补：广→广、阳→阳、九→九、玉→玉、翔→翔、方→方。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、阅读《加点歌》2. 填一填：厂 + 、 = ( )"}', '广。', '「广」字形如「厂」+「丶」组合而成（字源演变），加点后即为「广」。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、阅读《加点歌》2. 填一填：鸟 + 、 = ( )（图示估读）"}', '鸟字加点示意（具体字因版本而异）。', '「鸟」字加点后字形变化不同教材不一，依原卷字为准。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、阅读《加点歌》2. 填一填：万 + 、 = ( )"}', '万加点示意（具体字因版本而异）。', '「万」字加点后字形变化需依原卷字为准。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "3. 我会编儿歌：( )字加点 ___。"}', '示例：日字加点照四方。', '仿照《加点歌》格式，挑选一个学过的字加一点编成儿歌。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "九、看图写话。提示：什么时候，同学们在干什么？请你用几句话写一写。（图：同学划船）"}', '示例：星期天，天气晴朗，同学们一起来到公园划船。他们一边划一边笑，玩得真开心！', '看图写话三要素：时间、地点、人物在做什么。写 2-3 句完整话即可。', 'paper', '[]', '["/static/qimg/mz_yw_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。t( )"}', '提。', '拼音「t」对应汉字笔画「提」（由下向上斜挑的笔画）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。wò gōu( )"}', '卧钩。', '拼音「wò gōu」= 卧钩（钩形先横后弯再上挑的笔画，如「心」第二画）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。héng xié gōu( )"}', '横斜钩。', '拼音「héng xié gōu」= 横斜钩（横起斜行再钩的笔画，如「风」第二画）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。dān rén páng( )"}', '单人旁。', '拼音「dān rén páng」= 单人旁（「亻」，单立人）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。jiāo sī páng( )"}', '绞丝旁。', '拼音「jiāo sī páng」= 绞丝旁（「纟」，绞字头/绞丝）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。zhǔ zì tóu( )"}', '主字头。', '拼音「zhǔ zì tóu」= 主字头（「主」上部，类似宝盖头）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。bāo zì tóu( )"}', '包字头。', '拼音「bāo zì tóu」= 包字头（「勹」）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关·我会拼 1. 拼一拼，写出相应的笔画和部首。bǎo gài tóu( )"}', '宝盖头。', '拼音「bǎo gài tóu」= 宝盖头（「宀」）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "第一关·我会拼 2. 给汉字的正确拼音涂上你喜欢的颜色。旗 qí/pí、对 duì/duí、皮 qí/pí、队 duì/duí。"}', '旗qí、对duì、皮pí、队duì。', '「旗」拼音 qí（不是 pí）；「对」拼音 duì（不是 duí）；「皮」拼音 pí（不是 qí）；「队」拼音 duì（不是 duí）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第二关·我会连 1. 猜一猜，连一连。字：休、看、泪、明。配图：①人靠树 ②手+眼 ③眼+水 ④日+月。"}', '休→①、看→②、泪→③、明→④。', '字谜：「休」= 亻+木（人靠树）；「看」= 手+目（手放眼上）；「泪」= 氵+目（水在眼边）；「明」= 日+月（日月同辉）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第二关·我会连 2. 读一读，连一连。字：朋、天、儿、木。书写规则：从左到右、先横后捺。"}', '朋→从左到右（两个月并排）；木→先横后捺（一横+撇+捺）；天→从左到右；儿→从左到右。', '「朋」由两个月组成，左右结构，书写从左到右；「天」= 一+大，从左到右；「儿」单字，从左到右；「木」= 一+丨+乀+㇏，先横后捺。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会写 1. 比一比，再组词。上( )、木( )、正( )、本( )、力( )、牛( )、立( )、午( )。"}', '上（上海/上学）；木（树木/木头）；正（正确/立正）；本（本子/课本）；力（力气/用力）；牛（牛羊/黄牛）；立（站立/立正）；午（中午/上午）。', '比一比是形近字组词：「上」加一横为「本」；「木」加一横为「本」；「力」加一撇为「牛」；「立」加一横为「正」；「午」加一撇为「牛」（但字形不同，注意区分）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关·我会写 2. 照样子，写一写。例：——（十）（十分）。大 → ( )( ) ( )( )。"}', '大→（天）（天上）；大→（太）（太阳）。', '「大」加一横为「天」；「大」加一点为「太」。一个字加一笔/减一笔可变成另一个字。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关·我会读 1. 多音字组词。色 sèn / shè。"}', 'sè（颜色）；shǎi（落色/掉色）。', '「色」是多音字：读 sè（颜色/色彩）；读 shǎi（口语「落色」「掉色」「褪色」）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关·我会读 1. 多音字组词。乐 lè / yuè。"}', 'lè（快乐/欢乐）；yuè（音乐/乐曲）。', '「乐」是多音字：读 lè（快乐、欢乐）；读 yuè（音乐、乐器、乐曲）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关·我会读 1. 多音字组词。声 shēng / shēn。"}', 'shēng（声音/声响）。', '「声」常见读音 shēng（声音、生声）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关·我会读 1. 多音字组词。男 lán / nán。"}', 'nán（男生/男孩）。', '「男」常见读音 nán（男生、男孩）。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关·我会读 3. 把花插进对应的花瓶，再填一填。6 个字：桃花、花、树、莲、桥、草。"}', '草字头（艹）花瓶：花、莲、苹、桃、草（植物）；木字旁花瓶：树、桥（木制结构）。', '按部首分类：「花、莲、苹、桃、草」均含草字头（艹），归入草字头花瓶；「树、桥」均含木字旁，归入木字旁花瓶。', 'paper', '[]', '["/static/qimg/mz_yw_p32.jpg"]', 0);
