INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "《小蜡笔》共有 ___ 个句子。"}', '6', '儿歌共 6 句：1)我爱你，可爱的小蜡笔。2)我用红色画国旗，3)我用绿色画草地，4)我用蓝色画海洋，5)我用黄色画金鸡，6)十二种颜色，画出家乡的美丽。答：6。', 'paper', '[]', NULL, 0);
