INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "连线：绿色的—___；黄色的—___；蓝色的—___；红色的—___。"}', '草地；金鸡；海洋；国旗', '儿歌原文：红色—国旗，绿色—草地，蓝色—海洋，黄色—金鸡。答：绿色—草地；黄色—金鸡；蓝色—海洋；红色—国旗。', 'paper', '[]', NULL, 0);
