INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 3, '{"stem": "选出没有错别字的一项。（  ）n①看见 刀法 两头 影子n②蓝色 双手 明天 晚上n③黑狗 前后 才能 姐妹n④朋友 小船 闪亮 常常", "options": ["①看见 刀法 两头 影子", "②蓝色 双手 明天 晚上", "③黑狗 前后 才能 姐妹", "④朋友 小船 闪亮 常常"]}', '②', '【图示估读】常见答案：②「蓝色」为标准写法。①「刀法」、③「姐妹」等可能为错别字。答：②。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '单选', 3, '{"stem": "选出表达正确的一项。（  ）n①叔叔是妈妈的爸爸n②爷爷是爸爸的爸爸n③弟弟的年龄一般比哥哥大n④日字旁的字大多和月亮有关", "options": ["①叔叔是妈妈的爸爸", "②爷爷是爸爸的爸爸", "③弟弟的年龄一般比哥哥大", "④日字旁的字大多和月亮有关"]}', '②', '①错：叔叔是爸爸的弟弟；②对：爷爷是爸爸的爸爸；③错：弟弟比哥哥小；④错：日字旁多与太阳有关，月字旁才与月亮有关。答：②。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "「云、我、头、在」中笔画数是五画的有：___。"}', '头', '云 4 画、我 7 画、头 5 画✓、在 6 画。答：头。', 'paper', '[]', NULL, 0);
