INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "「的」共有 8 笔，第六笔是 ___。"}', '撇（丿）', '「的」8 笔：撇、竖、横折、点、横、撇、横折钩、横。第六笔是撇。答：撇。', 'paper', '[]', NULL, 0);
