INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "「好」共有 ___ 笔，第五笔是 ___，和它部首相同的字有 ___ 和 ___。"}', '6，撇，妈、她', '「好」6 笔：撇点、撇、横、横、撇、横。第五笔撇。女字旁字：妈、她、姐、姑。答：6 笔，撇，妈、她。', 'paper', '[]', NULL, 0);
