INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "蘑菇连线：弯弯的—___，蓝蓝的—___，闪闪的—___，青青的—___。"}', '月儿，天空，星星，草地', '弯弯的月儿，蓝蓝的天空，闪闪的星星，青青的草地。答：弯弯的—月儿；蓝蓝的—天空；闪闪的—星星；青青的—草地。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "把下列字按结构分类：前、里、早、晚、外、白、后。"}', '独体字：白、里、后；上下结构：早；左右结构：前、晚、外', '「前」左右结构（月+刀）；「里」独体字；「早」上下结构（日+十）；「晚」左右结构（日+免）；「外」左右结构（夕+卜，教材归左右结构）；「白」独体字；「后」独体字。答：独体字：白、里、后；上下结构：早；左右结构：前、晚、外。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "把下列字按结构分类：船、星、月、它、好、也。"}', '独体字：星、月、它、好、也；左右结构：船', '「船」左右结构（舟+几）；其余独体字。答：独体字：星、月、它、好、也；左右结构：船。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "成语连线：种瓜得瓜—___，后人乘凉—___，千里之行—___，百尺竿头—___。"}', '前人栽树，前人栽树，始于足下，更进一步', '种瓜得瓜—前人栽树；后人乘凉—前人栽树（「前人栽树，后人乘凉」）；千里之行—始于足下；百尺竿头—更进一步。答：种瓜得瓜—前人栽树；后人乘凉—前人栽树；千里之行—始于足下；百尺竿头—更进一步。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "为下列词语排序（写编号），别忘记 ___。"}', '标点符号', '【图示估读】原图未显示具体词语和「别忘记」内容。常见为「别忘记加标点（句号/问号）」。答：标点符号。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "连词成句，并加上标点：①坐 ②小小的 ③在 ④那里 ⑤我。"}', '我坐在小小的那里。', '连词成句：我（⑤）+ 坐（①）+ 在（③）+ 小小的（②）+ 那里（④），加句号。答：我坐在小小的那里。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "照样子，写句子。例：影子就像一条小黑狗。（  ）就像（  ）。"}', '月亮就像一条小船', '比喻句仿写。如：月亮就像一条小船。开放题，答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "用加点词造句：影子【常常】陪着我。（  ）"}', '老师常常关心我们', '用「常常」造句，表经常。如：老师常常关心我们。开放题，答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "阅读《影子》短文，这篇短文共有（  ）个自然段，请在文中标上自然段号。"}', '5', '【图示估读】短文按空行/缩进分自然段：伞出场（小红伞）、小绿伞、小蓝伞、小黄伞+总结、小花伞及结尾，共 5 个自然段。答：5。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读《影子》：选择合适的词语填在文中横线上（填序号）。①红红的 ②绿绿的 ③黄黄的 ④黑黑的 ⑤蓝蓝的。小绿伞影子是（  ），小蓝伞影子是（  ），小黄伞影子是（  ），大家的影子都是（  ）。"}', '②绿绿的，⑤蓝蓝的，③黄黄的，④黑黑的', '小绿伞对应绿绿的（②），小蓝伞对应蓝蓝的（⑤），小黄伞对应黄黄的（③），结尾揭示影子都是黑黑的（④）。答：②，⑤，③，④。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "阅读《影子》：小花伞让大家看地上的影子，小花伞看出自己的影子是（  ）的。最后他们看了以后是怎样的表现？用「____」画出相关语句。"}', '黑黑的；画「小红伞一看就愣住了，小绿伞、小蓝伞、小黄伞都愣住了。」', '【图示估读】影子没有光的地方都是黑的，故小花伞的影子也是黑黑的。表现句为「小红伞一看就愣住了，小绿伞、小蓝伞、小黄伞都愣住了。」', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "阅读《影子》：为什么他们的影子都是黑色的呢？请你用「____」画出表示原因的句子。"}', '画「你们挡住了我的光，没有光的地方，都是黑的。」', '太阳公公说的话点明原因：挡住了光，没有光的地方都是黑的。答：画该句。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "看图写话：图上画的是谁？他的身后有什么？请你用第六课的话写几句话。"}', '开放题', '看图写话，开放题。用第六课（影子相关）的语言描写，如：小朋（小动物）身后有影子，太阳出来就有影子等。答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "拼一拼，写出「我」字的部首（偏旁）。"}', '戈', '【图示估读】「我」字的偏旁是「戈」部。答：戈。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "写出下列偏旁：反犬旁、舟字旁、门字框、女字旁、月字旁、禾字旁、日字旁。"}', '犭、舟、门、女、月、禾、日', '常见偏旁书写。答：犭（反犬旁）、舟（舟字旁）、门（门字框）、女（女字旁）、月（月字旁）、禾（禾字旁）、日（日字旁）。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "读一读，圈出汉字的正确拼音：闪(shǎn/sǎn)、星(xīng/xīn)、常(chán/cháng)、影(yǐng/yīn)、能(nén/néng)、姐(jiě/jěi)。", "options": ["shǎn/sǎn", "xīng/xīn", "chán/cháng", "yǐng/yīn", "nén/néng", "jiě/jěi"]}', 'shǎn、xīng、cháng、yǐng、néng、jiě', '选择正确读音。闪 shǎn、星 xīng、常 cháng、影 yǐng、能 néng、姐 jiě。答：shǎn、xīng、cháng、yǐng、néng、jiě。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "看拼音，写词语：wǒ men、hǎo xīn、gōng rén、yǒu shí、ér zi、bà mā。"}', '我们、好心、工人、有时、儿子、爸妈', '看拼音写词语。答：我们、好心、工人、有时、儿子、爸妈。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "加一加，减一减：女+（  ）=好；月+（  ）=（  ）；会-（  ）=（  ）；他-（  ）=（  ）。"}', '女+子=好；月+日=明；会-人=云；他-亻=也', '【图示估读】加一加减一减。女+子=好；月+日=明（或月+几=有）；会-人=云；他-亻=也。答：女+子=好；月+日=明；会-人=云；他-亻=也。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "按要求填空：「的」共有（  ）笔，第六笔是（  ）。"}', '8 笔，撇', '「的」共 8 笔：撇、竖、横折、横、竖、撇、点、点。第六笔是撇。答：8 笔，撇。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "按要求填空：「在」共有（  ）笔，第三笔是（  ）。"}', '6 笔，撇', '「在」共 6 笔：横、撇、竖、横、竖、横。第三笔是撇。答：6 笔，撇。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "按要求填空：「里」共有（  ）笔，第五笔是（  ），拼音是（  ）。"}', '7 笔，竖，lǐ', '「里」共 7 笔：竖、横折、横、横、竖、横、横。第五笔是竖。拼音 lǐ。答：7 笔，竖，lǐ。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "找朋友（连一连）：左、黑、平、小 —— 大、右、白、晚。"}', '左—右、黑—白、小—大（平—晚 估读）', '【图示估读】找反义词配对：左—右、黑—白、小—大。平字反义「仄」不在选项中，疑为「平—晚」或印刷设置，估读存疑。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "找朋友（连一连）：看、朋、做、蓝 —— 工、天、见、友。"}', '看—见（看见）、朋—友（朋友）、蓝—天（蓝天）、做—工（做工）', '【图示估读】组词配对：看见、朋友、蓝天、做工。答：看—见、朋—友、蓝—天、做—工。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "积累，连一连：种瓜得瓜、前人栽树、千里之行、百尺竿头 —— 后人乘凉、种豆得豆、更进一步、始于足下。"}', '种瓜得瓜—种豆得豆；前人栽树—后人乘凉；千里之行—始于足下；百尺竿头—更进一步', '谚语配对。答：种瓜得瓜—种豆得豆；前人栽树—后人乘凉；千里之行—始于足下；百尺竿头—更进一步。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "根据课文内容选择填空（填序号）：①小小的 ②弯弯的 ③闪闪的 ④蓝蓝的。我在（  ）那里坐，只看见（  ）星星（  ）天。"}', '①小小的；③闪闪的；④蓝蓝的', '出自课文《小小的船》：「我在小小的船里坐，只看见闪闪的星星蓝蓝的天。」答：①小小的，③闪闪的，④蓝蓝的。', 'paper', '[]', '["/static/qimg/mz_yw_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "选择合适的形容词填在下面的句子中（填编号）。①青青的 ②弯弯的 ③清清的 ④蓝蓝的。今天天气特别好，（ ）天空 中飘着几朵白云。（ ）草地 河岸上有几只可爱的小狗在玩耍。河水（ ），小河中央还有一条（ ）的小船。"}', '④蓝蓝的、①青青的、③清清的、②弯弯的', '形容词搭配：蓝蓝的天空、青青的草地、清清的河水、弯弯的小船。答：④蓝蓝的、①青青的、③清清的、②弯弯的。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读诗歌《阳光》（林武宪）：阳光在（  ），在（  ），在（  ），在妈妈的眼里。阳光会爬、会笑、会流、会（  ）。"}', '窗上、花上、溪上、闪', '出自诗歌《阳光》：阳光在窗上爬着；阳光在花上笑着；阳光在溪上流着；阳光在妈妈的眼里闪着。答：窗上、花上、溪上、闪。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "阳光还会在哪里做什么？你能模仿上面的小诗也来写一写吗？（  ）"}', '开放题', '仿写诗歌，开放题。示例：阳光在叶上舞着 / 阳光在草地上跑着 / 阳光在水面上跳着。答案不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读诗歌《最轻的孩子》（圣野）：「我」做哪些事最轻最轻？读读小诗，用「○」把它们圈出来。"}', '搬凳子、走路、敲门', '出自诗歌《最轻的孩子》：我搬凳子的时候最轻最轻；我走路的时候最轻最轻；我敲门的时候最轻最轻。圈出「搬凳子」「走路」「敲门」三处。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "「我」（ ）的时候，最响最响。"}', '回答老师的问题', '出自诗歌《最轻的孩子》最后两句：「可我回答老师的问题 却最响最响」。答：回答老师的问题。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "照样子，写一写。（1）最轻最轻 最美最美 → 最大（  ） 最快（  ）。（2）最（  ）最（  ）。"}', '（1）最重 最慢（开放）；（2）开放', '照样子，用「最…最…」结构仿写。（1）示例：最大最重、最快最慢；（2）自由仿写，如：最高最高、最长最长。答不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "用上「最……最……」，我能说几句诗给小伙伴们听一听。我（ ）的时候，最（ ）最（ ）。我（ ）的时候，最（ ）最（ ）。老师说我，是一个最（ ）的孩子。"}', '开放题', '用「最…最…」结构仿写诗歌。示例：我看书的时候最静最静；我唱歌的时候最响最响；老师说我是一个最爱看书的孩子。答不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "看图写话。要求：写清是什么时候，谁在哪里干什么，心情怎样。（  ）"}', '开放题', '【图示估读】看图写话，图中小孩在海边/沙滩玩耍。要求写清时间、人物、地点、事件、心情。示例：夏天到了，小明和小红在沙滩上开心地玩耍，他们的心情真愉快！答不唯一。', 'paper', '[]', '["/static/qimg/mz_yw_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "看拼音，写词语：duō shǎo、niú yáng、nǐ wǒ、shí hou、chū qù、bàn tiān。"}', '多少、牛羊、你我、时候、出去、半天', '看拼音写词语。答：多少、牛羊、你我、时候、出去、半天。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "为加点字注音：1. 一只（ ）乌鸦口渴了，到处找水喝。2. 只（ ）要用手和脑，事情都能做得好。3. 不（ ）久，花更红了，草更绿了。4. 我们今天晚上不（ ）去奶奶家。"}', 'zhī、zhǐ、bù、bù', '一字多音注音。「只」表量（一只）读 zhī；表仅（只要）读 zhǐ。「不」在去声前变调读 bú，本题统一记作 bù。答：1. zhī、2. zhǐ、3. bù、4. bù。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "选出拼音完全正确的一项。（  ）①尾（uěi） 最（zuì） 短（duǎn） ②旁（páng） 进（jìng） 谁（shuí） ③许（wǔ） 放（fàng） 彩（cǎi） ④答（dá） 久（jiǔ） 更（gèng）"}', '④', '拼音正误辨析。①尾 wěi（非 uěi）；②进 jìn（非 jìng）；③许 xǔ（非 wǔ）；④全对。答：④。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "选出没有错别字的一项。（  ）①到处 尾巴 办法 ②工鸡 天空 回答 ③做工 半天 许多 ④采色 看见 放手"}', '①', '错别字辨析。②「工鸡」应为「公鸡」；④「采色」应为「彩色」。①「到处 尾巴 办法」均正确；③「半天 做工 许多」亦无误但本卷出题者选 ①。答：①。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "选出和课文内容相符的一项。（  ）①鸭子的尾巴最好看。 ②乌鸦想出了好办法，喝到了水。 ③大雨点儿要去有花有草的地方。 ④鸭子的尾巴弯。"}', '②', '课文内容辨析。①《比尾巴》说各有特点非「最好看」；②《乌鸦喝水》乌鸦用石子喝到水，正确；③《雨点儿》中是大雨点儿去「没有花没有草的地方」，小雨点儿去有花有草的地方，故③错；④《比尾巴》中鸭子的尾巴「扁」非「弯」。答：②。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "找出偏旁相同的字（填编号）。①进 ②把 ③近 ④黑 ⑤找 ⑥点 ⑦空 ⑧它 ⑨家。辶：（  ）；扌：（  ）；宀：（  ）；灬：（  ）。"}', '①③；②⑤；⑦⑧⑨；④⑥', '偏旁归类。辶（走之底）：进、近；扌（提手旁）：把、找；宀（宝盖头）：空、它、家；灬（四点底）：黑、点。答：辶 ①③；扌 ②⑤；宀 ⑦⑧⑨；灬 ④⑥。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "读一读，分一分：山 风 月 小 水 用。"}', '全部为独体字', '【图示估读】六个字均为独体字/象形字：山（山形）、风（风形）、月（月形）、小（细小）、水（水流）、用（使用）。六个字都无法拆出明确偏旁部首，故均为「独体字」。答：全部为独体字。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "先中间后两边的字，写三个：（ ）（ ）（ ）。"}', '开放题', '【图示估读】先中间后两边的字，如：小、水、禾、米、办。答不唯一，写三个即可。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "先外后内的字，写三个：（ ）（ ）（ ）。"}', '开放题', '【图示估读】先外后内的字，如：月、用、同、问、闹。答不唯一，写三个即可。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连一连。一只、一个、一颗、一把 —— 瓶子、公鸡、雨伞、石子。"}', '一只—公鸡；一个—瓶子；一颗—石子；一把—雨伞', '量词搭配。公鸡用「只」（飞禽/小动物）；瓶子用「个」（无明显形状特征的可数名词）；石子用「颗」（小颗粒状物体）；雨伞用「把」（有柄器物）。答：一只—公鸡；一个—瓶子；一颗—石子；一把—雨伞。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "看清字的结构，连一连。第一行星形：阳、送、旁、共、奖；下方方框：花、口、作。图上已印出：阳→花。"}', '阳→花（其余连线待校验）', '字形结构分类题。星形里5个字：阳（左右结构：阝+日）、送（半包围：辶+关）、旁（半包围/左右：立+方，方在右可视为左右）、共（上下：八+厶）、奖（上下：大+将）。方框里3个字「花、口、作」非结构名称，而是字例：花（上下：艹+化）、口（独体字）、作（左右：亻+乍）。原图已印出唯一可见连线「阳→花」，但「阳=左右」与「花=上下」结构不同，疑为配对题（如部首/形近字/同音字）而非结构分类。其余 4 个星形（送、旁、共、奖）→ 3 个方框的连线未印出，无法精确判定。答：阳→花（图中已印），其余待校验。建议以教材原题为准。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "看清字的结构。第二行星形（5个）：送、旁、共、共、奖（按字形结构分类）。"}', '【图示估读】分类待校验', '【图示估读】第二行星形5个字：送（半包围：辶+关）、旁（半包围/左右：立+方）、共（上下：八+厶）、奖（上下：大+将）。疑为「按字形结构分一分」题（上下/半包围/左右等），但图上无明确分类标准与目标容器，连线关系不清晰，无法精确判定。建议以教材原题为准。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "根据课文内容排一排。（  ）乌鸦把小石子一颗一颗地放进瓶子里。（  ）乌鸦看见一个瓶子，瓶子里有水。（  ）瓶子里的水渐渐升高，乌鸦就喝着水了。（  ）可是瓶子里的水不多，瓶口又小，乌鸦喝着水。"}', '2、4、1、3', '《乌鸦喝水》课文顺序：①（2）乌鸦看见一个瓶子，瓶子里有水；②（4）可是瓶子里的水不多，瓶口又小，乌鸦喝着水；③（1）乌鸦把小石子一颗一颗地放进瓶子里；④（3）瓶子里的水渐渐升高，乌鸦就喝着水了。答：2、4、1、3。', 'paper', '[]', '["/static/qimg/mz_yw_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "根据课文内容填空：猴子的尾巴（____），兔（____）的尾巴短。", "options": null}', '长；子', '出自课文《比尾巴》。猴子尾巴长，兔子尾巴短。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "根据课文内容填空：解落（____）秋（____），能（____）。", "options": null}', '三；叶；开二月花', '出自古诗《风》（李峤）：解落三秋叶，能开二月花。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "根据课文内容填空：过江千（____）浪，入竹万竿斜。", "options": null}', '尺', '出自古诗《风》（李峤）：过江千尺浪，入竹万竿斜。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连词成句（写编号，并加上标点）：①尾巴 ②最 ③谁的 ④好看", "options": null}', '③④①②。', '句子：谁的尾巴最好看？', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连词成句（写编号，并加上标点）：①尾巴 ②是 ③我的 ④最 ⑤长的", "options": null}', '③①②④⑤。', '句子：我的尾巴是最长的。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连词成句（写编号，并加上标点）：①长出了 ②小花 ③地上 ④和 ⑤小草", "options": null}', '③①②④⑤。', '句子：地上长出了小花和小草。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "连词成句（写编号，并加上标点）：①旁边 ②乌鸦 ③有 ④许多 ⑤看见 ⑥小石子", "options": null}', '②⑤①③④⑥。', '句子：乌鸦看见旁边有许多小石子。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 1, '{"stem": "阅读《时钟花》：短文共有（____）句话。", "options": null}', '4', '全文共 4 个句号，故 4 句话。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 1, '{"stem": "阅读《时钟花》：小白兔请（____）帮忙想办法，后者送给它（____）盆花。", "options": null}', '小山羊；三', '关键句：它请小山羊帮忙想办法，小山羊送给它三盆花。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读《时钟花》连一连：牵牛花/午时花/夜来香 对应 早晨/中午/晚上（按图上右侧三组时间选项位置）。", "options": null}', '牵牛花—晚上；午时花—早晨；夜来香—中午（按图印位置）', '图上右侧印出三组时间与花名对应：牵牛花—晚上、午时花—早晨、夜来香—中午（印面位置如此，与常理「牵牛花-早晨」相反，疑为题目印错，按图面位置记录）。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '解答', 3, '{"stem": "看图写话：图上画着一个小朋友在雪地里滑雪。提示：这是什么季节？图上画着谁？他在干什么？心情怎么样？", "options": null}', '开放题（参考：冬天到了，小明在雪地里滑雪，他玩得真开心！）', '提示三问：什么季节/画着谁/干什么/心情。看图：雪地+滑雪小朋友+笑脸。开放式答案。', 'paper', '[]', '["/static/qimg/mz_yw_p39.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "拼一拼，写出相应的笔画和部首：树木（____）、横钩（____）、提手旁（____）、把字头（____）、斜刀头（____）、走之底（____）、四点底（____）、血字头（____）。", "options": null}', '【图示估读存疑】树木=横竖撇捺；横钩=㇀；提手旁=扌；把字头=㔾；斜刀头=刂；走之底=辶；四点底=灬；血字头=⺗', '【图示估读存疑】图字小，笔画名/部首名按常用字形给出，建议以教材原题为准核对。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "给汉字的正确拼音涂上颜色：伞（sǎn / shǎn）；谁（suí / shéi）。", "options": null}', '伞 sǎn；谁 shéi', '伞读 sǎn（三声），谁读 shéi（二声）。shǎn（伞的错读形近）、suí（谁的错读）为误读。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "给加点字正确读音涂色：旁（páng / pán）；放（fàng / fǎng）；问（wèn / jiān）；答（dá / bá）。", "options": null}', '旁 páng；放 fàng；问 wèn；答 dá', '正确读音：旁边 páng、放学 fàng、问题 wèn、回答 dá。其他读音为不常见错读。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "比一比，再组词：只（____）、个（____）、出（____）、口（____）、人（____）、山（____）。", "options": null}', '只（一只）；个（一个）；出（出门）；口（口里）；人（大人）；山（上山）', '6 字组词，参考常见搭配。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读句子，写生字：乌鸦把许多颗（____）子放进瓶子里。", "options": null}', '石', '出自《乌鸦喝水》。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读句子，写生字：小兔想（____）了好办法运南瓜。", "options": null}', '出', '出自《小兔运南瓜》。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读句子，写生字：暑假（____）到了，你最想（____）去？", "options": null}', '【图示估读存疑】里/哪；哪/什', '【图示估读存疑】图字小糊，常见为「里」与「哪」或类似生字组合，建议以教材原题为准。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "读句子，写生字：小动物们在（____）尾巴。", "options": null}', '【图示估读存疑】比', '【图示估读存疑】小动物们在一起比尾巴，常用生字为「比」，但图字小，建议以教材原题为准。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "「巴」共有（____）笔，第二笔是（____）。", "options": null}', '4；横折（ㄅ）', '巴笔顺：横折、竖、横、竖弯钩。第二笔为横折。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "「从」共有（____）笔，第二笔是（____）。", "options": null}', '4；点（丶）', '从笔顺：点、撇、点、撇（人人）。第二笔为点。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "「来」共有（____）笔，第五笔是（____）。和它意思相反的字是（____）。", "options": null}', '7；撇（㇓）；去', '来笔顺：横、竖、点、撇、横、竖、撇折。第五笔为撇。与来相反为去。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "「见」共有（____）笔，第二笔是（____）。组词：（____）。", "options": null}', '4；竖（丨）；看见', '见笔顺：竖、竖弯钩、撇、捺。第二笔为竖。组词：看见。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "把字谜和字连一连：水边去一去／用上两点法／鸟儿闭眼睛／日中来会谈 对应 乌/法/许/办。", "options": null}', '【图示估读存疑】建议以教材原题连线为准', '字谜超纲，且图上无明显连线标注。候选推理：鸟儿闭眼睛=鸟去一点=乌；其余按字形结构推测但不确定。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "把书写规则和字连一连（图右下角，字迹小模糊）。", "options": null}', '【图示估读存疑】建议以教材原题为准', '右下角图字小糊，无法精确判定。', 'paper', '[]', '["/static/qimg/mz_yw_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "1. 按笔顺规则写下列字：先外后内（____）　先左到右（____）　先撇后捺（____）　先中间后两边（____）（对应字：叶、小、月、人）。"}', '"先外后内（月，丿𠃌一一，4 画）；先左到右（叶，丨𠃌一一丨，5 画）；先撇后捺（人，丿㇏，2 画）；先中间后两边（小，亅丶丶，3 画）。【注：图上印的规则与字配对错位（叶配先外后内、小配先左到右、月配先撇后捺、人配先中间后两边），属印刷错位，按权威笔顺规则作答】"', '"汉字笔顺基本规则：先横后竖、先撇后捺、从左到右、从上到下、从外到内、先中间后两边。月先外后内、叶先左到右、人先撇后捺、小先中间后两边。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "3. 找朋友。把下列字与对应的图连起来：第一组 5 个鱼形字（池、进、打、们、扫）；第二组三个鱼缸图（鱼身标有偏旁/字符提示）。"}', '"【图示估读】第一组：5 个鱼形字连到对应图形；第二组：三个鱼缸图，鱼身字符（形似土、t、L 等）与字配对，具体按图示，估读存疑。"', '"考察形声字/字形结构认读，鱼形图标与鱼缸内含偏旁提示（池氵、进辶、打扌、们亻、扫扌）。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "第四关 1. 根据课文内容选择合适的选项（填编号）。①弯 ②扁 ③长 ④短 ⑤好像一把伞 ⑥最好看。"}', '"猴子的尾巴③长；兔子的尾巴④短；松鼠的尾巴⑤好像一把伞；公鸡的尾巴①弯；鸭子的尾巴②扁；孔雀的尾巴⑥最好看。"', '"课文《比尾巴》：猴子长、兔子短、松鼠好像一把伞、公鸡弯、鸭子扁、孔雀最好看。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "（2）选词填空。①三秋叶 ②万竿斜 ③二月花 ④千尺浪。解落（____），能开（____），过江（____），入竹（____）。"}', '"解落①三秋叶；能开③二月花；过江④千尺浪；入竹②万竿斜。"', '"古诗《风》（李峤）：「解落三秋叶，能开二月花。过江千尺浪，入竹万竿斜。」"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "2. 选择合适的量词（填编号）。①朵 ②颗 ③张 ④片 ⑤个 ⑥幅。"}', '"一（⑥）图画；一（③）白纸；一（⑤）瓶子；一（②）星星；一（④）树叶；一（①）红花。"', '"量词搭配：图画配「幅」、白纸配「张」、瓶子配「个」、星星配「颗」、树叶配「片」、红花配「朵」。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第五关 阅读《雪花》。1. 短文共有（____）个自然段。"}', '"3（个自然段）。"', '"短文共 3 个自然段：①风吹雪花飘；②雪花落大树；③雪花落田地。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第五关 阅读《雪花》。2. 按短文内容填空：雪花落在（____），给树枝穿上雪白的「棉衣」；雪花落在（____），给麦子盖上厚厚的「棉被」。"}', '"雪花落在大树上，给树枝穿上雪白的「棉衣」；雪花落在田地里，给麦子盖上厚厚的「棉被」。"', '"短文第二段：雪花落在大树上；第三段：雪花落在田地里。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第五关 阅读《雪花》。3. 仿写词语：纷纷扬扬（____）。"}', '"示例：开开心心、高高兴兴、快快乐乐、干干净净、整整齐齐。"', '"AABB 式词语仿写。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 2, '{"stem": "第五关 阅读《雪花》。4. 雪花还会落在什么地方？"}', '"开放题示例：雪花落在屋顶上，给屋顶盖上「棉被」；雪花落在山上，给大山披上白衣。"', '"仿照短文表达方式（雪花落在 XX，给 XX 穿上/盖上棉衣/棉被）展开想象。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 3, '{"stem": "第六关 我会写话。新年快到了，给家人或朋友几句祝福的话吧！"}', '"开放题示例：新年到，祝福到！祝爷爷奶奶身体健康，祝爸爸妈妈工作顺利，祝小朋友们学习进步！"', '"考查写话能力：1-3 句完整通顺的祝福语，使用常用礼貌用语。"', 'paper', '[]', '["/static/qimg/mz_yw_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音，写词语。gōng cháng（____）　yuè ér（____）　lái qù（____）　lì zhèng（____）　shū běn（____）　kāi guān（____）　bàn tiān（____）　xià wǔ（____）　zuǒ yòu（____）"}', '"工厂、月儿、来去、立正、书本、开关、半天、下午、左右。"', '"9 个常用双字词的拼音认读与书写，复习第一至四单元识字写字。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "二、按要求给下列字分类（按笔画数分 4 类）。8 个字：头、女、比、长、马、竹、用、有。"}', '"三画：女、马；四画：比、长；五画：头、用；六画：竹、有。"', '"笔画数：女(3)、马(3)；比(4)、长(4)；头(5)、用(5)；竹(6)、有(6)。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "三、比一比，再组词。牙（____）/目（____）　四（____）/西（____）　刀（____）/力（____）　果（____）/里（____）。"}', '"牙（牙齿、月牙）；目（目光、耳朵/耳目）；四（四个、四季）；西（西瓜、西方）；刀（小刀、菜刀）；力（力气、力量）；果（水果、果子）；里（里面、公里）。"', '"形近字辨析组词，区分字形相近字的不同含义和用法。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。1. \\\"木\\\"加一笔变成（____）。\\\"", "options": null}', '"本、末、未、禾（任写一个即可，最常见\"本\"或\"末\"）。"', '"\"木\"加横→本；加点→末；改横为撇→未；加撇→禾。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。2. \\\"十\\\"加一笔变成（____）。\\\"", "options": null}', '"土、干、士、千（任写一个即可，最常见\"土\"）。"', '"\"十\"加横→土；加竖钩→干；上加横→士；下加竖→千。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。3. \\\"口\\\"加一笔变成（____）。\\\"", "options": null}', '"日、目、田、白（任写一个即可，最常见\"日\"或\"目\"）。"', '"\"口\"中间加横→日；上下各加一横→目；四边封口→田；口内加撇→白。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。4. \\\"大\\\"加一笔变成（____）。\\\"", "options": null}', '"太、犬、天、夫（任写一个即可，最常见\"太\"或\"天\"）。"', '"\"大\"加点→太；改捺为点→犬；上加点→天；下加横→夫。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。5. \\\"个\\\"减一笔变成（____）。\\\"", "options": null}', '"人（最常见）。"', '"\"个\"为撇、捺、竖三画，减掉竖画即\"人\"（撇、捺）。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、汉字小魔术。6. \\\"去\\\"减一笔变成（____）。\\\"", "options": null}', '"云、土、专（任写一个即可，最常见\"云\"或\"土\"）。"', '"\"去\"为土+厶，减下部分→土；减上部分→厶（不独立成字）；改折为点状→云。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、按课文内容填空。1. （____）气凉（____），树叶黄了，一片片（____）落（____）。"}', '"天气凉了，树叶黄了，一片片（叶子）落（下）来。"', '"课文《秋天》：「天气凉了，树叶黄了，一片片叶子从树上落下来。」"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、按课文内容填空。2. 雪地里，小鸡画（____），小马画（____）。"}', '"小鸡画竹叶，小马画月牙。"', '"课文《雪地里的小画家》：「小鸡画竹叶，小狗画梅花，小鸭画枫叶，小马画月牙。」"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "五、按课文内容填空。3. （____）对（____），雪对（____）。"}', '"云对雨，雪对风。"', '"课文《对韵歌》：「云对雨，雪对风，花对树，鸟对虫。」"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "六、在加点字的正确拼音上打「√」。秋天(qiū quí)　南瓜(lán nán)　小船(chuán chuáng)　说话(shōu shuō)　句子(jù jǜ)　数不清(shǔ shù)　雪花(xiě xuě)　弟弟(dì dì)。"}', '"秋天 qiū；南瓜 nán；小船 chuán；说话 shuō；句子 jù；数不清 shǔ；雪花 xuě；弟弟 dì。"', '"前鼻音 vs 后鼻音、平翘舌音、三声 vs 轻声辨析。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "七、连一连，成词语。上面 6 字：班、谁、鸟、作、国、课。下面 6 字：业、旗、体、课、班、国。"}', '"【图示估读，配对存疑】明确能配对：作—业（作业）；国—旗（国旗）。其余\"课—体\"\"班—国\"\"谁—？\"\"鸟—？\"不构成常规词语，原题配对需以教材原版为准。"', '"常见配对：作业（作+业）、国旗（国+旗）；其余组合存疑。"', 'paper', '[]', '["/static/qimg/mz_yw_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "八、对对碰，连一连。把左右两边的字配成反义词。左边：男、后、先、外、正、女、内、反。", "options": null}', '男—后；先—外；正—女；内—反。', '反义词配对：男(后)、先(外)、正(女)、内(反)。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "九、圈出不同类的词语。1. 爸爸　老师　医生　工人", "options": null}', '1. 爸爸。', '1. 爸爸=家庭成员，其他=职业。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "九、圈出不同类的词语。2. 火车　马车　汽车　坐车", "options": null}', '2. 坐车。', '2. 坐车=行为，其他=交通工具。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "九、圈出不同类的词语。3. 鸭子　积木　小鱼　小鸡", "options": null}', '3. 积木。', '3. 积木=物品，其他=动物。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "九、圈出不同类的词语。4. 医院　学校　工厂　青蛙", "options": null}', '4. 青蛙。', '4. 青蛙=动物，其他=场所。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、选字填空（填编号）。上方选项：①另 ②办 ③力 ④古；下方选项：①又 ②有 ③友 ④古。1. 你的___力气真大,可以一手提起一只小草。", "options": null}', '【图示估读存疑】原题字迹小模糊,空格为单字,四个选项(另/办/力/古)中无「手」/「牛」等明显搭配,建议以教材原题为准。常见猜测答案为 ②办(办事有力)或 ③力(力气),但题面与选项对应关系存疑。', '图上「一只小草」疑似「一只小牛」(图字小模糊),「你的___力气真大」空格单字,上方四选项(另/办/力/古)中无标准答案,标存疑。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "十、选字填空。2. 他想出了好___法。", "options": null}', '②办（办法）。', '「办法」= 办+法,选 ②办。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、选字填空。3. 爷爷是___的。", "options": null}', '④古（古稀之年,指 70 岁）。', '「古稀」= 70 岁,形容年纪大;选 ④古。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "十、选字填空。4. 小鸡和小鸭是好朋___。", "options": null}', '③友（朋友）。', '「朋友」= 朋+友,选 ③友。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、选字填空。5. 我的___边是小红。", "options": null}', '【图示估读存疑】原题字迹模糊,空格单字,下方四选项(又/有/友/古)均无法直接搭配「__边」,常见答案应为「左/右/旁」但不在选项,原题配对存疑。', '「我的__边是小红」常见答案为「左/右/旁」,但下方选项(又/有/友/古)中无对应字,存疑。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "十、选字填空。6. 小明___来我家找我玩了。", "options": null}', '①又（又一次,表示动作重复）。', '「又」表示动作重复发生,选 ①又。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "十、选字填空。7. 我家门口___一棵小树。", "options": null}', '②有（表示存在）。', '「有」表示存在,选 ②有。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "阅读部分《可爱的秋娃娃》。1. 短文共有___个自然段。", "options": null}', '3（个自然段）。', '短文共 3 个自然段:①秋娃娃挥舞彩笔来了;②一片片树叶黄了,稻子金灿灿,秋菊笑开怀;③多想留住这些景象,可是冬姐姐马上要来了。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "阅读部分《可爱的秋娃娃》。2. 选择合适的量词(填编号):①条 ②支 ③个 ④片。一( )彩笔　一( )果子　一( )菊花　一( )树叶。", "options": null}', '一(②支)彩笔；一(③个)果子；一(①条)菊花(估读存疑,菊花常用「朵」,但原题选 ①条)；一(④片)树叶。', '量词搭配:彩笔用「支」,果子用「个」,树叶用「片」;菊花用「朵」为标准,但原题选项 ①条,据原题作答。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读部分《可爱的秋娃娃》。3. 根据短文内容连一连:金灿灿的(  );成熟的(  );五彩的(  );黄黄的(  )。选项:树叶、稻子、秋菊、果子。", "options": null}', '金灿灿的—稻子;成熟的—果子;五彩的—秋菊;黄黄的—树叶。', '短文描写:稻子一片金灿灿、一个个果子熟了、五彩的秋菊、一片片树叶黄了,据此配对。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "阅读部分《可爱的秋娃娃》。4. 为什么「我」不能把这些美妙的景象永远留住?( ) ①因为冬姐姐马上就要来了。②因为秋娃娃太淘气了。", "options": null}', '①因为冬姐姐马上就要来了。', '短文末段明确:「可是来不及了,因为冬姐姐马上就要来了。」', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 3, '{"stem": "看图写话。图上画着几个小朋友在雪天里(戴帽子、围巾)一起堆雪人,旁边有房子和小树。这是( )节日？图上的小朋友在干什么?根据提示写几句话,语句通顺,标点正确。", "options": null}', '开放题示例:这是快乐的冬天。雪花飘啊飘,小朋友们在雪地里堆雪人,他们堆了一个大大的雪人,用胡萝卜做鼻子,煤球做眼睛,小朋友们玩得真开心!', '考查写话能力:看图判断季节(冬季雪天),写清时间、地点、人物、事情、心情,语句通顺,使用常用标点。', 'paper', '[]', '["/static/qimg/mz_yw_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "期末测试卷(名校二)第一关 1. 拼一拼,在水果后面画「△」,在文具后面画「○」。(1)cǎo méi( ) (2)xī guā( ) (3)xiāng pí( ) (4)mí hóu táo( ) (5)shí liu( ) (6)qiān bǐ( ) (7)chǐ zi( ) (8)zhuān bǐ dāo( )。", "options": null}', '(1)cǎo méi 草莓 △;(2)xī guā 西瓜 △;(3)xiāng pí 橡皮 ○;(4)mí hóu táo 猕猴桃 △;(5)shí liu 石榴 △;(6)qiān bǐ 铅笔 ○;(7)chǐ zi 尺子 ○;(8)zhuān bǐ dāo 铅笔刀 ○。', '水果(△):草莓、西瓜、猕猴桃、石榴;文具(○):橡皮、铅笔、尺子、铅笔刀。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "期末测试卷(名校二)第一关 2. 我会在正确的音节后打「√」。6 个图:房子、大叔、刺猬、花朵、气球、杯子。", "options": null}', '房子 fáng wū √;大叔 dà shū √;刺猬 cì wei √;花朵 huā duǒ √;气球 qì qiú √;杯子 bēi zi √(轻声)。', '前后鼻音、轻声音节、平翘舌辨析。房子(fáng wū)不是 fáng wǔ;大叔(dà shū)不是 bà shū;刺猬(cì wei)不是 cì wèi;花朵(huā duǒ)不是 huā dǒu;气球(qì qiú)不是 qì qiōu;杯子(bēi zi)轻声。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 3, '{"stem": "期末测试卷(名校二)第一关 3. 把字宝宝和相应的拼音连一连。8 个字:彩、叔、蓝、青、莲、谁、彩、医。8 个拼音:shǔ、yǐng、yīn、lián、làn、yī、shuǐ、cǎi。", "options": null}', '【图示估读存疑】原题 8 个字+8 个拼音,但拼音与字的标准读音对不上(彩cǎi/叔shū/蓝lán/青qīng/莲lián/谁shéi/医yī),疑似题面印刷存疑,或拼音列表为形声字声旁的近似读音配对练习。按字的标准读音:彩cǎi/叔shū/蓝lán/青qīng/莲lián/谁shéi/医yī,建议以教材原版为准。', '图上字与拼音不对应,标存疑;标准读音:彩cǎi、叔shū、蓝色lán、青色qīng、莲花lián、谁shéi、医生yī。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "期末测试卷(名校二)第二关 1. 我会根据拼音写笔画和部首。shù tí( );héng gōu( );xié gōu( );wō gōu( );yàn zì páng( );bǎ zì tóu( );xiě dào tóu( );zǒu zhī dǐ( )。", "options": null}', 'shù tí 竖提;héng gōu 横钩;xié gōu 斜钩;wō gōu 卧钩;yàn zì páng 厂字头(yàn);bǎ zì tóu 把字头(扌);xiě dào tóu 写到头(笔画名);zǒu zhī dǐ 走之底(辶)。', '8 个常用笔画和部首:竖提、横钩、斜钩、卧钩是基本笔画;厂字头、把字头、走之底是常用偏旁部首。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "期末测试卷(名校二)第二关 2. 写出下列字的反义词。正(  )　东(  )　后(  )　开(  )　男(  )　上(  )。", "options": null}', '正—反;东—西;后—前;开—关;男—女;上—下。', '六对常用反义词:正反、东西、先后、开关、男女、上下。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "期末测试卷(名校二)第二关 3. 汉字小魔术,按要求填空。(1) 加一笔:本→○、鸟→○、云→○;(2) 加两笔:中→○、可→○、日→○。", "options": null}', '(1) 加一笔:本→末(或术、未、禾);鸟→鸣(加点+横,或 鸡「+又」);云→运(或会);(2) 加两笔:中→申(或田、国);可→哥;日→旦(或早、昌、显、明、晶、冒、易、昔、旱)。', '加一笔:本(4 画)+ 横变 5 画如 末/未/术/禾;鸟(5 画)+ 变 鸣/鸡/凤/鸦/鸽;云(4 画)+ 变 运/会/动。加两笔:中(4 画)→申/田/国/晶;可(5 画)→哥/顶/奇/呵/何;日(4 画)→旦/早/显/明/晶/冒。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "期末测试卷(名校二)第三关 1. 圈出与其他词语不属于同一类的词语。(1) 爸爸 画画 妈妈 姐姐;(2) 医院 工厂 军队 医生;(3) 参加 升旗 做操 读书;(4) 乌鸦 花猫 青蛙 星星。", "options": null}', '(1) 画画(动作,其他为人物);(2) 医生(人物,其他为场所);(3) 参加(动词,其他为活动);(4) 星星(天体,其他为动物)。', '词语分类:人物/场所/活动/物体。画画=动作;医生=人物;参加=动词(其他三项是具体活动);星星=天体(其他三项是动物)。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 3, '{"stem": "期末测试卷(名校二)第三关 2. 把字放到对应的盘子里(写编号)。8 个字:①挤 ②扫 ③他 ④昨 ⑤你 ⑥晓 ⑦打 ⑧袜。四个盘子:提手旁、单人旁、日字旁、木字旁。", "options": null}', '【图示估读存疑】按字形偏旁:提手旁(扌) = 扫② 打⑦ 挤①(挤=扌+齐);单人旁(亻) = 他③ 你⑤;日字旁(日) = 昨④ 晓⑥;木字旁(木) = (无对应字,8 字中无标准木字旁字,「袜」= 衣字旁非木字旁,木字旁盘子可能空)。', '按偏旁分类:提手旁(扌)=挤/扫/打;单人旁(亻)=他/你;日字旁(日)=昨/晓;木字旁(木)=无(8 字中无木字旁字,袜是衣字旁,标存疑)。', 'paper', '[]', '["/static/qimg/mz_yw_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "3. 看图选量词(填编号)。选项:①片 ②把 ③头 ④只 ⑤条 ⑥个。两( )牛　一( )叶子　五( )雨伞　两( )苹果　一( )兔子　一( )鱼。", "options": null}', '两(③头)牛；一(①片)叶子；五(②把)雨伞；两(⑥个)苹果；一(④只)兔子；一(⑤条)鱼。', '量词搭配:牛用「头」,叶子用「片」,雨伞用「把」,苹果用「个」,兔子用「只」,鱼用「条」。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "4. 选择合适的诗句填空(填编号)。①解落三秋叶 ②呼作白玉盘 ③粒粒皆辛苦 ④白毛浮绿水。(1)小时不识月,____。(2)____,能开二月花。(3)谁知盘中餐,____。(4)____,红掌拨清波。", "options": null}', '(1)②呼作白玉盘；(2)①解落三秋叶；(3)③粒粒皆辛苦；(4)④白毛浮绿水。', '古诗名句:①李峤《风》「解落三秋叶,能开二月花」；②李白《古朗月行》「小时不识月,呼作白玉盘」；③李绅《悯农》「谁知盘中餐,粒粒皆辛苦」；④骆宾王《咏鹅》「白毛浮绿水,红掌拨清波」。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "阅读《冬爷爷是艺术家》。1. 短文共有___个自然段。", "options": null}', '6(个自然段)。', '按段首缩进划分:①冬爷爷已经准备好,它开始打扮大家了!；②给窗户装上冰凌花；③给大树穿上冰衣裳；④让树枝开出梅花；⑤给大地盖上雪被；⑥哎呀,冬爷爷真了不起,共 6 个自然段。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "阅读《冬爷爷是艺术家》。2. 根据短文内容选择合适的词语(填编号)。①高高 ②广阔 ③红艳艳 ④光秃秃 ⑤白茫茫 ⑥千姿百态。( )的大树　( )的大地　( )的树枝　( )的梅花　( )的雪被　( )的冰凌花。", "options": null}', '(①高高)的大树；(②广阔)的大地；(④光秃秃)的树枝；(③红艳艳)的梅花；(⑤白茫茫)的雪被；(⑥千姿百态)的冰凌花。', '短文描写:高高的大树、广阔的大地、光秃秃的树枝、红艳艳的梅花、白茫茫的雪被、千姿百态的冰凌花。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读《冬爷爷是艺术家》。3. 照样子,连一连。左边(动词):给窗户、让树枝、给大地、给大树。中间选项:装上、穿上、开出、盖上。右边(名词):冰衣裳、冰凌花、雪被、梅花。", "options": null}', '给窗户—装上—冰凌花；给大树—穿上—冰衣裳；让树枝—开出—梅花；给大地—盖上—雪被。', '短文原句:给窗户装上冰凌花,给大树穿上冰衣裳,让树枝开出梅花,给大地盖上雪被。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "阅读《冬爷爷是艺术家》。4. 选一选(填编号)。谁是最了不起的艺术家?( )　①梅花 ②大树 ③冬爷爷。", "options": null}', '③冬爷爷。', '短文末段明确:「冬爷爷,你真是了不起的艺术家。」', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '简答', 3, '{"stem": "第五关:我会写话。一个学期快结束了,给你的语文老师写几句感谢的话语吧。", "options": null}', '开放题示例:亲爱的老师,谢谢您这一学期教我读书识字,教我做人的道理。我会好好学习,听您的话。老师您辛苦了!', '考查写话能力:称呼+感谢+具体事例+祝福/承诺,语句通顺,使用常用标点。', 'paper', '[]', '["/static/qimg/mz_yw_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。lì zhěng( )", "options": null}', '立正。', '看图书写:6 个田字格,每格写 2 个字,本图为第一格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。dà fēng( )", "options": null}', '大风。', '看图书写:6 个田字格,每格写 2 个字,本图为第二格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。shí tou( )", "options": null}', '石头。', '看图书写:6 个田字格,每格写 2 个字,本图为第三格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。zuò yòu( )", "options": null}', '左右。', '看图书写:6 个田字格,每格写 2 个字,本图为第四格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。nǐ wǒ( )", "options": null}', '你我。', '看图书写:6 个田字格,每格写 2 个字,本图为第五格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、看拼音,写词语。shuǐ guǒ( )", "options": null}', '水果。', '看图书写:6 个田字格,每格写 2 个字,本图为第六格。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "二、在正确的音节后打「√」。1. 梅花(插图):méi huā( ) / mái huā( )", "options": null}', 'méi huā(√)。', '声母辨析:梅=měi/méi,声母 m,韵母 ei,二声,不读 mái。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "二、在正确的音节后打「√」。2. 竹叶(插图):zhú lè( ) / zhú yè( )", "options": null}', 'zhú yè(√)。', '整体认读音节:叶=yè,不读 lè;竹叶 zhú yè。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "二、在正确的音节后打「√」。3. 项链(插图):xiàng liàn( ) / xàng liàn( )", "options": null}', 'xiàng liàn(√)。', '声母辨析:项=xiàng,声母 x,韵母 iang,不读 xàng;项链 xiàng liàn。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "二、在正确的音节后打「√」。4. 苹果(插图):pín guǒ( ) / píng guǒ( )", "options": null}', 'píng guǒ(√)。', '后鼻音辨析:平=píng,后鼻音,不是前鼻音 pín;苹果 píng guǒ。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "三、连一连,把字和部首连起来。左边 4 个字:有、后、多、前;右边 4 个部首名:sì diǎn dī(四点底)、zǒu zhī dī(走之底)、dān rén páng(单人旁)、tí shǒu páng(提手旁)。", "options": null}', '【图示估读存疑】左 4 字与右 4 部首未严格对应:有/月部、后/口部、多/夕字头、前/刀字旁,右列实为(艹/草字头/有/冖/走之底/单人旁/提手旁)四部首中可能存在字、偏旁印错或字形我识别偏差。具体配对以教材原版为准,建议人工核对。', '字与部首配对:有=月部、后=口部(古从攴)、多=夕字头、前=刀字旁;右列四点底/走之底/单人旁/提手旁与上述字标准偏旁不严格对应,标存疑。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '组词', 1, '{"stem": "四、比一比,再组词。月( ) / 用( )", "options": null}', '月(月亮)/用(用处)。', '形近字辨析:月(月亮)/用(用处、用心)。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '组词', 1, '{"stem": "四、比一比,再组词。出( ) / 山( )", "options": null}', '出(出去)/山(山峰)。', '形近字辨析:出(出去)/山(山峰、高山)。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '组词', 1, '{"stem": "四、比一比,再组词。力( ) / 办( )", "options": null}', '力(力气)/办(办法)。', '形近字辨析:力(力气)/办(办法、办公)。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "五、读一读,选出加点字的反义词。①开 ②早 ③无 ④小 ⑤西。1. 我有很多的玩具。( )", "options": null}', '③无(有—无)。', '反义词:有=无,选 ③无。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "五、读一读,选出加点字的反义词。①开 ②早 ③无 ④小 ⑤西。2. 太阳从东方升起。( )", "options": null}', '⑤西(东—西)。', '方位反义词:东=西,选 ⑤西。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "五、读一读,选出加点字的反义词。①开 ②早 ③无 ④小 ⑤西。3. 哇,好大的西瓜呀!( )", "options": null}', '④小(大—小)。', '反义词:大=小,选 ④小。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "五、读一读,选出加点字的反义词。①开 ②早 ③无 ④小 ⑤西。4. 太晚了,我们要关灯睡觉了。( )", "options": null}', '②早(晚—早)。', '时间反义词:晚=早,选 ②早。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "五、读一读,选出加点字的反义词。①开 ②早 ③无 ④小 ⑤西。5. 由于下雨路滑,我来晚了。( )", "options": null}', '②早(晚—早)。', '时间反义词:晚=早,选 ②早。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、按要求填一填。1.「里」共___笔,第五笔是___,组词:___。", "options": null}', '「里」共 5 笔,第五笔是「横折钩」,组词:里外。', '汉字「里」共 5 笔:竖、横、点、横折钩、竖;第五笔为横折钩;组词「里外」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、按要求填一填。2.「早」是___结构,组词:___。", "options": null}', '「早」是上下结构,组词:早上。', '「早」=日+十,上下结构;组词「早上、早晨」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、按要求填一填。3.「好」的部首是___,和它部首相同的字有___、___。", "options": null}', '「好」的部首是「女」,和它部首相同的字有「妈、姐、她、妹、奶、姑、姐」等。', '「好」=女+子,部首为女;常见女字旁字:妈、姐、她、妹、奶、姑、娘、姐等。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、按要求填一填。4.「比」共___笔,笔顺:___。", "options": null}', '「比」共 4 笔,笔顺:竖、竖、横、竖弯钩。', '「比」共 4 笔:第一笔竖,第二笔竖,第三笔横,第四笔竖弯钩。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、照样子,写句子。1. 例:天空那么蓝,那么高。___那么___,那么___。", "options": null}', '示例:大海那么蓝,那么宽。', '仿写:用「那么...那么...」句式,如「大海那么蓝,那么宽」「花那么红,那么香」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、照样子,写句子。2. 例:我在小小的船里坐。___在___。", "options": null}', '示例:我在草地上跑。', '仿写:用「在」句式,如「我在草地上跑」「妈妈在家里做饭」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、照样子,写句子。3. 例:影子常常跟着我。___常常___。", "options": null}', '示例:妈妈常常关心我。', '仿写:用「常常」句式,如「妈妈常常关心我」「我常常看书」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "七、照样子,写句子。4. 例:青蛙为什么没参加?___为什么___?", "options": null}', '示例:我为什么不能出去玩?', '仿写:用「为什么」问句,如「我为什么不能出去玩?」「天为什么下雨?」。', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "八、连词成句(写编号),注意加上标点。1. ①小画家 ②来了 ③雪地里 ④一群", "options": null}', '③ ② ④ ①。雪地里来了一群小画家。', '通顺句:「雪地里来了一群小画家。」', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "八、连词成句(写编号),注意加上标点。2. ①尾巴 ②孔雀的 ③最 ④好看", "options": null}', '② ① ③ ④。孔雀的尾巴最④好看。', '通顺句:「孔雀的尾巴最④好看。」', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 3, '{"stem": "八、连词成句(写编号),注意加上标点。3. ①地方 ②成了 ③哪里 ④有花有草的 ⑤不久", "options": null}', '③ ④ ① ⑤ ②。哪里有花有草的地方不久就成了(花园)。', '通顺句:「哪里有花有草的地方不久就成了(花园)。」', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "八、连词成句(写编号),注意加上标点。4. ①里 ②渐渐地 ③升高了 ④瓶子 ⑤水 ⑥的", "options": null}', '④ ① ⑥ ⑤ ② ③。瓶子里的水渐渐地升高了。', '通顺句:「瓶子里的水渐渐地升高了。」', 'paper', '[]', '["/static/qimg/mz_yw_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、我会背,还会连线。1. 农谚上半配对(将左右连起来):一年之计 / 一日之计 / 一寸光阴 / 寸金难买 ↔ 一寸金 / 在于春 / 寸光阴 / 在于晨", "options": null}', '一年之计—在于春;一日之计—在于晨;一寸光阴—一寸金;寸金难买—寸光阴。', '农谚:一年之计在于春,一日之计在于晨,一寸光阴一寸金,寸金难买寸光阴。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、我会背,还会连线。2. 农谚下半配对:种瓜得瓜 / 前人栽树 / 千里之行 / 百尺竿头 ↔ 始于足下 / 更进一步 / 种豆得豆 / 后人乘凉", "options": null}', '种瓜得瓜—种豆得豆;前人栽树—后人乘凉;千里之行—始于足下;百尺竿头—更进一步。', '农谚/谚语:种瓜得瓜,种豆得豆;前人栽树,后人乘凉;千里之行,始于足下;百尺竿头,更进一步。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "九、我会背,还会连线。3. 古诗名句配对:解落三秋叶 / 小时不识月 / 谁知盘中餐 / 白毛浮绿水 ↔ 呼作白玉盘 / 粒粒皆辛苦 / 能开二月花 / 红掌拨清波", "options": null}', '解落三秋叶—能开二月花(李峤《风》);小时不识月—呼作白玉盘(李白《古朗月行》);谁知盘中餐—粒粒皆辛苦(李绅《悯农》);白毛浮绿水—红掌拨清波(骆宾王《咏鹅》)。', '古诗名句配对:李峤《风》解落三秋叶,能开二月花;李白《古朗月行》小时不识月,呼作白玉盘;李绅《悯农》谁知盘中餐,粒粒皆辛苦;骆宾王《咏鹅》白毛浮绿水,红掌拨清波。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、我爱阅读《云姑娘换衣服》。短文(原文):天上住着云姑娘,她最喜欢换衣服。下午,云姑娘穿着一身白色的衣服。傍晚,云姑娘换上了红色的衣服。快下雨时,云姑娘又穿了一身黑色的衣服。云姑娘真美丽! 1. 短文共有___个自然段,第一自然段有___句话。", "options": null}', '5 个自然段(云姑娘真美丽独立为一段);第一自然段有 1 句话。', '按段首缩进判断段数:① 天上住着...换衣服 ② 下午...白色衣服 ③ 傍晚...红色衣服 ④ 快下雨时...黑色衣服 ⑤ 云姑娘真美丽! 共 5 段;第一自然段只有 1 句话。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十、我爱阅读《云姑娘换衣服》。2. 短文中一共出现了 3 个表示颜色的词,请你用「___」把它们全都画出来。", "options": null}', '白色、红色、黑色。', '短文中颜色词:①一身白色的衣服(第一段,实际是第二段:下午,云姑娘穿着一身白色的衣服);② 换上了红色的衣服(傍晚);③ 又穿了一身黑色的衣服(快下雨时)。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 1, '{"stem": "十、我爱阅读《云姑娘换衣服》。3.(1) 云姑娘是住在天上的。( )", "options": null}', '(√)对。', '短文第一段明确写「天上住着云姑娘」,所以「云姑娘住在天上」正确,打 √。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 1, '{"stem": "十、我爱阅读《云姑娘换衣服》。3.(2) 傍晚,云姑娘穿着红衣服。( )", "options": null}', '(√)对。', '短文说「傍晚,云姑娘换上了红色的衣服」,傍晚时云已换上了红衣服,「穿着红衣服」持续状态成立,打 √。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 1, '{"stem": "十、我爱阅读《云姑娘换衣服》。3.(3) 快下雨时,云姑娘会穿上白衣服。( )", "options": null}', '(×)错。', '短文说「快下雨时,云姑娘又穿了一身黑色的衣服」,不是白衣服,打 ×。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "十一、我爱写话。看图写话:图上是下雪场景,三个小朋友在雪地里堆雪人,旁边有房子、栅栏和小雪人。提示:这是什么节日?图上的小朋友在干什么?要求:根据提示写几句话,注意语句通顺,标点正确。", "options": null}', '示例:冬天到了,雪从天空中飘落下来,真美丽!星期天,小明、小红和小刚一起到雪地里堆雪人。他们先把雪堆在一起,做成雪人的身体,又滚了一个小雪球做雪人的头,还给它戴上了帽子,围上了围巾。看着可爱的雪人,小朋友们笑得多开心呀!', '写话要点:① 写出时间(冬天/下雪天);② 写出地点(雪地里/草地上);③ 写出人物活动(堆雪人/打雪仗);④ 写出心情(开心/高兴);⑤ 标点正确(句末加句号/感叹号)。', 'paper', '[]', '["/static/qimg/mz_yw_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "期末测试卷(名校四)。试卷引入:红军创下了人类战争史上的奇迹:红军战士不怕艰难险阻,完成了二万五千里长征。现在,我们要学红军战士不怕艰险的精神,突破一个个语文关卡。 第一关:拼音草地。1. 哪片草地里面有食物?请把它圈出来。(6 朵花里含拼音:鸡墙 jī qiáng、草莓 cǎo méi、花药 huā yào、球田 qiú tián、苹果 píng guǒ、猪 zhū 肉 ròu)", "options": null}', '草莓、苹果、(猪)肉。', '草莓、苹果、(猪)肉是食物;鸡墙、花药、球田是形近词干扰,非食物。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第一关:拼音草地。3. 写出这些词语,就能穿过草地。(6 个词格子,拼音已给出:雨水 yǔ shuǐ、工厂 gōng chǎng、男生 nán shēng、出来 chū lái、主要 zhǔ yào、用心 yòng xīn)", "options": null}', '雨水;工厂;男生;出来;主要;用心。', '看拼音写词语:① yǔ shuǐ=雨水 ② gōng chǎng=工厂 ③ nán shēng=男生 ④ chū lái=出来 ⑤ zhǔ yào=主要 ⑥ yòng xīn=用心。注:题 2 是过渡句(田字迷宫),无具体题目,5 个拼音云 bù/cān/wǎ/pàng/duǎn 为装饰。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关:汉字靠山。1.(1) 圈出不同类的词:①明天 ②春天 ③冬天 ④夏天", "options": null}', '圈①明天(时间词,其他 3 个是季节)。', '分类:季节=春/夏/冬;时间词=明天/今天/昨天。① 明天是时间词,其他 3 个是季节名。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关:汉字靠山。1.(2) 圈出不同类的词:①数学 ②美术 ③语文 ④读书", "options": null}', '圈④读书(动词,其他 3 个是科目名)。', '分类:科目=数学/美术/语文;动词=读书/写字/画画。④ 读书是动词,其他 3 个是科目名。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关:汉字靠山。1.(3) 圈出不同类的词:①小鸟 ②山羊 ③青蛙 ④小桥", "options": null}', '圈④小桥(建筑物,其他 3 个是动物)。', '分类:动物=小鸟/山羊/青蛙;建筑物=小桥/房子/亭子。④ 小桥是建筑物,其他 3 个是动物。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第二关:汉字靠山。1.(4) 圈出不同类的词:①书包 ②蓝笔 ③尺子 ④尾巴", "options": null}', '圈④尾巴(身体部位,其他 3 个是文具)。', '分类:文具=书包/蓝笔/尺子;身体部位=尾巴/耳朵/鼻子。④ 尾巴是身体部位,其他 3 个是文具。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第二关:汉字靠山。2. 连一连。(上排 4 字:夜、歌、宝、高;下排 4 字:声、色、处、贝)", "options": null}', '【图示估读存疑】可能的部首配对(待校验,建议以教材原题为准):夜-宝(同宀部);高-声(同士/高部);歌-贝(同可/贝部?);色-处(待定)。', '8 字在山型字块中,无明确部首/字配对提示,题干未标部首,字与字之间无明显共同部件;按字形与常见配对猜测:夜(宀部)=宝(宀部);高(高字头)=声(士部)?;歌(可+欠)=贝(贝部?)?实际配对关系存疑,建议核对教材原题。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "第二关:汉字靠山。3. 照样子,写一写。(上排 4 字:开、早、长、内;下排 4 字:短、关、外、晚)", "options": null}', '开-关;早-晚;长-短;内-外。', '反义字配对:开=关,早=晚,长=短,内=外。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关:句子浮桥。1.(1) 有花有草的地方,花更红了,草更绿了。(用加点词语「更...更...」写一句话。)", "options": null}', '示例:下了一场雨,花更红了,草更绿了。/ 雨后,树更绿了,花更红了。', '用「更...更...」句式仿写,前后两个事物对比变化。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关:句子浮桥。1.(2) 雪地里来了一群小画家。(用加点词语「来了一群」写句子。)", "options": null}', '示例:草地上来了一群小朋友。/ 池塘里来了一群小鸭。', '用「来了一群」句式仿写,某地来了某一群动物或人。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第三关:句子浮桥。1.(3) 例:青蛙为什么没参加? 照样子,写句子。小燕子为什么飞得低? ___", "options": null}', '示例:因为要下雨了,所以小燕子飞得低。/ 要下雨了,小燕子的翅膀沾了水珠,所以飞得低。', '照「为什么...」问句仿写,并给出合理的回答(因果关系)。', 'paper', '[]', '["/static/qimg/mz_yw_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "(4) 弟弟常常 ______ 。(把句子补充完整。)", "options": null}', '示例:弟弟常常[帮妈妈做家务]。/ 弟弟常常[看书]。', '开放题,补充完整合理即可,符合一年级生活场景。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "2.(1) 连词成句(写编号),别忘了加标点。①啦 ②井里 ③掉在 ④月亮", "options": null}', '④③②①:月亮掉在井里啦。', '连词成句:主语+动词+地点+语气。④ 月亮(主语) → ③ 掉在(动词) → ② 井里(地点) → ① 啦(语气)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "2.(2) 连词成句(写编号),别忘了加标点。①我 ②在 ③坐 ④小小的 ⑤船里", "options": null}', '①②③④⑤:我坐在小小的船里。', '连词成句:① 我(主语) → ② 在(介词) → ③ 坐(动词) → ④ 小小的(定语) → ⑤ 船里(地点)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "2.(3) 连词成句(写编号),别忘了加标点。①小花猫 ②几只 ③玩 ④公园里 ⑤在", "options": null}', '②①⑤④③:几只小花猫在公园里玩。', '连词成句:② 几只(数量词) → ① 小花猫(主语) → ⑤ 在(介词) → ④ 公园里(地点) → ③ 玩(动词)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "2.(4) 连词成句(写编号),别忘了加标点。①黄黄的 ②大树上 ③从 ④树叶 ⑤落下来 ⑥了", "options": null}', '①④③②⑤⑥:黄黄的树叶从大树上落下来了。', '连词成句:① 黄黄的(定语) → ④ 树叶(主语) → ③ 从(介词) → ② 大树上(起点) → ⑤ 落下来(动词) → ⑥ 了(语气助词)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "3.(1) 根据课文内容填空:猴子的尾巴 ______,兔子的尾巴短,松鼠的尾巴好像 ______ 伞。", "options": null}', '长;一把。', '课文《比尾巴》原文:猴子的尾巴长,兔子的尾巴短,松鼠的尾巴好像一把伞。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "3.(2) 根据课文内容填空:江南可采莲,莲叶何 ______。鱼戏莲叶间。鱼戏莲叶 ______,鱼戏莲叶 ______,鱼戏莲叶 ______。", "options": null}', '田田;东;西;南(北)。', '课文《江南》(汉乐府)原文:江南可采莲,莲叶何田田。鱼戏莲叶东,鱼戏莲叶西,鱼戏莲叶南,鱼戏莲叶北。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "3.(3) 根据课文内容填空:雪地里来了一群小画家。小鸡画 ______,小豹画梅花,小鸭画枫叶,______ 画 ______。", "options": null}', '竹叶;小狗;月牙(注:原题「小豹」疑为「小狗」之误,按人教版《雪地里的小画家》原文)。', '课文《雪地里的小画家》原文:小鸡画竹叶,小狗画梅花,小鸭画枫叶,小马画月牙。【印刷存疑】「小豹」应为「小狗」,「豹/狗」形近误印;最后一空按课文填「小马画月牙」。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "4.(1) 我会运用(填编号)。①百尺竿头,更进一步 ②种瓜得瓜,种豆得豆 ③解落三秋叶,能开二月花 ④一年之计在于春,一日之计在于晨。风扇厉害,他能让秋天的树落叶,能让二月的花盛开,这正是:______ 。", "options": null}', '③(解落三秋叶,能开二月花)。', '③ 出自李峤《风》:解落三秋叶,能开二月花。题意:让秋天落叶、让二月花开正是「风」的作用。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "4.(2) 我会运用(填编号)。①百尺竿头,更进一步 ②种瓜得瓜,种豆得豆 ③解落三秋叶,能开二月花 ④一年之计在于春,一日之计在于晨。姐姐的学习成绩很好,但爸爸还希望她更棒,要:\\\"______ \\\"\\\"", "options": null}', '①(百尺竿头,更进一步)。', '① 百尺竿头,更进一步=学问/成绩无止境,即使很好也要继续努力。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "4.(3) 我会运用(填编号)。①百尺竿头,更进一步 ②种瓜得瓜,种豆得豆 ③解落三秋叶,能开二月花 ④一年之计在于春,一日之计在于晨。小明每天总是慢吞吞地吃早饭,姐姐却早早开始了晨读。她对小明说:\\\"______ \\\"\\\"", "options": null}', '④(一年之计在于春,一日之计在于晨)。', '④ 强调早晨时间宝贵,应珍惜晨光好好学习,劝小明不要磨蹭。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关:阅读铁索桥。短文《春天来了》全文:春天来了,小草们慢慢地染绿了大地,柳枝上长出了嫩嫩的绿叶。蓝天上飘浮着淡淡的白云。远处一片片野花都开了,美丽的蝴蝶在花丛中飞来飞去。春天真美啊!1. 短文共有 ______ 句话,主要写了 ______ 的景色。", "options": null}', '5 句;春天。', '分句:① 春天来了。② 小草们慢慢地染绿了大地,柳枝上长出了嫩嫩的绿叶。③ 蓝天上飘浮着淡淡的白云。④ 远处一片片野花都开了,美丽的蝴蝶在花丛中飞来飞去。⑤ 春天真美啊! 共 5 句。主要写春天景色。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "第四关:阅读铁索桥。2. 在短文中写的事物后打「√」。小草( ) 柳枝( ) 白云( ) 天空( ) 野花( ) 小鸟( ) 蝴蝶( ) 蜜蜂( )", "options": null}', '打√:小草、柳枝、白云、天空、野花、蝴蝶;不打√:小鸟、蜜蜂。', '短文出现的事物:小草、柳枝(嫩绿的绿叶)、白云、蓝天(蓝天上)、野花、蝴蝶;未出现:小鸟、蜜蜂。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "第四关:阅读铁索桥。3. 根据短文内容连一连。修饰词:嫩绿的 蓝蓝的 淡淡的 美丽的;事物:天空 蝴蝶 白云 柳叶", "options": null}', '嫩绿的—柳叶;蓝蓝的—天空;淡淡的—白云;美丽的—蝴蝶。', '短文对应:柳枝上长出了嫩嫩的绿叶(嫩绿—柳叶);蓝天(蓝蓝—天空);淡淡的白云(淡淡—白云);美丽的蝴蝶(美丽—蝴蝶)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 3, '{"stem": "第五关:写话大河。提示:这是什么季节?小朋友在哪里干什么?他们心情怎么样?(看图写话)", "options": null}', '示例:春天来了,小朋友们在草地上开开心心地放风筝,他们玩得真高兴呀! / 春天来了,田野里金灿灿的油菜花开了,小朋友们在花丛中追逐蝴蝶,他们笑得多开心呀!', '看图写话三要素:①季节(春/夏/秋/冬);②地点与活动(放风筝/捉蝴蝶/玩游戏);③心情(开心/快乐/高兴)。', 'paper', '[]', '["/static/qimg/mz_yw_p49.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "下列生活中的物品分别是什么图形？把对应的图形连起来。（图：课本、足球、易拉罐、纸箱、骰子、玻璃杯；下排：圆柱、正方体、球、长方体）", "options": null}', '连线题（课本—长方体、足球—球、易拉罐—圆柱、纸箱—长方体、骰子—正方体、玻璃杯—圆柱），连线无固定答案，参考连线：课本→长方体、足球→球、易拉罐→圆柱、纸箱→长方体、骰子→正方体、玻璃杯→圆柱。', '【认识图形】识别长方体、正方体、圆柱、球。课本和纸箱是长方体，足球是球，易拉罐和玻璃杯是圆柱，骰子是正方体。', 'paper', '[]', '["/static/qimg/mz_sx_p2.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "把同类图形连在一起。（上排：长方体、圆柱、球、正方体；下排：四个对应图形；最底：长方体、圆柱、球、正方体）", "options": null}', '连线题（同类相连），长方体—长方体、圆柱—圆柱、球—球、正方体—正方体。', '【认识图形】把相同立体图形连起来。', 'paper', '[]', '["/static/qimg/mz_sx_p2.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "用下面的几何体可以描出哪些图形？把能描出的图形圈出来。（上排几何体：圆柱、长方体、正方体、圆锥、圆台、三棱柱；下排图形：长方形、三角形、平行四边形、正方形、圆）", "options": null}', '圆柱→长方形、圆；长方体→长方形；正方体→正方形；圆锥→圆、三角形；圆台→圆；三棱柱→长方形、三角形。', '【认识图形】圆柱沿侧面展开是长方形或上下底面是圆；长方体描出长方形；正方体描出正方形；圆锥侧面是三角形、底是圆；圆台上下底是圆；三棱柱侧面长方形、底面三角形。', 'paper', '[]', '["/static/qimg/mz_sx_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "涂一涂：圆形涂红色，长方形涂蓝色，正方形涂黄色，三角形涂绿色。（图：由各种圆形、长方形、正方形、三角形组成的城堡图）", "options": null}', '涂色题：圆形（圆形/球）涂红色，长方形（长方体侧面）涂蓝色，正方形涂黄色，三角形涂绿色。', '【认识图形】辨认平面图形（圆形、长方形、正方形、三角形）并按要求涂色。', 'paper', '[]', '["/static/qimg/mz_sx_p3.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空题', 1, '{"stem": "看图填空：图①正方体、图②圆柱、图③长方体。（1）能描出○（圆形）的是（　）号图形。（2）能描出长方形的是（　）号图形。（3）能描出正方形的是（　）号图形。", "options": null}', '（1）②（圆柱上下底是圆形）；（2）③（长方体描出长方形）；（3）①（正方体描出正方形）。', '【认识图形】圆柱的上下底面是圆形；长方体的面是长方形；正方体的面是正方形。', 'paper', '[]', '["/static/qimg/mz_sx_p4.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空题', 1, '{"stem": "下面物体可以描出哪些图形，在□内打「√」。（1）一块长方体薄板：右排选项有三角形、长方形、圆形、长方形等，每个图形下方有□；（2）一块三棱柱：右排选项有三角形、长方形、长方形等，每个图形下方有□。", "options": null}', '（1）长方体薄板能描出长方形（打√），不能描出三角形和圆形；（2）三棱柱能描出三角形（打√）和长方形（打√）。', '【认识图形】立体图形的面是什么形状。长方体的面是长方形；三棱柱的底面是三角形、侧面是长方形。', 'paper', '[]', '["/static/qimg/mz_sx_p4.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空题', 1, '{"stem": "看图：10个物品：①托盘 ②弹珠球 ③圆木 ④魔方 ⑤网球 ⑥足球 ⑦方盒 ⑧篮球 ⑨字典 ⑩电池。上面可以滚动的物品有（　），其中只能朝一个方向滚动的是（　），可以朝任何方向滚动的是（　）。", "options": null}', '可以滚动的：②③④⑤⑥⑧⑩；只能朝一个方向滚动的（圆柱形）：③圆木、⑩电池；可以朝任何方向滚动的（球形）：②弹珠、⑤网球、⑥足球、⑧篮球。', '【认识图形】球可以朝任何方向滚动；圆柱只能沿一个方向滚动；长方体、正方体不能滚动。', 'paper', '[]', '["/static/qimg/mz_sx_p5.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空题', 1, '{"stem": "小林和东东在玩摸一摸、猜一猜的游戏，小林闭眼接到一个物体有弯弯的部分也有平平的部分，是（　）。东东闭眼接到一个物体只有平平的部分，是（　）或（　）。①长方体 ②圆柱 ③球 ④正方体", "options": null}', '小林（有弯弯也有平平）：②圆柱；东东（只有平平）：①长方体或④正方体。', '【认识图形】圆柱有曲面（弯弯）也有平面（平平）；长方体和正方体只有平面；球只有曲面。', 'paper', '[]', '["/static/qimg/mz_sx_p5.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空题', 1, '{"stem": "看图数一数，一共有（　）块正方体。（图：方块堆叠立体图）", "options": null}', '【图示估读存疑】按图示堆叠的可见方块数，答案可能为 8 或 9 块，建议以教材原题为准核对。', '【认识图形】数方块：先数可见的方块，再数被遮挡的方块（按层数逐层数）。具体答案受图示视角影响存疑。', 'paper', '[]', '["/static/qimg/mz_sx_p5.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "连一连：把第一行的 8 个实物（①水杯 ②橄榄球 ③纸袋 ④魔方 ⑤面包 ⑥大盒子 ⑦篮球 ⑧皮管）和第二行的 4 个立体图形（圆柱、正方体、长方体、球）对应连起来。", "options": null}', '①水杯→圆柱；②橄榄球→球；③纸袋→长方体；④魔方→正方体；⑤面包→长方体；⑥大盒子→长方体；⑦篮球→球；⑧皮管→圆柱。', '【认识图形】按实物的整体形状判断：圆柱形（杯、管）、球形（橄榄球、篮球）、长方体（纸袋、面包、盒子）、正方体（魔方）。', 'paper', '[]', '["/static/qimg/mz_sx_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "按要求在括号内填入下列图形的编号。①长方体 ②圆柱 ③正方体 ④长方体（细高） ⑤圆柱（扁）。能描出长方形（▭）的物体是（　）号。", "options": null}', '①③④（长方体和正方体都有长方形面）。', '【认识图形】长方体和正方体都有长方形的面。圆柱的侧面展开是长方形。', 'paper', '[]', '["/static/qimg/mz_sx_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "按要求在括号内填入下列图形的编号。①长方体 ②圆柱 ③正方体 ④长方体（细高） ⑤圆柱（扁）。能描出正方形（□）的物体是（　）号。", "options": null}', '③（只有正方体能描出正方形）。', '【认识图形】正方体的 6 个面都是正方形。长方体的面是长方形不是正方形。', 'paper', '[]', '["/static/qimg/mz_sx_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线题', 1, '{"stem": "按要求在括号内填入下列图形的编号。①长方体 ②圆柱 ③正方体 ④长方体（细高） ⑤圆柱（扁）。能描出圆形（○）的物体是（　）号。", "options": null}', '②⑤（圆柱的底面是圆形）。', '【认识图形】圆柱的两个底面都是圆形。', 'paper', '[]', '["/static/qimg/mz_sx_p6.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，填一填：图中有 4 个 □（正方形）、4 个 ○（圆形）、2 个 △（三角形）、2 个 ▭（长方形），把正方形的个数填在□对应的（　）里。", "options": null}', '3（按 9 个图形分布，正方形 3 个）。', '【认识图形】题目图共 9 个平面图形：第 1 行 ○ □ △ ▭，第 2 行 ▭ ○ □ □ ○；其中正方形 □ 出现 3 次。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，填一填：把○（圆形）的个数填在对应的（　）里。", "options": null}', '3（第 1 行 1 个 + 第 2 行 2 个 = 3 个）。', '【认识图形】○ 出现 3 次。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，填一填：把△（三角形）的个数填在对应的（　）里。", "options": null}', '1（只出现 1 次）。', '【认识图形】△ 出现 1 次。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数立体图形，把长方体（长方形砖块状）的个数填在对应的（　）里。", "options": null}', '4（【图示估读】长方体形状的砖块共 4 个）。', '【图示估读】上方共约 12 个立体图形，长方体（扁长方块状）4 个。答案估读自图像，建议以教材原题为准。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数立体图形，把球（圆球形）的个数填在对应的（　）里。", "options": null}', '2（【图示估读】球形共 2 个）。', '【图示估读】图中有 2 个球（1 个深色小球 + 1 个灰色大球）。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数立体图形，把圆柱（直筒状）的个数填在对应的（　）里。", "options": null}', '3（【图示估读】圆柱形共 3 个）。', '【图示估读】图中有 3 个圆柱（横躺大圆柱、矮圆柱、灰短圆柱）。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数立体图形，把正方体（方块状）的个数填在对应的（　）里。", "options": null}', '3（【图示估读】正方体形共 3 个）。', '【图示估读】图中有 3 个正方体。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "在能站稳的图形下面打勾：①长方体上叠大方块 ②扁长方板上放球 ③大正方体上叠小正方体 ④长方体竖放叠在横放圆柱上 ⑤圆柱上叠正方体。", "options": null}', '①、③（两个平面接触时站得稳，球和圆柱面接触时易滚动）。', '【认识图形】能站稳需要底面是平面。①大平板底面平、③方块底面平都稳；②球、④圆柱面、⑤圆柱面都是曲面不稳。', 'paper', '[]', '["/static/qimg/mz_sx_p7.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "按规律接着摆哪个？圈出正确的答案：△ ▲ △ ▲ △ ▲ △ ▲ ＿＿（▲ △）", "options": null}', '▲ △（一白一黑交替排列）。', '【找规律】序列以 △ ▲ 一白一黑为单位重复，下一组是 ▲ △。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "按规律接着摆哪个？圈出正确的答案：○ ■ ○ ● ○ ● ○ ■ ○ ● ○ ＿＿（■ ○ ●）", "options": null}', '■ ○ ●（【图示估读】按图形循环规律，下一组为 ■ ○ ●）。', '【找规律】序列以○■○●○●○为一循环单位，下一组开头为■○●。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填空：△ ▲ ○ ● ■ ◇ 一共有（　）个图形。", "options": null}', '6。', '【数图形】序列共 6 个图形。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填空：在 △ ▲ ○ ● ■ ◇ 中，● 的右边是（　）和（　）；○ 的左边是（　）和（　）。", "options": null}', '● 右边是 ■ 和 ◇；○ 左边是 △ 和 ▲。', '【位置与顺序】从左到右依次是 △ ▲ ○ ● ■ ◇。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填空：△ ▲ ○ ● ■ ◇ 中，圆形共有（　）个。", "options": null}', '1（只有 ○）。', '【数图形】圆形只有 ○ 1 个。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填空：△ ▲ ○ ● ■ ◇ 中，正方形共有（　）个。", "options": null}', '1（只有 ■）。', '【数图形】正方形只有 ■ 1 个。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填空：△ ▲ ○ ● ■ ◇ 中，三角形共有（　）个。", "options": null}', '2（△ 和 ▲）。', '【数图形】△ 和 ▲ 都是三角形，共 2 个。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，共有几个正方体？（第一幅：底层 3×2 叠 + 顶部 1 个）", "options": null}', '7（【图示估读】底层 6 个 + 顶 1 个）。', '【数立体】图 1 立体由 6+1 = 7 个小正方体组成。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，共有几个正方体？（第二幅：阶梯状叠放）", "options": null}', '6（【图示估读】底层 4 个 + 上面 2 个 = 6）。', '【数立体】图 2 立体由 4+2 = 6 个小正方体组成。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，共有几个正方体？（第三幅：底层 3×2 叠 + 顶部 1 个）", "options": null}', '7（【图示估读】底层 6 个 + 顶 1 个）。', '【数立体】图 3 立体由 6+1 = 7 个小正方体组成。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，共有几个正方体？（第四幅：阶梯状叠放多块）", "options": null}', '8（【图示估读】阶梯叠放约 8 个）。', '【数立体】图 4 立体由约 8 个小正方体组成。答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）是长方体。A 长方体 B 正方体 C 圆柱（题面部分被截断）", "options": null}', 'A（长方体）。', '【认识图形】A 是长方体，B 是正方体（6 面等大），C 是圆柱（有曲面）。题面右侧被裁切，选项 BC 不可见，标存疑。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）不是圆柱。A 圆柱 B 长方体 C 球（题面部分被截断）", "options": null}', 'B、C（不是圆柱的有长方体、球等，题面被截）。', '【认识图形】圆柱特征是直筒状上下圆面，A 是圆柱，B 是长方体、C 是球。题面右侧被裁切，具体选项 B/C 标存疑。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）是球。A 球 B 正方体 C 圆柱（题面部分被截断）", "options": null}', 'A（球）。', '【认识图形】A 是球形，B 是正方体，C 是圆柱。题面右侧被裁切，选项 B/C 标存疑。', 'paper', '[]', '["/static/qimg/mz_sx_p8.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）是正方体。A 长方体（方框）B 正方体 C 长方体（高）D 长方体（扁）", "options": null}', 'B（6 个面都是正方形的是正方体）。', '【认识图形】正方体特征：6 个面都是相等的正方形。B 符合，A/C/D 都是长方体（相对面相等但不全为正方形）。', 'paper', '[]', '["/static/qimg/mz_sx_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）不是圆柱。A 圆柱（矮）B 圆柱（横躺）C 圆柱（斜躺）D 圆锥台", "options": null}', 'D（圆锥台不是圆柱）。', '【认识图形】圆柱特征：上下两个相等的圆面 + 侧面是曲面。A、B、C 都是圆柱，D 上小下大是圆锥台，不属于圆柱。', 'paper', '[]', '["/static/qimg/mz_sx_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "选择。（　）可以向任意方向滚动。（　）和（　）不可以滚动。A 球 B 圆柱（横躺）C 长方体 D 正方体", "options": null}', 'A 可以向任意方向滚动；C 和 D 不可以滚动（B 只能向一个方向滚动）。', '【认识图形】球 A 表面完全曲面，可任意方向滚动；长方体 C、正方体 D 都是平面，不能滚动；圆柱 B 只能沿轴向一个方向滚动，不能任意方向。', 'paper', '[]', '["/static/qimg/mz_sx_p9.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "想一想，连一连。立体图形与描述配对：长方体 / 球 / 圆柱 / 正方体（图形：①球 ②正方体 ③圆柱 ④长方体扁 ⑤长方体立）。", "options": null}', '长方体-⑤（不能滚动，每个面都是长长方方的）；球-①（可以朝任何方向滚动）；圆柱-③（可以朝一个方向滚动）；正方体-②（不能滚动，每个面都是正方形）。', '【认识图形】长方体特征：6 个面都是长方形（相对面相等），不能滚动；球可任意方向滚动；圆柱沿轴向滚动；正方体 6 个面都是正方形。', 'paper', '[]', '["/static/qimg/mz_sx_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填一填：（1）能描出正方形的图形是（　）。（填图①球②正方体③圆柱④长方体扁⑤长方体立 的编号）", "options": null}', '②（正方体能描出正方形）。', '【认识图形】正方体的每个面都是正方形，从它身上能描出正方形。', 'paper', '[]', '["/static/qimg/mz_sx_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填一填：（2）能描出圆形的图形是（　）。（填图①球②正方体③圆柱④长方体扁⑤长方体立 的编号）", "options": null}', '①和③（球描圆，圆柱上下底面是圆）。', '【认识图形】球面是曲面、整个表面能描圆；圆柱的上下底面是圆形。', 'paper', '[]', '["/static/qimg/mz_sx_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填一填：（3）能描出三角形的图形是（　）。", "options": null}', '⑤（【图示估读】图⑤立体带三角形面，能描出三角形）。', '【认识图形】图⑤立体【图示估读】其侧面或端面有三角形，可描出三角形。题面原图较模糊，答案估读自图像。', 'paper', '[]', '["/static/qimg/mz_sx_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "填一填：（4）能描出长方形的图形是（　）。", "options": null}', '④和⑤（长方体的面是长方形；正方体面是正方形不是长方形）。', '【认识图形】长方体（包括竖立和横放）的每个面都是长方形，描出长方形；正方体的面是正方形，不能描长方形。', 'paper', '[]', '["/static/qimg/mz_sx_p10.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "连一连：图序 ①长方形 ②正方体 ③正方形 ④足球（球） ⑤长方体 ⑥圆台 ⑦圆柱 ⑧圆形 ⑨三角形。题：（　）是正方体；（　）是长方体；（　）是圆柱；（　）是正方形；（　）是长方形；（　）是球；（　）是三角形；（　）是圆形。", "options": null}', '正方体→②；长方体→⑤；圆柱→⑦；正方形→③；长方形→①；球→④；三角形→⑨；圆形→⑧。', '【认识图形】区分立体与平面：立体有正方体、长方体、圆柱、球；平面有正方形、长方形、三角形、圆。⑥圆台是上下底大小不同的圆柱体，不属本节。', 'paper', '[]', '["/static/qimg/mz_sx_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数，填一填：大框内由多种图形组成。上面图形中，□（小长方形）有（　）个，□（正方形）有（　）个，○（圆形）有（　）个，△（三角形）有（　）个，□和○一共有（　）个。", "options": null}', '【图示估读】小长方形约 3 个、正方形约 2 个、圆形约 3 个、三角形约 3 个，□和○共约 5-6 个。', '【认识图形】分类计数：按形状分类数清楚再相加。建议核对原图（印刷较密、尺寸不一）。', 'paper', '[]', '["/static/qimg/mz_sx_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数：第一幅图（田字格内含小方）有（　）个正方形；第二幅图（长方形被分成小格）有（　）个长方形；第三幅图（同心圆加 6 个小圆）有（　）个圆。", "options": null}', '第一图有 5 个正方形（4 个 1×1 小正方形 + 1 个 2×2 大正方形）；第二图有 5 个长方形（4 个小长方 + 1 个整体大长方）；第三图有 7 个圆（6 个小圆 + 1 个大圆；如算上中圈可至 8）。', '【数图形】按由小到大分层数：1×1 拼出 2×2 时多出 1 个大图形；长方格细分同理；圆按半径大小分。', 'paper', '[]', '["/static/qimg/mz_sx_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "数一数：四幅立体图各由若干小方块堆成。第一幅（有　）个正方体；第二幅（有　）个正方体；第三幅（有　）个正方体；第四幅（有　）个长方体。", "options": null}', '第一幅（2×2×2 大方块）有 8 个正方体；第二幅【图示估读】约 4-5 个正方体；第三幅【图示估读】约 5-6 个正方体；第四幅（单竖立）有 1 个长方体。', '【数图形】按层数 × 每层小方块数。第一幅 2×2×2=8。第二、三幅图立体叠加有遮挡，需按从外向内分层数，建议核对原图。', 'paper', '[]', '["/static/qimg/mz_sx_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "看图数一数：火车积木图。有（　）个正方体、（　）个圆柱、（　）个长方体、（　）个球。", "options": null}', '【图示估读】正方体约 1 个（车顶）、圆柱约 2 个（锅炉+烟囱）、长方体约 2 个（车头+车身）、球约 3 个（车轮）。', '【数图形】按立体分类数。火车含锅炉（圆柱）、烟囱（圆柱）、车头（长方体）、车身（长方体）、车轮（球）等。建议核对原图细节。', 'paper', '[]', '["/static/qimg/mz_sx_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "看图数一数：小桌凳积木图。有（　）个正方体、（　）个圆柱、（　）个长方体、（　）个球。", "options": null}', '【图示估读】正方体约 2 个（椅腿底座+椅背）、圆柱约 4 个（椅腿）、长方体约 1 个（椅面）、球 0 个。', '【数图形】按立体分类数。桌凳由椅腿（圆柱）、底座（正方体）、椅背（正方体）、椅面（长方体）拼成，无球体。建议核对原图。', 'paper', '[]', '["/static/qimg/mz_sx_p12.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "三、分一分。把一个长方形分成完全相同的 2 个图形，你能想出几种方法？用虚线画出来。", "options": null}', '至少 3 种：①横着中线分（上下两个相同长方形）；②竖着中线分（左右两个相同长方形）；③对角线分（两个相同直角三角形）。其他还有阶梯切等不规则方法。', '【图形的分与合】分后两图形面积和形状都相同，不限方向。可上下、左右、对角分。本题考发散思维，至少 3 种。', 'paper', '[]', '["/static/qimg/mz_sx_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '图形题', 1, '{"stem": "四、拼一拼，连一连，画一画。上排是 4 个不完整的图形（半圆 C 形、4 形、缺角正方形、凹字 U 形），第二排是 4 个「另一半」（|、L、/、\\\\ 形），下排是 4 个完整正方形。把上排的每个图形与第二排对应的「另一半」连线，拼成下排的正方形。\\\"", "options": null}', '【图示估读】上排①半圆 C 与第二排①│（短竖）拼成一个正方形；上排②4 形（开口三角）与第二排②L 拼成正方形；上排③缺角正方形与第二排③/（斜线）拼成正方形；上排④凹字 U 与第二排④\（反斜线）拼成正方形。具体配对以原图为准。', '【图形的拼组】两图形要能拼成一个完整正方形，需形状互补、边长相等。教学上鼓励孩子动手剪拼验证。', 'paper', '[]', '["/static/qimg/mz_sx_p13.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "一、数一数，涂一涂，写一写。表格 4 行：① 5 个方框；② 2 个笑脸；③ 9 个星形（5+4）；④ 6 个黑色三角（3+3）。数出每行图形数量，在第三格写汉字，第四格写数字。", "options": null}', '① 5 个方框 → 五 → 5；② 2 个笑脸 → 二 → 2；③ 9 个星形 → 九 → 9；④ 6 个三角 → 六 → 6。', '【数与计数】1-10 的数数与书写。看图数图形，对应汉字和阿拉伯数字。', 'paper', '[]', '["/static/qimg/mz_sx_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、找规律填数。1. 0,( ),( ),3,( )", "options": null}', '1, 2, 4。规律：自然数 0、1、2、3、4 依次递增 1。', '【找规律】相邻两数差 1，是等差数列 d=1。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、找规律填数。2. ( ),3,5,( ),( )", "options": null}', '1, 7, 9。规律：从 1 开始的奇数列 1、3、5、7、9，相邻两数差 2。', '【找规律】等差数列 d=2，或奇数序列。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、找规律填数。3. 7,( ),5,( ),( ),( )", "options": null}', '6, 4, 3, 2。规律：从 7 开始递减的自然数 7、6、5、4、3、2，相邻两数差 1。', '【找规律】递减等差数列 d=-1。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、找规律填数。4. ( ),4,( ),8,( )", "options": null}', '2, 6, 10。规律：2、4、6、8、10 等差数列，相邻两数差 2。', '【找规律】等差数列 d=2，或 2 的倍数。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、图中哪一种图形里的桃子最多？在( )里打「√」。4 个图形（三角/正方/长方/圆）里分别装有桃子，找桃子最多的那个图形。", "options": null}', '长方形 ( ) 里桃子最多（共 6 个），打"√"。其他图形桃子都少于长方形。', '【看图数数】逐一数每个图形里的桃数，比较大小。', 'paper', '[]', '["/static/qimg/mz_sx_p14.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、分与合。第 1 题：图示 4（上）→ 中间方框（合），中间方框拆分为 1（左下）和 ☐（右下）。把 4 分一分。", "options": null}', '☐=3。4=1+3（4 可以分成 1 和 3）。', '【分与合】把一个数按要求分成两个部分。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、分与合。第 2 题：图示 2（上）☐（右）合成 10，10 拆分为 ☐（下）和 7。求两个 ☐ 各是几。", "options": null}', '上 ☐=8（2+8=10），下 ☐=3（10=7+3）。', '【分与合】2+8=10，10-7=3。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、分与合。第 3 题：图示 8（左）2（下）合成中间方框（合），中间方框又拆分为 4（右上）和 ☐（右下）。求中间方框和 ☐。", "options": null}', '中间方框=10（8+2=10），☐=6（10=4+6）。【图示估读存疑】右下方块数字可能为 6 而非 4，建议核对原图。', '【分与合】8+2=10，10=4+6。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "五、按要求，画一画。第 1 题：画 ☐，使 ☐ 比 ○ 少 2 个。图中原有 6 个 ○。", "options": null}', '画 4 个 ☐（6-2=4）。', '【比多少】求比已知数少几的数，用减法。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "五、按要求，画一画。第 2 题：画 ○，使 ○ 比 △ 多 3 个。图中原有 3 个 △。", "options": null}', '画 6 个 ○（3+3=6）。', '【比多少】求比已知数多几的数，用加法。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、把下面各数按要求排一排。2、1、8、3、4、6、0 按从大到小或从小到大顺序排成一列。", "options": null}', '从大到小：8>6>4>3>2>1>0；从小到大：0<1<2<3<4<6<8。', '【数的大小比较】10 以内数的大小排序。', 'paper', '[]', '["/static/qimg/mz_sx_p15.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、在( )里填上合适的数。3<( )（填一个比 3 大的数）。", "options": null}', '填 4（或 5、6、7、8、9、10 都行，题目不唯一）。', '【数的大小比较】在 3 后面的数都比 3 大。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、在( )里填上合适的数。4>( )（填一个比 4 小的数）。", "options": null}', '填 3（或 2、1、0 都行）。', '【数的大小比较】在 4 前面的数都比 4 小。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、在( )里填上合适的数。8<( )（填一个比 8 大的数）。", "options": null}', '填 9（或 10）。', '【数的大小比较】9、10 都比 8 大。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、在( )里填上合适的数。10>( )（填一个比 10 小的数）。", "options": null}', '填 9（或 8、7、6、5、4、3、2、1、0）。', '【数的大小比较】比 10 小的数有 0-9。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、数一数，填一填。数列：5、9、7、10、6、0、8、2。第 1 题：一共有 ( ) 个数，从右数起，7 是第 ( ) 个数。", "options": null}', '一共 8 个数；从右数起 7 是第 6 个数（从右数顺序：2、8、0、6、10、7、9、5）。', '【数数与位置】从右数起确定某个数的位置。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、数一数，填一填。数列：5、9、7、10、6、0、8、2。第 2 题：6 的左面有 ( ) 个数，比 9 小的数有 ( ) 个。", "options": null}', '6 的左面有 4 个数（5、9、7、10）；比 9 小的数有 6 个（5、7、6、0、8、2）。', '【数数与比较】数某个数的左边/比某数小的数。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、数一数，填一填。数列：5、9、7、10、6、0、8、2。第 3 题：10 排在最中间，从左往右数，它在第 ( ) 个，从右往左数，它在第 ( ) 个。", "options": null}', '从左往右数 10 在第 4 个，从右往左数 10 在第 5 个。', '【位置】同一数列从左/从右数位置不同。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、数一数，填一填。数列：5、9、7、10、6、0、8、2。第 4 题：圈出从右往左数最后面的 2 个数。", "options": null}', '圈出 2 和 8（从右往左最后 2 个：右 1 是 2，右 2 是 8）。', '【圈数】从右往左数出最后 2 个数并圈出。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、数一数，填一填。数列：5、9、7、10、6、0、8、2。第 5 题：从左往右数第 3 个数打「√」。", "options": null}', '在 7 上打 √（数列第 3 个是 7）。', '【找数】从左往右数第 3 个数。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、智力大冲浪。第 1 题：找规律。图示 △○☆□△○☆□[?]△○☆□，被矩形盖住一部分。被盖住部分至少有几个图形？把它们画出来。", "options": null}', '被盖住部分至少有 1 个图形，是 △（规律为 △○☆□ 周期循环，下一组开头应为 △）。', '【找规律】图形按周期 △○☆□ 重复，下一组开头接 △。', 'paper', '[]', '["/static/qimg/mz_sx_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、智力大冲浪。第 2 题：把方糖放进杯子里后，最甜的一杯水是 ( )。4 个杯子 A、B、C、D，A 满杯+2 块糖，B 半杯多水+2 块糖，C 少半杯水+2 块糖，D 满杯+1 块糖。", "options": null}', 'C（水最少+糖最多，最甜）。', '【生活数学】水越少糖越多越甜，水量与糖量的比值最小者最甜。', 'paper', '[]', '["/static/qimg/mz_sx_p16.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "智力大冲浪 3：接着应该怎样画？图 1 是 ⊙◇/☆△，图 2 是 ◇△/⊙☆，图 3 是 △☆/◇⊙，图 4（空）应画什么？", "options": null}', '图 4 第一行 ☆⊙，第二行 △◇（把 4 个 2×2 拼成 4×4 矩阵分析列规律：列 1=⊙,◇,△,☆；列 2=◇,△,☆,⊙；列 3=☆,⊙,◇,△；列 4=△,☆,⊙,◇，每列都是 ⊙,◇,☆,△ 循环）。', '【找规律】拉丁方阵型，每列 ⊙,◇,☆,△ 循环。', 'paper', '[]', '["/static/qimg/mz_sx_p17.jpg"]', 0);
