INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、解决问题 1：盘子里有 8 个苹果，吃掉一些，还剩 4 个。吃掉多少个苹果？", "options": null}', '8 - 4 = 4（个）。', '【减法应用】吃掉的 = 总数 - 剩下的 = 8 - 4 = 4。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、解决问题 2：一包饼干，小红吃了 4 块，还剩 4 块。一包饼干一共有几块？", "options": null}', '4 + 4 = 8（块）。', '【加法应用】总数 = 吃掉的 + 剩下的 = 4 + 4 = 8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、解决问题 3：一根绳子长 10 米，第一次剪去 4 米，第二次剪去 3 米，一共剪去几米？", "options": null}', '4 + 3 = 7（米）。', '【连续减法应用】一共剪去 = 第一次 + 第二次 = 4 + 3 = 7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、解决问题 4：图书角有连环画 4 本、故事书 6 本、科技书 8 本，故事书再买几本就和科技书本数一样多了？", "options": null}', '8 - 6 = 2（本）。', '【求差应用】再买的 = 科技书 - 故事书 = 8 - 6 = 2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、想一想：把 1、2、3、4、5 分别填在□中（一种方法中数字不可重复），使横行、竖列的和相等。", "options": null}', '【图示估读存疑】标准参考填法之一：中心填 3、底行填 1 与 5、剩余两□填 2 与 4，使各行各列和相等（建议以教材原题为准）。', '【幻方变种】把 1、2、3、4、5 填入 L 形或十字形使行/列和相等，答案多解。', 'paper', '[]', '["/static/qimg/mz_sx_p37.jpg"]', 0);
