INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "五、看图列式（10）：公交车上有一些小朋友，车外有 3 个小朋友在排队（□○□=□）", "options": null}', '8+3=11 或 3+8=11', '车上 8 人 + 车外 3 人 = 11 人；【图示估读】车上人数含驾驶员与乘客，请以教材原图为准。', 'paper', '[]', '["/static/qimg/mz_sx_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、填加法与减法算式（试）：根据例 7+2=9 推出 2+7=9、9-2=7、9-7=2，将 ○+□=☆ 写出对应的三个算式。", "options": null}', '□+○=☆；☆-○=□；☆-□=○', '加法交换律得 □+○=☆；由和差关系得 ☆-○=□、☆-□=○。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、填加法与减法算式（1）：根据 4+3=□ 推出 □-3=□；根据 3+5=□ 推出 □-5=□；根据 □-6=□ 推出 1+6=□。", "options": null}', '4+3=7, 7-3=4；3+5=8, 8-5=3；7-6=1, 1+6=7', '加法变减法，和-加数=另一加数。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、看图列两个加法算式和两个减法算式（左图 8 个白○ + 2 个灰○）：写出 □+□=□、□+□=□、□-□=□、□-□=□。", "options": null}', '8+2=10；2+8=10；10-8=2；10-2=8', '合起来 10 个○，10 = 8+2 = 2+8，差为 10-8 和 10-2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、看图列两个加法算式和两个减法算式（右图 3 只鸭 + 5 只鸭）：写出 □+□=□、□+□=□、□-□=□、□-□=□。", "options": null}', '3+5=8；5+3=8；8-3=5；8-5=3', '合起来 8 只鸭，加法交换得两组，减法得两组。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、用 9、3、2、4、7 选出三个数组成两个加法算式和两个减法算式。", "options": null}', '2+7=9；7+2=9；9-2=7；9-7=2', '选 2、7、9 三个数：2+7=9，交换得 7+2=9；和-加数=另一加数得 9-2=7、9-7=2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、智力大冲浪（1）：把 2、3、4、5、6、7 这几个数分别填在□里，使 □+□=□+□=□+□ 成立。", "options": null}', '2+7=3+6=4+5', '六个数总和 2+3+4+5+6+7=27，平均分 3 组每组和 9，组合为 2+7=3+6=4+5。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、智力大冲浪（2）：在○里填「>」或「<」。① 如果☆+9=△-9，那么☆○△；② 如果□-7=◇+7，那么□○◇。", "options": null}', '① ☆<△；② □>◇', '① 等式两边相等：☆+9=△-9，移项 △-☆=18，所以 ☆<△；② □-◇=14，所以 □>◇。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、智力大冲浪（3）：填数。①（ ）+1+4=9；② 10-（ ）-5=2；③（ ）-2-3=3。", "options": null}', '① 4；② 3；③ 8', '① 9-1-4=4；② 10-3-5=2；③ 3+2+3=8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、智力大冲浪（4）：明明有 10 本书，玲玲有 6 本书，明明给玲玲（ ）本书后，两人的书就一样多了。", "options": null}', '2', '明明比玲玲多 10-6=4 本，平分后每人都 8 本，明明给玲玲 2 本；检验：10-2=8，6+2=8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "一、直接写出得数。n2+4=    4+3=    5-3=    10-7-2=    8-4+2=n10-6=    5+5=    7-6=    3+6-6=    8-2-1=n8+1=    7+3=    0+3=    10-5+2=    7-7+4=n7-5=    1+8=    9-4=    2+8-6=    6+1-2=", "options": null}', '2+4=6；4+3=7；5-3=2；10-7-2=1；8-4+2=6；10-6=4；5+5=10；7-6=1；3+6-6=3；8-2-1=5；8+1=9；7+3=10；0+3=3；10-5+2=7；7-7+4=4；7-5=2；1+8=9；9-4=5；2+8-6=4；6+1-2=5', '按从左到右、从上到下的顺序依次口算：2+4=6、4+3=7、5-3=2、10-7-2=1、8-4+2=6；10-6=4、5+5=10、7-6=1、3+6-6=3、8-2-1=5；8+1=9、7+3=10、0+3=3、10-5+2=7、7-7+4=4；7-5=2、1+8=9、9-4=5、2+8-6=4、6+1-2=5。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "二、填表格（加法表）：第一列 加数 5 + 加数 3 = 和 8；第二列 加数□ + 加数 8 = 和 10；第三列 加数 2 + 加数□ = 和 9；第四列 加数□ + 加数 5 = 和 5。", "options": null}', '5+3=8；2+8=10；2+7=9；0+5=5', '由和-加数=另一加数补□：列 2 = 10-8=2；列 3 = 9-2=7；列 4 = 5-5=0。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "二、填表格（减法表）：第一列 被减数 7 - 减数 3 = 差□；第二列 被减数□ - 减数 5 = 差 1；第三列 被减数 4 - 减数□ = 差 2；第四列 被减数□ - 减数 3 = 差 3。", "options": null}', '7-3=4；6-5=1；4-2=2；6-3=3', '由被减数-减数=差、被减数-差=减数、被减数=减数+差 互推：列 1=7-3=4；列 2 被减数=1+5=6；列 3 减数=4-2=2；列 4 被减数=3+3=6。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "三、填空题（1）：减数是 8，差是 2，被减数是（    ）。", "options": null}', '10', '被减数=减数+差=8+2=10；验证：10-8=2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "三、填空题（2）：9 的分与合：6+( )=9；( )+1=9；( )+2=9。", "options": null}', '6+3=9；8+1=9；7+2=9', '9 的分与合共有 4 组：0+9=9、1+8=9、2+7=9、3+6=9、4+5=9。图中 6、1、2 分别对应 3、8、7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "三、填空题（3）：小华给了小明 1 个苹果后，两人的苹果就一样多了。小华原来比小明多（    ）个苹果。", "options": null}', '2', '给了 1 个就一样多，说明原本多 2 个；检验：多 2 个，给 1 个后差 1 个仍多 1 个？不对，给 1 个差减 2→0：原差 2×1=2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "5-5 ○ 5+1；7-1 ○ 7；8-3+1 ○ 4；5 ○ 2+3；▲+4 ○ ▲+2；◇-3 ○ ◇-8。分别填入「>」「<」或「=」。", "options": null}', '<；<；>；=；>；>', '依次计算：5-5=0<5+1=6；7-1=6<7；8-3+1=6>4；5=2+3=5；▲+4 比 ▲+2 多 2；◇-3 比 ◇-8 多 5。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "(1) 7-(  )=3；(2) 2+(  )=9；(3) (  )+3=6-2；(4) 8=1+(  )；(5) (  )-3=5；(6) 1+3+(  )=8；(7) (  )-2+3=6；(8) 7+(  )-3=6。", "options": null}', '4；7；1；7；8；4；5；2', '(1) 7-?=3→4；(2) 2+?=9→7；(3) 6-2=4, ?+3=4→1；(4) 8=1+?→7；(5) ?-3=5→8；(6) 1+3=4, ?=8-4=4；(7) ?-2+3=6→?=5；(8) 7+?-3=6→?=2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "5 盘 〇 排列（从左到右）。(1) 第 1 盘有（    ）个〇，第 2 盘有（    ）个〇。(2) 有 6 个〇的是第（    ）盘，它左面一盘有（    ）个〇，右面一盘有（    ）个〇。(3) 第（    ）盘和第（    ）盘〇合起来是 7 个。【图示估读存疑】每盘具体个数以教材原题为准。", "options": null}', '（1）3, 1；（2）5, 5, 无；（3）1 和 4 盘（3+4=7）或 2 和 5 盘（1+6=7）。', '由题反推：若第 1 盘 3 个、第 2 盘 1 个、则后三盘可推；常见排列 3,1,4,5,6。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "在 8、6、3、5 中选 3 个数，列出 4 个算式（用三个方框表示所选数字）。", "options": null}', '3+5=8；5+3=8；8-3=5；8-5=3', '选 3、5、8：因为 3+5=8 是这四个数里唯一可组成 3 数算式的关系；其他组合 6、3、5 → 6-3=3 用不到另一数；6、5、8 → 6+5=11, 8-6=2 用到 2。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 2, '{"stem": "□-2>4，□ 里不能填（    ）。A. 7；B. 9；C. 6；D. 10。", "options": null}', 'C（6）。因为 □-2>4 即 □>6，所以 7、9、10 都满足，6 不满足。', '□-2>4 → □>6；选项中只有 6 不满足（6-2=4 不大于 4）。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "2. 7 比（    ）大 2。A. 3；B. 5；C. 7；D. 9。", "options": null}', 'B（5）。因为 7-2=5，5 比 7 小 2 等价于 7 比 5 大 2。', '7-2=5；选项 A=3（差 4），B=5（差 2 ✓），C=7（差 0），D=9（差 -2）。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。1. 10 个南瓜, 虚线分隔成 6+4 两组, 列算式。", "options": null}', '6+4=10', '凑十法：6+4=10；虚线表示将 10 拆为 6 和 4 两组。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。2. 自行车若干辆（图中可见约 5 辆）, 加上 ? 辆, 共有 10 辆, 列算式。【图示估读存疑】", "options": null}', '5+5=10（或 4+6=10，视具体可见数而定）', '图示估读：若图可见 5 辆则 ?=5；若可见 4 辆则 ?=6。题目表达「共有 10 辆」, 列加法算式。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。3. 5 个蛋糕, 其中 2 个被叉划掉, 剩 1 个, 列算式。", "options": null}', '5-2=3（3 个未被划掉）；或 5-4=1（剩 1 个）。两种解读，建议 5-4=1。', '5 个蛋糕, 划掉 4 个, 剩 1 个 → 5-4=1；若理解为划掉 2 个剩 3 个 → 5-2=3。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。4. 左 3 个〇, 右 3 个〇, 箭头合并, 列算式。", "options": null}', '3+3=6', '两部分合并用加法: 3+3=6。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。5. 4 个五角星 + 3 个方块, 箭头合并, 列算式。", "options": null}', '4+3=7', '两部分合并用加法: 4+3=7。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "六、看图列式。6. 3 个盒子, 各装〇: 第一个 3 个, 第二个 2 个, 第三个 5 个, 列算式。", "options": null}', '3+2+5=10', '三个盒子总数 = 各盒之和: 3+2+5=10。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、看图: 6 个白△ + 2 个黑▲ = 8 个三角形, 列 3 个算式（加 1 道、减 2 道）。", "options": null}', '6+2=8；8-2=6；8-6=2', '总数=白+黑=6+2=8；总数-黑=白=8-2=6；总数-白=黑=8-6=2。', 'paper', '[]', '["/static/qimg/mz_sx_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "七、根据问题列式。看图: 鸟巢中有 1 只大鸟和 3 只小鸟, 共 4 只。n(1) 一共有几只鸟？( )+( )=( )(只)n(2) 一共有几只鸟？( )+( )=( )(只)（另一顺序）n(3) 大鸟有几只？( )-( )=( )(只)n(4) 小鸟有几只？( )-( )=( )(只)", "options": null}', '(1) 1+3=4；(2) 3+1=4；(3) 4-3=1；(4) 4-1=3', '总数=大+小=4；加法交换律: 1+3=3+1=4；减法: 总数-部分=另一部分。', 'paper', '[]', '["/static/qimg/mz_sx_p45.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "1. 蝴蝶和蜻蜓一共有 10 只, 其中蜻蜓有 6 只, 蝴蝶有几只？", "options": null}', '10-6=4（只）', '总数-蜻蜓=蝴蝶: 10-6=4。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "2. 树上原来有 4 只鸟, 又飞来 3 只, 现在有几只鸟？", "options": null}', '4+3=7（只）', '原来+增加=现在: 4+3=7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "3. 亮亮买书用去 5 元, 还剩 3 元, 亮亮原来有几元？", "options": null}', '5+3=8（元）', '用去+剩=原有: 5+3=8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "4. 车上原来有 10 人, 先下去了 5 人, 又上来了 5 人, 现在有几人？", "options": null}', '10-5+5=10（人）', '原来-下去+上来=现在: 10-5+5=10, 人数不变。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "5. 水里有 8 只鸭子, 游走几只后, 水里还剩 5 只？（求游走几只）", "options": null}', '8-3=5, 游走 3 只', '总数-游走=剩, 故游走=8-5=3, 列式 8-3=5。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "一、用不同的方法把 8 个星星分成两堆。n可以分成( )个和( )个；( )个和( )个；( )个和( )个；( )个和( )个。", "options": null}', '1+7=8, 2+6=8, 3+5=8, 4+4=8（任选 4 种, 如 5+3、3+5、2+6、6+2）【图示估读存疑：原图 8 星分布, 4 种分法供参考】', '8 的分解: 0+8, 1+7, 2+6, 3+5, 4+4, 5+3, 6+2, 7+1, 8+0, 任选 4 种即可。', 'paper', '[]', '["/static/qimg/mz_sx_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、哪些小猫是好朋友？用线连一连。n算式: 3+4, 4+4, 5+2, 9-0, 10-1, 10-2n（和/差相等的算式配对）", "options": null}', '3+4=7 与 5+2=7 配对；9-0=9 与 10-1=9 配对；4+4=8 与 10-2=8 配对（共 3 对朋友）', '等值配对: 和/差相同的算式是小猫朋友。3 对: (3+4, 5+2) 都=7; (9-0, 10-1) 都=9; (4+4, 10-2) 都=8。', 'paper', '[]', '["/static/qimg/mz_sx_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "三、看图, 在 □ 里填数。图: 2 个蛋糕 + 3 个蛋糕。n5=2+□n5=□+2n2+□=□+2", "options": null}', '5=2+3, 5=3+2, 2+3=3+2', '2+3=5, 5=2+3, 5=3+2, 加法交换律: 2+3=3+2。', 'paper', '[]', '["/static/qimg/mz_sx_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "2. 看图填数。图: 4 朵大花 + 5 朵小花 = 9 朵。n9 = □ + 4n9 = 4 + □n□ + 4 = 4 + □", "options": null}', '9=5+4, 9=4+5, 5+4=4+5（□=5）', '4+5=9, 加法交换律: 5+4=4+5。', 'paper', '[]', '["/static/qimg/mz_sx_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "3. 看图填数。图: 5 个苹果 + 3 个樱桃。n□ = □ + □n□ = □ + 3n□ + □ = □ + □", "options": null}', '8=5+3, 8=5+3, 5+3=3+5', '5+3=8, 8=5+3, 加法交换律: 5+3=3+5。', 'paper', '[]', '["/static/qimg/mz_sx_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "四、填不同的算式, 使它们的得数都等于 5。（中心 5, 6 个分支, 上方已给 10-5）", "options": null}', '10-5=5, 0+5=5, 1+4=5, 2+3=5, 3+2=5, 4+1=5（任选 5 个填入, 与上方 10-5 不重复即可）', '得数为 5 的算式: 0+5, 1+4, 2+3, 3+2, 4+1, 5+0, 10-5, 9-4, 8-3, 7-2, 6-1 等, 6 个分支各填 1 个, 不得重复。', 'paper', '[]', '["/static/qimg/mz_sx_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "五、填一填。1) 3 +3=□ +4=□", "options": null}', '3+3=6, 6+4=10', '3+3=6, 6+4=10。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "五、填一填。2) 9 -1=□ -5=□", "options": null}', '9-1=8, 8-5=3', '9-1=8, 8-5=3。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "五、填一填。3) 4 +5=□ -6=□", "options": null}', '4+5=9, 9-6=3', '4+5=9, 9-6=3。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "五、填一填。4) 10 -7=□ +3=□", "options": null}', '10-7=3, 3+3=6', '10-7=3, 3+3=6。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "六、把下面算式按答案从小到大的顺序排列。n7+0, 5-3, 2+4, 4+1, 6+3n( ) < ( ) < ( ) < ( ) < ( )", "options": null}', '5-3=2 < 4+1=5 < 2+4=6 < 7+0=7 < 6+3=9', '先算各算式结果: 7, 2, 6, 5, 9；排序: 2<5<6<7<9, 对应 (5-3) < (4+1) < (2+4) < (7+0) < (6+3)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、这些花朵各应该放在哪个花盆中？用线将算式和结果连起来。n算式（花朵）: 2+5+3, 5+5-5, 9-5+2, 7-4+7, 10-1-3, 8-3+0, 4+6-0, 9-2-2n花盆: 10 / 6 / 5", "options": null}', '10: 2+5+3, 7-4+7, 4+6-0；6: 9-5+2, 10-1-3；5: 5+5-5, 8-3+0, 9-2-2', '逐个计算: 2+5+3=10, 5+5-5=5, 9-5+2=6, 7-4+7=10, 10-1-3=6, 8-3+0=5, 4+6-0=10, 9-2-2=5；按得数归入对应花盆。', 'paper', '[]', '["/static/qimg/mz_sx_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、说一说，列式计算。图: 一只猫和 6 条鱼，旁边写了「吃掉 2 条」, 问现在还剩下几条鱼？n□ ○ □ = □（  ）", "options": null}', '6 - 2 = 4（条）', '原有 6 条, 吃掉 2 条, 剩下 6-2=4 条。', 'paper', '[]', '["/static/qimg/mz_sx_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、说一说，列式计算。图: 三组树叶（虚线框区分），一共有多少片树叶？n□ + □ + □ = □（  ）", "options": null}', '【图示估读存疑】3 + 4 + 1 = 8（片）', '【图示估读存疑】按图中三组树叶估读为 3+4+1=8, 实际数量需以教材原题为准; 关键考点是三数连加。', 'paper', '[]', '["/static/qimg/mz_sx_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、说一说，列式计算。图: 一组水果（虚线框）, 划掉一部分, 还剩多少个水果？n□ - □ - □ = □（  ）", "options": null}', '【图示估读存疑】5 - 2 - 1 = 2（个）', '【图示估读存疑】按图中估读为 5-2-1=2, 实际数量需以教材原题为准; 关键考点是连减法。', 'paper', '[]', '["/static/qimg/mz_sx_p48.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。6 + □ + 2 = 9", "options": null}', '□ = 1', '设□=x: 6+x+2=9, 8+x=9, x=1。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。8 - 3 - □ = 1", "options": null}', '□ = 4', '设□=x: 8-3-x=1, 5-x=1, x=4。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。7 = 3 + □ - 3", "options": null}', '□ = 7', '设□=x: 7=3+x-3= x, 所以 x=7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。10 - 4 = 5 - □ + 2", "options": null}', '□ = 1', '10-4=6; 设□=x: 5-x+2=6, 7-x=6, x=1。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。3 + 1 = □ - 0 - 4", "options": null}', '□ = 8', '3+1=4; 设□=x: x-0-4=4, x=8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、在□中填数。3 + □ < 9 - 5（□里可以填几？）", "options": null}', '□ 可填 0, 1, 2, 3（即 □ < 4 的非负整数）', '9-5=4; 3+□<4 即 □<4, □可填 0、1、2、3。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十、在（）里填 \\\">\\\" \\\"<\\\" 或 \\\"=\\\"。△ + 2 = □ - 2, △（  ）□\\\"", "options": null}', '△ < □', '△+2=□-2 → △+4=□ → △ 比 □ 少 4, 所以 △<□。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十、在（）里填 \\\">\\\" \\\"<\\\" 或 \\\"=\\\"。△ - 9 = ○ - 7, △（  ）○\\\"", "options": null}', '△ > ○', '△-9=○-7 → △-○=2 → △ 比 ○ 多 2, 所以 △>○。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十一、先选择合适的词填在 __ 上, 再列式计算。明明吹了 10 个气球, 飞走了 3 个, __ 几个？n（A）剩下  （B）一共  （C）飞走n算式: __", "options": null}', '选（A）剩下；算式: 10 - 3 = 7（个）', '「飞走了 3 个」后求「现在有几个」, 应用「剩下」, 列式 10-3=7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十一、先选择合适的词填在 __ 上, 再列式计算。草地上的马跑了 4 匹后, 还剩 5 匹, __ 有多少匹？n（A）还剩  （B）原来  （C）跑来n算式: __", "options": null}', '选（B）原来；算式: 4 + 5 = 9（匹）', '「跑了 4 匹后还剩 5 匹」, 求「一共有多少」, 应用「原来」, 列式 4+5=9。', 'paper', '[]', NULL, 0);
