INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、1. 16 是一个( )位数, 与它相邻的两个数是( )和( ); 2 个十是( ), 它里面有( )个 5。", "options": null}', '两; 15, 17; 20; 4', '16 是两位数, 相邻两个数是 15 和 17。2 个十是 20, 20÷5=4, 里面有 4 个 5。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、2. 20-6=( )+4=( )-5=17-( ), 填空。", "options": null}', '10; 19; 3', '20-6=14, 所以 ( )+4=14 → 10; ( )-5=14 → 19; 17-( )=14 → 3。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、3(1). 给定 7 个数: 1, 15, 12, 7, 4, 20, 16, 其中双数是( ), 共( )个; 单数是( ), 共( )个。", "options": null}', '双数 4, 12, 16, 20 共 4 个; 单数 1, 7, 15 共 3 个', '双数 (个位 0/2/4/6/8): 4, 12, 16, 20 共 4 个。单数: 1, 7, 15 共 3 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、3(2). 从右边数起第 5 个数是( ), 它的左边有( )个数。", "options": null}', '4; 4', '从右数起第 5 个: 1, 15, 12, 7, 4 → 4。左边有 4 个数 (1, 15, 12, 7)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算题', 1, '{"stem": "二、3(3). 把这些数 (1, 15, 12, 7, 4, 20, 16) 从小到大排列, 用小于号连接。", "options": null}', '1 < 4 < 7 < 12 < 15 < 16 < 20', '从小到大: 1, 4, 7, 12, 15, 16, 20。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、4. 😊 表示一个数, 如果😊+4=11, 那么😊+😊=( )。", "options": null}', '14', '😊+4=11 → 😊=7, 😊+😊=7+7=14。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、5. 在○里填\\\">&\\\"<\\\"或\\\"=\\\"：9○11、6+13○3+6、△-4○△-6、7+8○20-5、17-3○17+3、□-1○□+1。\\\"", "options": null}', '<; >; >; =; <; <', '9<11; 6+13=19>3+6=9; △-4>△-6 (减 4 比减 6 大); 7+8=15=20-5; 17-3=14<17+3=20; □-1<□+1。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、6. 从 6, 8, 12, 18 中选三个数, 写出两个加法算式和两个减法算式（示例：6, 8）。", "options": null}', '6+8=14, 8+6=14, 14-6=8, 14-8=6', '用 6, 8, 14: 两个加法 6+8=14, 8+6=14; 两个减法 14-6=8, 14-8=6。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、7(1). 6+( )=10, ( )-2=8, 14-( )=( )+12。", "options": null}', '4; 10; 14-2=0+12 (即 14-(2)=0+12)', '6+4=10; 10-2=8; 14-2=0+12 满足 14-( )=( )+12, 答案不唯一。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、7(2). 8+( )+3=16, ( )-7+2=12, 16-( )-2=10。", "options": null}', '5; 17; 4', '8+5+3=16; 17-7+2=12; 16-4-2=10。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、8. 如果△+○=□, 那么( )-( )=( ), ( )-( )=( )。填空。", "options": null}', '□-○=△, □-△=○', '由 △+○=□ 可推出 □-○=△, □-△=○。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、9. 照样子填数：示例 (15 14 在上, 6 9 5 在下), 现 (13 12 / 1 12 0) 和 (17 ? / 8 ? 7)。求第三组的方框数字。", "options": null}', '中间方框=9, 上面右侧方框=16', '规律: 中间=左侧+右侧, 上面=中间+另一侧。第三组: 中间=8+? 应等于 17 → ?=9 (中间); 上面右侧=9+7=16。【图示估读】图形结构依赖原图, 答案以教材为准。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、1. 一个加数是 12, 和是 20, 另一个加数是几？", "options": null}', '20-12=8', '加数+加数=和, 另一个加数=和-加数=20-12=8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、2. 减数是 11, 差是 5, 被减数是多少？", "options": null}', '11+5=16', '被减数-减数=差, 被减数=减数+差=11+5=16。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、3. 比 14 大 6 的数是多少？", "options": null}', '20', '14+6=20, 即比 14 大 6 的数是 20。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、1. 原来有 16 个小朋友在做游戏, 有 7 个小朋友回家了, 现在有几个小朋友在做游戏？", "options": null}', '16-7=9', '总数 - 回家 = 留下, 16-7=9 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、2. 妈妈买来一些苹果, 吃掉 8 个后, 还剩 9 个, 妈妈买来几个苹果？", "options": null}', '8+9=17', '吃掉的 + 剩下的 = 总数, 8+9=17 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、3. 原来有 17 粒糖, 小华吃掉一些后, 还剩 12 粒, 小华吃了几粒？", "options": null}', '17-12=5', '总数 - 剩下 = 吃掉的, 17-12=5 粒。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、4. 小辰一周得到 8 颗星, 小巧和小亚都得了 6 颗星。他们三人共得多少颗星？", "options": null}', '8+6+6=20', '小辰 8 + 小巧 6 + 小亚 6 = 20 颗星。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、5(1). 一根彩带共长 20 米, 第一次用去 6 米, 第二次用去 5 米, 一共用去多少米？", "options": null}', '6+5=11', '第一次用去 + 第二次用去 = 一共用去, 6+5=11 米。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、5(2). 一根彩带共长 20 米, 第一次用去 6 米, 第二次用去 5 米, 还剩多少米？", "options": null}', '20-11=9', '总长 - 用去 = 剩下, 20-11=9 米。', 'paper', '[]', NULL, 0);
