INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、1. 看图: 蘑菇房子内 ? 只, 外 6 只, 共 10 只。算式: ☐○☐=☐( )。", "options": null}', '10-6=4(只); 房子内有 4 只', '总数 - 外面 = 里面, 10-6=4 只。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、2. 看图: 星星分两堆, 一堆 5 颗, 一堆 6 颗, 共多少? 算式: ☐○☐○☐=☐。", "options": null}', '5+6=11(颗)', '【图示估读】5+6=11 颗, 共 11 颗。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、1. 妈妈买来 18 个梨, 吃了几个后还剩 6 个, 吃了几个?", "options": null}', '18-6=12(个)', '总 - 剩 = 吃, 18-6=12 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、2. 操场上有 15 个学生, 男生有 3 个, 女生有几个?", "options": null}', '15-3=12(个)', '总 - 男 = 女, 15-3=12 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、3. 树上原有 5 只小鸟, 飞走了 2 只, 又飞来了 7 只, 现在有几只小鸟?", "options": null}', '5-2+7=10(只)', '原 - 飞走 + 飞来 = 5-2+7=10 只。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、4(1). 小巧做了 6 朵花, 小亚做了 5 朵花, 她俩一共做了多少朵花?", "options": null}', '6+5=11(朵)', '6+5=11 朵。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、4(2). 她俩再做几朵就有 16 朵花了?", "options": null}', '16-11=5(朵)', '目标 - 已有 = 还需, 16-11=5 朵。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十、1. 小辰原来有 8 本故事书, 又买了 5 本。问题: 还剩多少本/现在有多少本? 连线后再列式。", "options": null}', '连「现在有多少本」; 8+5=13(本)', '已知原来 + 又买, 条件适合「现在有多少本」(8+5=13), 不适合「还剩多少本」(无卖出数据)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十、2. 小巧一家吃了 7 个苹果, 还剩 10 个。问题: 一共有几个苹果? 列式。", "options": null}', '7+10=17(个)', '吃了 + 还剩 = 总, 7+10=17 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "十、2. 小巧一家吃了 7 个苹果, 还剩 10 个。问题: 还剩几个苹果? 列式。", "options": null}', '10(个)', '已知还剩 10 个, 直接写 10 个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "一、1. 在( )里填数: ( )+6=12, 14-( )=8, ( )-5=13。", "options": null}', '6; 6; 18', '( )=12-6=6; ( )=14-8=6; ( )=13+5=18。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "一、2. 在○里填>、<或=: 11-5○11+5, 12-4○3+5, ◆-18○◆-19。", "options": null}', '<; =; >', '11-5=6 < 11+5=16; 12-4=8 = 3+5=8; 减数小的差大, ◆-18 > ◆-19。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、从 19、8、17、16、9、14、2、7 中选三个数, 组成两道加法算式和两道减法算式(最少写两组)。", "options": null}', '组1: 7+2=9, 7+9=16, 16-7=9, 9-7=2; 组2: 9+8=17, 17-8=9, 19-2=17, 19-17=2', '【图示估读】三数满足 a+b=c, 任一组如 7+2=9, 再衍生 7+9=16/9+8=17, 即可配出加+减算式。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、推算(找规律)。表格: 5+6=11 (左上), 7+6=13 (右上), 6+7=13 (中下), 其余空格。", "options": null}', '【图示估读】左下: 5+7=12; 右下: 5+8=13(规律: 左列+右列=右下)。', '【图示估读】横竖交叉规律, 不同理解有不同答案, 实际以教材原题为准。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、1. 数一数, 下面一共有( )辆小汽车, 再增加( )辆就是 20 辆车了。", "options": null}', '12(辆); 8(辆)', '【图示估读】3 行 × 4 列 = 12 辆; 20-12=8 辆。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、在○里填>、<或=: 19○3+13, 5+11○4+7, 15-9○15+9, 18-5○6+7, 9+7-4○9-7+4, 20-☆○10-☆。", "options": null}', '> ; > ; < ; = ; = ; >', '19>3+13=16; 5+11=16>4+7=11; 15-9=6<15+9=24; 18-5=13=6+7=13; 9+7-4=12=9-7+4=12; ☆(≤10)时 20-☆>10-☆。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、找规律填数(1) 20, 18, ( ), ( ), 12, ( )。规律: 依次减 2。", "options": null}', '16, 14, 10', '公差 -2: 20-2=18, 18-2=16, 16-2=14, 14-2=12, 12-2=10。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "三、找规律填数(2) 2, 3, ( ), 3, 6, 3, ( ), ( )。规律: 奇数位 +2, 偶数位均为 3。", "options": null}', '4; 8', '【图示估读】奇数位 2,?,6,? 公差 4, 故为 2,4,6,8; 偶数位恒为 3。实际以教材原题为准。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、1. 看图填编号。长方体是__, 正方体是__, 球是__, 圆柱是__。图中 8 个立体: ①球 ②长方体 ③三棱柱 ④长方体 ⑤正方体 ⑥长方体 ⑦圆柱 ⑧正方体。", "options": null}', '②; ⑤⑧; ①; ⑦', '【图示估读】长方体②⑥(三棱柱非长方), 正方体⑤⑧, 球①, 圆柱⑦; ④图为三棱柱非长方体。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "四、2. 能朝任何方向滚动的是__。", "options": null}', '①(球)', '球可朝任何方向滚动, 圆柱只能沿一个方向(轴向)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "五、★=2, △=3, ●=6, 填(): △△●=( ), ★★△=( ), ★●●=( )。已知 ★△●=11。", "options": null}', '12; 7; 14', '★★△=2+2+3=7; △△●=3+3+6=12; ★●●=2+6+6=14; 验证 ★△●=2+3+6=11 ✓。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、1. 看图: 盒子里有 8 个苹果, 圈出 5 个, 剩下多少个苹果?", "options": null}', '3 个', '8-5=3(个); 答: 剩下 3 个苹果。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、2. 美术组有女同学 8 名, 男同学 9 名, 美术组共有多少名同学?", "options": null}', '17 名', '8+9=17(名); 答: 美术组共有 17 名同学。', 'paper', '[]', NULL, 0);
