INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、4. 盒子里放了红花和黄花共 13 朵, 其中黄花有 4 朵, 红花有多少朵?", "options": null}', '9 朵', '13-4=9(朵); 答: 红花有 9 朵。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、5. 商店星期天卖出 12 台彩电, 还剩下 5 台, 商店原来有多少台彩电?", "options": null}', '17 台', '12+5=17(台); 答: 商店原来有 17 台彩电。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "六、6. 一本书有 20 页, 小巧第一天看了 6 页, 第二天看的页数与第一天同样多, 还有多少页没有看?", "options": null}', '8 页', '20-6-6=8(页); 答: 还有 8 页没有看。', 'paper', '[]', NULL, 0);
