INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "七、想一想填一填: 已知 □+□+□=○, □=#+#+#, 则 #+○+#=(  )个□。【图示估读存疑】", "options": null}', '3 个□', '#+○+# = 2#+3□ = (11/3)个□ 非整数，存疑；按整数最接近填 3 个□。建议以教材原题为准。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、1. 小华买了 2 杯豆浆, 一共花了多少元?", "options": null}', '4 元', '2+2=4(元); 答: 一共花了 4 元。', 'paper', '[]', NULL, 0);
