INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、3. 小华爸爸付给营业员 20 元, 买了一个汉堡, 找回多少元?", "options": null}', '5 元', '20-15=5(元); 答: 找回 5 元。', 'paper', '[]', NULL, 0);
