INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "八、5. 一个热狗的价格比一个汉堡的价格便宜多少元?", "options": null}', '5 元', '15-10=5(元); 答: 便宜 5 元。', 'paper', '[]', NULL, 0);
