INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 56% | 三、Read and choose.（情景选择。）15% 4. 在街上碰到同学，你可以说：", "options": ["A. Thank you!", "B. Hello!"]}', 'B', '【Unit 2 情景选择】街头打招呼用 Hello。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 56% | 三、Read and choose.（情景选择。）15% 5. 当你想说「我叫 Alice.」时，可以说：", "options": ["A. Your name is Alice.", "B. I''m Alice."]}', 'B', '【Unit 2 情景选择】自我介绍用 I am / I''m + 名字。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 3, '{"stem": "Part 2 Reading and writing 56% | 四、Read and complete.（补全对话，一空一词。）21% A: Hello! 1. ______ ______ is Kate Perry.", "options": null}', 'My;name', '【Unit 2 补全对话】自我介绍 My name is Kate Perry.，一空一词。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 3, '{"stem": "Part 2 Reading and writing 56% | 四、Read and complete.（补全对话，一空一词。）21% B: Hi, Perry! 2. ______ Daming.", "options": null}', 'I''m', '【Unit 2 补全对话】自我介绍 I''m Daming.。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 3, '{"stem": "Part 2 Reading and writing 56% | 四、Read and complete.（补全对话，一空一词。）21% B: 3. ______.", "options": null}', 'Welcome', '【Unit 2 补全对话】承接欢迎话题，此处 B 对 A 的名字表示欢迎：Welcome。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 3, '{"stem": "Part 2 Reading and writing 56% | 四、Read and complete.（补全对话，一空一词。）21% 4. ______ ______ China, Kate.", "options": null}', 'to;Welcome', '【Unit 2 补全对话】Welcome to China, Kate.（欢迎来到中国。）注意 4 题在 3 题 Welcome 句子里，4 题承接 3 题共两空，答案为 to;Welcome。', 'paper', '[]', NULL, 0);
