INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 一、Look and tick.（看图打√）4. 图：尺子", "options": ["A. Use my ruler.", "B. Use my pencil."]}', 'A', '【Unit 3】图为带刻度的尺子,应选 Use my ruler(用我的尺子)。pencil 铅笔与图不符。', 'paper', '[]', '["/static/qimg/yg_yy_p013.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 一、Look and tick.（看图打√）5. 图：铅笔盒（深色长方体）", "options": ["A. Oh, no! My pencil case!", "B. Oh, no! My schoolbag!"]}', 'A', '【Unit 3】图为深色长方体铅笔盒,应选 Oh, no! My pencil case!(噢不!我的铅笔盒!)。schoolbag 书包与图不符。', 'paper', '[]', '["/static/qimg/yg_yy_p013.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 二、Read and choose.（选出不同类的一项）10% 1.", "options": ["A. book", "B. pencil", "C. evening"]}', 'C', '【Unit 3】A. book(书) B. pencil(铅笔) 都是学习用品,C. evening(傍晚) 是时间名词,不同类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 二、Read and choose.（选出不同类的一项）10% 2.", "options": ["A. hi", "B. hello", "C. good"]}', 'C', '【Unit 3】A. hi(喂) B. hello(你好) 都是问候语,C. good(好的) 是形容词/副词,不同类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 二、Read and choose.（选出不同类的一项）10% 3.", "options": ["A. me", "B. my", "C. your"]}', 'A', '【Unit 3】B. my(我的) C. your(你的) 都是形容词性物主代词,A. me(我,宾格) 是宾格代词,不同类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 二、Read and choose.（选出不同类的一项）10% 4.", "options": ["A. pack", "B. nice", "C. use"]}', 'B', '【Unit 3】A. pack(装) C. use(使用) 都是动词,B. nice(美好的) 是形容词,不同类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 二、Read and choose.（选出不同类的一项）10% 5.", "options": ["A. what", "B. how", "C. name"]}', 'C', '【Unit 3】A. what(什么) B. how(怎样) 都是疑问词,C. name(名字) 是名词,不同类。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 三、Choose the best answer.（选择最恰当的答案）10% 1. Pack _____ schoolbag.", "options": ["A. my", "B. me", "C. I"]}', 'A', '【Unit 3】修饰名词 schoolbag 应用形容词性物主代词 my。me 宾格、I 主格都不行。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 三、Choose the best answer.（选择最恰当的答案）10% 2. I pack _____ eraser.", "options": ["A. a", "B. an", "C. some"]}', 'B', '【Unit 3】eraser 以元音音素开头,不定冠词用 an。a 用于辅音音素,some 后接复数/不可数。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 三、Choose the best answer.（选择最恰当的答案）10% 3. What _____ I take to school?", "options": ["A. am", "B. do", "C. are"]}', 'B', '【Unit 3】主语 I 对应助动词 do。am/are 不能与 I take 构成一般疑问。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 三、Choose the best answer.（选择最恰当的答案）10% 4. I pack some _____.", "options": ["A. book", "B. my eraser", "C. pencils"]}', 'C', '【Unit 3】some 后接可数复数或不可数名词。book 是单数,my eraser 也是单数,只有 pencils 是复数,故选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单选题', 1, '{"stem": "Part 2 Reading and writing 58% | 三、Choose the best answer.（选择最恰当的答案）10% 5. —Oh, no! My eraser! —_____. Use my eraser.", "options": ["A. Good", "B. Don''t worry", "C. Thank you"]}', 'B', '【Unit 3】别人丢失物品,应先安慰 Don''t worry(别担心),再提出帮助 Use my eraser。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 1, '{"stem": "Part 2 Reading and writing 58% | 四、Look and write.（看图,将句子补充完整）18% 1. Oh, no! My _____ ![图: 一支铅笔]", "options": null}', 'pencil', '【Unit 3】图为一支铅笔(pencil)。Oh, no! My pencil!(噢不!我的铅笔!) 单数。', 'paper', '[]', '["/static/qimg/yg_yy_p014.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 1, '{"stem": "Part 2 Reading and writing 58% | 四、Look and write.（看图,将句子补充完整）18% 2. You can use my _____. [图: 一块橡皮]", "options": null}', 'eraser', '【Unit 3】图为一块橡皮(eraser)。You can use my eraser.(你可以用我的橡皮。) 单数。', 'paper', '[]', '["/static/qimg/yg_yy_p014.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 2, '{"stem": "Part 2 Reading and writing 58% | 四、Look and write.（看图,将句子补充完整）18% 3. —What do I take to school? —I pack some _____ [图: 书包], a _____ [图: 铅笔盒], and two _____ [图: 尺子].", "options": null}', 'books; pencil case; rulers', '【Unit 3】书包里装一些书,一个铅笔盒,和两把尺子。some 后接可数复数 books;a 后接单数 pencil case;two 后接复数 rulers。', 'paper', '[]', '["/static/qimg/yg_yy_p014.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空题', 1, '{"stem": "Part 2 Reading and writing 58% | 四、Look and write.（看图,将句子补充完整）18% 4. I pack my _____. [图: 一个双肩书包]", "options": null}', 'schoolbag', '【Unit 3】图为深色双肩书包(schoolbag)。I pack my schoolbag.(我装好我的书包。) 单数。', 'paper', '[]', '["/static/qimg/yg_yy_p014.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '匹配题', 1, '{"stem": "Part 2 Reading and writing 58% | 五、Read and match.（问答句配对）10% 1. Use my eraser.", "options": ["A. I take my pencil case.", "B. Goodbye.", "C. I''m fine. Thank you.", "D. Thank you.", "E. Don''t worry. Use my pencil."]}', 'D', '【Unit 3】Use my eraser.(用我的橡皮。) 别人主动提供帮助,应感谢 Thank you(谢谢你)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '匹配题', 1, '{"stem": "Part 2 Reading and writing 58% | 五、Read and match.（问答句配对）10% 2. What do I take to school?", "options": ["A. I take my pencil case.", "B. Goodbye.", "C. I''m fine. Thank you.", "D. Thank you.", "E. Don''t worry. Use my pencil."]}', 'A', '【Unit 3】What do I take to school?(我要带什么去学校?) 回应回答带什么 → I take my pencil case(我带我的铅笔盒)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '匹配题', 1, '{"stem": "Part 2 Reading and writing 58% | 五、Read and match.（问答句配对）10% 3. Oh, no! My pencil!", "options": ["A. I take my pencil case.", "B. Goodbye.", "C. I''m fine. Thank you.", "D. Thank you.", "E. Don''t worry. Use my pencil."]}', 'E', '【Unit 3】Oh, no! My pencil!(噢不!我的铅笔!) 别人主动提供帮助 → Don''t worry. Use my pencil.(别担心,用我的铅笔。)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '匹配题', 1, '{"stem": "Part 2 Reading and writing 58% | 五、Read and match.（问答句配对）10% 4. Goodbye.", "options": ["A. I take my pencil case.", "B. Goodbye.", "C. I''m fine. Thank you.", "D. Thank you.", "E. Don''t worry. Use my pencil."]}', 'B', '【Unit 3】Goodbye.(再见。) 告别回应 Goodbye(再见)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '匹配题', 1, '{"stem": "Part 2 Reading and writing 58% | 五、Read and match.（问答句配对）10% 5. How are you?", "options": ["A. I take my pencil case.", "B. Goodbye.", "C. I''m fine. Thank you.", "D. Thank you.", "E. Don''t worry. Use my pencil."]}', 'C', '【Unit 3】How are you?(你好吗?) 回应 → I''m fine. Thank you.(我很好,谢谢。)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 一、Listen and choose.（听录音,选出与你听到的内容相符的图片）10% 1. 听一听,选一选。", "options": ["A. [图: 一支铅笔]", "B. [图: 一把椅子]"]}', 'B', '【Unit 4】【听力题需音频确认】图 A 为铅笔(pencil),图 B 为椅子(chair)。chair 为本课核心词,故选 B。', 'paper', '[]', '["/static/qimg/yg_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 一、Listen and choose.（听录音,选出与你听到的内容相符的图片）10% 2. 听一听,选一选。", "options": ["A. [图: 一扇门]", "B. [图: 一块黑板]"]}', 'B', '【Unit 4】【听力题需音频确认】图 A 为门(door),图 B 为黑板(blackboard)。blackboard 为本课核心词,故选 B。', 'paper', '[]', '["/static/qimg/yg_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 一、Listen and choose.（听录音,选出与你听到的内容相符的图片）10% 3. 听一听,选一选。", "options": ["A. [图: 一把椅子]", "B. [图: 一张桌子]"]}', 'A', '【Unit 4】【听力题需音频确认】图 A 为椅子(chair),图 B 为桌子(desk)。chair 为本课核心词,故选 A。', 'paper', '[]', '["/static/qimg/yg_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 一、Listen and choose.（听录音,选出与你听到的内容相符的图片）10% 4. 听一听,选一选。", "options": ["A. [图: 一把尺子]", "B. [图: 一扇门]"]}', 'B', '【Unit 4】【听力题需音频确认】图 A 为尺子(ruler),图 B 为门(door)。door 为本课核心词,故选 B。', 'paper', '[]', '["/static/qimg/yg_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 一、Listen and choose.（听录音,选出与你听到的内容相符的图片）10% 5. 听一听,选一选。", "options": ["A. [图: 一扇门]", "B. [图: 一摞书]"]}', 'A', '【Unit 4】【听力题需音频确认】图 A 为门(door),图 B 为一摞书(books)。door 为本课核心词,故选 A。', 'paper', '[]', '["/static/qimg/yg_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 二、Listen and choose.（听录音,选出你听到的内容）10% 1. 听一听,选一选。", "options": ["A. Who''s on duty?", "B. Who''s on duty today?"]}', 'B', '【Unit 4】【听力题需音频确认】A 是 Who''s on duty?(谁值日?);B 是 Who''s on duty today?(今天谁值日?)。本课核心句型含 today,故选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 二、Listen and choose.（听录音,选出你听到的内容）10% 2. 听一听,选一选。", "options": ["A. Let me clean the floor.", "B. Let me clean the door."]}', 'A', '【Unit 4】【听力题需音频确认】A 是 Let me clean the floor.(让我擦地板。);B 是 Let me clean the door.(让我擦门。)。floor 为本课核心词,故选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 二、Listen and choose.（听录音,选出你听到的内容）10% 3. 听一听,选一选。", "options": ["A. Clean the desk.", "B. Clean your desk."]}', 'B', '【Unit 4】【听力题需音频确认】A 是 Clean the desk.(擦桌子——祈使句);B 是 Clean your desk.(擦你的桌子)。your 为关键词,故选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 二、Listen and choose.（听录音,选出你听到的内容）10% 4. 听一听,选一选。", "options": ["A. Let me help you.", "B. I can help you."]}', 'A', '【Unit 4】【听力题需音频确认】A 是 Let me help you.(让我帮助你。);B 是 I can help you.(我能帮助你。)。Let me 为本课重点句型,故选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 二、Listen and choose.（听录音,选出你听到的内容）10% 5. 听一听,选一选。", "options": ["A. Clean my classroom.", "B. Clean our classroom."]}', 'B', '【Unit 4】【听力题需音频确认】A 是 Clean my classroom.(打扫我的教室);B 是 Clean our classroom.(打扫我们的教室)。our classroom 为本课核心句型,故选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 三、Listen and number.（听录音,用数字给下列图片排序）16% 1. 听一听,给下列图片按听到的顺序编号。", "options": ["[图1: 一扇门]", "[图2: 一张桌子]", "[图3: 一把椅子]", "[图4: 一块黑板]"]}', '【图示排序需音频确认】', '【Unit 4】【听力题需音频确认】图依次为门(door)、桌子(desk)、椅子(chair)、黑板(blackboard)。具体排序需听音频确认,本题答案为排序数字,非单选。', 'paper', '[]', '["/static/qimg/yg_yy_p016.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 三、Listen and number.（听录音,用数字给下列句子排序）16% 2. 听一听,给下列句子按听到的顺序编号。", "options": ["Put the books back.", "Clean my desk.", "Let me clean the floor.", "Let me help you."]}', '【句子排序需音频确认】', '【Unit 4】【听力题需音频确认】4 句均为本课核心句型,具体排序需听音频确认,本题答案为排序数字,非单选。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Unit 4 单元测试卷 Part 1 Listening 44% | 四、Listen and match.（听录音,将人名和相应的物品连线）8% 1. 听一听,连一连。", "options": ["1. [图: 椅子]", "A. [图: Jim 男孩]", "B. [图: Lucy 女孩(双辫)]", "C. [图: Tom 男孩]", "D. [图: Amy 女孩]"]}', '【人名配对需音频确认】', '【Unit 4】【听力题需音频确认】将 1 号图(椅子)与下方人名 A-D 中正确者连线,具体匹配需听音频确认。', 'paper', '[]', '["/static/qimg/yg_yy_p016.jpg"]', 0);
