INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 一、Look and circle.（看图,圈出正确单词）16% 1. 字母矩阵圈词。【图: 门】", "options": ["m o d o o r q m p d o r o m r"]}', 'door', '【Unit 4】图为门(door)。在字母矩阵 m o d o o r q m p d o r o m r 中可圈出 d-o-o-r(位置 2-6)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
