INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 一、Look and circle.（看图,圈出正确单词）16% 3. 字母矩阵圈词。【图: 桌子】", "options": ["d e s p d k p q d e s k l p s"]}', 'desk', '【Unit 4】图为桌子(desk)。在字母矩阵 d e s p d k p q d e s k l p s 中可圈出 d-e-s-k(位置 9-12)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 二、Look and tick.（看图,在符合图意的内容前打√）8% 1. 【图: 女孩弯腰擦地】", "options": ["( ) Let me clean the floor.", "( ) Let me clean the door."]}', 'A', '【Unit 4】图为一女孩弯腰用抹布擦地,故选 A. Let me clean the floor.(让我擦地板。)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 二、Look and tick.（看图,在符合图意的内容前打√）8% 2. 【图: 男孩在桌旁擦桌子】", "options": ["( ) Clean the chair.", "( ) Clean the desk."]}', 'B', '【Unit 4】图为一男孩站在桌子旁擦桌子,故选 B. Clean the desk.(擦桌子。)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 二、Look and tick.（看图,在符合图意的内容前打√）8% 3. 【图: 男孩站在黑板前擦黑板】", "options": ["( ) Let me clean the blackboard.", "( ) Let me clean the door."]}', 'A', '【Unit 4】图为一男孩站在黑板前擦黑板,故选 A. Let me clean the blackboard.(让我擦黑板。)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 二、Look and tick.（看图,在符合图意的内容前打√）8% 4. 【图: 女孩抱着一摞书】", "options": ["( ) Let me put the chairs back.", "( ) Let me put the books back."]}', 'B', '【Unit 4】图为一女孩抱着一摞书,故选 B. Let me put the books back.(让我把书放回原处。)。', 'paper', '[]', '["/static/qimg/yg_yy_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 三、Read and choose.（选出不同类的一项）6% 1. 选出不同类的单词。", "options": ["A. chair", "B. desk", "C. classroom"]}', 'C', '【Unit 4】chair(椅子)和 desk(桌子)都是具体家具物品;classroom(教室)是场所/地点,故选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 三、Read and choose.（选出不同类的一项）6% 2. 选出不同类的单词。", "options": ["A. let", "B. fine", "C. help"]}', 'B', '【Unit 4】let(让,实义动词)和 help(帮助,实义动词)都是动词;fine(好的,形容词)词性不同,故选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 三、Read and choose.（选出不同类的一项）6% 3. 选出不同类的单词。", "options": ["A. who", "B. how", "C. do"]}', 'C', '【Unit 4】who(谁)和 how(如何)都是特殊疑问词;do(做,实义动词)词性不同,故选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 四、Read and choose.（情景选择）15% 1. 当老师想知道今天谁值日时,会问:", "options": ["A. Who are you?", "B. Who''s on duty today?"]}', 'B', '【Unit 4】询问今天谁值日,选 B. Who''s on duty today?(今天谁值日?)。Who are you?(你是谁?)答非所问。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 四、Read and choose.（情景选择）15% 2. 看到同学拿着很多书,你上前帮忙,可以说:", "options": ["A. Let me help you.", "B. Goodbye!"]}', 'A', '【Unit 4】主动帮忙时用 Let me help you.(让我帮你。),故选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 四、Read and choose.（情景选择）15% 3. 家里在大扫除,你来扫地,和妈妈说:", "options": ["A. Let me clean the floor.", "B. Let me clean the classroom."]}', 'A', '【Unit 4】场景是"家里",应是 clean the floor(擦地板),classroom(教室)不符合家庭场景,故选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 四、Read and choose.（情景选择）15% 4. 妈妈让你清理你的书桌,她说:", "options": ["A. Clean my desk.", "B. Clean your desk."]}', 'B', '【Unit 4】妈妈对孩子说"清理你的书桌",用 your(你的),故选 B. Clean your desk.。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 四、Read and choose.（情景选择）15% 5. 当别人给予你帮助时,你应该说:", "options": ["A. Don''t worry.", "B. Thank you."]}', 'B', '【Unit 4】接受帮助应表示感谢,选 B. Thank you.(谢谢。)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 短文: This is my 1. c_____. You can see a 2. d_____, a 3. b_____, some 4. d_____ and some chairs. A 5. b_____ is cleaning the blackboard. A boy is reading a 6. b_____. You can see a pencil case on the 7. d_____. [图: 教室场景,女孩擦黑板,男孩读书,有门/桌椅/铅笔盒] 1. c_____ 句首填空。", "options": ["classroom", "computer", "card"]}', 'classroom', '【Unit 4】句首"This is my c_____"指代图中的地点(教室),首字母 c,填 classroom。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 2. You can see a d_____. [图: 门] 句首填空。", "options": ["door", "desk", "drawer"]}', 'door', '【Unit 4】图中可见门(door),首字母 d,填 door。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 3. a b_____. [图: 黑板] 句首填空。", "options": ["blackboard", "book", "bag"]}', 'blackboard', '【Unit 4】图中可见黑板(blackboard),首字母 b,填 blackboard。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 4. some d_____ and some chairs. [图: 桌子,复数] 句首填空。", "options": ["desks", "doors", "drawers"]}', 'desks', '【Unit 4】some 后接复数,图中有桌子,首字母 d,填 desks。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 2, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 5. A b_____ is cleaning the blackboard. [图: 女孩擦黑板] 句首填空。", "options": ["boy", "girl", "baby"]}', 'girl', '【Unit 4】根据图意(女孩擦黑板),填 girl;但空格在 A b_____ 后,后文又写"A boy is reading a 6. b_____",前空不可再用 boy,故可能卷面是 girl。【图示存疑:卷面 A b_____ 与下方 A boy 重复,推测为 girl】', 'paper', '["存疑"]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 6. A boy is reading a b_____. [图: 男孩读书] 句首填空。", "options": ["book", "bag", "board"]}', 'book', '【Unit 4】read a book(读书)是固定搭配,首字母 b,填 book。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写题', 1, '{"stem": "Unit 4 单元测试卷 Part 2 Reading and writing 56% | 五、Look and write.（看图并结合首字母将短文补充完整）21% 7. on the d_____. [图: 铅笔盒在桌上] 句首填空。", "options": ["desk", "door", "drawer"]}', 'desk', '【Unit 4】铅笔盒在桌子上,首字母 d,填 desk。', 'paper', '[]', '["/static/qimg/yg_yy_p018.jpg"]', 0);
