INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 二、Listen and choose.（听录音,选择正确的图片完成句子。）10% 1. Can you see an _____? [图: 一只大眼睛]", "options": ["A. eye(单数,符合 an)", "B. ear(单数,符合 an)"]}', 'A', '【听力题需音频确认】【Unit 5】图意是一只大眼睛(eye),an 后接元音开头的单数名词,eye 以元音开头,选 A。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p019.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 二、Listen and choose.（听录音,选择正确的图片完成句子。）10% 2. Draw a big _____.", "options": ["A. 嘴(mouth)图", "B. 鼻子(nose)图"]}', 'B', '【听力题需音频确认】【Unit 5】Draw a big nose/ear 句型,根据图片含"big 鼻子"提示选 B(鼻子 nose)。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p020.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 二、Listen and choose.（听录音,选择正确的图片完成句子。）10% 3. Look, a big _____.", "options": ["A. 鼻子(nose)图", "B. 耳朵(ear)图"]}', 'A', '【听力题需音频确认】【Unit 5】图意是一只大鼻子 nose,Look, a big nose 句型,选 A(鼻子)。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p020.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 二、Listen and choose.（听录音,选择正确的图片完成句子。）10% 4. Draw a red _____.", "options": ["A. 嘴(mouth)图", "B. 鼻子(nose)图"]}', 'A', '【听力题需音频确认】【Unit 5】图意是一张大嘴(mouth)且为红色,Draw a red mouth 句型,选 A(嘴)。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p020.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 二、Listen and choose.（听录音,选择正确的图片完成句子。）10% 5. Aha, two big _____.", "options": ["A. 双眼(eyes)图", "B. 双耳(ears)图"]}', 'B', '【听力题需音频确认】【Unit 5】图意是两只大耳朵(ears),two big ears 复数形式,选 B(双耳)。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p020.jpg"]', 0);
