INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 2, '{"stem": "Unit 5 单元测试卷 Part 1 Listening 35% | 三、Listen and number.（听录音,用数字给下列句子排序。）15% 5. ( ) Aha, a funny face!", "options": null}', '待回填', '【听力题需音频确认】【Unit 5】画脸步骤题结尾,Aha, a funny face! 通常是最后一步,建议以教材原题为准。', 'paper', '["听力"]', '["/static/qimg/yg_yy_p020.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图打勾', 1, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 一、Look and tick.（看图,在符合图意的内容前打「✓」。）6% 1. 鼻子图 ( ) I draw a nose. ( ) I draw a mouth.", "options": null}', 'I draw a nose.', '【Unit 5】图为鼻子(nose),句子 I draw a nose. (我画了一个鼻子) 符合图意,打勾。', 'paper', '[]', '["/static/qimg/yg_yy_p021.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图打勾', 1, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 一、Look and tick.（看图,在符合图意的内容前打「✓」。）6% 2. 两只耳朵图 ( ) Two big eyes. ( ) Two big ears.", "options": null}', 'Two big ears.', '【Unit 5】图为两只大耳朵(ears),Two big ears. (两只大耳朵) 符合图意,打勾。', 'paper', '[]', '["/static/qimg/yg_yy_p021.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图打勾', 1, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 一、Look and tick.（看图,在符合图意的内容前打「✓」。）6% 3. 嘴巴图 ( ) Oh, a mouth. ( ) Oh, a mouse.", "options": null}', 'Oh, a mouth.', '【Unit 5】图为嘴巴(mouth)非老鼠(mouse),发音相同易混淆,Oh, a mouth. 符合图意,打勾。', 'paper', '[]', '["/static/qimg/yg_yy_p021.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 二、Read and choose.（选出不同类的一项。）10% ( ) 1. A. lovely  B. funny  C. face", "options": ["A. lovely", "B. funny", "C. face"]}', 'C', '【Unit 5】lovely 和 funny 是形容词,face 是名词,选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 二、Read and choose.（选出不同类的一项。）10% ( ) 2. A. draw  B. sea  C. see", "options": ["A. draw", "B. sea", "C. see"]}', 'A', '【Unit 5】sea 和 see 是同音异义词(名词/动词),draw 是动词词义不同,选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 二、Read and choose.（选出不同类的一项。）10% ( ) 3. A. red  B. big  C. a", "options": ["A. red", "B. big", "C. a"]}', 'C', '【Unit 5】red 和 big 是形容词,a 是冠词,选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 二、Read and choose.（选出不同类的一项。）10% ( ) 4. A. can  B. what  C. how", "options": ["A. can", "B. what", "C. how"]}', 'A', '【Unit 5】what 和 how 是疑问词,can 是情态动词,选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 二、Read and choose.（选出不同类的一项。）10% ( ) 5. A. find  B. make  C. small", "options": ["A. find", "B. make", "C. small"]}', 'C', '【Unit 5】find 和 make 是动词,small 是形容词,选 C。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '写单词', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 三、Read and write.（按要求写单词。）8% 1. nose(复数) _______", "options": null}', 'noses', '【Unit 5】nose(鼻子)复数加 s,noses。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '写单词', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 三、Read and write.（按要求写单词。）8% 2. big(反义词) _______", "options": null}', 'small', '【Unit 5】big(大)反义词是 small(小)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '写单词', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 三、Read and write.（按要求写单词。）8% 3. ear(复数) _______", "options": null}', 'ears', '【Unit 5】ear(耳朵)复数加 s,ears。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '写单词', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 三、Read and write.（按要求写单词。）8% 4. eye(复数) _______", "options": null}', 'eyes', '【Unit 5】eye(眼睛)复数加 s,eyes。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 Reading and writing 65% | 四、Choose the best answer.（选择最恰当的答案。）10% ( ) 1. I see a red _____. A. mouths  B. nose  C. ears", "options": ["A. mouths", "B. nose", "C. ears"]}', 'B', '【Unit 5】a red 后接单数名词,mouths 是复数排除,常见搭配 a red nose (一只红鼻子),选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 四、Choose the best answer.（选择最恰当的答案。）10% ( ) 2. _____ a face. A. Let  B. Can  C. Draw", "options": ["A. Let", "B. Can", "C. Draw"]}', 'B', '【Unit 5】情态动词 Can 引导省略主语的句子,Can... a face? 合语法;Let 后需接代词;Draw 后需接宾语,选 B。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 四、Choose the best answer.（选择最恰当的答案。）10% ( ) 3. I see _____ eye. A. a  B. an  C. /", "options": ["A. a", "B. an", "C. /"]}', 'A', '【Unit 5】eye 发音以元音字母 e 开头,但读音为 /ɪ/ 辅音音素开头,用 a(eye 是辅音音素开头的特殊词),选 A。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 四、Choose the best answer.（选择最恰当的答案。）10% ( ) 4. Look, _____. A. two big eyes  B. two big nose  C. a red noses", "options": ["A. two big eyes", "B. two big nose", "C. a red noses"]}', 'A', '【Unit 5】B 缺少复数 s 排除,C noses 复数与 a 单数矛盾,选 A(two 修饰复数 eyes)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 四、Choose the best answer.（选择最恰当的答案。）10% ( ) 5. Can you find _____? A. a faces  B. the a face  C. the faces", "options": ["A. a faces", "B. the a face", "C. the faces"]}', 'C', '【Unit 5】A 冠词与复数矛盾(the/a 不能修饰 faces 复数时 a 错),B 同时用 the 和 a 矛盾,选 C(特指的复数脸)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 五、Read and fill in the blanks.（用所给词的适当形式填空。）10% 1. I see a _____(love) face.", "options": null}', 'lovely', '【Unit 5】动词 love 修饰名词 face 需用形容词,lovely(可爱的)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 五、Read and fill in the blanks.（用所给词的适当形式填空。）10% 2. Draw _____(a) eye, _____(a) big eye.", "options": null}', 'an,a', '【Unit 5】eye 发音为 /ɪ/ 辅音音素开头,两空都用 a;第一个强调单个,第二个是 a big eye 的固定搭配。实际填写: a, a(两空都是 a,因 eye 是辅音音素开头)。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 五、Read and fill in the blanks.（用所给词的适当形式填空。）10% 3. Can you _____(see) the _____(nose)? One is big and one is small.", "options": null}', 'see,noses', '【Unit 5】情态动词 Can 后接动词原形 see;后文 One...one is... 暗示两只鼻子,用复数 noses。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '补全短文', 2, '{"stem": "Unit 5 单元测试卷 Part 2 | 六、Look and write.（看图并结合首字母将短文补充完整。）21% 1. I see a f___. (脸)", "options": null}', 'face', '【Unit 5】首字母 f,脸部 face。', 'paper', '[]', NULL, 0);
