INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 1, '{"stem": "Unit 8 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的内容前打「√」。) 6% 2. [图:两只黑鸟并排站枝头] ( ) I see two bees.  ( ) I see two birds.", "options": ["I see two bees.", "I see two birds."]}', 'I see two birds.', '图是两只鸟(birds),不是蜜蜂(bees),选 I see two birds.', 'paper', '[]', '["/static/qimg/yg_yy_p032.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 1, '{"stem": "Unit 8 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的内容前打「√」。) 6% 3. [图:飞鸟] ( ) The bird comes back.  ( ) The bird flies away.", "options": ["The bird comes back.", "The bird flies away."]}', 'The bird flies away.', '图中是飞起来的鸟,The bird flies away(鸟飞走了)更符合图意【图示估读存疑】', 'paper', '[]', '["/static/qimg/yg_yy_p033.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 8 单元测试卷 Part 2 | 二、Read and choose.(选出不同类的一项。) 10% ( ) 1. A. fly    B. come    C. high", "options": ["A", "B", "C"]}', 'C', 'A. fly(飞)和 B. come(来)是动词,C. high(高的)是形容词,选 C high 不同类', 'paper', '[]', NULL, 0);
