INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力', 3, '{"stem": "Unit 9 单元测试卷 Part 1 | 四、Listen and tick.(听录音,在表格相应的地方打「√」。) 14% [矩阵:表头为 clean the desk / pack the schoolbag / wash the lunch box / take a photo / tie shoelaces 五列;行: Helen / Danny / Linda 三人。需根据听力勾选每个人能做的事。]", "options": null}', '【听力题需音频确认】', '听力勾选矩阵题,3人×5事=15个勾选空格,全部需音频确认', 'paper', '["听力题"]', '["/static/qimg/yg_yy_p036.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的句子前打「√」。) 10% ( ) 1. [图:鞋带] ( ) Can you tie my shoelaces?  ( ) Can you wash your shoes?", "options": null}', 'Can you tie my shoelaces.', '图示为鞋带,正确表述为"你能帮我系鞋带吗?"(tie 系鞋带;wash 洗)', 'paper', '[]', '["/static/qimg/yg_yy_p036.jpg"]', 0);
