INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的句子前打「√」。) 10% ( ) 3. [图:老人拍照] ( ) My grandma can take a photo.  ( ) My grandpa can take a photo.", "options": null}', 'My grandpa can take a photo.', '图示为老爷爷(grandpa),应选"我的爷爷会拍照";奶奶应为 grandma', 'paper', '[]', '["/static/qimg/yg_yy_p036.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的句子前打「√」。) 10% ( ) 4. [图:男孩系鞋带] ( ) My brother can tie his shoelaces.  ( ) My sister can tie her shoelaces.", "options": null}', 'My brother can tie his shoelaces.', '图示为男孩(brother 兄弟),对应 his(他的);sister 姐妹对应 her(她的)', 'paper', '[]', '["/static/qimg/yg_yy_p036.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 一、Look and tick.(看图,在符合图意的句子前打「√」。) 10% ( ) 5. [图:书包] ( ) I can pack my schoolbag.  ( ) I can pack my pencil case.", "options": null}', 'I can pack my schoolbag.', '图示为书包 schoolbag,正确表述为"我能收拾我的书包"而非铅笔盒 pencil case', 'paper', '[]', '["/static/qimg/yg_yy_p037.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 二、Read and choose.(选出不同类的一项。) 8% ( ) 1.  A. can  B. tie  C. wash", "options": ["A", "B", "C"]}', 'A', 'can 是情态动词;tie 系、wash 洗是实义动词;选不同类的情态动词 A', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 二、Read and choose.(选出不同类的一项。) 8% ( ) 2.  A. your  B. my  C. yourself", "options": ["A", "B", "C"]}', 'C', 'your 你的、my 我的是物主代词;yourself 你自己是反身代词;选不同类的反身代词 C', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 二、Read and choose.(选出不同类的一项。) 8% ( ) 3.  A. high  B. hello  C. good", "options": ["A", "B", "C"]}', 'A', 'high 高的(high 的字母 i 与 hi 同音,易混)是形容词;hello 你好、good 好的是问候/问候应答语;选不同类的形容词 A', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 二、Read and choose.(选出不同类的一项。) 8% ( ) 4.  A. bag  B. photo  C. find", "options": ["A", "B", "C"]}', 'C', 'bag 书包、photo 照片是名词;find 找是动词;选不同类的动词 C', 'paper', '[]', NULL, 0);
