INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 三、Read and write.(按要求写单词。) 8%  3. shoelace(复数) ____________", "options": null}', 'shoelaces', 'shoelace 鞋带的复数形式为 shoelaces(以 ce 结尾的单词变复数加 s)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 三、Read and write.(按要求写单词。) 8%  4. yes(反义词) ____________", "options": null}', 'no', 'yes 是的反义词为 no(是→否)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷 Part 2 | 四、Choose the best answer.(选择最恰当的答案。) 10% ( ) 1. My mum can ______ the plates.  A. wash  B. washes  C. washing", "options": ["A", "B", "C"]}', 'A', '情态动词 can 后接动词原形 wash(洗);washes 是第三人称单数,washing 是现在分词', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷 Part 2 | 四、Choose the best answer.(选择最恰当的答案。) 10% ( ) 2. I can tie ______ shoelaces by ______.  A. me; my  B. my; myself  C. me; myself", "options": ["A", "B", "C"]}', 'C', 'tie my/... shoelaces 系我的鞋带(by + 反身代词,by myself 靠我自己);my 形容词性物主代词修饰 shoelaces;myself 反身代词作 by 的宾语', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷 Part 2 | 四、Choose the best answer.(选择最恰当的答案。) 10% ( ) 3. Cindy can take ______.  A. a photos  B. photoes  C. a photo", "options": ["A", "B", "C"]}', 'C', 'take a photo 拍一张照片(单数);photo 的复数为 photos 不是 photoes;a 不能修饰复数', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷 Part 2 | 四、Choose the best answer.(选择最恰当的答案。) 10% ( ) 4. —Can you find my bag? —Yes, ______.  A. I can''t  B. I can  C. you can", "options": ["A", "B", "C"]}', 'B', '一般疑问句 Can you...? 肯定回答 Yes, I can.;you can 与问句主语重复', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷 Part 2 | 四、Choose the best answer.(选择最恰当的答案。) 10% ( ) 5. —Can ______ wash ______ lunch box? —Yes, he can.  A. him; his  B. she; her  C. he; his", "options": ["A", "B", "C"]}', 'C', '答句主语为 he(他),问句主语也用 he;his lunch box 他的饭盒(形容词性物主代词);him 是宾格,she 是女性主语', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷末页 | 五、Read and fill in the blanks.(用所给词的适当形式填空。)14% 1. My dad can ______ (clean) the house, but he ______ (can) take ______ (photo).", "options": null}', 'cleans; can''t; photos', 'My dad can clean the house(情态动词后用原形 clean), but he can''t take photos.(but 表转折,否定 can;take photos 拍照片用复数)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷末页 | 五、Read and fill in the blanks.(用所给词的适当形式填空。)14% 2. Look, I can tie ______ (shoelace) by ______ (me).", "options": null}', 'my shoelaces; myself', 'tie my shoelaces 系我的鞋带(形容词性物主代词 my + 复数 shoelaces);by myself 靠我自己(by + 反身代词)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 3, '{"stem": "Unit 9 单元测试卷末页 | 五、Read and fill in the blanks.(用所给词的适当形式填空。)14% 3. —Can you wash ______ (you) lunch box?  —Yes, ______ (me) can.", "options": null}', 'your; I', 'Can you wash your lunch box?(形容词性物主代词 your 修饰 lunch box);Yes, I can.(主格 I 作主语,首字母大写)', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷末页 | 六、Read and choose.(情景选择。)10% ( ) 1. 你和对方说你妹妹会绑鞋带,可以说:  A. My brother can tie shoelaces.  B. My sister can tie shoelaces.", "options": ["A", "B"]}', 'B', '妹妹是 sister(不是 brother);My sister can tie shoelaces. 我妹妹会绑鞋带', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷末页 | 六、Read and choose.(情景选择。)10% ( ) 2. 当询问对方是否会洗午餐盒时,可以问:  A. What can you do?  B. Can you wash your lunch box?", "options": ["A", "B"]}', 'B', '询问对方是否做某事用一般疑问句 Can you...;What can you do? 询问能力范围', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 1, '{"stem": "Unit 9 单元测试卷末页 | 六、Read and choose.(情景选择。)10% ( ) 3. 当你不小心撞到对方时,应该说:  A. I''m sorry.  B. Don''t worry.", "options": ["A", "B"]}', 'A', '撞到对方应道歉 I''m sorry.(对不起);Don''t worry 别担心是安慰对方', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷末页 | 六、Read and choose.(情景选择。)10% ( ) 4. 你让妈妈帮你绑鞋带,可以说:  A. Can you tie my shoelaces, please?  B. Can you find my bag, please?", "options": ["A", "B"]}', 'A', '让对方帮忙绑鞋带 Can you tie my shoelaces, please?(你能帮我绑鞋带吗?);find my bag 找我的书包 不符语境', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '读写', 2, '{"stem": "Unit 9 单元测试卷末页 | 六、Read and choose.(情景选择。)10% ( ) 5. 当表示你可以自己做时,可以说:  A. I can do it by myself.  B. I can do it by yourself.", "options": ["A", "B"]}', 'A', 'by myself 靠我自己(主语 I 对应反身代词 myself);yourself 是"你自己",主语应是 you', 'paper', '[]', NULL, 0);
