INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图填空', 2, '{"stem": "期末基础测试卷 Part 2 四、Look and write (看图,将句子补充完整) 10% | 第1题: 图为一只母鸡。A ____ can give us eggs.", "options": null}', 'A Hens', '图示为母鸡,hens 母鸡能给我们鸡蛋,填 Hens 复数。', 'paper', '["看图填空"]', '["/static/qimg/yg_yy_p69.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图填空', 2, '{"stem": "期末基础测试卷 Part 2 四、Look and write (看图,将句子补充完整) 10% | 第2题: 图为一只小鸡。____ is a little ear. (注:题干末段被截断/版式不完整,建议以教材原题为准)", "options": null}', 'A Chick (存疑)', '图示为小鸡,chick 小鸡,但「is a little ear」句意不完整,题干可能印刷不全。建议以教材原题为准。', 'paper', '["看图填空","存疑"]', '["/static/qimg/yg_yy_p69.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图填空', 2, '{"stem": "期末基础测试卷 Part 2 四、Look and write (看图,将句子补充完整) 10% | 第3题: 图为一个球。I have a ____ for you.", "options": null}', 'ball', '图示为球,ball 球,填 ball。', 'paper', '["看图填空"]', '["/static/qimg/yg_yy_p70.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图填空', 2, '{"stem": "期末基础测试卷 Part 2 四、Look and write (看图,将句子补充完整) 10% | 第4题: 图为一只猫和一只狗。These ____ are my pets.", "options": null}', 'animals', '图示为一只猫和一只狗,均为动物,these 后接复数,填 animals 最准确。', 'paper', '["看图填空"]', '["/static/qimg/yg_yy_p70.jpg"]', 0);
