INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '问答配对', 1, '{"stem": "黄浦区期末卷 Part 2 四、Read and match 问答句配对 | 1. How are you?（A. Good afternoon, Miss Li. B. It''s me. C. I''m fine. Thank you. D. Yes, he can. E. Horses can give us rides.）", "options": null}', 'C. I''m fine. Thank you.', 'How are you? 是问候语，答 I''m fine. Thank you.', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '问答配对', 1, '{"stem": "黄浦区期末卷 Part 2 四、Read and match 问答句配对 | 2. Who is on duty today?（A. Good afternoon, Miss Li. B. It''s me. C. I''m fine. Thank you. D. Yes, he can. E. Horses can give us rides.）", "options": null}', 'B. It''s me.', 'Who is on duty today? 问今天谁值日，答 It''s me.（是我）', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '问答配对', 1, '{"stem": "黄浦区期末卷 Part 2 四、Read and match 问答句配对 | 3. Can Minmin wash his lunch box?（A. Good afternoon, Miss Li. B. It''s me. C. I''m fine. Thank you. D. Yes, he can. E. Horses can give us rides.）", "options": null}', 'D. Yes, he can.', 'Can Minmin...? 问 Minmin 会不会，答 Yes, he can.', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '问答配对', 1, '{"stem": "黄浦区期末卷 Part 2 四、Read and match 问答句配对 | 4. What can horses do for you?（A. Good afternoon, Miss Li. B. It''s me. C. I''m fine. Thank you. D. Yes, he can. E. Horses can give us rides.）", "options": null}', 'E. Horses can give us rides.', 'What can horses do? 问马能做什么，答 Horses can give us rides.（马能驮我们）', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '问答配对', 1, '{"stem": "黄浦区期末卷 Part 2 四、Read and match 问答句配对 | 5. Good afternoon, class.（A. Good afternoon, Miss Li. B. It''s me. C. I''m fine. Thank you. D. Yes, he can. E. Horses can give us rides.）", "options": null}', 'A. Good afternoon, Miss Li.', 'Good afternoon, class. 老师下午问候全班，答 Good afternoon, Miss Li.', 'paper', '[]', NULL, 0);
