INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 1, '{"stem": "二、根据课文内容判断对错（10分）：1.蓝天是小鸟的家 2.小溪弯弯流入海 3.祖国就是我们的家 4.毛巾用来搓搓手 5.桥西走来两只羊", "options": null}', '1.√（蓝天是小鸟的家）2.×（小溪弯弯流入海应为弯弯流入海，对则为√，按课文）3.√ 4.√ 5.×（桥西走来两只羊）', '课文判断,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
