INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图填空', 2, '{"stem": "五、看图读故事，选音节填空（6分）：mù qiáo、xué xiào、yì tiān 等", "options": null}', '【看图题·图意待你补】', '看图故事选音节,图意需人工核对', 'paper', '["看图题·图意待你补"]', '["/static/qimg/yg_yw_p030.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、根据课文内容填空（11分）：《秋天》《雪地里的小画家》《江南》《四季》", "options": null}', '《秋天》：天气凉了，树叶黄了，一片片叶子从树上落下来；《雪地里的小画家》：小鸡画竹叶，小狗画梅花，小鸭画枫叶，小马画月牙，青蛙为什么没参加？它在洞里睡着啦；《江南》：江南可采莲，莲叶何田田；《四季》：草芽尖尖，他对小鸟说“我是春天”', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写汉字', 2, '{"stem": "二、看拼音，写字词（22分）：huáng le、dà rén、yé、zǐ、yí gè、èr、sì、shí、sān yuè、dōng xī、kě shì、tiān xià、yuè ér、nán nǚ、kāi guān", "options": null}', '黄了、大人、爷、子、一个、二、四、十、三月、东西、可是、天下、月儿、男女、开关', '看拼音写汉字,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线题', 1, '{"stem": "三、连一连，读一读：小鸡/小鸭/小狗/小马 分别画什么（竹叶/梅花/枫叶/月牙）（8分）", "options": null}', '小鸡—竹叶，小狗—梅花，小鸭—枫叶，小马—月牙', '《雪地里的小画家》动物脚印连线,可推导', 'paper', '["连线题"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、照样子，填一填（8分）：例：星星像宝石。1.西瓜像___ 2.白云像___ 3.月儿像___ 4.太阳像___", "options": null}', '1.西瓜像皮球 2.白云像棉花 3.月儿像小船 4.太阳像火球', '比喻填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
