INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "六、填入合适的词（18分）：的秋天/春天/夏天/冬天/大地/青蛙；弯弯的( )/高高的( )/黄黄的( )/小小的( )/闪闪的( )/红红的( )/尖尖的( )/凉凉的( )/绿绿的( )/圆圆的( )/大大的( )/蓝蓝的( )", "options": null}', '弯弯的（月儿/小路）高高的（树/山）黄黄的（叶子/沙滩）小小的（船/虫子）闪闪的（星星）红红的（太阳/苹果）尖尖的（草芽）凉凉的（风）绿绿的（草）圆圆的（荷叶）大大的（眼睛）蓝蓝的（天）', '填合适词语,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
