INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '判断', 2, '{"stem": "六、选一选，对的打“√”（12分）：1.莲叶何田田(茂密/展开) 2.江南可采莲(莲子/莲叶) 3.草芽代表季节(春/夏/秋) 4.秋天有什么(多选：雪人/谷穗/大雁/菊花)", "options": null}', '1.莲叶何田田（茂密）2.江南可采莲（莲叶）3.草芽代表季节（春）4.秋天有（大雁/菊花/谷穗）', '课文判断,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
