INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、根据课文内容填空（22分）：《对韵歌》《日月明》《小书包》《升国旗》", "options": null}', '《对韵歌》：云对雨，雪对风，花对树，鸟对虫，山清对水秀，柳绿对桃红。《日月明》：日月明，田力男，小大尖，小土尘。《小书包》：宝贝真不少，课本作业本，铅笔转笔刀。《升国旗》：五星红旗，我们的国旗；国歌声中，徐徐升起；向着国旗，立正；望着国旗，敬礼。', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写汉字', 2, '{"stem": "二、看拼音，写词语（24分）：chóng zi、xiǎo dāo、shàng shān、bú shì、chǐ zi、shū běn、nán shēng、gōng chǎng、xīn lǐ、lì zhèng、mù tou、zhōng guó、bǐ yi bǐ", "options": null}', '虫子、小刀、上山、不是、尺子、书本、男生、工厂、心里、立正、木头、中国、比一比', '看拼音写汉字,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
