INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '拼音分类', 2, '{"stem": "二、按要求归类（写序号）（10分）：①红②本③昨④转⑤黄⑥早⑦唱⑧色⑨成⑩听 → 平舌音/翘舌音/前鼻音/后鼻音", "options": null}', '平舌音：③昨⑧色⑩听；翘舌音：①红④转⑦唱⑨成；前鼻音：①红③昨④转⑦唱⑨成；后鼻音：②本⑤黄⑥早⑧色⑩听', '拼音归类,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 1, '{"stem": "三、圈出正确的汉字，组成词语（6分）：1.可(是/足) 2.(右/在)手 3.国(其/旗) 4.(明/朋)友 5.(东/冬)天 6.写(宇/学)", "options": null}', '是、右、旗、朋、冬、字', '形近字组词,可推导', 'paper', '["选择"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "四、背一背、拼一拼、写一写（11分）：《日月明》填空 + 妈妈买的新( )和( )", "options": null}', '日月明，田力男，小大尖，小土尘，三人众，双木林，三口品，三日晶。妈妈买的新(本)和(书)。', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '部首', 2, '{"stem": "五、照样子，写出下列字的部首，并再写一个带该部首的字（12分）：国、猫、听、红、迎、作", "options": null}', '国（囗，围）猫（犭，狗）听（口，叫）红（纟，纸）迎（辶，过）作（亻，他）', '部首,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '字谜', 1, '{"stem": "六、根据意思圈字（16分）：1.一人倚树 2.乔木丛生 3.三人团结 4.色彩丰富 5.不端不正 6.田间长草 7.上小下大 8.眼睛流水", "options": null}', '休、林、众、艳、歪、苗、尖、泪', '字谜猜字,可推导', 'paper', '["字谜"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "七、读《对韵歌》回答问题（12分）：1.补充句子(云对雨/雪对风/花对树/鸟对虫) 2.图片与生字连一连 3.天对( )对风(①地②雨③人)", "options": ["①地", "②雨", "③人"]}', '3.天对(①地)，(②雨)对风【2.看图·图意待补】', '对韵歌填空与选择,3可推导', 'paper', '["看图题·图意待你补"]', '["/static/qimg/yg_yw_p045.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读', 2, '{"stem": "八、阅读《蔬菜》回答问题（13分）：1.蔬菜有的吃___有的吃___有的吃___有的吃___有的吃___ 2.吃萝卜的___黄花菜的___西红柿的___", "options": null}', '1.蔬菜有的吃（根）有的吃（茎）有的吃（叶）有的吃（花）有的吃（果实）。2.吃萝卜的（根），吃卷心菜的（叶），吃黄花菜的（花），吃西红柿的（果实）。', '阅读《蔬菜》,回填答案页', 'paper', '["阅读"]', NULL, 0);
