INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、根据课文内容填空（12分）：《影子》《小小的船》《两件宝》", "options": null}', '《影子》：影子在左，影子在右，影子常常陪着我，就像一条小黑狗。《小小的船》：弯弯的月儿小小的船，小小的船儿两头尖，我在小小的船里坐，只看见闪闪的星星蓝蓝的天。《两件宝》：人有两件宝，双手和大脑。', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写汉字', 2, '{"stem": "二、看拼音，写字词（27分）：hé、sì jiàn、zuǒ bian、yòu shǒu、yě xǔ、hòu lái、yuè er、yǒu shí、xiàn zài、wǒ de、bú huì、rén cái、bà mā、bái yún、dà shān、yòng xīn", "options": null}', '和、四件、左边、右手、也许、后来、月儿、有、有时、现在、我的、不会、人才', '看拼音写汉字,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字填空', 2, '{"stem": "三、选字填空（12分）：①… 1.一( )井，两( )小鸟 2.我( )两个好朋( ) 3.我非( )喜欢跳( )绳", "options": null}', '1.一(口)井，两(只)小鸟 2.我(有)两个好朋(友) 3.我非(常)喜欢跳(绳)绳', '选字填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
