INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '发现规律', 2, '{"stem": "五、比一比两组词语，你发现了什么（6分）：明晚昨春 / 妈奶姐妹", "options": null}', '“明晚昨春”都带日字旁，意思和时间有关；“妈奶姐妹”都带女字旁，意思和女性有关。', '偏旁规律,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
