INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '标点', 2, '{"stem": "七、在方框里填上合适的标点（6分）：1.种瓜得瓜［种豆得豆 2.影子在前［影子在后［影子常常跟着我［就像一条小黑狗［", "options": null}', '1.种瓜得瓜，种豆得豆。2.影子在前，影子在后，影子常常跟着我，就像一条小黑狗。', '填标点,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读', 2, '{"stem": "八、阅读《两件宝》回答问题（13分）：1.共几句话 2.填空(两件宝/做工靠/思考靠/用…又用…才有) 3.认真地( ) 辛勤地( ) 聪明的( ) 勤劳的( )", "options": null}', '1.共 2 句话。2.两件宝指双手和大脑；做工靠手，思考靠脑；做事用手又用脑，才能有创造。3.认真地(学) 辛勤地(劳动) 聪明的(脑子) 勤劳的(双手)。', '阅读《两件宝》,回填答案页', 'paper', '["阅读"]', NULL, 0);
