INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "五、根据所学内容填空（16分）：1.种瓜得( ) 2.( )栽树，后人乘凉 3.千里之行，( ) 4.百尺竿头，( )", "options": null}', '1.种瓜得瓜 2.前人栽树 3.始于足下 4.更进一步', '谚语填空,可推导', 'paper', '["填空"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线题', 2, '{"stem": "六、什么时候要大声说话？什么时候要小声说话？想一想，连一连（16分）：大声说话/小声说话 + 图书馆/上课/饭店/给大家/读书/发言/吃饭/讲故事", "options": null}', '大声说话：发言、给大家讲故事、上课回答；小声说话：图书馆、读书、吃饭、饭店交谈。', '情境连线,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读', 2, '{"stem": "七、阅读《鸭子捉鱼》回答问题（9分）：1.短文有几个自然段 2.小鸭子以为月牙的( )是一条( ) 3.照样子写句子", "options": null}', '1.短文有 2 个自然段。2.小鸭子以为月牙的(影子)是一条(小鱼)。3.（照样子写句子，如“小猫在墙角捉老鼠”。）', '阅读《鸭子捉鱼》,回填答案页', 'paper', '["阅读"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "八、填空，画一画（12分）：有( )座漂亮的房( )，前面嫩嫩的( )苗，后面青青的高( )，左边( )红的小花，右边绿绿的树( )，还飘着朵朵( )云", "options": null}', '有(一)座漂亮的房(子)，前面嫩嫩的(草)苗，后面青青的高(山)，左边(开)红的小花，右边绿绿的树(林)，还飘着(白云)。', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "一、根据课文内容填空（8分）：《比尾巴》《乌鸦喝水》《雨点儿》", "options": null}', '《比尾巴》：谁的尾巴长？谁的尾巴短？猴子的尾巴长，兔子的尾巴短。《乌鸦喝水》：乌鸦把小石子一颗一颗放进瓶子里，瓶子里的水升高，乌鸦就喝着水了。《雨点儿》：大雨点儿去没有花没有草的地方，小雨点儿去有花有草的地方。', '课文填空,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写汉字', 2, '{"stem": "二、看拼音，写字词（25分）：yì bǎ、bǐ jiào、cháng duǎn、xià yǔ、nǐ men、gōng jī、yì bān、wěi ba、shí zi、lái qù、gè tóu、niú yáng、duō shǎo、shuǐ guǒ", "options": null}', '一把、比较、长短、下雨、你们、公鸡、一般、问好、我们、半天、从不、自己', '看拼音写汉字,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
