INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "五、根据课文内容排序（8分）：雨点儿（ ）半空中大雨点儿问小雨点儿（ ）数不清的雨点儿（ ）小雨点儿回答（ ）从云彩里飘落下来", "options": null}', '2、4、1、3（数不清的雨点儿→飘落→大雨点儿问→小雨点儿回答）', '课文排序,可推导', 'paper', '["排序"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '标点', 2, '{"stem": "六、在方框里填上合适的标点（7分）：1.下雨了、雨点儿淅沥沥、沙啦啦 2.小猴子叫起来 糟啦糟啦_月亮掉在井里啦", "options": null}', '1.下雨了，雨点儿淅沥沥，沙啦啦。2.小猴子叫起来：“糟啦糟啦，月亮掉在井里啦！”', '填标点,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读', 2, '{"stem": "七、阅读《雨点儿》节选回答问题（9分）：1.选文有几个自然段 2.小雨点儿/大雨点儿分别去哪儿 3.你喜欢吗为什么", "options": null}', '1.选文有 2 个自然段。2.小雨点儿去有花有草的地方，大雨点儿去没有花没有草的地方。3.（开放题，喜欢哪样都可，说明理由）', '阅读《雨点儿》,回填答案页', 'paper', '["阅读"]', NULL, 0);
