INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连词成句', 2, '{"stem": "一、将下列拼音连成一句话，并写下来（12分）：1.xiǎo wá shēng shì mén lā xué 2.qǐ bái tù huí láng bù néng dǎ suì kāi mén 3.dào huáng le qiū tiān le shì yè", "options": null}', '1. xiǎo wá shì mén xué shēng lā（小朋友是门学生啦）→ 应为：wǒ shì xiǎo xué shēng（我是小学生）2.（按拼音连词成句）', '连词成句,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
