INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线题', 1, '{"stem": "三、连一连（3分）：春天/秋天/冬天 + 青蛙/大雁/小燕子 + 筑巢/往南飞/在洞里睡觉", "options": null}', '春天—青蛙—筑巢；秋天—大雁—往南飞；冬天—小燕子—在洞里睡觉（或：青蛙冬眠、小燕子南飞）', '连线,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '扩词造句', 2, '{"stem": "四、照样子，先扩词，再写句子（12分）：例：片（一片片）一片片树叶从树上落下来。1.个（ ）2.棵（ ）3.座（ ）4.朵（ ）", "options": null}', '1.个（一个个）一个个苹果红通通。2.棵（一棵棵）一棵棵大树长在路边。3.座（一座座）一座座房子真漂亮。4.朵（一朵朵）一朵朵花开满枝头。', '扩词写句,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '造句', 2, '{"stem": "五、用加点的词语造句（15分）：一会儿…一会儿 / 怎样 / 干净 / 到处", "options": null}', '一会儿…一会儿：小猫一会儿跑，一会儿跳。怎样：你怎样去学校？干净：我把房间打扫干净。到处：春天到处开满鲜花。', '造句,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '补充句子', 2, '{"stem": "六、把句子补充完整（14分）：1.我爱__ 2.我会__，还会__ 3.弯弯的月亮像__ 4.北京是__ 5.我家住在__ 6.老师正在__ 7.我和好朋友一起__", "options": null}', '1.我爱妈妈。2.我会唱歌，还会跳舞。3.弯弯的月亮像小船。4.北京是中国的首都。5.我家住在上海。6.老师正在批改作业。', '补充句子,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '写句子', 2, '{"stem": "七、照样子，写句子（9分）：例：弯弯的月亮像香蕉。", "options": null}', '圆圆的太阳像火球。/ 蓝蓝的天空像大海。/ 闪闪的星星像眼睛。', '写句子,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "八、背一背，填一填（8分）：1.白毛浮绿水，__ 2.弯弯的月儿小小的船，__ 3.一寸光阴一寸金，__ 4.__，几步就成一幅画", "options": null}', '1.红掌拨清波 2.小小的船儿两头尖 3.寸金难买寸光阴 4.小鸡画竹叶', '古诗/课文默写,可推导', 'paper', '["填空"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "九、给下列句子排排队（填序号）（10分）：乌鸦喝水（ ）喝到水（ ）放石子（ ）口渴找水（ ）不想放弃想办法（ ）看见瓶子水浅喝不着", "options": null}', '3、5、4、2、1（口渴→看见水浅→想办法→放石子→喝到）', '课文排序,可推导', 'paper', '["排序"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '组词', 2, '{"stem": "十、爬楼梯（12分）：小马/马/虫/鸟/正/自 等组词", "options": null}', '小马—马—马车；虫—虫子；鸟—小鸟；正—正在；自—自己', '组词,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 1, '{"stem": "一、把诗句补充完整（不会写的字可用拼音）（15分）：1.鹅鹅鹅，__ 2.__，能开二月花 3.又疑瑶台镜，__ 4.__，汗滴禾下土 5.江南可采莲，__", "options": null}', '1.曲项向天歌 2.解落三秋叶 3.飞在青云端 4.锄禾日当午 5.莲叶何田田', '古诗默写,可推导', 'paper', '["填空"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '句子练习', 2, '{"stem": "二、根据要求完成句子练习（8分）：1.仿写（落叶黄黄，他对__说“我是秋天”）2.用“那么…那么”写一句话", "options": null}', '1.落叶黄黄，他对大地说“我是秋天”。2.天空那么蓝，那么高。', '句子练习,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线题', 1, '{"stem": "三、读一读，连一连（12分）：闪闪的/蓝蓝的/红红的 + 太阳/星星/天空 + 白云飘/升起来/亮晶晶", "options": null}', '闪闪的星星；蓝蓝的天空；红红的太阳；白云飘、升起来、亮晶晶（按搭配连线）', '连线,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线题', 1, '{"stem": "比尾巴连线：猴子的尾巴/兔子的尾巴/松鼠的尾巴/公鸡的尾巴/鸭子的尾巴/孔雀的尾巴 与 长/短/好像一把伞/弯/扁/最好看", "options": null}', '猴子—长、兔子—短、松鼠—好像一把伞、公鸡—弯、鸭子—扁、孔雀—最好看', '《比尾巴》连线,可推导', 'paper', '["连线题"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "四、连词成句（填序号）（10分）：1.①一群②雪地③小画家④里⑤来了 2.①要②我③去④有草⑤的⑥有花⑦地方 3.①叶子②从③一片片④下来⑤树上⑥落 4.①来②小姑娘③喊④帮忙⑤小狗 5.①读书②大家③老师④教", "options": null}', '1.④②⑤①③ 2.②①③⑥④⑤⑦ 3.③①②⑤⑥④ 4.②③⑤①④ 5.③④②①', '连词成句,可推导', 'paper', '["排序"]', NULL, 0);
