INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图写句', 2, '{"stem": "六、看图，写句子（12分）：圆圆的西瓜像__/胖胖的蘑菇像__/细长的柳枝像__/弯弯的月亮像__", "options": null}', '圆圆的西瓜像皮球；胖胖的蘑菇像小伞；细长的柳枝像辫子；弯弯的月亮像小船。', '看图写句,图意待补(此处填文字)', 'paper', '["待答案页核对"]', NULL, 0);
