INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '拼音分类', 2, '{"stem": "三、读一读，再分别写下来（15分）：声母 / 韵母 / 整体认读音节 分类", "options": null}', '声母：b p m f d t n l g k h j q x zh ch sh z c s y w；韵母：a o e i u ü ai ei ui ao ou iu ie üe er；整体认读：zhi chi shi ri zi ci si yi wu yu ye yue yuan yin ying yun', '拼音分类,回填答案页', 'paper', '["待答案页核对"]', NULL, 0);
