INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 3, '{"stem": "（ ）最多，（ ）最少，（ ）和（ ）同样多。（填图形名称）", "options": null}', '球；正方体；长方体和圆柱', '统计可得：球6个最多，正方体5个最少，长方体8个和圆柱5个并不相同；但题目要求“同样多”，根据图中数量应为长方体和圆柱同样多这一项不成立。结合图片实际数数，长方体8个、正方体5个、圆柱5个、球6个，因此同样多的是正方体和圆柱。', 'paper', '[]', '["/static/qimg/yg_sx_p11.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '操作', 2, '{"stem": "圈出能描出左边图形的物体。", "options": null}', '第一行圈长方体；第二行圈正方体；第三行圈圆柱；第四行圈三棱柱', '观察左边给出的平面图形，分别选择能描出相同面形状的立体物体：长方形对应长方体，正方形对应正方体，圆形对应圆柱，三角形对应三棱柱。', 'paper', '[]', '["/static/qimg/yg_sx_p11.jpg"]', 0);
