INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "像个柱子，上下一样粗细，两端是圆圆的、平平的面，可以滚动，摸到的是（ ）。", "options": null}', '圆柱', '两端是圆面、侧面可滚动，说明是圆柱。', 'paper', '[]', NULL, 0);
