INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "按形状分一分（填序号）：把图中的物体按“长方体”分类，填写对应的序号。", "options": null}', '4、8、11', '图中4号是长方体形状的微波炉，8号是长方体盒子，11号墨水盒也是长方体。', 'paper', '[]', '["/static/qimg/yg_sx_p13.jpg"]', 0);
