INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 2, '{"stem": "现在车上有多少名乘客？", "options": null}', '14名', '图中对话框直接给出“车上有乘客14人”。', 'paper', '[]', '["/static/qimg/yg_sx_p52.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算', 2, '{"stem": "小兔队和小猴队一共有多少名运动员？", "options": null}', '16名', '小兔队4名，小猴队12名，4+12=16。', 'paper', '[]', '["/static/qimg/yg_sx_p52.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算', 2, '{"stem": "小兔队、小熊队、松鼠队一共有多少名运动员？", "options": null}', '17名', '小兔队4名，小熊队7名，松鼠队6名，4+7+6=17。', 'paper', '[]', '["/static/qimg/yg_sx_p52.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 3, '{"stem": "你能再提出一个数学问题，并列式计算吗？", "options": null}', '', '开放题，需根据图中信息自行提出问题并列式计算。', 'paper', '[]', '["/static/qimg/yg_sx_p52.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 2, '{"stem": "树上原来有8只鸟，先是飞来了7只鸟，再是飞走了3只鸟，现在树上有多少只鸟？", "options": null}', '12只', '先加上飞来的7只，再减去飞走的3只：8+7-3=12。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 2, '{"stem": "小华今年7岁，她的哥哥今年10岁，5年后，小华的哥哥比小华大多少岁？", "options": null}', '3岁', '年龄差不变，哥哥比小华一直大10-7=3岁。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 2, '{"stem": "排队时，从左往右数，小华是第4个；从右往左数，小华是第8个。小华这一队一共有多少人？", "options": null}', '11人', '总人数=左边人数+右边人数-1=4+8-1=11。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '解答', 2, '{"stem": "啄木鸟今天为多少棵树捉了虫？", "options": null}', '9棵', '图中提示“今天我从第10棵开始捉虫，到第18棵结束”，包括第10棵到第18棵共18-10+1=9棵。', 'paper', '[]', '["/static/qimg/yg_sx_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 3, '{"stem": "下列每种图形代表的数字分别是几？（右边和下边的数字分别是对应各行、各列的三个图形代表数字的和）", "options": null}', '△=5，♡=3，□=11，○=7，☺=10', '由第2行三个三角形和为15，得△=5；第1行19=△+○+□，得○+□=14；第3行14=♡+☺+△，得♡+☺=9。再看第1列12=△+△+♡，得♡=2？但与第3行不符，结合图中列和分别为12、20、16：第1列12=△+△+♡=10+♡，得♡=2；第2列20=○+△+☺=7+5+☺，得☺=8；第3列16=□+△+△=□+10，得□=6。这样第1行19=5+7+6成立。故图形对应为△=5，♡=2，□=6，○=7，☺=8。', 'paper', '[]', '["/static/qimg/yg_sx_p56.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 1, '{"stem": "看图写数。", "options": null}', '苹果图是6；圆柱图是9；圆圈图是10；数位图是2', '分别数出四幅图中的物体个数：苹果6个，圆柱9个，圆圈10个，数位图中十位2、个位0，对应2。', 'paper', '[]', '["/static/qimg/yg_sx_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "在□里填上正确的数。数轴上从8到18，空格依次对应：8后面一个数、10后面一个数、13后面一个数、15后面一个数、18后面两个数。", "options": null}', '9，12，16，19，20', '按数轴顺序依次填写相邻整数：8后面是9，10后面是11；题图中空格位置对应的是8后、11后、15后、18后两个数，结合数轴可填9、12、16、19、20。', 'paper', '[]', '["/static/qimg/yg_sx_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "19里面有（ ）个十和（ ）个一，比它大1的数是（ ）个十。", "options": null}', '1，9，20', '19由1个十和9个一组成；比19大1是20，20是2个十。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "10后面的第3个数是（ ），前面3个数分别是（ ）、（ ）、（ ）。", "options": null}', '13，9，8，7', '10后面依次是11、12、13，所以第3个数是13；10前面依次是9、8、7。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "一个数的十位上是1，个位上的数比十位上的多6，这个数是（ ），读作（ ），与它相邻的两个数分别是（ ）和（ ）。", "options": null}', '17，十七，16，18', '十位是1表示十位数字为1；个位比十位多6，所以个位是7，组成17，读作十七；相邻数是16和18。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 1, '{"stem": "比10多6的数是（ ），比15少5的数是（ ）。", "options": null}', '16，10', '10+6=16；15-5=10。', 'paper', '[]', NULL, 0);
