INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '解答', 2, '{"stem": "Make a new friend. Lily 正在介绍自己，请根据先后顺序，给她说的话排序。My name is Lily White.; Hello.; You can call me Lily.; Good to meet you.", "options": null}', 'Hello. → My name is Lily White. → You can call me Lily. → Good to meet you.', '按自我介绍的常见顺序：先打招呼，再介绍姓名，再说明称呼，最后礼貌回应。', 'paper', '[]', '["/static/qimg/mz_yy_p018.jpg"]', 0);
