INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "先看图填空,再列出算式:1.两幅图均为4行5列共20个贝壳,□个□相加的和是□;加法算式:____;乘法算式:____;□×□=□×□。", "options": null}', '5个4相加的和是20;加法:5+5+5+5=20;乘法:5×4=20(交换律4×5=20)', '4个5相加=20,加法算式5+5+5+5=20,乘法算式5×4=4×5=20(乘法交换律)。', 'paper', '[]', '["/static/qimg/tb_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "看图写出两个乘法算式:图1(3行5列共15个△);图2(3行7列共21个△)。", "options": null}', '图1:5×3=15;图2:7×3=21', '图1有3个5,列乘法算式5×3=15;图2有3个7,列乘法算式7×3=21。', 'paper', '[]', '["/static/qimg/tb_p29.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填一填:3.(1)3×9=9×□,4×8=□×□,□×7=7×6,▲×★=□×□。", "options": null}', '3;4,8;6;★,▲', '3×9=9×3(交换律),4×8=4×8,□×7=7×6→□=6,▲×★=★×▲(交换律)。', 'paper', '[]', '["/static/qimg/tb_p30.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填一填:3.(2)8×3=3×□=□+□+□=□。", "options": null}', '8;8;8;8;24', '8×3=3×8=8+8+8=24,乘法交换律。', 'paper', '[]', '["/static/qimg/tb_p30.jpg"]', 0);
