INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "填一填:3.(4)在加法算式\\\"8+8+8+8+8+8+3\\\"中,如果再加上□,就可以用乘法算式\\\"6×8\\\"表示。\\\"", "options": null}', '5(注:题目应理解为 5个8+3 凑 6个8=48, 5个8+3+5=48;若严格按 6个8+3=51, 无解,可能题目印刷有误,按 5个8+3 情形解为 5)', '5个8+3=43, 加上5凑成48=6×8;若按6个8+3则题目有误,正确解为5。', 'paper', '[]', '["/static/qimg/tb_p30.jpg"]', 0);
