INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "想一想,算一算 A级 3:1×3,1×5,6×0;2×3,2×5,7×0;3×3,3×5,8×0;4×3,4×5,9×0;5×3,5×5,10×0。", "options": null}', '3,5,0;6,10,0;9,15,0;12,20,0;15,25,0', '1×3=3,1×5=5,6×0=0;2×3=6,2×5=10,7×0=0;3×3=9,3×5=15,8×0=0;4×3=12,4×5=20,9×0=0;5×3=15,5×5=25,10×0=0。任何数乘0得0。', 'paper', '[]', '["/static/qimg/tb_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "想一想,填一填 B级 1:(1)■+■=12,■=□;(2)❤+❤+❤=12,❤=□;(3)▲+▲+▲+▲=12,▲=□;(4)★+★+★+★+★+★=12,★=□。", "options": null}', '6,4,3,2', '12÷2=6,12÷3=4,12÷4=3,12÷6=2(乘除法互逆)。', 'paper', '[]', '["/static/qimg/tb_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "看图写乘法算式 B级 2:图1(4行5列共20个圆),图2(4行7列共28朵花),你能写出几个?", "options": null}', '图1:4×5=20或5×4=20;图2:4×7=28或7×4=28', '图1:4个5,4×5=5×4=20;图2:4个7,4×7=7×4=28(乘法交换律)。', 'paper', '[]', '["/static/qimg/tb_p32.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "算一算 A级 1:8×5,30-5,25=5×□;5×10,25+5,35=□×5;5×3,15+15,45=□×5。", "options": null}', '40,25,5;50,30,7;15,30,9', '8×5=40,30-5=25,25=5×5;5×10=50,25+5=30,35=7×5;5×3=15,15+15=30,45=9×5。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "在○内填入\\\"十\\\"\\\"-\\\"或\\\"×\\\" A级 2:5○5=10,15○5=10,5○5○5○5=20,5○5=25,5○6=25○5,40○5=5○7。\\\"", "options": null}', '+,+;-,+;+,+,+;×;×, +;-,×', '5+5=10,15-5=10;5+5+5+5=20(3个+);5×5=25;5×6=25+5=30(×和+);40-5=5×7=35(-和×)。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "一个一个摆,摆4个独立的□(正方形) A级 3,一共需要多少根小棒?", "options": null}', '算式:4×4=16;答:16根', '一个正方形用4根小棒,4个独立正方形(不共用边)需要4×4=16根小棒。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "填一填 B级:(1)2与5的和是____;2个5的和是____;2个5的积是____。(2)买了一本书,付给收银员7张5元,找回的钱不到5元。这本书的价格可能是____元(填序号:①35 ②30 ③32)。", "options": null}', '(1)7,10,25;(2)①和③', '(1)2+5=7,2个5相加=5+5=10,2个5相乘=5×5=25。(2)7张5元=35元,找回<5元,书价>30元且≤35元,选项①35(找回0元)和③32(找回3元)均<5元,②30找回5元不满足"不到5元"。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "算一算 A级 1:8×2,7+7,12=2×□;2×10,9+9,16=□×2;2×9,8+8,8=2×□。", "options": null}', '16,14,6;20,18,8;18,16,4', '8×2=16,7+7=14,12=2×6;2×10=20,9+9=18,16=8×2;2×9=18,8+8=16,8=2×4。', 'paper', '[]', '["/static/qimg/tb_p34.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "应用题 A级 2:棒棒糖每根2元,冰淇淋每个5元。(1)买4个冰淇淋需要多少元?(2)有3张5元钱,买7根棒棒糖,钱够不够?(3)请再提出一个数学问题,并列式解答。", "options": null}', '(1)4×5=20(元);(2)3×5=15(元),7×2=14(元),15>14,钱够;(3)开放题', '(1)冰淇淋4个:4×5=20元。(2)7根棒棒糖:7×2=14元,3张5元=15元,15>14,钱够。(3)开放题,例如买5个冰淇淋要多少元:5×5=25元。', 'paper', '[]', '["/static/qimg/tb_p34.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级:参加猜灯谜游戏,获得5分和2分的积分卡各8张。他想兑换一辆30分的玩具车,可以怎么兑换?写出两种兑换方式。", "options": null}', '方式1:6张5分卡=30分(用6张5分);方式2:4张5分卡+5张2分卡=20+10=30分(用4张5分卡和5张2分卡)', '5分卡8张、2分卡8张,要凑30分:6×5=30(仅用5分卡);4×5+5×2=20+10=30(混合兑换);还有2×5+10×2=10+20=30但2分卡只有8张,不可行。', 'paper', '[]', '["/static/qimg/tb_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "A级 课本46~47页 算一算:8×4=□;4×□=16;20=□×4;7×4=□;4×□=8;24=4×□;4×10=□;4×□=12;36=□×4", "options": null}', '8×4=32;4×4=16;20=5×4;7×4=28;4×2=8;24=4×6;4×10=40;4×3=12;36=9×4', '本题为4的乘法口诀应用。8×4=32(八四三十二),4×4=16,20÷4=5,7×4=28,4×2=8,24÷4=6,4×10=40,4×3=12,36÷4=9。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 课本46~47页 找规律填数:(1)20,18,□,14,□,□,8;(2)4,8,□,□,20,□,28,□,36", "options": null}', '(1)16,12,10;(2)12,16,24,32', '规律题:(1)每一项比前一项少2,依次为20,18,16,14,12,10,8;(2)每一项比前一项多4,依次为4,8,12,16,20,24,28,32,36。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 课本46~47页 应用题(1):一包瓜子9元,4包瓜子一共多少元?", "options": null}', '9×4=36(元)', '求4包瓜子的总价,用单价×数量=总价:9×4=36(元)。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 课本46~47页 应用题(2):有8盒巧克力,每盒有4块。一共有多少块巧克力?", "options": null}', '8×4=32(块)', '求巧克力的总块数,用每盒块数×盒数=总块数:8×4=32(块)。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 课本46~47页 应用题(3):有25名乘客,每辆车限坐乘客7人。4辆车坐得下吗?", "options": null}', '4×7=28(人),28>25,坐得下。', '4辆车最多坐4×7=28人,28>25,所以4辆车能坐得下25名乘客。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "A级 课本46~47页 应用题(4):每天看6页书,已经看了4天。第5天应从第几页开始看?", "options": null}', '6×4=24(页),24+1=25(页),第5天应从第25页开始看。', '前4天一共看了6×4=24页,第5天应从已看完的下一页开始,即第25页。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 3, '{"stem": "B级 课本46~47页:有一筐萝卜,分给4只小兔,每只分到的数量正好相同。这筐萝卜的数量不可能是____。(填序号)①36 ②30 ③32", "options": ["A. 36", "B. 30", "C. 32"]}', 'B(30)', '萝卜数量必须能被4整除(每只分到的数量相同)。36÷4=9,32÷4=8,30÷4=7.5不是整数。所以不可能是30。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级 课本46~47页:已知▲+▲+▲+▲=24,★+★+★=15,那么▲×★=____。", "options": null}', '▲×★=6×5=30', '由4个▲=24,得▲=24÷4=6;由3个★=15,得★=15÷3=5;所以▲×★=6×5=30。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "A级 课本48~49页 算一算:8×6=□;2×□=16;40=□×8;7×8=□;8×□=32;24=8×□;10×8=□;□×8=72;64=□×8", "options": null}', '8×6=48;2×8=16;40=5×8;7×8=56;8×4=32;24=8×3;10×8=80;9×8=72;64=8×8', '本题为8的乘法口诀应用。8×6=48,2×8=16,40÷8=5,7×8=56,8×4=32,24÷8=3,10×8=80,72÷8=9,64÷8=8。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 课本48~49页 看图列式:上面一组足球8个,下面一组篮球是?个。□×□=□(个)", "options": null}', '8×2=16(个)', '看图:上面1组足球8个,下面1组篮球也是8个(2组共16个),即篮球的数量是足球的2倍,8×2=16(个)。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 课本48~49页 应用题(1):二(3)班有8个小组,每个小组有4名学生。二(3)班一共有多少名学生?", "options": null}', '8×4=32(名)', '求班级总人数,用每组人数×组数=总人数:8×4=32(名)。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "A级 课本48~49页 应用题(2):一罐可乐3元,买8罐可乐。如果全部用20元纸币付,至少要付几张?", "options": null}', '3×8=24(元),24>20,至少要付2张20元纸币。', '8罐可乐共需3×8=24元,1张20元不够(差4元),所以至少要付2张20元。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "(3) 每个面包 8 元，第一小组买了 8 个面包，第二小组买了 6 个面包。第一小组比第二小组多花了多少元？", "options": null}', '16 元', '第一小组花费 8×8=64 元；第二小组花费 8×6=48 元；多花 64-48=16 元；或 (8-6)×8=2×8=16 元', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级★1 在一次登高活动中，李老师从 1 楼走到 2 楼用了 8 秒。照这样的速度，她从 1 楼走到 9 楼，一共需要多少秒？", "options": null}', '64 秒', '从 1 楼到 2 楼爬了 1 层，用 8 秒；从 1 楼到 9 楼共有 9-1=8 层；共需 8×8=64 秒', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "B级★2 7 位小伙伴去游乐园玩，碰碰车每人 6 元、小火车每人 5 元、摩天轮每人 8 元。(1) 他们一起乘坐摩天轮，一共需要多少元？", "options": null}', '56 元', '摩天轮每人 8 元，共 7 人；7×8=56 元', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级★2 7 位小伙伴去游乐园玩，碰碰车每人 6 元、小火车每人 5 元、摩天轮每人 8 元。(2) 请再提出一个数学问题，并列式解答。", "options": null}', '开放题（示例：一起坐小火车需要多少元？答：7×5=35 元）', '开放题；可提出：一起坐碰碰车/小火车/摩天轮各需多少元；或 三种都坐一次共多少元 6×7+5×7+8×7=42+35+56=133 元', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "A级★1 算一算：5×5-7=□，8×9-16=□，2×8+8=□，40-3×4=□，6×8+12=□，9×8-8=□，56-8×7=□，4×8+9=□，8×8-8=□，8×9-9=□", "options": null}', '18; 56; 24; 28; 60; 64; 0; 41; 56; 63', '5×5-7=25-7=18；8×9-16=72-16=56；2×8+8=16+8=24；40-3×4=40-12=28；6×8+12=48+12=60；9×8-8=72-8=64；56-8×7=56-56=0；4×8+9=32+9=41；8×8-8=64-8=56；8×9-9=72-9=63', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★2 看图：一共有5盘苹果，前4盘每盘8个，最后1盘6个。要求出一共有多少个苹果，不正确的算式是（  ）A. 4×8+6  B. 5×8-6  C. 5×8-2", "options": null}', 'B', '前 4 盘共 4×8=32 个；第 5 盘 6 个；共有 32+6=38 个；A. 4×8+6=38 ✓ 正确；B. 5×8-6=40-6=34 ≠ 38 ✗ 不正确；C. 5×8-2=40-2=38 ✓ 正确；不正确的是 B', 'paper', '[]', '["/static/qimg/tb_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 2, '{"stem": "A级★3 看图列式解答：(1) 图中 5 摞小方块，前 4 摞每摞 4 块，第 5 摞 2 块，求一共有多少个小方块？算式：______  答：一共有 ____ 个小方块。", "options": null}', '4×4+2=18 个', '前 4 摞每摞 4 块，共 4×4=16 块；第 5 摞 2 块；共有 16+2=18 块；算式：4×4+2=18', 'paper', '[]', '["/static/qimg/tb_p40.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 2, '{"stem": "看图列式：(2) 3 盆花每盆 8 元 + 1 根跳绳 = 42 元，跳绳每根多少元？算式：______  答：一根跳绳 ____ 元。", "options": null}', '42-8×3=18 元', '3 盆花共 3×8=24 元；4 项共 42 元；跳绳 42-24=18 元；算式：42-8×3=18', 'paper', '[]', '["/static/qimg/tb_p41.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级★1 在超市买了 4 包抽纸，每包 8 元。如果全部用 10 元 支付，她至少要付几张？还要找回多少元？", "options": null}', '至少付 4 张，找回 8 元', '总钱 4×8=32 元；用 10 元 付 3 张是 30 元不够，需 4 张共 40 元；找回 40-32=8 元', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★1 填表：求下列各积。4×7=□, 8×4=□, 7×6=□, 5×8=□, 7×5=□, 3×7=□, 7×9=□, 9×8=□, 7×7=□", "options": null}', '28; 32; 42; 40; 35; 21; 63; 72; 49', '4×7=28；8×4=32；7×6=42；5×8=40；7×5=35；3×7=21；7×9=63；9×8=72；7×7=49', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "A级★2 算一算：5×7=□, 9×7=□, 0×7=□, 7×8=□, 7×6=□, 3×7=□, 10×7=□, 4×7=□, 7×7=□", "options": null}', '35; 63; 0; 56; 42; 21; 70; 28; 49', '5×7=35；9×7=63；0×7=0；7×8=56；7×6=42；3×7=21；10×7=70；4×7=28；7×7=49', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 2, '{"stem": "A级 算一算：7×8+7=□, 2×7+7×5=□, 9×7-7=□, 8×7-7×8=□", "options": null}', '63; 49; 56; 0', '7×8+7=56+7=63；2×7+7×5=14+35=49；9×7-7=63-7=56；8×7-7×8=56-56=0', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 应用题 (1) 看图：4 串气球每串 5 个，3 串气球每串 4 个，求一共有多少个气球？算式：□×□+□×□=□ (个)  答：一共有 □ 个气球。", "options": null}', '4×5+3×4=32 个', '4 串每串 5 个：4×5=20；3 串每串 4 个：3×4=12；共 20+12=32 个', 'paper', '[]', '["/static/qimg/tb_p42.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "(2) 看图：3 盘苹果每盘 5 个，2 盘草莓每盘 6 个，苹果和草莓一共有多少个？", "options": null}', '27 个', '苹果 3×5=15 个；草莓 2×6=12 个；共 15+12=27 个', 'paper', '[]', '["/static/qimg/tb_p43.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "(3) 30 名学生乘坐小火车，每节车厢能坐 4 人，共 7 节车厢。坐得下吗？如果坐不下，求出几人没有座位；如果坐得下，求出还剩几个空位。", "options": null}', '坐不下，2 人没座位', '7 节车厢每节 4 人共 4×7=28 个座位；28 < 30 坐不下；30-28=2 人没座位', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级 学校合唱队表演时，队员们排成了一个正方形方阵。无论是从前往后数，还是从后往前数，某一列的第 4 个都是同一人。合唱队一共有多少人？", "options": null}', '16 人', '正方形方阵，前后数第 4 个都是同一人，说明每列 4 人；正方形每行也是 4 人；共 4×4=16 人', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "A级★1 算一算：3×7=□, 4×3=□, 2×3+3×4=□, 9×3=□, 3×6=□, 9×3-7×3=□, 3×5=□, 8×3=□, 8×3-3×3=□", "options": null}', '21; 12; 18; 27; 18; 6; 15; 24; 15', '3×7=21；4×3=12；2×3+3×4=6+12=18；9×3=27；3×6=18；9×3-7×3=27-21=6；3×5=15；8×3=24；8×3-3×3=24-9=15', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★2(1) 看图：①号是 12 个心形，②号是 11 个星形，③号是 9 个圆点。下列能用算式\\\"3×4-1\\\"计算的是（  ）\\\"", "options": null}', '②', '3×4-1=12-1=11；①号 12 个心形=3×4 不能用"3×4-1"；②号 11 个星形=3×4-1 ✓；③号 9 个圆点=3×3 不能用"3×4-1"', 'paper', '[]', '["/static/qimg/tb_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "A级★2(2) 已知 ▲ + ▲ = 18，那么 ▲ = ___；● + ● + ● = ▲，那么 ● = ___。", "options": null}', '▲ = 9；● = 3', '▲+▲=18 → 2▲=18 → ▲=9；●+●+●=▲=9 → 3●=9 → ●=3', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(3) 像下面这样继续摆下去（每图依次为 1×1, 2×2, 3×3 的小方格），第 4 个图形中有 ____ 个小方格，第 7 个图形中有 ____ 个小方格。", "options": null}', '16 个；49 个', '第 n 个图形是 n×n 的方格；第 4 个：4×4=16；第 7 个：7×7=49', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级★ 想一想，填一填。看天平图：左边 1 桃 + 2 樱桃 = 右边 3 桃，1 桃 = □ 个樱桃。", "options": null}', '1 桃 = 1 樱桃', '天平：1 桃 + 2 樱桃 = 3 桃；两边同时减去 1 桃：2 樱桃 = 2 桃；所以 1 桃 = 1 樱桃', 'paper', '[]', '["/static/qimg/tb_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "A级★1 算一算：7×6=□, 4×6+6=□, 54-6×6=□, 6×3=□, 8×6-19=□, 60-6×7=□, 9×6-6×4=□, 2×6+6×5=□", "options": null}', '42; 30; 18; 18; 29; 18; 30; 42', '7×6=42；4×6+6=24+6=30；54-6×6=54-36=18；6×3=18；8×6-19=48-19=29；60-6×7=60-42=18；9×6-6×4=54-24=30；2×6+6×5=12+30=42', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(1) 1 只青蛙 1 张嘴，2 只眼睛、4 条腿。6 只青蛙 ___ 张嘴，___ 只眼睛、___ 条腿。", "options": null}', '6; 12; 24', '嘴：张数=青蛙数=6；眼睛：青蛙数×2=6×2=12；腿：青蛙数×4=6×4=24', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "A级★2(2) 一箱饮料有 8 瓶，6 箱饮料有 ___ 瓶。", "options": null}', '48', '6 箱饮料：6×8=48 瓶', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(3) 汉字\\\"口\\\"的笔画有 3 画，\\\"口吕品\\\"这三个字一共有 ___ 画。\\\"", "options": null}', '18', '口=3 画；吕=6 画（两个口）；品=9 画（三个口）；共 3+6+9=18 画', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(4) 二(2)班学生参加春游。如果每个小组 6 人，可以分成 6 个小组。如果每个小组 4 人，可以分成 ___ 个小组。", "options": null}', '9', '总人数 6×6=36 人；每组 4 人：36÷4=9 组', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "A级★2(5) 6 与 6 的和是 ___，6 个 6 的和是 ___。", "options": null}', '12; 36', '6 与 6 的和=6+6=12；6 个 6 的和=6×6=36', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(6) 在做一道乘法计算时，把其中一个乘数 8 看成了 6，算出的结果是 24。正确的结果是 ___。", "options": null}', '24', '把 8 看成 6 算出 24 → 另一乘数 = 24÷6 = 4；正确算式 = 8×4 = 24；巧合正确结果也是 24', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "A级★2(7) 已知 ▲ × ▲ = 25，● + ● = 12，那么 ▲ × ● = ___。", "options": null}', '30', '▲×▲=25 → ▲=5；●+●=12 → ●=6；▲×●=5×6=30', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★3(1) 下面得数最大的是（  ）A. 2 和 6 相加 B. 2 个 6 相乘 C. 2 个 6 相加", "options": null}', 'B', 'A. 2+6=8；B. 2×6=12；C. 2+6=8；最大是 B', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 3, '{"stem": "A级★3(2) 每两面旗间隔 6 米（看图 6 面旗），第 1 面旗与第 6 面旗之间一共间隔（  ）A. 36 米 B. 30 米 C. 42 米", "options": null}', 'B', '6 面旗之间有 5 个间隔；总长 5×6=30 米', 'paper', '[]', '["/static/qimg/tb_p46.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★3(3) 下面的算式中，结果与\\\"6+6+6+6+6+5\\\"相等的是（  ）A. 6×5+6 B. 6×6+5 C. 6×5+5\\\"", "options": null}', 'C', '6+6+6+6+6+5 = 6×5+5；6×5+5=30+5=35 与原式 30+5=35 一致；B. 6×6+5=36+5=41 不对；A. 6×5+6=30+6=36 不对', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级★1 将一根绳子对折 2 次后，每段绳子长 6 米。这根绳子原来长 ___ 米。", "options": null}', '24', '对折 1 次变 2 段，对折 2 次变 4 段；每段 6 米 → 原来 4×6=24 米', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级★2 二(1)班的学生排队检查视力，每批进去 5 个人，乐乐排在第 6 批。乐乐可能是全班第 ___ 个检查视力的学生。（写出所有可能的情况）", "options": null}', '26, 27, 28, 29, 30 共 5 种可能', '前 5 批各 5 人共 25 人已查完；第 6 批第 1 个：第 26 个；第 2 个：第 27；... 第 5 个：第 30；所以可能是 26、27、28、29、30，共 5 种', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★1 想一想，填一填：□×5=45, 9×□=54, 9×8=□, 9×9-□=27, □+4×9=70, 9×9-□×9=4×9+2×9", "options": null}', '9; 6; 72; 54; 34; 3', '9×5=45 □=9；9×6=54 □=6；9×8=72；9×9-54=27 □=54；34+4×9=34+36=70 □=34；9×9-3×9=9×6=54=4×9+2×9=36+18=54 □=3', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2 在 ○ 内填入\\\">\\\"\\\"<\\\"或\\\"=\\\"：9×9-9○70, 4×9○9×3+9, 53+36○46+43, 7×9○9×8-9, 63-3×6○9×5, 81-3×9○2×9+5×9\\\"", "options": null}', '>、=、=、=、=、<', '9×9-9=72>70；4×9=36, 9×3+9=36 → =；53+36=89, 46+43=89 → =；7×9=63, 9×8-9=63 → =；63-3×6=45, 9×5=45 → =；81-3×9=54, 2×9+5×9=63 → 54<63', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "A级★3 下面是某所小学的会议室座位示意图。现在有 40 人要在这个会议室参加会议，坐得下吗？先列式，再解答。（单人座 4 行 6 列 = 24 个，双人座 3 行 2 对 = 12 人）", "options": null}', '坐不下', '单人座 6×4=24 个；双人座 2×3=6 对=12 个；共 24+12=36 个座位；40>36 坐不下', 'paper', '[]', '["/static/qimg/tb_p47.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "马路上有一排树，每两棵树间隔9米。第1棵树与第9棵树之间一共间隔多少米？", "options": null}', '72米', '9棵树之间有8个间隔，每个间隔9米，共8×9=72米。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级 有一堆小棒，一个一个摆，正好可以摆9个六边形。像这样摆，这堆小棒可以摆多少个五边形？", "options": null}', '10个', '9个六边形共9×6=54根小棒；摆五边形需5根，54÷5=10余4，所以可摆10个。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级 玩具店有一些玩偶，数量在60~80个之间。如果每层货架上放9个玩偶，那么还剩下1个玩偶。玩具店可能有多少个玩偶？", "options": null}', '64个或73个', '每层9个还剩1，即玩偶数为9的倍数+1。在60-80之间的9的倍数有63,72；加1得64和73。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 把口诀补充完整：四七____；六____四十八；八八____；七____六十三；____三十二；____五十六。", "options": null}', '二十八；八；六十四；九；四八；七八', '四七二十八；六八四十八；八八六十四；七九六十三；四八三十二；七八五十六。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 2, '{"stem": "A级 看图写算式（图：3组足球，每组8个，写出加法与乘法算式）。", "options": null}', '加法：8+8+8=24；乘法：3×8=24（或8×3=24）', '每组8个，3组共3×8=24个；加法是3个8相加。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "A级 从32、6、4、48、8、24中选出3个数组成乘法算式，并写出所用的乘法口诀（写出2组）。", "options": null}', '4×8=32（四八三十二）；6×8=48（六八四十八）', '用3个数中前两个相乘等于第三个数：4×8=32，6×8=48，4×6=24，3×8=24（3不在表中），6×4=24，8×6=48。任选两组即可。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级 找规律填数：(1) 6,9,□,15,□,21,□；(2) 81,□,49,36,□,16,□。", "options": null}', '(1) 12,18,24；(2) 64,25,9', '(1) 前后两项差为3：6,9,12,15,18,21,24；(2) 是9²,8²,7²,6²,5²,4²,3²的序列：81,64,49,36,25,16,9。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级 在○内填入\\\"+\\\"\\\"-\\\"或\\\"×\\\"，使式子成立：4○2=9○1；3○4=9○3；6○6=4○9；4○4=8○8。\\\"", "options": null}', '4×2=9-1；3×4=9+3；6×6=4×9；4×4=8+8', '两边结果分别相等：(1)4×2=8=9-1；(2)3×4=12=9+3；(3)6×6=36=4×9；(4)4×4=16=8+8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem": "A级 算一算：6×4, 9×3, 8×4, 5×9, 4×7, 8×3, 2×6, 5×7, 6×9, 7×6, 9×7, 7×7。", "options": null}', '24,27,32,45,28,24,12,35,54,42,63,49', '乘法口诀直接计算。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 □内最大能填几：(1)6×□<42；(2)30>5×□；(3)□×9<56；(4)28>7×□；(5)□×4<18；(6)37>6×□；(7)7×□<44；(8)20>□×3；(9)□×2<16。", "options": null}', '6,5,6,3,4,6,6,6,7', '(1)6×6=36<42, 6×7=42不<；(2)5×5=25<30, 5×6=30不>；(3)6×9=54<56, 7×9=63>；(4)7×3=21<28, 7×4=28不>；(5)4×4=16<18, 5×4=20>；(6)6×6=36<37；(7)7×6=42<44；(8)6×3=18<20；(9)7×2=14<16。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 填一填：(1)从42里连续减6，减几次刚好减完？(2)一本连环画共52页，如果每天最多看8页，至少需要几天看完？(3)求图中涂色小方格数（部分涂色网格），用算式____表示（①6×3+4 ②4×5+6 ③6×5-2）。", "options": null}', '(1)7次；(2)7天；(3)②', '(1)42÷6=7；(2)52÷8=6余4，至少需7天；(3)图中整涂部分为4行5列+1行6列=26=4×5+6，选②。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "B级 先数一数，再用两种方法列式计算（图：4个完整堆每堆10个桃子+1堆显示部分共5堆）。问：共有多少个？", "options": null}', '5×10=50（或10+10+10+10+10=50）', '每堆10个，5堆共50个；可用5个10相加或5×10计算。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级 欢欢在计算下面这道题时，弄错了运算顺序，先算了加法，后算了乘法，得到的结果是72。正确的结果是多少？4+★×8（★的下面藏了一个数字）", "options": null}', '44', '欢欢错误：(4+★)×8=72 → 4+★=9 → ★=5；正确运算顺序：4+5×8=4+40=44。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 一个书架9层，每层能放8本书。书架上一共能放多少本书？", "options": null}', '72本', '9×8=72本。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 欢欢一共要写60个毛笔字，她每天写9个。欢欢一个星期（7天）能写完吗？", "options": null}', '能写完（9×7=63>60）', '7天共写9×7=63个，63>60，所以能写完。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "A级 旅行团去餐厅吃饭。餐厅一共安排了6张桌子，每张桌子可以坐8人。所有人都坐下后，还有3个空位。旅行团一共有多少人？", "options": null}', '45人', '总座位6×8=48个，减去3个空位，48-3=45人。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 商店部分生活用品价格：每双袜子4元、每条毛巾9元、每把牙刷7元、每顶帽子45元。(1)买7双袜子和7把牙刷，一共需要多少元？", "options": null}', '77元', '7×4+7×7=28+49=77元。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "A级 李老师带了一张100元，买了6条毛巾。剩下的钱够买一顶帽子吗？（每条毛巾9元，每顶帽子45元）", "options": null}', '够（6×9=54，100-54=46>45）', '买毛巾花6×9=54元，剩余100-54=46元，46>45元，够买一顶帽子。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级 小华带了一些钱去买笔记本。如果她买3本，那么还剩下8元；如果她再多买1本，那么就还剩下3元。小华一共带了多少钱？", "options": null}', '23元', '多买1本少8-3=5元，即每本5元；买3本花3×5=15元，共带15+8=23元。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 填一填。(1) 1只螃蟹8条腿，7只螃蟹___条腿 (2) 1把三角尺有___个角，9把三角尺有___个角 (3) 8个4是___，4个8是___ (4) 3个6加5个6是___个6，结果是___ (5) 成语「半斤八两」原意是「半斤等于八两」，1斤等于___两 (6) 买6支9元的钢笔，全部用10元付，至少要付___张 (7) 已知 ●+●+●=21，▲+▲=16，那么 ●×▲=___ (8) 摆三角形：第1个3根，第2个5根，第3个7根，照这样第9个图形要用___根小棒", "options": null}', '(1)56 (2)3, 27 (3)32, 32 (4)8, 48 (5)16 (6)6 (7)56 (8)19', '(1)7×8=56；(2)三角尺3个角，9把共3×9=27；(3)8×4=32；(4)3+5=8个6，8×6=48；(5)8×2=16；(6)6×9=54元，10元6张共60元；(7)●=21÷3=7，▲=16÷2=8，7×8=56；(8)规律第n个用2n+1根，第9个=19。', 'paper', '[]', '["/static/qimg/tb_p54.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "A级 □内最大能填几？6×7>□；8×□<64；21>□×3；35>□×5；9×□<68；□<7×8；9×4>□×6；39-□>4×8", "options": null}', '41, 7, 6, 6, 7, 55, 5, 6', '逐个试最大整数值：6×7=42则□≤41；8×7=56<64则□≤7；7×3=21不大于21则□≤6；7×5=35则□≤6；9×7=63<68则□≤7；7×8=56则□≤55；6×6=36>36不行则□≤5；39-□>32则□<7即□≤6。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 小华去超市购物（蛋糕每块7元、牛奶每盒9元、糖每包8元）。(1) 买6块蛋糕，需要多少元？", "options": null}', '42元', '6×7=42元。', 'paper', '[]', '["/static/qimg/tb_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "A级 请根据上图商品价格（蛋糕7元/块、牛奶9元/盒、糖8元/包），再提出一个数学问题并列式解答。", "options": null}', '开放题，例如：买3盒牛奶需要多少元？3×9=27元', '考察提问题能力，答案不唯一，列式合理即可。', 'paper', '[]', '["/static/qimg/tb_p55.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级（星） 有一包糖果，比40颗多，比50颗少。把这包糖果分给9个小朋友，每人分到的数量一样多。这包糖果一共有多少颗？每人分到多少颗？", "options": null}', '共45颗，每人5颗', '9的倍数在41-49之间只有9×5=45，所以共45颗，9人每人5颗。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "B级（星） 如果▲×■=6，▲×★=24，那么▲、■、★分别表示几？你能写出多少种不同的情况？", "options": null}', '共4种：①▲=1, ■=6, ★=24；②▲=2, ■=3, ★=12；③▲=3, ■=2, ★=8；④▲=6, ■=1, ★=4', '▲必须整除6和24，从▲=1,2,3,6逐一代入求■、★，共4种。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级 把下列算式按结果位数分类（结果是一位数或两位数）：①43-29=14 ②25-16 ③38+6-35 ④52-14-19 ⑤26+27-45 ⑥90-67-17 ⑦63-8-37 ⑧31-13-9 ⑨76+7-66", "options": null}', '一位数：②③⑤⑥⑧（9、9、8、6、9）；两位数：①④⑦⑨（14、19、18、17）', '逐题计算结果再按位数分类：②=9，③=9，⑤=8，⑥=6，⑧=9；①=14，④=19，⑦=18，⑨=17。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "观察下面的火车图案，完成分类统计表。火车由 4 节车厢组成，每节车厢底部有 2 个圆形车轮，顶部为不同的形状（3 个白色方块、1 个黑色长方形）。请按形状统计：圆形、方块、长方形、三角形各有多少个。", "options": null}', '圆形 8 个（4 节车厢每节 2 个车轮）、白色方块 3 个、黑色长方形 1 个、三角形 0 个。', '按形状分类时逐类数：每节车厢有 2 个车轮，4 节共 2×4=8 个圆形；顶部形状数一数即可。分类统计是学习「数的整除」的基础，关键是同一标准不重不漏。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem": "用不同的标准，把下面的图形分一分，再用符号记录结果。图中有：长方形 2 个、正方形 2 个、三角形 3 个、圆 3 个、梯形 2 个。", "options": null}', '按形状分：长方形 2 个、正方形 2 个、三角形 3 个、圆 3 个、梯形 2 个；按颜色分（浅色/深色）分别计数。答案不唯一。', '分类标准可以不同（形状、颜色、大小等），按同一标准不重不漏地数即可。鼓励用不同标准多角度分类，体会分类思想。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "选择不同的标准，把下面的数卡分一分，并用表格记录结果。数卡：20、3、8、14、7、3、15、9、13、17。", "options": null}', '标准一（单双数）：单数 7 个（3、7、3、15、9、13、17），双数 3 个（20、8、14）；标准二（位数）：一位数 5 个（3、8、7、3、9），两位数 5 个（20、14、15、13、17）；标准三（能否被 3 整除）：3 的倍数 4 个（3、15、9、3），其余 6 个。', '数的分类可从单双数、位数、能否被某数整除等角度入手。注意 20、8、14 都是双数，3、7、15、9、13、17 都是单数。本题训练数的多种分类，是后续「数的整除」概念的基础。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem": "用逐层分类的方法，把下面的 12 个气球分一分、数一数。先按颜色（绿色、白色）分，再按形状（圆形、心形、椭圆形）分。", "options": null}', '第一层按颜色分：绿色 5 个、白色 7 个。第二层按形状分：绿色中圆形 2 个、心形 2 个、椭圆形 1 个；白色中圆形 3 个、心形 1 个、椭圆形 3 个。', '「逐层分类」指先按一个标准分大类，再在每个大类里按另一个标准分小类。先数颜色，再在每类里数形状，逐层不重不漏。', 'paper', '[]', '["/static/qimg/tb_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem": "用逐层分类的方法，把下面的 16 个图形分一分、数一数。图中有：三角形 6 个、圆 2 个、正方形 3 个、梯形 3 个、长方形 2 个（其中部分为深色、部分为浅色）。", "options": null}', '第一层按形状分：三角形 6 个、圆 2 个、正方形 3 个、梯形 3 个、长方形 2 个。第二层按颜色分：深色三角形 3 个、浅色三角形 3 个；其余同理按深浅再分。', '逐层分类先分形状大类，再在每个形状里按颜色深浅分小类。共 6+2+3+3+2=16 个，逐类核对不重不漏。', 'paper', '[]', '["/static/qimg/tb_p59.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "找规律填数：(1) 3、8、13、18、___、___、___。(2) 80、71、62、53、___、___、___。", "options": null}', '(1) 后一个数比前一个数大 5：23、28、33。(2) 后一个数比前一个数小 9：44、35、26。', '(1) 8-3=5、13-8=5、18-13=5，公差为 5，依次 +5 得 23、28、33。(2) 71-80=-9、62-71=-9、53-62=-9，公差为 -9，依次 -9 得 44、35、26。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem": "找规律填数：(1) 42、___、___、24、18、___、6。(2) 1、2、4、7、11、___、___、29。", "options": null}', '(1) 相邻两项相差 6：42、36、30、24、18、12、6，填 36、30、12。(2) 相邻差依次 +1、+2、+3、+4、+5、+6、+7：1、2、4、7、11、16、22、29，填 16、22。', '(1) 从 42 到 6 每次减 6，是 6 的倍数递减数列。(2) 差值依次递增：2-1=1、4-2=2、7-4=3、11-7=4，下一个差 5 得 16，再差 6 得 22，再差 7 得 29。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "根据规律填一填：(1) 12-3 = 13-___ = 14-___ = 15-___。(2) 18-9 = ___-8 = ___-7 = ___-___。", "options": null}', '(1) 等式左边都是 9：13-4=9、14-5=9、15-6=9，填 4、5、6。(2) 18-9=9，需 ___-8=9、___-7=9、___-___=9，填 17、16、15、6（15-6=9）。', '等号左右两边结果相等。(1) 12-3=9，故 13-?=9、14-?=9、15-?=9，分别填 4、5、6。(2) 18-9=9，被减数依次 -1、-1，减数也依次 -1 保持差不变：17-8=9、16-7=9、15-6=9。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "根据第一个「数墙」的规律（上面一格等于下面两格之和），把后面两个「数墙」填完整。数墙一：底层 25、13、19，上层 38、32，顶层 70。数墙二：底层 26、___、___，上层 45、___，顶层 93。数墙三：底层 18、25、___，上层 ___、41，顶层 ___。", "options": null}', '数墙二：26+19=45，故底层第二格 19；45+48=93，上层第二格 48，底层第三格 48-19=29。即底层 26、19、29，上层 45、48，顶层 93。数墙三：25+16=41，故底层第三格 16；18+25=43，上层第一格 43；43+41=84，顶层 84。即底层 18、25、16，上层 43、41，顶层 84。', '数墙规律：上面一格 = 下面相邻两格之和。数墙二：26+a=45 得 a=19；a+b=45+48 的中间数，顶层 45+(19+b)=93 得 b=29。数墙三：25+b=41 得 b=16；18+25=43；43+41=84。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "从 2、5、6、8、10、12、15、18、20、24、30、40 中选出 4 个组成一组有规律的数，写出 4 组。", "options": null}', '① 5、10、15、20（相邻差 5）；② 6、12、18、24（相邻差 6）；③ 10、20、30、40（相邻差 10）；④ 2、8、14、20（相邻差 6，从 2 起）。答案不唯一。', '从一组数中找规律常见思路：等差数列（相邻差相等）或公倍数。如 5、10、15、20 是 5 的倍数，6、12、18、24 是 6 的倍数，10、20、30、40 是 10 的倍数。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "在○内填数，使横行、竖列、斜行上三个数的和都是 18。已给：第一行中间是 10、第一行右边是 5，中心是 6，其余 6 个○待填。", "options": null}', '第一行左边：3；第二行左边：8；第二行右边：4；第三行左边：7、中间：2、右边：9。完整幻方：第一行 3、10、5；第二行 8、6、4；第三行 7、2、9。', '每行、每列、每条对角线之和都等于 18。先由对角线 5+6+第三行左边=18 得 7；由对角线 第一行左边+6+第三行右边=18，结合第一行左边+10+5=18 得第一行左边=3、第三行右边=9；再由列、行依次推出其余各数。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "在空格中填数，使横行、竖列、斜行上三个数的和都相等。已给：第一行右边 29、中心 28、第三行左边 27、第三行中间 39。", "options": null}', '幻和 = 29+28+27 = 84。第一行左边 38、第一行中间 17、第一行右边 29；第二行左边 19、中心 28、第二行右边 37；第三行左边 27、第三行中间 39、第三行右边 18。', '先由对角线 29+28+27=84 求出幻和。再由第三行 27+39+第三行右边=84 得 18；由另一对角线 第一行左边+28+18=84 得 38；由第一列 38+第二行左边+27=84 得 19；再依次推出其余各数。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "把 1~9 填入下面 3×3 的表格中，使横行、竖列、斜行上三个数的和都是 15。已给：左上角是 4、右下角是 6。", "options": null}', '第一行 4、9、2；第二行 3、5、7；第三行 8、1、6。校验：4+9+2=15、3+5+7=15、8+1+6=15；4+3+8=15、9+5+1=15、2+7+6=15；4+5+6=15、2+5+8=15。', '1~9 总和 45，三行三列平均幻和 15。中心 5 所在的行、列、两条对角线共 4 条线，故 5 必在中心。已给左上角 4、右下角 6，正好与经典三阶幻方吻合，按标准幻方填充即可。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
