INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "照样子，读读选选填序号。\n例：__在__上飞。（①地 ②天 ③我）\n(1)__在__上跑。\n(2)他和__是__。", "options": null}', '例:②天; (1)①地; (2)⑤我【存疑】', '【存疑】据语义推导：鸟在天上飞、马在地上跑、他和我，OCR 序号与题面略有噪点，答案供参考需核对原书', 'paper', '["填空"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "选字填空（填序号）。\n①天 ②地 ③人 ④你 ⑤我 ⑥他\n(1)__，合称「三才」。\n(2)我先告诉__，你再转告__。", "options": null}', '(1)【存疑】 (2)④你，⑥他', '【存疑】(1)「天、地、人合称三才」单空填法待核原书；(2)我先告诉你，你再转告他，推导④⑤⑥', 'paper', '["填空"]', NULL, 0);
