INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "填字词，读诗歌。\n一二三四__，金木水火__。\n天地分__，日月照__。", "options": null}', '五；土；上下；今古', '课文《金木水火土》：一二三四五，金木水火土。天地分上下，日月照今古。', 'paper', '["填空"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "选字填空（填序号）。\n①三 ②二 ③一\n一生__，二生__，三生万物。", "options": null}', '②二；①三【存疑】', '【存疑】据「一生二，二生三，三生万物」推导；序号①三②二③一，故一生②二、二生①三。具体填法以原书为准', 'paper', '["填空"]', NULL, 0);
