INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红', 1, '{"stem": "基础小擂台 ② 描一描，写一写，填一填：描第二笔（田字格内汉字）【图意待补】", "options": null}', '【图意待补】', '描红题，田字格内汉字需人工核对。', 'paper', '["描红","图意待补"]', '["/static/qimg/ykl_pt_yw_p009.jpg"]', 0);
