INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ③ 读读连连填填：我们用__吃东西，用__听歌曲，用__看书，用__写作业，用__踢毽子。", "options": null}', '口；耳；目（眼）；手；足（脚）', '身体器官功能对应：口—吃，耳—听，目—看，手—写，足—踢毽子。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字填空', 2, '{"stem": "拓展新空间 ④ 我会圈：选正确字填空。（站 坐）如松，（座 坐）如钟，（行 仃）如风，（躺 卧）如弓。", "options": null}', '站如松，坐如钟，行如风，卧如弓', '体态歌诀：站如松，坐如钟，行如风，卧如弓。', 'paper', '["选字填空","课文"]', NULL, 0);
