INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红', 1, '{"stem": "基础小擂台 描一描，写一写，填一填：描第四笔、描第五笔（禾），描第二笔（火）【图意待补】", "options": null}', '【图意待补】', '描红题，田字格内汉字及笔画位置需人工核对。', 'paper', '["描红","图意待补"]', '["/static/qimg/ykl_pt_yw_p012.jpg"]', 0);
