INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "拓展新空间 ④ 读儿歌猜字，口头填空：画就是__，__像田里，__像天上，__像一张，__像林间。【OCR残损，存疑】", "options": null}', '【存疑，待核原文】', '儿歌猜字题，原文被 OCR 残损，需人工核对原书。', 'paper', '["填空","存疑"]', '["/static/qimg/ykl_pt_yw_p012.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地一·第一站：邵雍《数字诗》「一去二三里，烟村四五家。亭台六七座，八九十枝花。」这首诗中有哪些表示数字的字？请写在田字格里。", "options": null}', '一、二、三、四、五、六、七、八、九、十', '诗中包含的数字字：一、二、三、四、五、六、七、八、九、十。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 1, '{"stem": "语文园地一·第二站：照样子，把能组成词语的字连一连/圈一圈（例：今+天=今天）【图意待补】", "options": null}', '【图意待补】', '汉字组词连线/圈一圈活动，图中字组需人工核对。', 'paper', '["连线","图意待补"]', '["/static/qimg/ykl_pt_yw_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '操作', 1, '{"stem": "语文园地一·第三站：请你照着图，试着用火柴棒拼出「天」字。【图意待补】", "options": null}', '【图意待补】', '动手拼字活动，图中火柴棒摆法需人工核对。', 'paper', '["操作","图意待补"]', '["/static/qimg/ykl_pt_yw_p016.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '认读', 1, '{"stem": "语文园地一·第四站：请圈出《五宝歌》里你认识的字，再读一读。【图意待补】", "options": null}', '【图意待补】', '圈字认读活动，圈哪些字由学生自选，需人工核对。', 'paper', '["认读","图意待补"]', '["/static/qimg/ykl_pt_yw_p017.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地一·第三站：你还能用火柴棒拼出别的字吗？我用__根火柴棒拼出了__字。", "options": null}', '【开放题，答案不唯一】', '开放操作题，学生用火柴棒自由拼字，答案不唯一。', 'paper', '["填空","开放题"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地一·第四站：《五宝歌》「手足耳目口……用脑又用手。」「五宝」是哪五宝？把答案用「—」画出来。", "options": null}', '手、足、耳、目、口', '五宝歌点明五宝为：手、足、耳、目、口。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地一·第五站：《咏鹅》填空：鹅，鹅，鹅，曲项向__歌。__浮__水，__拨__波。", "options": null}', '天；白毛、绿；红掌、清', '原诗：鹅鹅鹅，曲项向天歌。白毛浮绿水，红掌拨清波。填空依次为：天／白毛、绿／红掌、清。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地一·第五站：《咏鹅》这首诗是唐代大诗人__写的。", "options": null}', '骆宾王', '《咏鹅》作者为初唐诗人骆宾王（相传作于七岁）。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ⑤ 选一选，填一填：（1）__，花朵真美！（2）妈妈__着肚子，把食物留给小鹅。", "options": null}', '（1）a（啊）；（2）ā（阿）【声调存疑，OCR 拼音声调有噪点】', '选韵母填空：表示赞叹用「啊(a)」，亲属称谓「阿(ā)妈」。', 'paper', '["填空","拼音","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌《大公鸡和大白鹅》，圈出韵母是单韵母 a、o、e 的字。儿歌：大公鸡，喔喔啼，大白鹅，咕咕叫。阿姨养鸡又养鹅。", "options": null}', '大(dà·a)、和(hé·e)、鹅(é·e)、喔(wō·o)、阿(ā·a)、鹅(é·e)', '韵母为单韵母 a/o/e 的字：大、和、鹅、喔、阿、鹅。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ④ 选一选，填一填：（1）要下__了，（2）天空__的云黑沉沉的，小__游到水面上来了。", "options": null}', '（1）雨(yǔ)；（2）乌(wū)；（3）鱼(yú)【声调存疑，OCR 拼音声调有噪点】', '选韵母填空：下雨(yǔ)、乌(wū)云、小鱼(yú)。', 'paper', '["填空","拼音","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑤ 跟家长一起读句子，圈出韵母是单韵母 i、u、ü 的字。（1）我和弟弟看着地图，讨论暑假去哪儿旅游。（2）森林里住着许多大大小小的动物，有白兔、毛驴、老虎、狐狸……", "options": null}', '（1）我(o)和(e)弟(i)弟(i)着(e)地(i)图(u)暑(u)去(ü)旅(ü)；（2）里(i)住(u)着(e)许(ü)的(e)物(u)兔(u)驴(ü)虎(u)狐(u)狸(i)', '韵母为单韵母 i/u/ü 的字：句(1)我和弟弟着地图暑去旅；句(2)里住着许的物兔驴虎狐狸。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ④ 连一连，再看图选一选（填序号）：音节 ①mī ②fó ③bà ④pō，与图片（米/佛/爸/坡）对应填序号。【图意待补】", "options": null}', '【图意待补】', '看图选音节连线题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p025.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌《伯伯和婆婆》，圈出声母是 b、p、m、f 的字。儿歌：伯伯和婆婆，马伯伯，变魔术，变出一尊小金佛。马婆婆，拔萝卜，拔出一个大萝卜。", "options": null}', '伯、伯、婆、婆、马、伯、伯、变、魔、佛、马、婆、婆、拔、卜、拔、卜', '声母为 b/p/m/f 的字：伯(b)伯(b)婆(p)婆(p)马(m)伯(b)伯(b)变(b)魔(m)佛(f)马(m)婆(p)婆(p)拔(b)卜(b)拔(b)卜(b)。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ③ 看图、读音节，用线连一连：bà ba / tù tu / dì di / lā la 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p028.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ④ 按要求写一写，再看图选一选（填序号）：音节 dǎ / tù / nù / lā，与图片（打/兔/怒/拉）对应填序号。【图意待补】", "options": null}', '【图意待补】', '看图选音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p028.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑤ 跟家长一起读儿歌《白石塔》，圈出声母是 d、t、l 的字。儿歌：白石塔，白石搭。白石搭白塔，白塔白石搭。搭好白石塔，白塔白又大。", "options": null}', '搭(d)、塔(t)、大(d)（注：原题为圈 d、l，诗中无 l 声母字，含 t 声母的「塔」亦在图画/题面内，按题面声母 d、t、l 圈出）', '声母为 d/t/l 的字：搭(d)塔(t)搭(d)塔(t)搭(d)塔(t)搭(d)大(d)塔(t)塔(t)。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '排序', 2, '{"stem": "语文园地二·第一关：这个单元学了六个单韵母 a、o、e、i、u、ü。请读一读，比一比，按发音时口形由大到小的顺序，把 6 块单韵母卵石串起来。", "options": null}', 'a、o、e、u、ü、i（a 开口最大，i 开口最小；u、ü 介于 e 与 i 之间）', '按发音口形由大到小排列：a > o > e > u/ü > i。', 'paper', '["排序","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图找声母', 1, '{"stem": "语文园地二·第二关：我发现下面的图里藏了我们学过的声母 b！你能找出更多的声母吗？把它们写下来。【图意待补】", "options": null}', '【图意待补】', '看图找声母题，图中隐藏的声母需人工核对。', 'paper', '["看图找声母","图意待补"]', '["/static/qimg/ykl_pt_yw_p031.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '找声母组合', 2, '{"stem": "语文园地二·第二关：照样子，按声母表顺序找出「b、p、m、f」或「d、n、t、l」的组合。【图意待补】", "options": null}', '【图意待补】', '声母组合连线/圈出题，图意需人工核对。', 'paper', '["找声母组合","图意待补"]', '["/static/qimg/ykl_pt_yw_p031.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "语文园地二·第三关：请按要求给下面的拼音标注声调，再看图选一选（填序号）：音节 lā / bá / bǔ / lú 与图片（车/豆/鱼）对应填序号。【图意待补】", "options": null}', '【图意待补】', '看图选音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p032.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地二·第四关：认识拼音本，请把相关信息填到对应的格子里（填序号）。信息：①学号 ②学校 ③姓名 ④班级；已知：一（2）班、红识小学、钟国仁、10。", "options": null}', '学号→10；学校→红识小学；姓名→钟国仁；班级→一（2）班', '拼音本栏目对应：学号填 10，学校填红识小学，姓名填钟国仁，班级填一（2）班。', 'paper', '["填空","生活"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '认读', 1, '{"stem": "语文园地二·第五关：跟家长读儿歌《秋天到》，再圈出你认识的字读一读。【图意待补】", "options": null}', '【图意待补】', '圈字认读活动，圈哪些字由学生自选，需人工核对。', 'paper', '["认读","图意待补"]', '["/static/qimg/ykl_pt_yw_p033.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地二·第六关：日积月累，背诵《画》并填空：远看__，近听__。__花还在，__鸟不惊。", "options": null}', '远看山有色，近听水无声。春去花还在，人来鸟不惊。填空：山有色／水无声／春去／人来', '《画》：远看山有色，近听水无声。春去花还在，人来鸟不惊。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ④ 看图，读音节，用线连一连，再选词填空：音节 luó bo / huā huā / guǒ guo / huā duǒ 与图画、词语对应。【图意待补】", "options": null}', '【图意待补】', '看图连音节+选词填空题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p035.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 选词填空：（1）公园里，美丽的__竞相开放。（2）夏天到了，__在草丛里叫。（3）广场上，人们敲锣__，热闹极了。【词库未全显，按语境填】", "options": null}', '（1）花朵；（2）知了（或蛐蛐）；（3）打鼓【存疑：原词库未完整OCR到，按语境推导】', '结合语境：花开、虫鸣、敲锣打鼓为常见搭配。', 'paper', '["填空","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌《华华和爸爸》，圈出拼音是三拼音节的字。儿歌：华华和爸爸，华华爱画画，画的是爸爸，爸爸爱花朵，也爱华华画的画。", "options": null}', '华(huá)、画(huà)、朵(duǒ)（均含介母 u，为三拼音节）', '三拼音节=声母+介母+韵母；华huá、画huà、朵duǒ 含介母 u。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ④ 看图，读音节，用线连一连：qí mǎ / jiá kè / xià qí / dā jī mù 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p038.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ④ 选词填空（接上题词库 qí mǎ/jiá kè/xià qí/dā jī mù）：（1）我穿上这件__，真帅气！（2）我最喜欢__，每周都上围棋课。", "options": null}', '（1）夹克(jiá kè)；（2）下棋(xià qí)', '穿上的是夹克，围棋课对应下棋。', 'paper', '["填空","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ⑤ 看图，读音节，在正确的音节后打「√」：jú huā/xiā mǐ/luò tuo/xià mǐ… 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图选正确音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p039.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌《稀奇》，圈出声母是 j、q、x 的字。儿歌：稀奇稀奇真稀奇，大公鸡呀当马骑，弟弟手拿小红旗，骑到东来骑到西。", "options": null}', '稀(x)奇(q)稀(x)奇(q)稀(x)奇(q)鸡(j)骑(q)小(x)旗(q)骑(q)骑(q)西(x)', '声母为 j/q/x 的字：稀、奇、鸡、骑、小、旗、西。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ④ 看图，读音节，用线连一连：zì mǔ / sī jī / dā jī mù… 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p041.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ④ 选词填空（接上题词库 zì mǔ/sī jī…）：（1）我爸爸是一名公交车__。（2）英语一共有26个__。", "options": null}', '（1）司机(sī jī)；（2）字母(zì mǔ)', '公交车司机、26个字母。', 'paper', '["填空","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 读读绕口令，圈出声母是平舌音（z、c、s）的字。绕口令：一个枣，两个枣，三个枣……十个枣；十个枣……一个枣。", "options": null}', '枣(zǎo)（绕口令中仅「枣」为平舌音 z，其余「个」等为非平舌音）', '平舌音 z/c/s；本绕口令里只有「枣」(zǎo) 是平舌音。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ④ 照样子，将图片与对应的音节、汉字连起来：cā zhuō zi / zhé zhǐ / zhuō zi / 擦桌子 / 折纸 / 桌子。【图意待补】", "options": null}', '【图意待补】', '看图连音节+汉字题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p044.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 读读绕口令，圈出声母是翘舌音（zh、ch、sh、r）的字。绕口令：天上有个日头，地下有块石头，嘴里有条舌头，手上有五根手指头。", "options": null}', '上(sh)、日(r)、石(sh)、舌(sh)、手(sh)、手(sh)、指(zh)（注：「嘴」zuǐ 为平舌音 z，不圈）', '翘舌音 zh/ch/sh/r：上、日、石、舌、手、指。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "基础小擂台 ④ 读拼音，圈出整体认读音节：ya yi / yyi / wu ya。", "options": null}', 'yi（整体认读）、wu（整体认读）；ya、yyi、ya 不是整体认读音节', '整体认读音节 yi、wu、yu；ya=y+a 为两拼音节，不是整体认读。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "基础小擂台 ⑤ 选一选，填一填（ya / wa）：（1）过年可以拿__岁钱！（2）福__在学__。【词库 ya/wa，原句未全显】", "options": null}', '（1）ya（压，压岁钱）；（2）wa（娃，福娃）【存疑：原句后段未完整OCR到】', '压岁钱用 ya（压），福娃用 wa（娃）。', 'paper', '["填空","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌，圈出拼音是整体认读音节（yi、wu、yu）的字。儿歌：一个太阳空中挂，两只乌龟地上爬，三条小鱼水里游，四个娃娃做游戏。", "options": null}', '一(yī)、乌(wū)、鱼(yú)、娃(wá)、娃(wá)', '整体认读 yi/wu/yu：一、乌、鱼、娃。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈声母', 2, '{"stem": "语文园地三·第一关：拼音宫。照样子，按声母表顺序依次圈出所有声母。字母网格：b p m f e d y i a t n s q k h u w s c h zh ch sh w s。", "options": null}', '圈声母：b、p、m、f、d、t、n、s、q、k、h、w、s、c、zh、ch、sh（不圈 e、y、i、a、u 等韵母）', '声母为 bpmfdtnl gkh jqx zh ch sh r zcs yw；网格中 e/y/i/a/u 是韵母不圈。', 'paper', '["圈声母","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "语文园地三·第二关：看图，圈出正确的音节：shé/shī、hā/huā、q/j、tī/rì 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图圈正确音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p050.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "语文园地三·第二关：读一读音节词，给同类的事物涂上相同的颜色。词表：tù zi、bō luó、luò tuo、zì、mǎ yǐ、shī zi、yā lí、wū yā、jú zi、shī zi。", "options": null}', '动物：兔子、骆驼、蚂蚁、狮子、乌鸦；水果：菠萝、鸭梨、橘子；「字」单独（文具/其他）', '按事物类别分组涂色：动物一类、水果一类。', 'paper', '["分类","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地三·第二关汉字宫：把可以搭配的字用线连起来。左：积、汉、扫、句、乌；右：地、语、木、字、棋。", "options": null}', '积—木（积木）、汉—语（汉语）、扫—地（扫地）、句—子（句子）；乌—？（应为「乌鸦」，原图选项待核）【存疑】', '可搭配组词：积木、汉语、扫地、句子。', 'paper', '["连线","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地三·第三关词语宫：把下列词语补充完整。独（ ）无（ ）；（ ）模（ ）样；（ ）颜（ ）色；（ ）头（ ）臂。", "options": null}', '独（一）无（二）；一（模）一（样）；五（颜）六（色）；三（头）六（臂）', '常见四字词语：独一无法、一模一样、五颜六色、三头六臂。', 'paper', '["填空","词语"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ③ 看图，读音节，圈出正确的音节：dài/péi/māi、zuǐ/cǎi/sāi 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图圈正确音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p054.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 看图，读音节，用线连一连：hǎi guī / tái qiú / shuǐ bēi / kāi huì 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p054.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选读音', 1, '{"stem": "基础小擂台 ⑤ 读绘本封面，圈出本课生字，并用「√」选出正确读音：bái cài / bèi cuì… 与图画（白菜）对应。【图意待补】", "options": null}', '【图意待补】', '看图选正确读音题，绘本封面图意需人工核对。', 'paper', '["看图选读音","图意待补"]', '["/static/qimg/ykl_pt_yw_p054.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌，圈出韵母是 ai、ei、ui 的字。儿歌：如果时光倒流，开放的玫瑰变回种子；和蔼的老师变回学生；白发的奶奶变回妈妈；我也会躲回妈妈的肚子。", "options": null}', '倒(dào)、开(kāi)、玫(méi)、瑰(guī)、回(huí)、蔼(ǎi)、白(bái)、奶(nǎi)、奶(nǎi)、会(huì)等（含 ai/ei/ui 韵母的字）', 'ai/ei/ui 韵母：倒、开、玫、瑰、回、蔼、白、奶、会。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ② 看图，读音节，用线连一连：niǎo / hóu / gǒu 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p056.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ③ 看图，读音节，在正确的音节后打「√」：hǎi ōu fēi / yú er yóu / yú er ròu… 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图选正确音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p057.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图识字', 1, '{"stem": "基础小擂台 看图，读音节，学汉字：小鸟、太阳、白云、柳树、流水、荷花、石桥、小河、围巾、手套 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图识字题，图画内容需人工核对。', 'paper', '["看图识字","图意待补"]', '["/static/qimg/ykl_pt_yw_p057.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌，圈出韵母中有 ao、ou、iu 的字。儿歌：冬天，北风吹，雪花飘，寒冷冬天已来到。戴皮帽，穿皮袄，狗熊背着兔子跑。戴口罩，穿棉袄，小猴骑着老牛跳。", "options": null}', '吹(chuī)、飘(piāo)、到(dào)、帽(mào)、袄(ǎo)、狗(gǒu)、跑(pǎo)、口(kǒu)、罩(zhào)、小(xiǎo)、猴(hóu)、老(lǎo)、牛(niú)、跳(tiào)等（含 ao/ou/iu 韵母的字）', 'ao/ou/iu 韵母：吹、飘、到、帽、袄、狗、跑、口、罩、小、猴、老、牛、跳。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选正确音节', 2, '{"stem": "基础小擂台 ③ 读词语，在正确的音节后打「√」：梅子（méi zi / miè zi）、开会（kāi huì / kāi huǐ）、夜校（yè xiào / yè xiǎo）、白色（bái sè / dái cè）。", "options": null}', '梅子 méi zi；开会 kāi huì；夜校 yè xiào；白色 bái sè', '正确读音：méi zi、kāi huì、yè xiào、bái sè。', 'paper', '["选正确音节","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ⑤ 看图，读音节，用线连一连，再选词填空：xié zi / dà xuě / zuò yè… 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图连音节+选词填空题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p060.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌，圈出拼音是整体认读音节 ye、yue 的字，以及韵母是 er 的字。儿歌：一片绿叶，一支歌儿。一轮明月，一支歌儿。绿叶和明月，合唱一支悦耳的歌。", "options": null}', 'ye/yue 整体认读：叶(yè)、月(yuè)、悦(yuè)；er 韵母：儿(ér)、儿(ér)、儿(ér)、耳(ěr)', '整体认读 ye/yue：叶、月、悦；er 韵母：儿、耳。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连词', 1, '{"stem": "基础小擂台 ② 看图连一连：云朵、草原、树林、柳树 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连词题，图画内容需人工核对。', 'paper', '["看图连词","图意待补"]', '["/static/qimg/ykl_pt_yw_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图选音节', 1, '{"stem": "基础小擂台 ④ 看图，读音节，圈出正确的音节：sēn lín/sin len、tiān ān mén/tan qin、fán qún/tan qin 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图圈正确音节题，图画内容需人工核对。', 'paper', '["看图选音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑥ 跟家长一起读儿歌，圈出韵母是 un、ün 的字。儿歌：天上云，一层层，像骏马，像羊群，还像几个小娃娃，蹲着坐着在谈心。", "options": null}', '云(yún)、骏(jùn)、群(qún)、蹲(dūn)、心(xīn)（含 un/ün 韵母的字）', 'un/ün 韵母：云、骏、群、蹲、心。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "基础小擂台 ② 看图，读音节，用线连一连：xīn/jīng/jǐn/xīng、shù lín、shēng jiàng、yǐn liào、yīng wǔ、lǎo yīng、yín háng 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p066.jpg"]', 0);
