INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈字', 2, '{"stem": "拓展新空间 ⑤ 跟家长一起读儿歌，圈出韵母是 ing 的字。儿歌：小蜻蜓，山青，水清，天气晴，小蜻蜓呀忙不停。请你来，请他来，大家一起做事情。", "options": null}', '蜻(qīng)、蜓(tíng)、青(qīng)、清(qīng)、晴(qíng)、听(tīng)、请(qǐng)、请(qǐng)、情(qíng)', 'ing 韵母：蜻、蜓、青、清、晴、听、请、情。', 'paper', '["圈字","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连词', 1, '{"stem": "语文园地四·第二关：看图，读音节，连一连（为小动物找到正确名牌）：kǒng què、wō niú… 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连动物题，图画内容需人工核对。', 'paper', '["看图连词","图意待补"]', '["/static/qimg/ykl_pt_yw_p068.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "语文园地四·第三关：你认识这些蔬果吗？把蔬果卡片涂成绿色。词表：pú tao、píng guǒ、níng méng、xī hóng shì、táo zi、bō luó、huáng guā、xiāng jiāo、jīn sī hóu、dà xiàng、dà yàn、cháng jǐng lù、luò tuo、zhào xiàng jī。", "options": null}', '蔬果（涂绿）：葡萄、苹果、柠檬、西红柿、桃子、菠萝、黄瓜、香蕉；动物不涂：金丝猴、大象、大雁、长颈鹿、骆驼（照相机为物品）', '按蔬果/动物分类，蔬果涂绿色。', 'paper', '["分类","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '拼写音节', 2, '{"stem": "语文园地四·第四关：照样子写音节。例：b-ó→(bo)。（h-u-à→ ）、p-à→（ ）、i-üe→（ ）、g-u-ó→（ ）、z-u-ó→（ ）。", "options": null}', 'h-u-à→huà；p-à→pà；i-üe→yue（ü遇 y 去两点）；g-u-ó→guó；z-u-ó→zuó', '声母+韵母拼读；ü 与 y 相拼去两点。', 'paper', '["拼写音节","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图加声调', 1, '{"stem": "语文园地四·第五关：看图，给音节加上声调：cǎo méi、jú huā、qié、shí zhōng 与图画对应。【图意待补】", "options": null}', '【图意待补】', '看图加声调题，图画内容需人工核对。', 'paper', '["看图加声调","图意待补"]', '["/static/qimg/ykl_pt_yw_p070.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "语文园地四·第六关：文具归类。读一读，把文具放入文具盒（在横线上写序号）。①kè běn ②chǐ ③zhuàn bǐ dāo ④zuò yè běn ⑤xiàng pí ⑥qiān bǐ ⑦là bǐ ⑧shuǐ bēi。", "options": null}', '文具（放入文具盒）：①②③④⑤⑥⑦；⑧水杯不是文具，不放入', '文具包括课本、尺、转笔刀、作业本、橡皮、铅笔、蜡笔；水杯属生活用品。', 'paper', '["分类","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地四·第七关：借助拼音读儿歌《家》，完成练习。① 用线连一连：天空—？海洋—？森林—？平原—？ （家：白云的家/鱼儿的家/小鸟的家/我们的家）。", "options": null}', '天空—白云的家；海洋—鱼儿的家；森林—小鸟的家；平原—我们的家', '儿歌《家》：蓝蓝的天空是白云的家，深深的海洋是鱼儿的家，密密的森林是小鸟的家，绿绿的平原是我们的家。', 'paper', '["连线","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·秋天 基础小擂台：描一描，写一写，填一填（了、子、人、大 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选正确拼音', 2, '{"stem": "阅读课·秋天 ② 选出下列汉字的正确拼音（在叶片上打√）：秋（qu/qiū）、树（shù/sù）、叶（iè/yè）。", "options": null}', '秋 qiū；树 shù；叶 yè', '正确读音：秋 qiū、树 shù、叶 yè。', 'paper', '["选正确拼音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·秋天 ③ 填表：字「个、叶、树」的共几笔与部首。", "options": null}', '个：3笔，部首 人（或丿）；叶：5笔，部首 口；树：9笔，部首 木', '个(人+丨)3笔；叶(口+十)5笔；树(木+又+寸)9笔。', 'paper', '["填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·秋天 ④ 读词语，积累词语，再连一连：一片/一片片、一排/一排排、一群/一群群 与 花儿、叶子、大雁、座位 搭配。【原图连线局部存疑】", "options": null}', '一片片—叶子；一排排—大雁（或座位）；一群群—（大雁/座位，原图待核）【存疑】', '量词重叠搭配：一片片叶子；一排排/一群群配大雁或座位。', 'paper', '["连线","存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·秋天 ⑤ 把可以搭配的字用线连起来：树—？ （可组词）", "options": null}', '树—叶（树叶）', '树+叶=树叶。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·秋天 ⑦ 填空：大雁一会儿排成个“__”字，一会儿排成个“__”字。", "options": null}', '“人”字、“一”字', '大雁南飞排成「人」字形和「一」字形。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字', 2, '{"stem": "阅读课·秋天 拓展新空间 ⑧ 圈出合适的字：（1）秋天来了，天气（凉/热）了，树叶（绿/黄）了。（2）秋天的天空那么（红/蓝），那么（高/大）。（3）秋天里，一群大雁往南（飞/走）。", "options": null}', '（1）凉、黄；（2）蓝、高；（3）飞', '秋天特征：天气凉、树叶黄、天蓝且高、大雁往南飞。', 'paper', '["选字","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·江南 基础小擂台 ① 描一描，写一写，填一填（可、东、西 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p075.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选正确拼音', 2, '{"stem": "阅读课·江南 ② 圈出下列加点字的正确拼音：江南（jiāng nán / lán nán）、采莲（cǎi lián / chái lián）、莲花（lián / nián）、小鱼（xiǎo yú / yà yú）、江水（jiāng shuǐ / jiàn shuǐ）、西北（xī běi / xī bì）。", "options": null}', '江南 jiāng nán；采莲 cǎi lián；莲花 lián；小鱼 xiǎo yú；江水 jiāng shuǐ；西北 xī běi', '正确读音：江 jiāng、采 cǎi、莲 lián、鱼 yú、江 jiāng、北 běi。', 'paper', '["选正确拼音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·江南 ③ 填表：字「江、莲、西」的共几笔与偏旁（西还需填第3笔笔画）。", "options": null}', '江：6笔，偏旁 氵（三点水）；莲：10笔，偏旁 艹（草字头）；西：6笔，第3笔 横折', '江(氵+工)6笔；莲(艹+连)10笔；西 第3笔为横折。', 'paper', '["填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·江南 ⑥ 把可以搭配的字用线连起来：戏、车、采、打、东 分别与 间、花、球、西、文 搭配。", "options": null}', '戏—文（戏文）；车—间（车间）；采—花（采花）；打—球（打球）；东—西（东西）', '可组词：戏文、车间、采花、打球、东西。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词', 2, '{"stem": "阅读课·江南 拓展新空间 ⑦ 圈出合适的词：江南可（采莲/采摘），莲叶何（田田/口口），鱼戏莲叶（间/闪），鱼戏莲叶（东/乐），鱼戏莲叶（西/四），鱼戏莲叶（南/两），鱼戏莲叶（水/北）。", "options": null}', '采莲、田田、间、东、西、南、北（出自《江南》：江南可采莲，莲叶何田田，鱼戏莲叶间/东/西/南/北）', '《江南》原诗用词。', 'paper', '["选词","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·江南 拓展新空间 ⑧ 按方向将字填入括号，再完成练习：我知道，每天早晨，太阳从（东/南/西/北）方升起（用〇圈出正确答案）。", "options": null}', '东（太阳从东方升起）', '方位常识：太阳东升西落。', 'paper', '["填空","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·雪地里的小画家 基础小擂台 ① 描一描，写一写，填一填（几、牙、马、用、竹 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p078.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·雪地里的小画家 ④ 根据课文内容填空：雪地里，小鸡的脚印像__，小狗的脚印像__，小鸭的脚印像__，小马的脚印像__。", "options": null}', '小鸡的脚印像竹叶；小狗的脚印像梅花；小鸭的脚印像枫叶；小马的脚印像月牙', '《雪地里的小画家》：小鸡画竹叶，小狗画梅花，小鸭画枫叶，小马画月牙。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "阅读课·雪地里的小画家 ⑤（2）青蛙没有去画画，是因为（ ）。① 青蛙去癞蛤蟆家做客啦。② 他在洞里睡着啦。", "options": null}', '② 他在洞里睡着啦（青蛙冬眠）', '课文：青蛙为什么没参加？他在洞里睡着啦。', 'paper', '["选择","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·雪地里的小画家 ⑤（3）这群小画家画的画，就是他们的__。", "options": null}', '脚印（或足迹；小动物的脚印就是它们在雪地上的「画」）', '课文「几步就成一幅画」，脚印即画作。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·四季 基础小擂台 ① 描一描，写一写，填一填（天、小、四、是 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p081.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '补拼音', 2, '{"stem": "阅读课·四季 ② 把字的拼音补完整：皮（__í）、春（ch__n）、说（sh__ō）、青（q__ng）、夏（x__à）、尖（j__ān）。", "options": null}', '皮 pí；春 chūn；说 shuō；青 qīng；夏 xià；尖 jiān', '补全声母/韵母：p、ch、sh、q、x、j。', 'paper', '["补拼音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·四季 ③ 填表：字「说、夏」的共几笔与偏旁（部首）。", "options": null}', '说：9笔，部首 讠（言字旁）；夏：10笔，部首 夂（折文，或夏本身）', '说(讠+兑)9笔；夏(夂+目+攵)10笔。', 'paper', '["填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选正确读音', 2, '{"stem": "阅读课·四季 ⑤ 圈出加点字的正确读音：春回大地（dì / de），小草从地（dì / de）下探出头来，河水哗哗地（dì / de）流着。", "options": null}', '大地 dì；地下 dì；哗哗地 de（结构助词读轻声 de）', '「地」作名词读 dì，作助词读轻声 de。', 'paper', '["选正确读音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·四季 ⑥ 用线连一连：春天、夏天、秋天、冬天 分别与 草芽尖尖、荷叶圆圆、谷穗弯弯、雪花飘飘 搭配。", "options": null}', '春天—草芽尖尖；夏天—荷叶圆圆；秋天—谷穗弯弯；冬天—雪花飘飘', '《四季》：草芽尖尖（春）、荷叶圆圆（夏）、谷穗弯弯（秋）、雪人（冬，雪花飘飘）。', 'paper', '["连线","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·四季 拓展新空间 ⑦ 口头填空：草芽对小鸟说：「我是__天。」荷叶对青蛙说：「我是__天。」谷穗鞠着躬说：「我是__天。」雪人顽皮地说：「我就是__天。」", "options": null}', '春、夏、秋、冬', '《四季》原文：草芽(春)、荷叶(夏)、谷穗(秋)、雪人(冬)。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "语文园地五·拼音花园 ① 看图，读音节，连一连：zá shuā、kuāng chǎn、pú shàn、yóu piào 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p084.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '写反义词', 2, '{"stem": "语文园地五·字词句海滩 ④ 看图写反义词：夜—（ ）、大—（ ）、地—（ ）、女—（ ）。", "options": null}', '夜—日（或昼）；大—小；地—天；女—男', '反义词配对：昼夜、大小、天地、男女。', 'paper', '["写反义词","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地五·字词句海滩 ⑤ 用线连一连：圆圆的、尖尖的、弯弯的 分别与 雪花、荷叶、草芽、谷穗 搭配（另含偏旁连线，图意待补）。", "options": null}', '圆圆的—荷叶；尖尖的—草芽；弯弯的—谷穗（雪花配「飘飘」）', '叠词搭配：圆圆荷叶、尖尖草芽、弯弯谷穗（出自《四季》）。', 'paper', '["连线","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "语文园地五 ⑥ 口头填空（记诵课文）：（1）天气__了，树叶__了，一片片叶子从树上__下来。（2）江南可采莲，莲叶何__。", "options": null}', '（1）天气凉了，树叶黄了，一片片叶子从树上落下来；（2）莲叶何田田', '课文《秋天》《江南》原句。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地五·阅读城堡 ⑦ 用线连一连：春天、夏天、秋天、冬天 分别与 花儿、蝉儿、枫叶、雪花 的「笑/鸣叫/变红/飞舞」搭配。", "options": null}', '春天—花儿（笑/开放）；夏天—蝉儿（叫/鸣叫）；秋天—枫叶（红/变红）；冬天—雪花（飘/飞舞）', '《四季歌》：春天花儿笑，夏天蝉儿叫，秋天枫叶红，冬天雪花飘。', 'paper', '["连线","课文"]', NULL, 0);
