INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "识字·对韵歌 ④ 口头填空：云对__，雪对__，花对__，鸟对__。山清对__，柳绿对__。", "options": null}', '云对雨，雪对风，花对树，鸟对虫；山清对水秀，柳绿对桃红', '《对韵歌》原文。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '对对子', 2, '{"stem": "识字·对韵歌 拓展新空间 ⑤ 试着对对子（填序号）：天对__，日对__。上对__，今对__。白雪对__，天地对__。选项：①古 ②下 ③山水 ④月 ⑤地 ⑥红云。", "options": null}', '天对⑤地；日对④月；上对②下；今对①古；白雪对⑥红云；天地对③山水', '对韵常识：天—地、日—月、上—下、今—古、白—红、天地—山水。', 'paper', '["对对子","课文"]', NULL, 0);
