INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "识字·日月明 ② 按要求给汉字分类（写序号）：①正 ②森 ③金 ④众 ⑤尘 ⑥双。分为前鼻音、后鼻音两类。", "options": null}', '前鼻音（韵母收 -n）：③金、⑤尘；后鼻音（韵母收 -ng）：①正、②森、④众、⑥双', '前鼻音 -n：金 jīn、尘 chén；后鼻音 -ng：正 zhèng、森 sēn、众 zhòng、双 shuāng。', 'paper', '["分类","拼音"]', NULL, 0);
