INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "识字·小书包 ④ 把可以搭配的字用线连起来：皮、学、课、作 分别与 业、包、校、桌 搭配。", "options": null}', '皮—包（皮包）；学—校（学校）；课—桌（课桌）；作—业（作业）', '可组词：皮包、学校、课桌、作业。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '补充句子', 2, '{"stem": "识字·小书包 ⑥ 把句子补充完整（填序号）：（1）小书包里有__。①作业本 ②数学（2）我的书包里有各种各样的__用品。①学习 ②学校。", "options": null}', '（1）①作业本；（2）①学习（学习用品）', '小书包里装作业本；书包里有学习用品。', 'paper', '["补充句子","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '分类', 2, '{"stem": "识字·小书包 拓展新空间 ⑦ 把学习用品写在相应的圈中：①铅笔 ②课本 ③作业本 ④橡皮 ⑤笔袋 ⑥转笔刀，分「笔袋」「书包」两个圈。", "options": null}', '笔袋圈：①铅笔、④橡皮、⑤笔袋、⑥转笔刀；书包圈：②课本、③作业本、（笔袋也放入书包，故⑤在交集）', '笔袋内装铅笔/橡皮/转笔刀；书包内装课本/作业本/笔袋。', 'paper', '["分类","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '猜谜语', 2, '{"stem": "识字·小书包 拓展新空间 ⑧ 猜谜语：（1）小小身子细又长，身穿彩衣直肚肠，嘴巴尖尖会写算，只见短来不见长。谜底？（2）有厚也有薄，有长也有方，打开看一看，知识里面藏。谜底？（3）一间小小理发店，瘦长顾客进里面，只用身子转几圈，脑袋理得光又尖。谜底？", "options": null}', '（1）铅笔；（2）书（课本）；（3）转笔刀（卷笔刀）', '谜语谜底：铅笔、书、转笔刀。', 'paper', '["猜谜语","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "识字·升国旗 ① 描一描，写一写，填一填（五、立、正、风 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p094.jpg"]', 0);
