INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "识字·升国旗 口头填空：五星红旗，我们的__。国歌声中，徐徐__。迎风飘扬，多么__。向着国旗，我们立正。望着国旗，我们__。", "options": null}', '我们的国旗；徐徐升起；多么美丽；我们敬礼', '《升国旗》课文：五星红旗，我们的国旗。国歌声中，徐徐升起。迎风飘扬，多么美丽。向着国旗，我们立正；望着国旗，我们敬礼。', 'paper', '["填空","课文"]', NULL, 0);
