INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "语文园地六 ④ 选词填空（填序号）：①上午 ②昨晚 ③今年。（1）__我上小学啦！（2）__有一节数学课。（3）__我梦见自己在天上飞。", "options": null}', '（1）③今年；（2）①上午；（3）②昨晚', '时间词搭配：今年上小学、上午有数学课、昨晚做梦。', 'paper', '["选词填空","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地六 ⑤ 用线连一连（反义词与量词）：多—少、先—后、开—关、黑—白；一把—直尺、一头—水牛、一只—（鸟）、一片—树叶。", "options": null}', '反义词：多—少、先—后、开—关、黑—白；量词：一把—直尺、一头—水牛、一片—树叶（一只—鸟）', '反义词与量词搭配。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·小小的船 ① 描一描，写一写，填一填（月、儿、里、头、见 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p100.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '偏旁名称', 2, '{"stem": "阅读课·小小的船 ③ 描出下列字的偏旁，并选出它们的名称：闪（ ）、船（ ）、绿（ ）、国（ ）。选项：①舟字旁 ②绞丝旁 ③国字框 ④门字框。", "options": null}', '闪—④门字框；船—①舟字旁；绿—②绞丝旁；国—③国字框', '偏旁名称：闪(门字框)、船(舟字旁)、绿(绞丝旁)、国(国字框)。', 'paper', '["偏旁名称","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·小小的船 ⑤ 用线连一连，再看图照样子写一写：弯弯的、蓝蓝的、闪闪的 分别与 星星、月儿、天空 搭配。", "options": null}', '弯弯的—月儿；蓝蓝的—天空；闪闪的—星星', '《小小的船》叠词搭配：弯弯的月儿、蓝蓝的天空、闪闪的星星。', 'paper', '["连线","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·小小的船 拓展新空间 ⑥ 口头填空：__的月儿__的船，小小的船儿两头尖。我在小小的船里坐，只看见__的星星__的天。", "options": null}', '弯弯的月儿小小的船；闪闪的星星蓝蓝的天', '《小小的船》原文：弯弯的月儿小小的船……只看见闪闪的星星蓝蓝的天。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·影子 ① 描一描，写一写，填一填（在、左、右、我、好 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p103.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈正确拼音', 2, '{"stem": "阅读课·影子 ② 跳房子，圈出汉字的正确拼音：影、左、朋、常、前、黑、狗、右、它。", "options": null}', '影 yǐng；左 zuǒ；朋 péng；常 cháng；前 qián；黑 hēi；狗 gǒu；右 yòu；它 tā', '正确读音如上（注意 yǐng/zuǒ/qián/hēi 的声调与字母）。', 'paper', '["圈正确拼音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·影子 （1）根据课文内容填空：影子在__，影子常常__我，它是我的__。", "options": null}', '影子在（前/后/左/右）；影子常常跟着（或陪着）我；它是我的好朋友', '《影子》：影子在前/后/左/右，影子常常跟着我，它是我的好朋友。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·影子 （2）光来了，影来了。光在前，影在__。光在左，影在__。光没了，影__了。", "options": null}', '光在前，影在后；光在左，影在右；光没了，影没了', '光影关系：影与光方向相反；无光则无影。', 'paper', '["填空","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '画图题', 1, '{"stem": "阅读课·影子 小明去公园玩，请按提示在地图上画出他的游览路线图（入口→海狮馆→右拐小卖部→东南游乐区→左直走到南门）。【地图路线题，图意待补】", "options": null}', '【图意待补】', '地图路线题，地图需人工核对。', 'paper', '["画图题","图意待补"]', '["/static/qimg/ykl_pt_yw_p105.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·两件宝 描一描，写一写，填一填（工、叉、才、也、会 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p106.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字填空', 2, '{"stem": "阅读课·两件宝 ④ 选字填空（填序号）：①工 ②公。 （1）爸爸__作很忙，经常加班。（2）星期天，我到__园去玩。 ①有 ②又 ③友。（3）妈妈温柔__大方。（4）我__一个好朋__。", "options": null}', '（1）①工（工作）；（2）②公（公园）；（3）②又；（4）①有…③友（朋友）', '形近/同音字：工作/公园、又(连词)/有(动词)、朋友。', 'paper', '["选字填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·两件宝 拓展新空间 ⑤ 口头填空：人有两件宝，__和__。双手会__，大脑会__。用手不用脑，事情__。用脑不用手，啥也__。用手又用脑，才能有__。", "options": null}', '双手和大脑；双手会做工，大脑会思考；用手不用脑事情做不好；用脑不用手啥也做不好；用手又用脑才能有创造', '《两件宝》原文：人有两件宝，双手和大脑。双手会做工，大脑会思考……才能有创造。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "语文园地七·拼音花园 ① 看图，读音节，连一连：jī māo、qīng cài、jīn yú、qín chái 与对应图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连音节题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p108.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写词语', 2, '{"stem": "语文园地七·字词句海滩 ③ 看拼音写词语：zuǒ yòu、zhèng zài、bà ba、hǎo xīn。", "options": null}', 'zuǒ yòu→左右；zhèng zài→正在；bà ba→爸爸；hǎo xīn→好心', '看拼音写词语。', 'paper', '["看拼音写词语","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '偏旁', 2, '{"stem": "语文园地七 ④ 描出下列字的偏旁，再写一个有同样偏旁的字：好（ ）、秋（ ）、问（ ）。", "options": null}', '好—女字旁（如妈/妹）；秋—禾字旁（如和/种）；问—门字框（如间/闪）', '偏旁归类并举例。', 'paper', '["偏旁","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "语文园地七 ⑤ 按要求连一连（汉字结构）：影、它、好、熊、到 分为「上下结构」「左右结构」两类。", "options": null}', '左右结构：影、好、到；上下结构：它、熊', '字形结构：影(左右)、好(左右)、到(左右)；它(上下)、熊(上下)。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "语文园地七 ⑥ 选词填空（填序号）：①哥哥 ②姐姐 ③弟弟 ④叔叔 ⑤爷爷。（1）我的__上幼儿园了。（2）我的__和__都是中学生。（3）我的__是老画家。（4）我的__是诗人。", "options": null}', '（1）③弟弟；（2）①哥哥、②姐姐；（3）⑤爷爷；（4）④叔叔', '亲属称谓：弟弟上幼儿园、哥哥姐姐中学生、爷爷老画家、叔叔诗人。', 'paper', '["选词填空","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连词成句', 2, '{"stem": "语文园地七 ⑧ 连词成句（写序号）：（1）①月 ②小船 ③像 → __（2）①我们 ②动脑 ③多 ④要 → __。", "options": null}', '（1）①③②（月像小船）；（2）①④③②（我们要多动脑）', '连词成句：月像小船；我们要多动脑。', 'paper', '["连词成句","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·比尾巴 ① 描一描，写一写，填一填（长、比、巴、公 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p112.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '加标点', 2, '{"stem": "阅读课·比尾巴 ④ 给句子加上标点符号（。 ？ ！）：（1）谁的个子高__（2）明明的个子高__（3）明明的个子真高啊__", "options": null}', '（1）？（2）。（3）！', '标点：疑问句用？，陈述句用。，感叹句用！。', 'paper', '["加标点","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·比尾巴 根据课文填空：谁的尾巴长？__的尾巴长。__的尾巴短。__尾巴好像一把伞。谁的尾巴弯？__的尾巴弯。__的尾巴扁。__的尾巴最好看。", "options": null}', '猴子尾巴长；兔子尾巴短；松鼠尾巴好像一把伞；公鸡尾巴弯；鸭子尾巴扁；孔雀尾巴最好看', '《比尾巴》原文：猴子的尾巴长，兔子的尾巴短，松鼠的尾巴好像一把伞；公鸡的尾巴弯，鸭子的尾巴扁，孔雀的尾巴最好看。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·乌鸦喝水 ① 描一描，写一写，填一填（个、只、石、多 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p116.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填表', 2, '{"stem": "阅读课·乌鸦喝水 ④ 填表：写出下列字的偏旁，并再写 3 个带这个偏旁的字：进（ ）、找（ ）、法（ ）。", "options": null}', '进—走之底（辶，如过、远、还）；找—提手旁（扌，如打、把、拍）；法—三点水（氵，如河、洗、没）', '偏旁归类：辶、扌、氵。', 'paper', '["填表","偏旁"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "阅读课·乌鸦喝水 ⑤ 把可以搭配的字用线连起来：乌、办、许 分别与 鸦、法、多 搭配。", "options": null}', '乌—鸦（乌鸦）；办—法（办法）；许—多（许多）', '可组词：乌鸦、办法、许多。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '描红笔顺', 1, '{"stem": "阅读课·雨点儿 ① 描一描，写一写，填一填（来、有、半、从、你 的笔顺描红）。【田字格描红，图意待补】", "options": null}', '【图意待补】', '田字格描红笔顺题，格子内容需人工核对。', 'paper', '["描红笔顺","图意待补"]', '["/static/qimg/ykl_pt_yw_p119.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '补拼音', 2, '{"stem": "阅读课·雨点儿 ② 把字的拼音补完整：数（sh__）、彩（c__i）、答（d__）、问（w__n）、久（j__ǔ）、更（g__ng）。", "options": null}', '数 shù；彩 cǎi；答 dá；问 wèn；久 jiǔ；更 gèng', '补全声母/韵母：sh、c、d、w、j、g + -u/-ai/-a/-en/-iu/-eng。', 'paper', '["补拼音","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写词语', 2, '{"stem": "阅读课·雨点儿 ③ 看拼音写词语：yǒu de、cóng lái、nǐ、hǎo、bàn tiān。", "options": null}', 'yǒu de→有的；cóng lái→从来；nǐ→你；hǎo→好；bàn tiān→半天', '看拼音写词语。', 'paper', '["看拼音写词语","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '偏旁名称', 2, '{"stem": "阅读课·雨点儿 ④ 描出下列字的偏旁，并选出它们的名称：没（ ）、家（ ）、空（ ）。选项：①穴字头 ②四点底 ③三点水 ④宝盖头。", "options": null}', '没—③三点水；家—④宝盖头；空—①穴字头', '偏旁名称：没(氵)、家(宀)、空(穴)。', 'paper', '["偏旁名称","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字填空', 2, '{"stem": "阅读课·雨点儿 选字填空：①问 ②闪。（1）有不懂的地方就要__。（2）夜晚，街上的霓虹灯一__，真好看。", "options": null}', '（1）①问；（2）②闪', '形近字：问(提问)、闪(闪烁)。', 'paper', '["选字填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "阅读课·雨点儿 选词填空（山、花、草、鸭、声、色、水、鸡）：有（ ）有（ ）、有（ ）有（ ）、有（ ）有（ ）、有（ ）有（ ）。", "options": null}', '有山有水、有花有草、有鸡有鸭、有声有色', '词语搭配：有山有水、有花有草、有鸡有鸭、有声有色。', 'paper', '["选词填空","词语"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "阅读课·雨点儿 选词填空（问 / 回答）：（1）大雨点儿__小雨点儿：「你要到哪里去？」（2）小雨点儿__：「我要去有花有草的地方。」", "options": null}', '（1）问；（2）回答', '对话中：提问用「问」，作答用「回答」。', 'paper', '["选词填空","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读课·雨点儿 学了课文，我知道是__使有花有草的地方更漂亮，使没有花没有草的地方长出红的花、绿的草。", "options": null}', '雨点儿', '《雨点儿》：雨点儿让花草生长、更繁茂。', 'paper', '["填空","课文"]', NULL, 0);
