INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写词语', 2, '{"stem": "语文园地八·字词句海滩 ③ 看拼音写词语：shí、tóu、zhǎng dà、lái、qù。", "options": null}', 'shí→石；tóu→头；zhǎng dà→长大；lái→来；qù→去', '看拼音写词语。', 'paper', '["看拼音写词语","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈不同类', 2, '{"stem": "语文园地八 ④ 圈出不是同一类的词：（1）学校、医院、工厂、老师（2）医生、老师、军队、军人（3）喝水、发芽、栽树、雪地。", "options": null}', '（1）老师（职业，其余是场所）；（2）军队（机构，其余是职业/身份）；（3）雪地（名词/自然物，其余是动作）', '分类：找出不同类的一项。', 'paper', '["圈不同类","分类"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "语文园地八 ⑤ 选词填空（填序号）：①大雁 ②青蛙 ③柳树 ④雪花。（1）春天来了，小河边的__发芽了。（2）夏天来了，池塘里的__呱呱叫。（3）秋天到了，一群__排着队往南飞。（4）冬天到了，大片大片的__从空中飘落下来。", "options": null}', '（1）③柳树；（2）②青蛙；（3）①大雁；（4）④雪花', '四季事物搭配：春柳、夏蛙、秋雁、冬雪。', 'paper', '["选词填空","常识"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连词成句', 2, '{"stem": "语文园地八 ⑥ 连词成句（写序号）：（1）①绿叶 ②长满了 ③树上 → __（2）①一片片 ②落下来 ③黄叶 ④树上 ⑤从 → __。", "options": null}', '（1）③②①（树上长满了绿叶）；（2）①③⑤④②（一片片黄叶从树上落下来）', '连词成句。', 'paper', '["连词成句","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '古诗连线', 2, '{"stem": "语文园地八·古诗天地 ⑦ 古诗《风》（［唐］李峤）连线：解落—、能开—、过江—、入竹—（选项：三秋叶、二月花、千尺浪、万竿斜）。", "options": null}', '解落—三秋叶；能开—二月花；过江—千尺浪；入竹—万竿斜', '李峤《风》：解落三秋叶，能开二月花。过江千尺浪，入竹万竿斜。', 'paper', '["古诗连线","古诗"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '填空', 2, '{"stem": "阅读城堡·贝壳 ⑨ 沙滩上的贝壳像__。（提示：像一只只小小的耳朵）", "options": null}', '小小的耳朵', '《贝壳》：亮晶晶的贝壳，像一只只小小的耳朵。', 'paper', '["填空","课文"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '拼音分类', 2, '{"stem": "期中自测 给拼音分类：ing、yin、wu、un。（1）声母：（2）韵母：（3）整体认读音节：", "options": null}', '（1）声母：无；（2）韵母：ing、un；（3）整体认读音节：yin、wu', 'ing、un 是韵母；yin、wu 是整体认读音节；本组无单独声母。', 'paper', '["拼音分类","拼音"]', NULL, 0);
