INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈正确词', 2, '{"stem": "期中自测 ⑤ 看拼音，圈出对应的词：bái zhǐ（白纸/百色）、qīng cài（清草/青菜）、xià qí（下棋/升旗）、shù xué（数学/手术）。", "options": null}', '白纸；青菜；下棋；数学', '正确词语：白纸、青菜、下棋、数学。', 'paper', '["圈正确词","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '补充句子', 1, '{"stem": "期中自测 ⑥ 看图，把句子补充完整：（1）明明在__（2）小朋友在__（3）嘉嘉喜欢__（4）__真美丽！【图意待补】", "options": null}', '【图意待补】', '看图补充句子题，图画内容需人工核对。', 'paper', '["补充句子","图意待补"]', '["/static/qimg/ykl_pt_yw_p128.jpg"]', 0);
