INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连线', 2, '{"stem": "期中自测 ⑧ 把可以搭配的字用线连起来：写、流、积、夜、学、白、山、开 分别与 字、水、木、晚、校、云、川、车 搭配。", "options": null}', '写—字；流—水；积—木；夜—晚；学—校；白—云；山—川；开—车', '可组词：写字、流水、积木、夜晚、学校、白云、山川、开车。', 'paper', '["连线","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '归类', 2, '{"stem": "期中自测 ⑨ 照样子归类，把字送回家（写序号）：①马 ②梅 ③鸭 ④柳 ⑤草 ⑥鱼 ⑦鸦 ⑧菜。分为「动物」和「植物」两类。", "options": null}', '动物：①马、③鸭、⑥鱼、⑦鸦；植物：②梅、④柳、⑤草、⑧菜', '按动物/植物归类。', 'paper', '["归类","分类"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选字填空', 2, '{"stem": "期中自测 10 选字填空（填序号）：①扫 ②打 ③行 ④站。（1）过马路要走人__道。（2）妈妈的爱好是__毛线。（3）地上有垃圾，请你把它__掉。（4）车上没有空座位了，他只能__着。", "options": null}', '（1）③行（人行道）；（2）②打（打毛线）；（3）①扫；（4）④站', '动宾/常用搭配：人行道、打毛线、扫掉、站着。', 'paper', '["选字填空","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连词成句', 2, '{"stem": "期中自测 11 连词成句（写序号）：（1）①我们 ②做游戏 ③在 ④操场上 → __（2）①学校 ②我们 ③的 ④漂亮 ⑤真 → __。", "options": null}', '（1）①③④②（我们在操场上做游戏）；（2）②①③⑤④（我们的学校真漂亮）', '连词成句。', 'paper', '["连词成句","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '涂色题', 1, '{"stem": "期中自测·阅读城堡 12 根据童谣内容，给下列物品涂色：冬瓜披白纱、茄子穿紫袍、白菜绿油油、辣椒又青又红。【涂色题，图意待补】", "options": null}', '【图意待补】', '涂色题，图画内容需人工核对。', 'paper', '["涂色题","图意待补"]', '["/static/qimg/ykl_pt_yw_p130.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选词填空', 2, '{"stem": "期中自测·阅读城堡 13 选一个合适的词语填在文中横线（填序号）：①庄稼 ②果子 ③蔬菜。「秋天到……地里__长得好」（冬瓜、茄子、白菜、辣椒）。", "options": null}', '③蔬菜', '文中列举冬瓜/茄子/白菜/辣椒均属蔬菜，故填③蔬菜。', 'paper', '["选词填空","词语"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图连音节', 1, '{"stem": "期末自测·外滩 ① 认一认有哪些交通方式，用线连一连：dì tiě、lún dù、gōng jiāo chē、chū zū chē 与对应交通工具图画相连。【图意待补】", "options": null}', '【图意待补】', '看图连交通方式题，图画内容需人工核对。', 'paper', '["看图连音节","图意待补"]', '["/static/qimg/ykl_pt_yw_p131.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '圈正确读音', 2, '{"stem": "期末自测·外滩 ⑥ 用「O」圈出加点字的正确读音：金（jīn/jīng）、一（yī/yi）年、一（yī/yi）件、土生土长（cháng/zhǎng）、细细地（de/dì）、长（cháng/zhǎng）廊。【声调标存疑】", "options": null}', '金 jīn；一 yì（年）；一 yí（件，声调变调）；长 cháng（长廊）；地 de；长 cháng（长廊）。注：「一」的声调依变调规则，OCR 声调可能有误，以教材为准。', '正确读音如上；「一」在第四声前变阳平（yí），在其它前变去声（yì）。', 'paper', '["圈正确读音","拼音","声调存疑"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看拼音写词语', 2, '{"stem": "期末自测·外滩 ⑦ 拼一拼，写一写：bái、gōng、pǔ、wài、bō（桥）、huáng pǔ（黄浦）、yuán（园）、tǎ（塔）、jīn róng（金融）、dōng（东）、zhōng xīn（中心）、dà zhōng（大钟）、míng zhū tǎ（明珠塔）。", "options": null}', '白、公、浦、外、波、黄浦、园、塔、金融、东、中心、钟、塔', '外滩景点相关看拼音写词。', 'paper', '["看拼音写词语","拼音"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '选择', 2, '{"stem": "期末自测·外滩 整理照片（选择题）：（1）这个景点是（①上海中入民英雄纪念答 ②上海市人民英雄纪念塔）。（2）「纪」的偏旁是（①绞丝旁 ②反犬旁）。（3）「英」遵循的笔顺规则是（①从左到右 ②从上到下），「雄」遵循的笔顺规则是（①从左到右 ②从上到下）。（4）「海」的偏旁是__，这个偏旁的字大多和__有关；「湍」的意思是（①水流得很急 ②火烧得很旺）。", "options": null}', '（1）②上海市人民英雄纪念塔；（2）①绞丝旁（纟）；（3）英②从上到下，雄①从左到右；（4）海—氵（三点水），大多和水有关；湍—①水流得很急', '偏旁与笔顺规则：纪(纟)、英(从上到下)、雄(从左到右)、海(氵,水)。', 'paper', '["选择","汉字"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '连词成句', 2, '{"stem": "期末自测·外滩 10 连词成句（写序号）：（1）①美 ②风景 ③外滩的 ④真！→ __（2）①我 ②还想 ③来 ④下次 → __（3）①一起去 ②能 ③陪我 ④吗 ⑤你 → __。", "options": null}', '（1）③②①④（外滩的风景真美！）；（2）④②③①（下次我还想来。）；（3）⑤②③①④（你能陪我一起去吗？）', '连词成句。', 'paper', '["连词成句","句子"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '数自然段', 2, '{"stem": "期末自测·阅读链接《湖》1 短文共有__个自然段。请标注出来。", "options": null}', '2 个自然段（第一自然段：白天……；第二自然段：夜晚……）', '按换行/空行划分自然段，本文写「白天」「夜晚」两段。', 'paper', '["数自然段","阅读"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读选择', 2, '{"stem": "期末自测·阅读链接《湖》12 选择：（1）白天的湖面映照着什么？（①垂柳、阳光、鲜花、花蝴蝶 ②垂柳、鲜花、蓝蜻蜓、花蝴蝶 ③垂柳、鲜花、小飞机、花蝴蝶）（2）夜晚的湖像什么？（①镜子 ②花蝴蝶 ③浴盆）", "options": null}', '（1）②（垂柳、鲜花、蓝蜻蜓、花蝴蝶）；（2）③（浴盆）', '原文：白天照着垂柳和阳光下开放的鲜花、蓝蜻蜓、花蝴蝶；夜晚变成浴盆。', 'paper', '["阅读选择","阅读"]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分类', 1, '{"stem": "我是小学生 1.在图中找一找，圈一圈：(1)~(3) 按要求在图中圈出指定物品。【看图题·图意待补】", "options": null}', '【图意待补】', '数学分类启蒙，需看图确定圈哪些物。', 'paper', '["分类","图意待补"]', '["/static/qimg/ykl_pt_sx_p003.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分类', 1, '{"stem": "1.我是小学生 2.把不同类的图圈出来。【看图题·图意待补】", "options": null}', '【图意待补】', '找出不同类的一项，需看图。', 'paper', '["分类","图意待补"]', '["/static/qimg/ykl_pt_sx_p004.jpg"]', 0);
