INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分类', 1, '{"stem": "1.2 玩一玩 1.分一分，圈一圈：(1)~(8) 把同类物品圈在一起。【看图题·图意待补】", "options": null}', '【图意待补】', '分类圈物，需看图确定分组。', 'paper', '["分类","图意待补"]', '["/static/qimg/ykl_pt_sx_p005.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '找规律', 2, '{"stem": "1.2 玩一玩 3.按规律穿珠子，圈出C的颜色：(1)(2)(3) 找出珠子排列规律并圈出色。【看图题·图意待补】", "options": null}', '【图意待补】', '找规律（颜色/位置），需看图。', 'paper', '["找规律","图意待补"]', '["/static/qimg/ykl_pt_sx_p006.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分类', 2, '{"stem": "1.2 玩一玩 4.按要求把小动物送到圈里：(1)画箭头把有4条腿的送到A圈、毛茸茸的送到B圈；(2)哪些动物既在A圈又在B圈？【看图题·图意待补】", "options": null}', '【图意待补】', '集合分类与交集，需看图。', 'paper', '["分类","图意待补"]', '["/static/qimg/ykl_pt_sx_p006.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '位置', 1, '{"stem": "位置 1.对的打√，错的打×：判断__在__的前面 / __在__的后面（等多组）。【看图题·图意待补】", "options": null}', '【图意待补】', '前后位置关系判断，需看图。', 'paper', '["位置","图意待补"]', '["/static/qimg/ykl_pt_sx_p007.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '位置', 1, '{"stem": "位置 2.看图，填「上」或「下」：__在__的（ ）面（等多组）。【看图题·图意待补】", "options": null}', '【图意待补】', '上下位置关系，需看图。', 'paper', '["位置","图意待补"]', '["/static/qimg/ykl_pt_sx_p008.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '位置', 1, '{"stem": "位置 3.按要求，画一画：在__的左边画○，在__的右边画△。【看图题·图意待补】", "options": null}', '【图意待补】', '左右位置与画图，需看图。', 'paper', '["位置","图意待补"]', '["/static/qimg/ykl_pt_sx_p008.jpg"]', 0);
