INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连线', 1, '{"stem": "单元练习1 1.找一找，连一连。【看图题·图意待补】", "options": null}', '【图意待补】', '看图连线，需看图。', 'paper', '["连线","图意待补"]', '["/static/qimg/ykl_pt_sx_p010.jpg"]', 0);
