INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分类', 2, '{"stem": "单元练习1 3.用不同的方法分一分：(1) 按不同标准给物品分类。【看图题·图意待补】", "options": null}', '【图意待补】', '多标准分类，需看图。', 'paper', '["分类","图意待补"]', '["/static/qimg/ykl_pt_sx_p010.jpg"]', 0);
