INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数数', 1, '{"stem": "3 小练习（1）1.看数画图（2/10/0/7/4各画对应数量）。2.数一数，记一记：(1)(2) 按类别统计数量。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p042.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数', 2, '{"stem": "3 小练习（2）3.在□里填数：(1)(2)。4.比一比，填一填。5.填一填，比一比。6.在下图标出4、7、2、9并从小到大排列。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p043.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数序', 2, '{"stem": "3 小练习（2）7.在下图标出比10小且比5大的数（6、7、8、9）。8.画一画（在0~10数轴上操作）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p044.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数数', 1, '{"stem": "3 小练习 1.找一找，连一连。2.数一数，连一连（数字6、七等）。3.分一分，圈一圈：(1)。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p045.jpg"]', 0);
