INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '序数', 2, '{"stem": "3 小练习 7.按事情发生先后顺序排一排。8.在图中填上合适的数（5）。9.看图填空：(1)从（ ）开始跳，每次跳（ ）格，最后跳到（ ）；(2)数轴填数。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p047.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '比大小', 2, '{"stem": "3 小练习 10.看图比多少：__比（ ）多2个；__比○少（ ）个；（ ）和（ ）同样多。11.在○里填＞＜=、□里填合适数：(1)5○7 (2)9○6 (3)4○4 (4)~(12)含□的比较填空（数字细节OCR不清）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p048.jpg"]', 0);
