INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.1 加法① 1.看图写加法算式（图示8个物品）。2.看图填一填：(1)(3)(4) 看图列加法算式。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p050.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.1 加法① 3.填一填（加法表）：加数 3/2/6/7/4，加数 5/8/0/1/4，求对应的和。", "options": null}', '和依次为：3+5=8，2+8=10，6+0=6，7+1=8，4+4=8。', '直接相加：3+5=8，2+8=10，6+0=6，7+1=8，4+4=8。', 'paper', '["加法","计算"]', '["/static/qimg/ykl_pt_sx_p051.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.1 加法① 4.算一算：(1)5+3=、2+4=、1+9=、7+2=；(2)6+4=、2+2=、3+3=。", "options": null}', '(1)5+3=8，2+4=6，1+9=10，7+2=9；(2)6+4=10，2+2=4，3+3=6。', '直接相加即可。', 'paper', '["加法","计算"]', '["/static/qimg/ykl_pt_sx_p051.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.1 加法① 6.写出和是5的加法算式（共5个空）。", "options": null}', '和为5的加法算式：0+5=5，1+4=5，2+3=5，3+2=5，4+1=5，5+0=5（写出其中5个即可）。', '两个加数之和为5的所有组合。', 'paper', '["加法","开放题"]', '["/static/qimg/ykl_pt_sx_p052.jpg"]', 0);
