INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.3 2.看算式画（ ），并计算：(1)+4=9 (2)2+□=7 (3)(4)6+1=7、3+5=8（画○并算）。3.根据要求列式计算：(1)~(4) 看图列算式。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p056.jpg"]', 0);
