INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.5 减法② 3.填空：5-□、4□、8-□、6-□、6-3、1□、9-□（图示填数）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p062.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.2 加法② 4.算一算：(1)6+2=、3+5=、4+4=、5+0=；(2)7+2=、7+1=、5+4=、2+6=；(3)3+2=、5+2=、0+10=、7+3=。", "options": null}', '(1)6+2=8，3+5=8，4+4=8，5+0=5；(2)7+2=9，7+1=8，5+4=9，2+6=8；(3)3+2=5，5+2=7，0+10=10，7+3=10。', '直接相加。', 'paper', '["加法","计算"]', '["/static/qimg/ykl_pt_sx_p054.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.3 看图列式 (5)：开走3辆，又开走了6辆，一共开走了多少辆？", "options": null}', '3+6=9（辆）。', '把两次开走的合起来用加法。', 'paper', '["加法","应用题"]', '["/static/qimg/ykl_pt_sx_p055.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.3 看图列式 (6)：吃掉4个，还剩2个，原来有几个？", "options": null}', '4+2=6（个）。', '剩下的加上吃掉的等于原来的。', 'paper', '["加法","应用题"]', '["/static/qimg/ykl_pt_sx_p055.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加法', 1, '{"stem": "4.3 算一算：(2)4+0=、3+7=、4+2=、□+4=9；(3)3+3=、5+2=、3+6=、□+7=7；(4)6+4=、3+4=、4+5=、8+□=10。", "options": null}', '(2)4+0=4，3+7=10，4+2=6，5+4=9；(3)3+3=6，5+2=7，3+6=9，0+7=7；(4)6+4=10，3+4=7，4+5=9，8+2=10。', '直接相加，方框填使等式成立的加数。', 'paper', '["加法","计算"]', '["/static/qimg/ykl_pt_sx_p057.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.4 减法① 1.看图列式计算 (1)：原来有6条鱼，吃掉2条，现在还剩下几条？", "options": null}', '6-2=4（条）。', '从总数里去掉吃掉的用减法。', 'paper', '["减法","应用题"]', '["/static/qimg/ykl_pt_sx_p058.jpg"]', 0);
