INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.4 减法① 4.填表：被减数 8/9/10/5、减数 2/1/4/3，求差（第5行OCR不全，仅列前4行）。", "options": null}', '8-2=6，9-1=8，10-4=6，5-3=2。', '被减数−减数=差。', 'paper', '["减法","计算"]', '["/static/qimg/ykl_pt_sx_p060.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.4 减法① 5.写出下列差是5的减法算式（共5个空）。", "options": null}', '差为5的减法算式：5-0=5，6-1=5，7-2=5，8-3=5，9-4=5，10-5=5（写出其中5个即可）。', '被减数比减数大5的所有组合。', 'paper', '["减法","开放题"]', '["/static/qimg/ykl_pt_sx_p060.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.5 减法② 2.看图列式计算（文字部分）：一共有7个水果，有4个，有几个？一共有10辆汽车，有6辆，有几辆？", "options": null}', '7-4=3（个）；10-6=4（辆）。', '总数减去已知部分等于另一部分。', 'paper', '["减法","应用题"]', '["/static/qimg/ykl_pt_sx_p061.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.5 减法② 4.算一算：(1)6-2=、5-3=、4-4=、5-0=；(2)7-6=、9-4=、6-3=、3-2=；(3)10-4=、7-3=。", "options": null}', '(1)6-2=4，5-3=2，4-4=0，5-0=5；(2)7-6=1，9-4=5，6-3=3，3-2=1；(3)10-4=6，7-3=4。', '直接相减。', 'paper', '["减法","计算"]', '["/static/qimg/ykl_pt_sx_p062.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.6 讲讲算算（2）1.看图列式计算（文字部分）：(a)原来有8个，拿走了3个，还剩下几个？(b)桌上有10个，小明吃掉了2个，桌上还有几个？(c)树上有6只，飞走了2只，树上还有几只？(d)停车场上有10辆，开走了7辆，现在还剩几辆？", "options": null}', '(a)8-3=5（个）；(b)10-2=8（个）；(c)6-2=4（只）；(d)10-7=3（辆）。', '总数减去去掉的部分等于剩下的。', 'paper', '["减法","应用题"]', '["/static/qimg/ykl_pt_sx_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "4.6 讲讲算算（2）(a)共有7副，其中___有5副，有几副？(b)公园里两种鸭子共有9只，其中___有4只，有几只？", "options": null}', '(a)7-5=2（副）；(b)9-4=5（只）。', '总数减去其中一部分等于另一部分。', 'paper', '["减法","应用题"]', '["/static/qimg/ykl_pt_sx_p064.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连加', 1, '{"stem": "4.9 连加连减① 4.看题列式计算：(1)草丛里有3只小鸭，河里有4只小鸭，岸边有2只小鸭，一共有几只小鸭？", "options": null}', '3+4+2=9（只）。', '把三部分合起来用连加。', 'paper', '["连加","应用题"]', '["/static/qimg/ykl_pt_sx_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连减', 1, '{"stem": "4.10 连加连减② 2.算一算：(1)7-2=、6-3=、8-4=；(2)5-1=、3-3=。", "options": null}', '(1)7-2=5，6-3=3，8-4=4；(2)5-1=4，3-3=0。', '按顺序连减。', 'paper', '["连减","计算"]', '["/static/qimg/ykl_pt_sx_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.6 讲讲算算（2）2.填一填（□-6、8-□=□、1□3、1-、10-、6=□、□-3=6、9- 等图示填数）。3.算一算：5+4= 等（图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p064.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.7 加与减 1.看图列式计算：(1)(2)(3) 含5+4=、4+3=、9-4=等（图示）。2.在□里填合适的数：(1)(2)。3.在□里填合适的数（含+3）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p065.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.7 加与减 3.在□里填合适的数（含+3）。4.算一算：(1)~(4) 含2+3=、7+1=、3+5=、2+7=及方框填空。5.算一算，填一填：(1)4+1= 等。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p066.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 3, '{"stem": "4.7 加与减 素养发展 7.想一想，在方框里填上0~10中的四个数，使各算式成立（□+5=、□-7=、8）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p067.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '凑十', 1, '{"stem": "4.8 10的游戏 1.哪两个数合起来是10（用线连起来）。2.画一画，使它们组成10。3.哪把钥匙开哪把锁（用线连起来）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p068.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '凑十', 1, '{"stem": "4.8 10的游戏 4.连线（算式与结果配对：2+8、2+7、7-5、7-4、4+5、5+3、9-3、6-4、2+6、3+4、8-4、9-5、3+7、8-2、9-2、6-3）。5.算一算：(1)5+（ ）=10 等。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p069.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连加连减', 1, '{"stem": "4.9 连加连减① 1.看图列式计算：一共有多少根/多少个（连加连减图示）。2.算一算：(1)3+5=、?+2= (2)2+6+1= 等（图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p070.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连加连减', 2, '{"stem": "4.9 连加连减① 3.填表（连加连减填数表）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p071.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连减', 1, '{"stem": "4.10 连加连减② 1.看图列式计算：现在还剩几条鱼（连减图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p072.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连减', 1, '{"stem": "4.10 连加连减 4.列式计算：(1)有8个气球，3个黄、2个蓝，红气球有几个？(2)10个苹果，先吃3个又吃3个，剩几个？(3)树上10只鸟，先飞2只又飞5只，共飞走几只？还剩几只？", "options": null}', '(1)8-3-2=3（个）；(2)10-3-3=4（个）；(3)共飞走2+5=7（只），还剩10-7=3（只）。', '总数依次减去各部分。', 'paper', '["连减","应用题"]', '["/static/qimg/ykl_pt_sx_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "4.11 加减混合 2.找朋友（算式与结果配对）：7-3+4、7+3、9+1-6、3+0+5、4-3+9、9-6+4、6-1+2。", "options": null}', '7-3+4=8；7+3=10；9+1-6=4；3+0+5=8；4-3+9=10；9-6+4=7；6-1+2=7。', '按顺序算。', 'paper', '["加减混合","计算"]', '["/static/qimg/ykl_pt_sx_p074.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '比大小', 2, '{"stem": "4.11 加减混合 3.在○里填＞＜或=：(1)5+2-3○8-2-3，8-4+2○6+2-5；(2)7-4+0○3+5-5，10+0-10○2+7-3；(3)6-1+5○4+2+3，9-4+2○7-7+7；(4)5+4-1○10-6+4，9+1-4○4-0+4。", "options": null}', '(1)5+2-3=4 > 8-2-3=3；8-4+2=6 > 6+2-5=3；(2)7-4+0=3 = 3+5-5=3；10+0-10=0 < 2+7-3=6；(3)6-1+5=10 > 4+2+3=9；9-4+2=7 = 7-7+7=7；(4)5+4-1=8 = 10-6+4=8；9+1-4=6 < 4-0+4=8。', '分别算出两边再比较。', 'paper', '["比大小","计算"]', '["/static/qimg/ykl_pt_sx_p075.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "4.11 加减混合 4.算一算：(1)2+4+3=、6-3+4=、8-4+2=；(2)6+4+0=、2+2+1=、1+6-5=。", "options": null}', '(1)2+4+3=9，6-3+4=7，8-4+2=6；(2)6+4+0=10，2+2+1=5，1+6-5=2。', '按从左到右顺序算。', 'paper', '["加减混合","计算"]', '["/static/qimg/ykl_pt_sx_p075.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.11 加减混合 拓展提升 6.想一想，填一填：□+1=8，□-2=6，□+2=2。", "options": null}', '□+1=8→7；□-2=6→8；□+2=2→0。', '用逆运算求方框里的数。', 'paper', '["加减混合","填数"]', '["/static/qimg/ykl_pt_sx_p076.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.11 加减混合 素养发展 7.小猴寻桃：在结果是10的道路上前行（4+3+1、4+4-3、8-6+4、7+1-3、6-3+5、5-0+5）。", "options": null}', '各算式结果：4+3+1=8，4+4-3=5，8-6+4=6，7+1-3=5，6-3+5=8，5-0+5=10。结果等于10的是 5-0+5。', '逐个计算找等于10的算式。', 'paper', '["加减混合","开放题"]', '["/static/qimg/ykl_pt_sx_p076.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "4.12 小练习（2）3.算一算：(1)1+3+4=、2+2+2=、2+3+5=、8-8+5=、9-5-2=；(2)8-2-3=、4+4-3=、7-6+8=、9-1-4=、7-1+4=、10-4-5=。", "options": null}', '(1)1+3+4=8，2+2+2=6，2+3+5=10，8-8+5=5，9-5-2=2；(2)8-2-3=3，4+4-3=5，7-6+8=9，9-1-4=4，7-1+4=10，10-4-5=1。', '按从左到右顺序算。', 'paper', '["加减混合","计算"]', '["/static/qimg/ykl_pt_sx_p077.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "4.12 小练习（2）4.列式计算：(1)鱼缸原来4条小鱼，买来3条后送给小华2条，现在有几条？(2)电梯原6人，第三层走出3人又进入4人，现在几人？", "options": null}', '(1)4+3-2=5（条）；(2)6-3+4=7（人）。', '先加后减或先减后加。', 'paper', '["加减混合","应用题"]', '["/static/qimg/ykl_pt_sx_p078.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减法', 1, '{"stem": "单元练习4 1.直接写出得数：(1)4+2=、5-5=、9-4=、6-3=；(2)7+0=、8-8=、3+6=、7-4=；(3)6+4=、10-3=、1+9=、9-7=；(4)2+5=、10-5=、4+4=、8-2=。", "options": null}', '(1)6、0、5、3；(2)7、0、9、3；(3)10、7、10、2；(4)7、5、8、6。', '直接计算。', 'paper', '["加减法","计算"]', '["/static/qimg/ykl_pt_sx_p079.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "单元练习4 6.讲讲算算：(1)原来有6只，飞来了4只，现在有几只？(2)机场上有7架，飞走了3架，又飞来4架，现在一共有多少架？", "options": null}', '(1)6+4=10（只）；(2)7-3+4=8（架）。', '飞来求和应用加法，飞走求现用减法。', 'paper', '["加减混合","应用题"]', '["/static/qimg/ykl_pt_sx_p080.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "单元练习4 6.讲讲算算续：(3)河里10条鱼，游走一些后还剩8条，游走了几条？(4)桌上6个，小明吃了3个，又给爸爸2个，现在桌上还剩几个？", "options": null}', '(3)10-8=2（条）；(4)6-3-2=1（个）。', '用总数减剩余求游走/吃掉的部分。', 'paper', '["加减混合","应用题"]', '["/static/qimg/ykl_pt_sx_p081.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '连加连减', 2, '{"stem": "4.10 连加连减 3.填表（连加连减填数表）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p073.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "4.11 加减混合 1.看图列式计算。2.看图列算式计算（小练习）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p074.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "4.12 小练习（2）1.□里可以填几（图示开放填数）。2.看图列算式计算。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p077.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填数', 3, '{"stem": "4.12 小练习（2）5.把1、2、3、4、5分别填入□，使横行、竖列三个数的和都等于10。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p078.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 2, '{"stem": "单元练习4 5.列式计算：一共有多少片树叶？还剩多少个水果？（图示）。7.把1~8填入□使算式成立。8.在○填数使每条线上三个数和都是10。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p080.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 1, '{"stem": "5.1 11~20的认识 1.先10个一圈，再填数。2.看小棒图，写数并读数（写作/读作）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p082.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '比大小', 2, '{"stem": "5.1 11~20的认识 6.在○里填＞＜或=，在□里填数：16○10、11○15、20=□、10○□、□<16<□、7○10、6○5、19○□（示例填法）。", "options": null}', '16>10；11<15；20=20；10=10；15<16<17（示例）；7<10；6>5；19<20。', '比较两位数与一位数大小，再按序填数。', 'paper', '["比大小","填数"]', '["/static/qimg/ykl_pt_sx_p084.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的组成', 1, '{"stem": "5.2 十几就是十和几 2.填写算式：(1)2+10=、5+10=、9+10=；(2)12-2=、15-5=、19-9=；(3)17=10+□、11=10+□、14=10+□、18=10+□、16=10+□、13=10+□；(4)20=10+□、19=10+□。", "options": null}', '(1)2+10=12，5+10=15，9+10=19；(2)12-2=10，15-5=10，19-9=10；(3)17=10+7，11=10+1，14=10+4，18=10+8，16=10+6，13=10+3；(4)20=10+10，19=10+9。', '十几 = 10 + 几；10 + 几 = 十几。', 'paper', '["数的组成","计算"]', '["/static/qimg/ykl_pt_sx_p086.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的组成', 1, '{"stem": "5.3 十几就是十和几 相关知识：(6)20里面有（ ）个十，也可以说有（ ）个一；(7)比20少1的数是（ ）。", "options": null}', '(6)20里面有2个十，也可以说有20个一；(7)比20少1的数是19。', '整十数的组成与相邻数。', 'paper', '["数的组成","填空"]', '["/static/qimg/ykl_pt_sx_p088.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '找规律', 2, '{"stem": "5.4 20以内数的排列 (6)比20小、比15大的数有（ ）。5.交换两个数位置使每行按规律排列：(1)20,19,18,17,15,16；(2)3,6,5,4,7；(3)4,12,8,16,20。6.找出不符合规律的数圈出来：(1)2,4,6,8,9；(2)18,17,15,13,11；(3)3,6,9,13,15,18。7.找规律填一填：(1)1,2,4,7,11,( )；(2)3,5,8,10,13,( ),( ),20。", "options": null}', '(6)16、17、18、19。5.(1)交换15和16→20,19,18,17,16,15；(2)交换6和4→3,4,5,6,7；(3)交换12和8→4,8,12,16,20。6.(1)9（应为10）；(2)15（应为16）；(3)13（应为12）。7.(1)16（差依次+1,+2,+3,+4,+5）；(2)15、18（差2,3,2,3,2,3）。', '观察数列差与排列规律。', 'paper', '["找规律","填空"]', '["/static/qimg/ykl_pt_sx_p090.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 2, '{"stem": "5.4 20以内数的排列 (2)一个数比12大，比15小，这个数可能是（ ）；(3)一个数比20小，比16大，这个数可能是（ ）；(4)一个数比20小，个位上的数字比十位上的数字大3，这个两位数是（ ）。", "options": null}', '(2)13或14；(3)17、18或19；(4)14（十位是1，个位1+3=4）。', '按大小范围与数位关系判断。', 'paper', '["数的认识","填空"]', '["/static/qimg/ykl_pt_sx_p091.jpg"]', 0);
