INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的组成', 1, '{"stem": "5.3 十几就是十和几 3.看数在计数器上添画珠子：12、16、20。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p088.jpg"]', 0);
