INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 1, '{"stem": "单元练习5 (4)在横线上填与19相邻的数。(5)在3、8、0、13、20、16中，最大是（ ）、最小是（ ），从大到小排列并用＞连接。(6)一个加数10，另一个加数9，和是（ ）。(7)被减数20，减数10，差是（ ）。(8)0+4=（ ）。", "options": null}', '(4)与19相邻的数：18、20。(5)最大20，最小0，排列：20＞16＞13＞8＞3＞0。(6)10+9=19。(7)20-10=10。(8)0+4=4。', '相邻数、比大小、加减法基本关系。', 'paper', '["数的认识","填空"]', '["/static/qimg/ykl_pt_sx_p093.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "20以内加减法（一）(3)3+11=、4+15=、2+16=、7+11=。(4)8-3=、9-4=、7-5=、5-2=。(5)18-3=、17-5=、15-2=、19-4=。", "options": null}', '(3)3+11=14，4+15=19，2+16=18，7+11=18；(4)8-3=5，9-4=5，7-5=2，5-2=3；(5)18-3=15，17-5=12，15-2=13，19-4=15。', '不进位加法与不退位减法。', 'paper', '["20以内加减","计算"]', '["/static/qimg/ykl_pt_sx_p095.jpg"]', 0);
