INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '进位加法', 1, '{"stem": "6.2 进位加法① 2.填表：9+2、9+3、9+4、9+5、9+6、9+7。", "options": null}', '9+2=11，9+3=12，9+4=13，9+5=14，9+6=15，9+7=16。', '9加几，凑十法：9+几=10+(几-1)。', 'paper', '["进位加法","计算"]', '["/static/qimg/ykl_pt_sx_p097.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '进位加法', 1, '{"stem": "6.2 进位加法① (3)9+1+8=、9+9=；(5)9+1+7=、9+8=；(6)9+1+1=、9+2=。", "options": null}', '(3)9+1+8=18，9+9=18；(5)9+1+7=17，9+8=17；(6)9+1+1=11，9+2=11。', '凑十分解：9+几=9+1+(几-1)。', 'paper', '["进位加法","计算"]', '["/static/qimg/ykl_pt_sx_p098.jpg"]', 0);
