INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "6.7 小练习（3）1.直接写得数：(1)4+8=、13-3=、19-4=、5+5=、13+7=、15+4=；(2)5+9+1=、14+3+2=、3+10+1=、6+3+8=、10+0+2=。", "options": null}', '(1)4+8=12，13-3=10，19-4=15，5+5=10，13+7=20，15+4=19；(2)5+9+1=15，14+3+2=19，3+10+1=14，6+3+8=17，10+0+2=12。', '直接算，连加按从左到右。', 'paper', '["20以内加减","计算"]', '["/static/qimg/ykl_pt_sx_p107.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "6.7 小练习（3）4.把下列算式按得数从大到小排列：14-10、5+7、16-6、17+3、11+8。", "options": null}', '17+3=20 ＞ 11+8=19 ＞ 5+7=12 ＞ 16-6=10 ＞ 14-10=4。', '先算得数再排序。', 'paper', '["20以内加减","排序"]', '["/static/qimg/ykl_pt_sx_p108.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "单元练习6 1.直接写出得数：(1)2+4=、10-7=、4+9=、8+2=；(2)14-0=、15-3=、7+7=、6+6=；(3)17-5=、9-4=、10-8=。", "options": null}', '(1)2+4=6，10-7=3，4+9=13，8+2=10；(2)14-0=14，15-3=12，7+7=14，6+6=12；(3)17-5=12，9-4=5，10-8=2。', '直接计算。', 'paper', '["20以内加减","计算"]', '["/static/qimg/ykl_pt_sx_p109.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "单元练习6 9.圈出得数小于15的卡片：12+2、5+10、3+17、9+8、14+6、8+5、10-3、2+7（注：OCR“5--10”按5+10处理）。10.把算式按得数从大到小排列：4+4、4+14、4+16。", "options": null}', '9.得数：12+2=14、5+10=15、3+17=20、9+8=17、14+6=20、8+5=13、10-3=7、2+7=9；小于15的是 12+2、8+5、10-3、2+7。10.从大到小：4+16=20 ＞ 4+14=18 ＞ 4+4=8。', '先算得数，再判断大小或排序。', 'paper', '["20以内加减","判断"]', '["/static/qimg/ykl_pt_sx_p111.jpg"]', 0);
