INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 1, '{"stem": "退位减法 2.想一想，填一填：(1)十位上是1，个位上的数字和十位上的数字相同，这个两位数是（ ）。", "options": null}', '11（十位1、个位也是1）。', '数位意义。', 'paper', '["数的认识","填空"]', '["/static/qimg/ykl_pt_sx_p114.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 2, '{"stem": "退位减法 3.判断（对的打√，错的打×）：(1)二十，写作：2。(2)一个两位数，十位是6，个位是1，这个数是16。(3)最大的一位数是9，最小的两位数是11。(4)18是由8个一和1个十组成的。", "options": null}', '(1)×（二十写作20）；(2)×（应为61）；(3)×（最小的两位数是10）；(4)√。', '数位与数的组成。', 'paper', '["数的认识","判断"]', '["/static/qimg/ykl_pt_sx_p115.jpg"]', 0);
