INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "7.3 复习3 1.直接写出得数：(1)19-9=、8-2=、6+14=、9+7=、11+8=、5+5=、17-6=、10-3=、6+6=；(2)16-10+12=。", "options": null}', '(1)19-9=10，8-2=6，6+14=20，9+7=16，11+8=19，5+5=10，17-6=11，10-3=7，6+6=12；(2)16-10+12=18。', '直接计算。', 'paper', '["20以内加减","计算"]', '["/static/qimg/ykl_pt_sx_p116.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '找规律', 2, '{"stem": "7.3 复习3 5.先算一算，发现规律：8+2=（ ）、8+3=（ ）、8+（ ）=（ ），①不变②增加1③减少1；第一个加数不变，第二个加数每次（ ），和每次（ ）。", "options": null}', '8+2=10，8+3=11，后续每次加1（如8+4=12……）；第一个加数不变，第二个加数每次②增加1，和每次②增加1。', '加数与和的变化规律。', 'paper', '["找规律","填空"]', '["/static/qimg/ykl_pt_sx_p117.jpg"]', 0);
