INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 2, '{"stem": "期末练习1 9.想一想，填一填：(1)1个十和2个一是（ ），它比最小的两位数大（ ）。(2)5,6,7,8……一直写到20，一共写了（ ）个数。(3)一个数，十位上是1，个位上的数字比十位上的数字大6，这个数是（ ）。(4)把2、6、0、20、19、8从大到小排列并用＞连接。", "options": null}', '(1)12，比最小两位数10大2；(2)20-5+1=16（个）；(3)17（十位1、个位1+6=7）；(4)20＞19＞8＞6＞2＞0。', '数位、计数、排序。', 'paper', '["数的认识","填空"]', '["/static/qimg/ykl_pt_sx_p131.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '减法', 1, '{"stem": "期末练习1 12.解决问题：(1)小松鼠要折17只小纸船，已经折好了4只，还要折几只？", "options": null}', '17-4=13（只）。', '总数减已完成的。', 'paper', '["减法","应用题"]', '["/static/qimg/ykl_pt_sx_p132.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "期中练习1 7.数的分与合。8.看图写算式：(1)(2)(3)(4)。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p124.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 1, '{"stem": "期中练习2 1.在□里填数（图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p125.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "期中练习2 5.看图列式计算：(2)(3)(4)。7.把正确的答案圈出来（图示）。10.填空：从右往左数，大客车是第五辆车，一共有（ ）辆车。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p126.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "期末练习1 1.看图写数（计数器）。(3)填数（10、13 等）。6.圈一圈，算一算（9+? 凑十）。7.填一填，算一算（计数器）。9.(5)接着画5个。10.数一数，圈一圈，填一填。12.(1)又飞来6只，一共有多少只（图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p129.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '排队问题', 2, '{"stem": "期末练习1 12.(4)一（1）班同学站成一排，从左往右数1号到8号是女生，12号到20号也是女生。这个班有多少名女生？", "options": null}', '8 + (20-12+1) = 8 + 9 = 17（名）。', '分两段数女生再加总。', 'paper', '["排队问题","应用题"]', '["/static/qimg/ykl_pt_sx_p133.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '20以内加减', 1, '{"stem": "期末练习2 第一部分 1.口算：(1)10+3=、16-6=、7+7+2=、（ ）+6=11、15-5=、4+12=、11-5+6=。", "options": null}', '10+3=13，16-6=10，7+7+2=16，(5)+6=11，15-5=10，4+12=16，11-5+6=12。', '直接计算。', 'paper', '["20以内加减","计算"]', '["/static/qimg/ykl_pt_sx_p134.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '分与合', 2, '{"stem": "期末练习2 5.在4、12、8、20、16中选择三个合适的数，组成两道加法算式和两道减法算式。", "options": null}', '选 4、12、16：4+12=16，12+4=16，16-4=12，16-12=4。', '利用数的分与合。', 'paper', '["分与合","开放题"]', '["/static/qimg/ykl_pt_sx_p135.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "期末练习2 7.列式计算：(1)小海上午剪了7个窗花，下午剪了8个，这一天一共剪了多少个？(3)红金鱼5条、花金鱼6条，送给小华3条后，鱼缸里还剩多少条？", "options": null}', '(1)7+8=15（个）；(3)5+6-3=8（条）。', '求和用加，给走用减。', 'paper', '["加减混合","应用题"]', '["/static/qimg/ykl_pt_sx_p136.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数的认识', 2, '{"stem": "期末练习2 第三部分 概念：(2)一个两位数，十位上是1，个位上是10的一半，这个数是（ ）。(3)20里面有（ ）个一；20里面有（ ）个5。(5)小朋友排队，从左往右数小海是第6个，从右往左数小海也是第6个，这排小朋友共（ ）人。", "options": null}', '(2)15（10的一半是5）；(3)20里面有20个一，有4个5；(5)6+6-1=11（人）。', '数位、包含分、排队重叠。', 'paper', '["数的认识","填空"]', '["/static/qimg/ykl_pt_sx_p137.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '生活应用', 2, '{"stem": "期末练习2 第三部分 概念：(9)小华看漫画书，今天从第10页看到第18页，明天从第19页看起，今天看了（ ）页。(10)花坛花的盆数是8的加倍（16），其中月季是8的一半（4），其余是玫瑰，玫瑰花种了（ ）盆。", "options": null}', '(9)18-10+1=9（页）；(10)16-4=12（盆）。', '页码含头尾；加倍与一半。', 'paper', '["生活应用","填空"]', '["/static/qimg/ykl_pt_sx_p138.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '加减混合', 1, '{"stem": "期末练习1 12.(5)欢欢带了20元，物品标价1号12元、2号8元、3号5元，（ ）号和（ ）号……（组合购买，图示）。【看图题·图意待补】", "options": null}', '【图意待补】', '需看图确定图意与答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_pt_sx_p133.jpg"]', 0);
