INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '表达', 2, '{"stem": "表达乐园：我上一次生日，是和爸爸、妈妈一起过的，爸爸祝我天天开心，妈妈祝我学习进步。我许的生日愿望是交到更多的好朋友。第十一周·基础游乐园：分组拼音（第一组 xióng māo míng shé / 第二组 lú méi xióng rì kuí / 第三组 dì tiě huǒ chē / 第四组 xiàng pí qiān bǐ ……）（表达+拼音，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yw_p182.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '阅读', 2, '{"stem": "阅读/表达：牛、驴、羊、狗、鹤、鸭、鹅……小鸭的爪印像枫叶；示例：我觉得秋天是金黄色的，因为稻子、谷穗、桂花、芒果……都是金黄色的。表达：开学以来，我学会了自己削铅笔、整理书包、穿衣服。（第十二周，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yw_p183.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '表达', 2, '{"stem": "表达/拼音：示例——校园里有教学楼、操场和食堂，我最喜欢操场，因为可以在那里奔跑玩耍。第十三周·拼音练习（in / ing ……）。（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yw_p184.jpg"]', 0);
