INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '表达', 2, '{"stem": "表达/拼音：示例——有一次我准备做作业，翻开本子垫好垫板，突然发现铅笔不见了，急得满头大汗。第十八周·阶段自测二（序号 ①⑧⑤⑥②⑦ ……）。（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yw_p190.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='语文' AND grade='一年级' AND level=1 LIMIT 1), '语文', '一年级', '看图书拼音', 1, '{"stem": "拼音/看图：扫—房子 / 一片黑 / 穿—风筝……（看图拼音词，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yw_p191.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "IV. Read, choose and draw：Meimei 在操场上遇到了 Ms Yu，请将他们的对话补充完整，将相应的形状画在横线上。选项参考：How are you? / Good evening, Mum/Dad. / I''m fine/five.（对话补全+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p003.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图选择', 1, '{"stem": "Tick and sing：下面哪幅图片可以用 Good morning 打招呼？在图片里的方框内打勾，并和同学唱一唱 morning 歌。（看图选择，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p004.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "2. This is __ Li. She is my teacher（老师）. A. Mr  B. Miss  C. Sir", "options": null}', 'B. Miss', ' She 是女性老师，用 Miss。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p005.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "3. In the __, I go to school（学校）. A. ……（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p005.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '单词迷宫', 1, '{"stem": "Read and draw：和 Lily 一起走单词迷宫，从起点开始沿着拼写正确的单词画一条路线走到终点，并大声朗读单词（naem / friend / hi / frend / name）。（单词迷宫，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p009.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "Read and circle：圈出正确的单词帮 Lily 完成介绍。1. Hello. My/I name is Lily White. 2. You/I can call me Lily. 3. Nice to meet you/me.", "options": null}', '1. My  2. You  3. you', '介绍自己用 My name；称呼对方用 You；Nice to meet you 固定搭配。', 'paper', '["圈词"]', '["/static/qimg/ykl_en_yy_p010.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '连词成句', 2, '{"stem": "Read, number and write：有个小马虎把句子中的单词顺序写错了，快来帮助他把单词连成句子，将数字编号写在火车箱内。（连词成句，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p010.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "有个同学看上去生病了，Lily 可以这样问候：A. Good to meet you.  B. How are you?", "options": null}', 'B. How are you?', '关心对方身体状况用 How are you?。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p011.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "晚上，Lily 出门看到还在工作的环卫工人，她这样和他问候：A. ……  B. Hi, Peter.（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p011.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Improvement Exercise 1 (Units 1-2) Part 1 Listening：1. Listen and circle（听录音，圈出与录音内容相符的图片或单词）。", "options": null}', '【听力题需音频确认】', '听录音作答，需音频确认。', 'paper', '["听力题需音频确认"]', '["/static/qimg/ykl_en_yy_p012.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "Part 1 Listening：II. Listen and number（听录音，根据听到的顺序，用 1—4 给下列单词编号：Lily / nice / name / hello）。", "options": null}', '【听力题需音频确认】', '听录音作答，需音频确认。', 'paper', '["听力题需音频确认"]', '["/static/qimg/ykl_en_yy_p013.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "Part 2 Vocabulary and Grammar：1. Read and circle（在字谜格中圈出下列单词）。（单词字谜，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p014.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "IV. Read and circle：① 吃完早餐后，Shenshen 准备去上学，她对妈妈说：A. Good morning, Mum.  B. Goodbye, Mum.", "options": null}', 'A. Good morning, Mum.', '早上出门上学用 Good morning 问候。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "IV. Read and circle：② Xinxin 的班上来了一个新朋友，她向朋友自我介绍道：A. Hello.  B. You can call me Xinxin.", "options": null}', 'B. You can call me Xinxin.', '向新朋友自我介绍用 You can call me...。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p015.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '阅读填空', 2, '{"stem": "II. Read and complete：请再次阅读短文，将属于两人的信息填写完整，把数字编号填在横线上（1.Zhang Lin 2.8 years old 3.Jenny 4.Shanghai 5.London）。（阅读填空，文意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p016.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "IV. Read, choose and draw：Minmin 背上新书包去学校了，他正在和 Shenshen 交谈。请将他们的对话补充完整，将相应的形状画在横线上（选项：Use my pencil. / Good morning, Shenshen. / Thank you. / Use my ruler. / Oh, no! My ruler.）。（对话补全+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p018.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '表达', 2, '{"stem": "专项提高：Draw and say（你的书包里有哪些文具呢？画一画，说一说：Hello. My name is... I have... I pack my schoolbag every day.）。（表达+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p019.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话选择', 2, '{"stem": "IV. Read, choose and write：下面图片中的人物正在交谈。他们如何对话？请读一读，选出正确的句子，把字母代号填在横线上（选项：Oh, no! My ruler. / Pack your books. / My name is Xiaopu. ...）。（对话选择，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p020.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "IV. Read, choose and draw：今天是校园清洁日，李老师正在和同学们交谈。请将他们的对话补充完整，将相应的形状画在横线上（选项：Let me clean the door. / Let me clean the blackboard. / Let me help you. / Let me put the books back. / Let''s clean our classroom.）。（对话补全+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p023.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '表达', 2, '{"stem": "专项提高：Draw and say（画一画你所在教室里的物品，并说一说值日时你是如何打扫教室的：Hello! My name is... Let me clean the classroom. Let me... Wow! Our classroom is clean and nice.）。（表达+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p024.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '连线', 1, '{"stem": "填空与连线：① you ② me ③ help（Let ...）；① on ② duty ③ Who''s（... on duty?）。IV. Read and match：读一读，将句子配对，用线连接起来（Let''s clean our classroom. ...）。（填空+连线，文意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p025.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "对话补全：Miss Chen: Tingting, clean the blackboard, please. → Tingting: Yes, Miss Chen. Let me clean it at once. Miss Chen: Jiajia, please put the books back. → Jiajia: OK. Xiaoya: ...（补全对话，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p026.jpg"]', 0);
