INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "II. Listen and number（听录音，根据听到的顺序，用 1—4 给下列图片或单词编号）。", "options": null}', '【听力题需音频确认】', '听录音作答，需音频确认。', 'paper', '["听力题需音频确认"]', '["/static/qimg/ykl_en_yy_p028.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '填空', 2, '{"stem": "Part 2 Vocabulary and Grammar：I. Read, choose and write（读单词，并将它们放入合适的空间中，在横线上写下数字编号：① pencil ② door ③ chair ④ eraser）。（归类/填空，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p029.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "3. 圈出正确的句子：A. Oh, no. My eraser!  B. Oh, no. My rulers!（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p030.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "IV. Read and circle（圈出正确的答案）：__ is on duty today？ A. How  B. Who  C. What", "options": null}', 'B. Who', '询问“谁”值日用 Who。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p030.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '阅读选择', 2, '{"stem": "Read and tick：阅读 Lily 的日记并勾出正确的答案（可多选）。Who is on duty today？□ Lily □ Miss Li □ Shenshen □ Minmin；What can you see in the school library？（阅读选择，文意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p031.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "圈出正确的词：1. Look! This is a picture of my face / mouth. 2. Look, a nose / face. It''s round like an apple. 3. I have two big eyes / ears. I can see you. 4. And I draw / see a small and lovely nose.", "options": null}', '1. face  2. nose  3. eyes  4. draw', '按语义搭配选择。', 'paper', '["圈词"]', '["/static/qimg/ykl_en_yy_p033.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "IV. Read, choose and draw：Minmin 和 Xiaowen 也在为对方画肖像画。请将他们的对话补充完整，将相应的形状画在横线上（选项含：Here you are. ...）。（对话补全+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p033.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '表达', 2, '{"stem": "专项提高：Draw and say（拿出小镜子观察自己，画一画自己的脸，并试着向爸爸妈妈介绍：Hello! My name is... Look! I have a... face. Two... A...）。（表达+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p034.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "Read and circle：读一读，圈出正确答案的字母代号，并将字谜格子图中的相应位置涂成红色，看看隐藏的字谜是什么（Look. ... face. It''s lovely. A / B / C ...）。（圈词+字谜，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p035.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '阅读', 2, '{"stem": "阅读：Nose: With me, Sally can smell flowers... Mouth: ... Who is super?（五官争功阅读，文意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p036.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "圈出正确的词：① I have a big / small family. There are 6 people in my family. ② My grandma and grandpa love me / my very much. ③ This is my father / mother. He drives me to school every day. ④ This nice lady is my father / mother. She is kind and dear. ⑤ My little brother is only two. I am his good sister / brother.", "options": null}', '1. big  2. me  3. father  4. mother  （第5题 sister/brother 图意待补）', '按人称/性别/语义搭配选择。', 'paper', '["圈词"]', '["/static/qimg/ykl_en_yy_p038.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '对话补全', 2, '{"stem": "IV. Read, choose and draw：Minmin 和 Xiaowen 相约一起踢球，Xiaowen 带来了两个男孩。请将对话补充完整，将相应的形状画在横线上。（对话补全+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p038.jpg"]', 0);
