INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "Mum, I love __. A. you  B. me  C. your", "options": null}', 'A. you', '向妈妈表达“我爱你”用 I love you。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p040.jpg"]', 0);
