INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "II. Read and circle：② 你在和同学玩猜谜游戏，可以这样描述大象：A. Two big eyes and a big mouth.  B. Two big ears and a long nose.", "options": null}', 'B. Two big ears and a long nose.', '大象的特征是大耳朵、长鼻子。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p045.jpg"]', 0);
