INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '看图圈词', 1, '{"stem": "Week 7 Unit 7 复习巩固：Read aloud and circle（Lily 家来了一位新成员 Ginger，请观察图片并大声朗读下列短语，并圈出这位新成员：a cozy house / a lovely dog / a round ball）。（看图圈词，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p047.jpg"]', 0);
