INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "— It''s time to swim. — Oh, no. I''m afraid. A. Have a try! ……（图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p060.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '阅读判断', 2, '{"stem": "阅读判断：Aiaopu: Rabbits! I see rabbits. They have long ears and red eyes. They are cute. They eat carrots. I like rabbits. I like the farm. 判断：① The children are on Happy Farm. ② The sheep are black and soft.（阅读判断，文意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p061.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '圈词', 1, '{"stem": "III. Read and circle：— Can you make your bed（铺床）？— Yes, I can / can''t. I can make my bed. — Can you clean the table？— Yes, I can. I can wash / clean the table.", "options": null}', '1. can  2. clean', '肯定回答用 can；clean the table 搭配 clean。', 'paper', '["圈词"]', '["/static/qimg/ykl_en_yy_p063.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '表达', 2, '{"stem": "专项提高：Draw and say（你是个自己的事情自己做的好孩子吗？请画出四格漫画记录四件你会做的事，并向爸爸妈妈介绍：Look! I can... I can...）。（表达+画图，图意待补）。", "options": null}', '【图意待补】', '需看图/听音确定答案。', 'paper', '["图意待补"]', '["/static/qimg/ykl_en_yy_p064.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "③ Can you clean the blackboard, Shenshen? A. No, I can.  B. Yes, I can.  C. Yes, she can.", "options": null}', 'B. Yes, I can.', '问 Shenshen 你能擦黑板吗，肯定答用 Yes, I can。', 'paper', '["选择"]', '["/static/qimg/ykl_en_yy_p065.jpg"]', 0);
