INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "听录音，根据听到的字母发音，在句子中圈出相应的字母：1.Let me clean our classroom. 2.Flap your wings, Jack! 3.Draw a big nose. 4.My pet is a lovely cat. 5.It''s time to fly.", "options": null}', '【听力题需音频确认】', '听录音完成，需音频确认。', 'paper', '["听力题需音频确认"]', '["/static/qimg/mz_yy_p097.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '听力题', 1, '{"stem": "听录音，圈出正确的应答（小朋友们学游泳）：1.A.Oh,no! It''s too deep. B.Sorry. 2.A.OK. Flap my arms. B.OK. Flap my wings. 3.A.Have a go! You can do it! B.Hooray! 4.A.OK.（选项见原题）。", "options": null}', '【听力题需音频确认】', '听录音完成，需音频确认。', 'paper', '["听力题需音频确认"]', '["/static/qimg/mz_yy_p098.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "读一读，圈出正确的单词完成句子：1.Two little birds sit (on/in) the branch. 2.Come back, (jack/Jack). 3.It''s time (too/to) eat. 4.Jill, flap your (wings/arms)!", "options": null}', '1-on, 2-Jack, 3-to, 4-wings', '1 鸟栖树枝用 on；2 人名首字母大写 Jack；3 It''s time to do 固定搭配；4 flap wings（拍翅膀）。', 'paper', '["选择"]', '["/static/qimg/mz_yy_p099.jpg"]', 0);
