INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='英语' AND grade='一年级' AND level=1 LIMIT 1), '英语', '一年级', '选择', 1, '{"stem": "看图，选择正确句子：2. Minmin 带了五支铅笔，他告诉 Xiaopu 说：A.I has five pencil. B.I have five pencils.  3. Shenshen 看到黑板上的数字“2”像只小鸭子，她对 Lily 说：A.Look! The two on the blackboard is a duck. B.Look! The four on the blackboard is a flag.  4. Xiaopu 看到班牌“一年级（4）班”说___（图见原题）。", "options": null}', '2-B, 3-A, 4-待核对', '2 主语 I 后用 have、pencil 用复数 pencils；3 “2像鸭子”对应 A。', 'paper', '["选择"]', '["/static/qimg/mz_yy_p125.jpg"]', 0);
