INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "九、根据题意，列式计算（12分）：1.欢欢折了4只千纸鹤，小华折了5只，一共折了几只？2.一共10盆花，已浇3盆，还有几盆没浇？3.捉迷藏已捉住4个，还有5个没捉住，一共有多少个小朋友在玩？", "options": null}', '1. 4+5=9  2. 10-3=7  3. 4+5+1=10', '1 求和；2 求剩余；3 玩捉迷藏总人数=捉住的+没捉住的+捉的人自己=4+5+1=10。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p028.jpg"]', 0);
