INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 1, '{"stem": "六、猜猜我是谁，比比大小（10分）：1.我是一个两位数，个位5十位1，我是（15）。2.我由3个一和1个十组成，我是（13）。3.8和10是我的相邻数，我是（9）。4.图中计数器表示的数是（ 待图意 ）。", "options": null}', '1-15, 2-13, 3-9, 4-【图意待补】', '数位与相邻数；第4题看计数器图。', 'paper', '["数位"]', '["/static/qimg/yg_sx_p036.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "在□里填数（8分）：18-□+2=12，□+6=16，□-10=5，□-5+2=12，4=14-□，13=3+□，2+3+□=15。", "options": null}', '8, 10, 15, 15, 10, 10, 10', '逐一逆推：18-x+2=12→x=8；x+6=16→10；x-10=5→15；x-5+2=12→15；4=14-x→10；13=3+x→10；2+3+x=15→10。', 'paper', '["填数"]', '["/static/qimg/yg_sx_p038.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 2, '{"stem": "填空：6.一个两位数的个位数字与十位数字的和是2，这个两位数是（11）。7.在12、8、17、18、9中：(1)最接近10的是（9），最接近20的是（18）。(2)最大（18）最小（8）。(3)8在（ ）左边（ ）右边。(4)比10大的数是（12、17、18）。", "options": null}', '6-11; 7-(1)9,18 (2)18,8 (3)待图意 (4)12,17,18', '个位+十位=2的两位数仅11；各数大小与相邻关系。', 'paper', '["数位"]', '["/static/qimg/yg_sx_p039.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "（2）从0开始，2格2格地数和7格7格地数都数到了我，我是（14）。六、应用（6分）：弟弟有6本书，哥哥有10本书。（1）两人一共有多少本？", "options": null}', '14; 6+10=16（本）', '2和7的公倍数（14内）为14；求和6+10=16。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p040.jpg"]', 0);
