INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '计算', 1, '{"stem": "看减法表填空（被减数-减数，求差）：被减数17减5=12；15减5=10；14减5=9；18减5=13；16减5=11（依原题表格）。", "options": null}', '12, 10, 9, 13, 11', '对应减法表逐行求差。', 'paper', '["计算"]', '["/static/qimg/yg_sx_p043.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "列式计算：2.商店有15台电视机，卖掉4台，还剩多少台？3.停车场有9辆汽车，又开来5辆，现在有多少辆？4.盒子里原来19块巧克力，吃了几块后剩3块，吃了几块？5.河里游走10条小鱼，还剩6条，原来有多少条？", "options": null}', '2.15-4=11  3.9+5=14  4.19-3=16  5.10+6=16', '文字应用题，依题意列式。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p044.jpg"]', 0);
