INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "二、根据问题，列式计算（一）（24分）：1.原来有15只鸟，飞来5只，现在多少只？2.原来有5只鸟，飞走3只，现在多少只？3.原15只飞走一些剩5只，飞走多少只？4.原8只飞来一些现10只，飞来多少只？", "options": null}', '1.15+5=20  2.5-3=2  3.15-5=10  4.10-8=2', '加减法数量关系应用题。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p067.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 2, '{"stem": "三、花丛中有9只蝴蝶，5只是花蝴蝶其余黄蝴蝶：①飞走了多少只蝴蝶？②黄蝴蝶有多少只？③花蝴蝶有多少只？四、列式计算（二）（12分）：1.马路两边各插8面小旗，又在一边插1面国旗，一共插多少面？", "options": null}', '②9-5=4  ③5  四1.8+8+1=17  (①依原题飞走条件)', '②其余为黄蝴蝶=9-5=4；③花蝴蝶5；四1 两边各8+额外1=17。①缺飞走条件，待原题。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p068.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "列算式：8.车上原来有9人，现在有多少人（依原题变化量）？9.一共有多少只小动物去郊游（我前面有8只，后面有4只）？", "options": null}', '8-依原题变化；9-8+4+1=13（只）', '排队含自己：前8+后4+自己1=13。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p070.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "（依图）跳绳6人、拍球5人、打乒乓球8人：（1）跳绳和拍球一共多少人？（2）拍球和打乒乓球一共多少人？", "options": null}', '1.6+5=11  2.5+8=13', '直接求和。', 'paper', '["应用题"]', '["/static/qimg/yg_sx_p071.jpg"]', 0);
