INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '数数', 1, '{"stem": "七、下列物体能描出什么样的图形？用线连起来（4分，图见原题）。八、数一数，填一填（9分）：（1）一共有（ ）个物体。（2）长方体（ ）个、正方体（ ）个、球（ ）个、圆柱（ ）个。（3）从左往右数__是第（ ）个（图见原题）。", "options": null}', '【图意待补】', '图意需人工核对（OCR 读不到图内信息）。', 'paper', '["图意待补"]', '["/static/qimg/yg_sx_p111.jpg"]', 0);
