INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '填空', 1, '{"stem": "填空：（3）与13相邻的两个数是（12）和（14）。（4）16和17中（17）更接近18。（5）比12大比15小的数有（13、14）。", "options": null}', '12和14；17；13、14', '相邻数与范围。', 'paper', '["数位"]', '["/static/qimg/yg_sx_p114.jpg"]', 0);
