INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='一年级' AND level=1 LIMIT 1), '数学', '一年级', '应用题', 1, '{"stem": "10.小朋友们排成一队，从前往后数欢欢排第3，从后往前数排第7，这一队一共有（9）人。", "options": null}', '3+7-1=9（人）', '排队总数=前+后-1=9。', 'paper', '["排队"]', '["/static/qimg/yg_sx_p115.jpg"]', 0);
