INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '判断', 1, '{"stem":"求3个3相加的和是多少,算式是3+3。","options":null}', '×', '3+3=6只是2个3相加,3个3相加=3+3+3=9,故算式应为3+3+3,本判断为错。', 'paper', '[]', '["/static/qimg/tb_p27.jpg"]', 0);
