INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"填一填 A级 2:(1)3+3+3+3+3+3+3+3=□×3=3×□=□;(2)4+4+4+4+4+4+4+4=□×4=4×□=□;(3)2+2+2+2+2+2+2+2=□×□=□×□=□;(4)□×8=32。","options":null}', '(1)8,8,24;(2)8,8,32;(3)8,2,2,8,16;(4)4', '8个3=24,8个4=32,8个2=16;□×8=32,□=4。', 'paper', '[]', '["/static/qimg/tb_p31.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem":"想一想,算一算 A级 3:1×3,1×5,6×0;2×3,2×5,7×0;3×3,3×5,8×0;4×3,4×5,9×0;5×3,5×5,10×0。","options":null}', '3,5,0;6,10,0;9,15,0;12,20,0;15,25,0', '1×3=3,1×5=5,6×0=0;2×3=6,2×5=10,7×0=0;3×3=9,3×5=15,8×0=0;4×3=12,4×5=20,9×0=0;5×3=15,5×5=25,10×0=0。任何数乘0得0。', 'paper', '[]', '["/static/qimg/tb_p31.jpg"]', 0);
