INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"在○内填入\"十\"\"-\"或\"×\" A级 2:5○5=10,15○5=10,5○5○5○5=20,5○5=25,5○6=25○5,40○5=5○7。","options":null}', '+,+;-,+;+,+,+;×;×, +;-,×', '5+5=10,15-5=10;5+5+5+5=20(3个+);5×5=25;5×6=25+5=30(×和+);40-5=5×7=35(-和×)。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"一个一个摆,摆4个独立的□(正方形) A级 3,一共需要多少根小棒?","options":null}', '算式:4×4=16;答:16根', '一个正方形用4根小棒,4个独立正方形(不共用边)需要4×4=16根小棒。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"填一填 B级:(1)2与5的和是____;2个5的和是____;2个5的积是____。(2)买了一本书,付给收银员7张5元,找回的钱不到5元。这本书的价格可能是____元(填序号:①35 ②30 ③32)。","options":null}', '(1)7,10,25;(2)①和③', '(1)2+5=7,2个5相加=5+5=10,2个5相乘=5×5=25。(2)7张5元=35元,找回<5元,书价>30元且≤35元,选项①35(找回0元)和③32(找回3元)均<5元,②30找回5元不满足"不到5元"。', 'paper', '[]', '["/static/qimg/tb_p33.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '计算', 1, '{"stem":"算一算 A级 1:8×2,7+7,12=2×□;2×10,9+9,16=□×2;2×9,8+8,8=2×□。","options":null}', '16,14,6;20,18,8;18,16,4', '8×2=16,7+7=14,12=2×6;2×10=20,9+9=18,16=8×2;2×9=18,8+8=16,8=2×4。', 'paper', '[]', '["/static/qimg/tb_p34.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"应用题 A级 2:棒棒糖每根2元,冰淇淋每个5元。(1)买4个冰淇淋需要多少元?(2)有3张5元钱,买7根棒棒糖,钱够不够?(3)请再提出一个数学问题,并列式解答。","options":null}', '(1)4×5=20(元);(2)3×5=15(元),7×2=14(元),15>14,钱够;(3)开放题', '(1)冰淇淋4个:4×5=20元。(2)7根棒棒糖:7×2=14元,3张5元=15元,15>14,钱够。(3)开放题,例如买5个冰淇淋要多少元:5×5=25元。', 'paper', '[]', '["/static/qimg/tb_p34.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem":"B级:参加猜灯谜游戏,获得5分和2分的积分卡各8张。他想兑换一辆30分的玩具车,可以怎么兑换?写出两种兑换方式。","options":null}', '方式1:6张5分卡=30分(用6张5分);方式2:4张5分卡+5张2分卡=20+10=30分(用4张5分卡和5张2分卡)', '5分卡8张、2分卡8张,要凑30分:6×5=30(仅用5分卡);4×5+5×2=20+10=30(混合兑换);还有2×5+10×2=10+20=30但2分卡只有8张,不可行。', 'paper', '[]', '["/static/qimg/tb_p35.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem":"A级 课本46~47页 算一算:8×4=□;4×□=16;20=□×4;7×4=□;4×□=8;24=4×□;4×10=□;4×□=12;36=□×4","options":null}', '8×4=32;4×4=16;20=5×4;7×4=28;4×2=8;24=4×6;4×10=40;4×3=12;36=9×4', '本题为4的乘法口诀应用。8×4=32(八四三十二),4×4=16,20÷4=5,7×4=28,4×2=8,24÷4=6,4×10=40,4×3=12,36÷4=9。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"A级 课本46~47页 找规律填数:(1)20,18,□,14,□,□,8;(2)4,8,□,□,20,□,28,□,36","options":null}', '(1)16,12,10;(2)12,16,24,32', '规律题:(1)每一项比前一项少2,依次为20,18,16,14,12,10,8;(2)每一项比前一项多4,依次为4,8,12,16,20,24,28,32,36。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"A级 课本46~47页 应用题(1):一包瓜子9元,4包瓜子一共多少元?","options":null}', '9×4=36(元)', '求4包瓜子的总价,用单价×数量=总价:9×4=36(元)。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"A级 课本46~47页 应用题(2):有8盒巧克力,每盒有4块。一共有多少块巧克力?","options":null}', '8×4=32(块)', '求巧克力的总块数,用每盒块数×盒数=总块数:8×4=32(块)。', 'paper', '[]', '["/static/qimg/tb_p36.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"A级 课本46~47页 应用题(3):有25名乘客,每辆车限坐乘客7人。4辆车坐得下吗?","options":null}', '4×7=28(人),28>25,坐得下。', '4辆车最多坐4×7=28人,28>25,所以4辆车能坐得下25名乘客。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem":"A级 课本46~47页 应用题(4):每天看6页书,已经看了4天。第5天应从第几页开始看?","options":null}', '6×4=24(页),24+1=25(页),第5天应从第25页开始看。', '前4天一共看了6×4=24页,第5天应从已看完的下一页开始,即第25页。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem":"B级 课本46~47页:已知▲+▲+▲+▲=24,★+★+★=15,那么▲×★=____。","options":null}', '▲×★=6×5=30', '由4个▲=24,得▲=24÷4=6;由3个★=15,得★=15÷3=5;所以▲×★=6×5=30。', 'paper', '[]', '["/static/qimg/tb_p37.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem":"A级 课本48~49页 算一算:8×6=□;2×□=16;40=□×8;7×8=□;8×□=32;24=8×□;10×8=□;□×8=72;64=□×8","options":null}', '8×6=48;2×8=16;40=5×8;7×8=56;8×4=32;24=8×3;10×8=80;9×8=72;64=8×8', '本题为8的乘法口诀应用。8×6=48,2×8=16,40÷8=5,7×8=56,8×4=32,24÷8=3,10×8=80,72÷8=9,64÷8=8。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"A级 课本48~49页 看图列式:上面一组足球8个,下面一组篮球是?个。□×□=□(个)","options":null}', '8×2=16(个)', '看图:上面1组足球8个,下面1组篮球也是8个(2组共16个),即篮球的数量是足球的2倍,8×2=16(个)。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"A级 课本48~49页 应用题(1):二(3)班有8个小组,每个小组有4名学生。二(3)班一共有多少名学生?","options":null}', '8×4=32(名)', '求班级总人数,用每组人数×组数=总人数:8×4=32(名)。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem":"A级 课本48~49页 应用题(2):一罐可乐3元,买8罐可乐。如果全部用20元纸币付,至少要付几张?","options":null}', '3×8=24(元),24>20,至少要付2张20元纸币。', '8罐可乐共需3×8=24元,1张20元不够(差4元),所以至少要付2张20元。', 'paper', '[]', '["/static/qimg/tb_p38.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★2(1) 看图：①号是 12 个心形，②号是 11 个星形，③号是 9 个圆点。下列能用算式\"3×4-1\"计算的是（  ）", "options": null}', '②', '3×4-1=12-1=11；①号 12 个心形=3×4 不能用"3×4-1"；②号 11 个星形=3×4-1 ✓；③号 9 个圆点=3×3 不能用"3×4-1"', 'paper', '[]', '["/static/qimg/tb_p44.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2(3) 汉字\"口\"的笔画有 3 画，\"口吕品\"这三个字一共有 ___ 画。", "options": null}', '18', '口=3 画；吕=6 画（两个口）；品=9 画（三个口）；共 3+6+9=18 画', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '单选', 2, '{"stem": "A级★3(3) 下面的算式中，结果与\"6+6+6+6+6+5\"相等的是（  ）A. 6×5+6 B. 6×6+5 C. 6×5+5", "options": null}', 'C', '6+6+6+6+6+5 = 6×5+5；6×5+5=30+5=35 与原式 30+5=35 一致；B. 6×6+5=36+5=41 不对；A. 6×5+6=30+6=36 不对', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem": "A级★2 在 ○ 内填入\">\"\"<\"或\"=\"：9×9-9○70, 4×9○9×3+9, 53+36○46+43, 7×9○9×8-9, 63-3×6○9×5, 81-3×9○2×9+5×9", "options": null}', '>、=、=、=、=、<', '9×9-9=72>70；4×9=36, 9×3+9=36 → =；53+36=89, 46+43=89 → =；7×9=63, 9×8-9=63 → =；63-3×6=45, 9×5=45 → =；81-3×9=54, 2×9+5×9=63 → 54<63', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem": "B级 在○内填入\"+\"\"-\"或\"×\"，使式子成立：4○2=9○1；3○4=9○3；6○6=4○9；4○4=8○8。", "options": null}', '4×2=9-1；3×4=9+3；6×6=4×9；4×4=8+8', '两边结果分别相等：(1)4×2=8=9-1；(2)3×4=12=9+3；(3)6×6=36=4×9；(4)4×4=16=8+8。', 'paper', '[]', NULL, 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem":"观察下面的火车图案，完成分类统计表。火车由 4 节车厢组成，每节车厢底部有 2 个圆形车轮，顶部为不同的形状（3 个白色方块、1 个黑色长方形）。请按形状统计：圆形、方块、长方形、三角形各有多少个。","options":null}', '圆形 8 个（4 节车厢每节 2 个车轮）、白色方块 3 个、黑色长方形 1 个、三角形 0 个。', '按形状分类时逐类数：每节车厢有 2 个车轮，4 节共 2×4=8 个圆形；顶部形状数一数即可。分类统计是学习「数的整除」的基础，关键是同一标准不重不漏。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 1, '{"stem":"用不同的标准，把下面的图形分一分，再用符号记录结果。图中有：长方形 2 个、正方形 2 个、三角形 3 个、圆 3 个、梯形 2 个。","options":null}', '按形状分：长方形 2 个、正方形 2 个、三角形 3 个、圆 3 个、梯形 2 个；按颜色分（浅色/深色）分别计数。答案不唯一。', '分类标准可以不同（形状、颜色、大小等），按同一标准不重不漏地数即可。鼓励用不同标准多角度分类，体会分类思想。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"选择不同的标准，把下面的数卡分一分，并用表格记录结果。数卡：20、3、8、14、7、3、15、9、13、17。","options":null}', '标准一（单双数）：单数 7 个（3、7、3、15、9、13、17），双数 3 个（20、8、14）；标准二（位数）：一位数 5 个（3、8、7、3、9），两位数 5 个（20、14、15、13、17）；标准三（能否被 3 整除）：3 的倍数 4 个（3、15、9、3），其余 6 个。', '数的分类可从单双数、位数、能否被某数整除等角度入手。注意 20、8、14 都是双数，3、7、15、9、13、17 都是单数。本题训练数的多种分类，是后续「数的整除」概念的基础。', 'paper', '[]', '["/static/qimg/tb_p57.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 2, '{"stem":"用逐层分类的方法，把下面的 12 个气球分一分、数一数。先按颜色（绿色、白色）分，再按形状（圆形、心形、椭圆形）分。","options":null}', '第一层按颜色分：绿色 5 个、白色 7 个。第二层按形状分：绿色中圆形 2 个、心形 2 个、椭圆形 1 个；白色中圆形 3 个、心形 1 个、椭圆形 3 个。', '「逐层分类」指先按一个标准分大类，再在每个大类里按另一个标准分小类。先数颜色，再在每类里数形状，逐层不重不漏。', 'paper', '[]', '["/static/qimg/tb_p58.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '解答', 3, '{"stem":"用逐层分类的方法，把下面的 16 个图形分一分、数一数。图中有：三角形 6 个、圆 2 个、正方形 3 个、梯形 3 个、长方形 2 个（其中部分为深色、部分为浅色）。","options":null}', '第一层按形状分：三角形 6 个、圆 2 个、正方形 3 个、梯形 3 个、长方形 2 个。第二层按颜色分：深色三角形 3 个、浅色三角形 3 个；其余同理按深浅再分。', '逐层分类先分形状大类，再在每个形状里按颜色深浅分小类。共 6+2+3+3+2=16 个，逐类核对不重不漏。', 'paper', '[]', '["/static/qimg/tb_p59.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem":"找规律填数：(1) 3、8、13、18、___、___、___。(2) 80、71、62、53、___、___、___。","options":null}', '(1) 后一个数比前一个数大 5：23、28、33。(2) 后一个数比前一个数小 9：44、35、26。', '(1) 8-3=5、13-8=5、18-13=5，公差为 5，依次 +5 得 23、28、33。(2) 71-80=-9、62-71=-9、53-62=-9，公差为 -9，依次 -9 得 44、35、26。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 1, '{"stem":"找规律填数：(1) 42、___、___、24、18、___、6。(2) 1、2、4、7、11、___、___、29。","options":null}', '(1) 相邻两项相差 6：42、36、30、24、18、12、6，填 36、30、12。(2) 相邻差依次 +1、+2、+3、+4、+5、+6、+7：1、2、4、7、11、16、22、29，填 16、22。', '(1) 从 42 到 6 每次减 6，是 6 的倍数递减数列。(2) 差值依次递增：2-1=1、4-2=2、7-4=3、11-7=4，下一个差 5 得 16，再差 6 得 22，再差 7 得 29。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"根据规律填一填：(1) 12-3 = 13-___ = 14-___ = 15-___。(2) 18-9 = ___-8 = ___-7 = ___-___。","options":null}', '(1) 等式左边都是 9：13-4=9、14-5=9、15-6=9，填 4、5、6。(2) 18-9=9，需 ___-8=9、___-7=9、___-___=9，填 17、16、15、6（15-6=9）。', '等号左右两边结果相等。(1) 12-3=9，故 13-?=9、14-?=9、15-?=9，分别填 4、5、6。(2) 18-9=9，被减数依次 -1、-1，减数也依次 -1 保持差不变：17-8=9、16-7=9、15-6=9。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"根据第一个「数墙」的规律（上面一格等于下面两格之和），把后面两个「数墙」填完整。数墙一：底层 25、13、19，上层 38、32，顶层 70。数墙二：底层 26、___、___，上层 45、___，顶层 93。数墙三：底层 18、25、___，上层 ___、41，顶层 ___。","options":null}', '数墙二：26+19=45，故底层第二格 19；45+48=93，上层第二格 48，底层第三格 48-19=29。即底层 26、19、29，上层 45、48，顶层 93。数墙三：25+16=41，故底层第三格 16；18+25=43，上层第一格 43；43+41=84，顶层 84。即底层 18、25、16，上层 43、41，顶层 84。', '数墙规律：上面一格 = 下面相邻两格之和。数墙二：26+a=45 得 a=19；a+b=45+48 的中间数，顶层 45+(19+b)=93 得 b=29。数墙三：25+b=41 得 b=16；18+25=43；43+41=84。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem":"从 2、5、6、8、10、12、15、18、20、24、30、40 中选出 4 个组成一组有规律的数，写出 4 组。","options":null}', '① 5、10、15、20（相邻差 5）；② 6、12、18、24（相邻差 6）；③ 10、20、30、40（相邻差 10）；④ 2、8、14、20（相邻差 6，从 2 起）。答案不唯一。', '从一组数中找规律常见思路：等差数列（相邻差相等）或公倍数。如 5、10、15、20 是 5 的倍数，6、12、18、24 是 6 的倍数，10、20、30、40 是 10 的倍数。', 'paper', '[]', '["/static/qimg/tb_p60.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"在○内填数，使横行、竖列、斜行上三个数的和都是 18。已给：第一行中间是 10、第一行右边是 5，中心是 6，其余 6 个○待填。","options":null}', '第一行左边：3；第二行左边：8；第二行右边：4；第三行左边：7、中间：2、右边：9。完整幻方：第一行 3、10、5；第二行 8、6、4；第三行 7、2、9。', '每行、每列、每条对角线之和都等于 18。先由对角线 5+6+第三行左边=18 得 7；由对角线 第一行左边+6+第三行右边=18，结合第一行左边+10+5=18 得第一行左边=3、第三行右边=9；再由列、行依次推出其余各数。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 2, '{"stem":"在空格中填数，使横行、竖列、斜行上三个数的和都相等。已给：第一行右边 29、中心 28、第三行左边 27、第三行中间 39。","options":null}', '幻和 = 29+28+27 = 84。第一行左边 38、第一行中间 17、第一行右边 29；第二行左边 19、中心 28、第二行右边 37；第三行左边 27、第三行中间 39、第三行右边 18。', '先由对角线 29+28+27=84 求出幻和。再由第三行 27+39+第三行右边=84 得 18；由另一对角线 第一行左边+28+18=84 得 38；由第一列 38+第二行左边+27=84 得 19；再依次推出其余各数。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES ((SELECT id FROM knowledge_nodes WHERE subject='数学' AND grade='二年级' AND level=1 LIMIT 1), '数学', '二年级', '填空', 3, '{"stem":"把 1~9 填入下面 3×3 的表格中，使横行、竖列、斜行上三个数的和都是 15。已给：左上角是 4、右下角是 6。","options":null}', '第一行 4、9、2；第二行 3、5、7；第三行 8、1、6。校验：4+9+2=15、3+5+7=15、8+1+6=15；4+3+8=15、9+5+1=15、2+7+6=15；4+5+6=15、2+5+8=15。', '1~9 总和 45，三行三列平均幻和 15。中心 5 所在的行、列、两条对角线共 4 条线，故 5 必在中心。已给左上角 4、右下角 6，正好与经典三阶幻方吻合，按标准幻方填充即可。', 'paper', '[]', '["/static/qimg/tb_p61.jpg"]', 0);
